SELECT '55f9d114-44dc-73f6-ba97-7a0a8af73629', 'ff7fcd47-1dc4-726e-a6a4-c5f556ff5ad6', 1, 'PUBLISHED', 'Circular Linked List', '[{"id":"b1b60f09-2195-746f-96a5-f52f1d6fb757","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A circular linked list is a singly linked list whose "},{"type":"text","text":"last node points back to the head","marks":[{"type":"bold"}]},{"type":"text","text":" instead of to "},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":". There is no end, so the list can be traversed from any node, and keeping a single pointer gives O(1) access to both the first and the last element."}]}]}},"revision":1},{"id":"c2ce39ed-5b91-7c82-b076-5d8730be09e3","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Circular linked list","marks":[{"type":"bold"}]},{"type":"text","text":" — a linked list in which the "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" of the last node refers to the first node. A one-node list points to itself. Traversal stops when we return to the node where we started, not when "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":" — because it never is."}]}]}},"revision":1},{"id":"c9a93f5d-0f53-77d5-96bf-d00ab1521e99","type":"code","position":"a2","content":{"language":"text","code":"head\n ↓\n┌──────┬────┐    ┌──────┬────┐    ┌──────┬────┐    ┌──────┬────┐\n│  10  │ ●──┼───▶│   5  │ ●──┼───▶│  20  │ ●──┼───▶│  15  │ ●──┼──┐\n└──────┴────┘    └──────┴────┘    └──────┴────┘    └──────┴────┘  │\n  ▲                                                               │\n  └───────────────────────────────────────────────────────────────┘\n                the last node links back to the head","filename":"10 → 5 → 20 → 15 → back to 10"},"revision":1},{"id":"8f37bd5d-3085-7e75-b383-a311ee11842b","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Building and traversing"}]},"revision":1},{"id":"b51c7baf-9e84-7578-9d4f-2c82157524b9","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The nodes are the same as in a singly linked list; only the last link differs. Traversal must "},{"type":"text","text":"stop when it comes back to the head","marks":[{"type":"bold"}]},{"type":"text","text":", so the loop prints the head first and then walks until "},{"type":"text","text":"curr == head","marks":[{"type":"code"}]},{"type":"text","text":" again. A "},{"type":"text","text":"while curr.next != head","marks":[{"type":"code"}]},{"type":"text","text":" loop (as in the original notes) also works but needs the last node printed separately."}]}]}},"revision":1},{"id":"0af73eb2-3c68-7ce5-9637-c6a565d65c86","type":"code","position":"a5","content":{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef print_circular(head):\n    if head is None:\n        print(\"empty\")\n        return\n    parts = [str(head.data)]\n    curr = head.next\n    while curr != head:              # stop when we are back at the start\n        parts.append(str(curr.data))\n        curr = curr.next\n    print(\" -> \".join(parts), f\"-> (back to {head.data})\")\n\nhead = Node(10)\nhead.next = Node(5)\nhead.next.next = Node(20)\nhead.next.next.next = Node(15)\nhead.next.next.next.next = head      # close the circle\nprint_circular(head)","filename":"Python"},"revision":1},{"id":"f6d849d9-220b-7b8f-ba05-69a5578f0bfa","type":"code","position":"a6","content":{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nvoid printCircular(Node* head) {\n    if (!head) { cout << \"empty\\n\"; return; }\n    cout << head->data;\n    for (Node* curr = head->next; curr != head; curr = curr->next)   // stop when back at the start\n        cout << \" -> \" << curr->data;\n    cout << \" -> (back to \" << head->data << \")\\n\";\n}\n\nint main() {\n    Node* head = new Node(10);\n    head->next = new Node(5);\n    head->next->next = new Node(20);\n    head->next->next->next = new Node(15);\n    head->next->next->next->next = head;    // close the circle\n    printCircular(head);\n}","filename":"C++"},"revision":1},{"id":"94901317-72e7-7dc8-9d1e-66620d241031","type":"code","position":"a7","content":{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static void printCircular(Node head) {\n        if (head == null) { System.out.println(\"empty\"); return; }\n        StringBuilder sb = new StringBuilder().append(head.data);\n        for (Node curr = head.next; curr != head; curr = curr.next)   // stop when back at the start\n            sb.append(\" -> \").append(curr.data);\n        System.out.println(sb + \" -> (back to \" + head.data + \")\");\n    }\n\n    public static void main(String[] args) {\n        Node head = new Node(10);\n        head.next = new Node(5);\n        head.next.next = new Node(20);\n        head.next.next.next = new Node(15);\n        head.next.next.next.next = head;    // close the circle\n        printCircular(head);\n    }\n}","filename":"Java"},"revision":1},{"id":"e2ec9b4d-0970-7879-bc65-b830bd4ee045","type":"code","position":"a8","content":{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction printCircular(head) {\n    if (head === null) { console.log(\"empty\"); return; }\n    const parts = [head.data];\n    for (let curr = head.next; curr !== head; curr = curr.next)   // stop when back at the start\n        parts.push(curr.data);\n    console.log(parts.join(\" -> \"), `-> (back to ${head.data})`);\n}\n\nconst head = new Node(10);\nhead.next = new Node(5);\nhead.next.next = new Node(20);\nhead.next.next.next = new Node(15);\nhead.next.next.next.next = head;        // close the circle\nprintCircular(head);","filename":"JavaScript"},"revision":1},{"id":"5e754619-5153-7bc8-bb2a-f701c25a15c5","type":"code","position":"a9","content":{"language":"text","code":"10 -> 5 -> 20 -> 15 -> (back to 10)","filename":"Output"},"revision":1},{"id":"a5010df4-1a98-762c-979c-f12935e68d14","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) traversal · Space O(1)"}]}]}},"revision":1},{"id":"37b70512-c800-71fc-84aa-854be67a7c4b","type":"callout","position":"aB","content":{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"while curr is not None","marks":[{"type":"code"}]},{"type":"text","text":" loop never terminates on a circular list. Every traversal must remember where it started and stop there."}]}]}},"revision":1},{"id":"02bae07a-0511-74db-92e6-389fbca84099","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Advantages and disadvantages"}]},"revision":1},{"id":"584a69af-1f76-74c9-aebb-7a5c3e57ce46","type":"callout","position":"aD","content":{"variant":"note","title":"Traverse from any node","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Starting anywhere, following "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" visits every node — no need to find the head first."}]}]}},"revision":1},{"id":"b79b88ad-e7a5-7daf-af33-3324869f662c","type":"callout","position":"aE","content":{"variant":"note","title":"Round-robin scheduling","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The OS gives each process a time slice and moves to "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":"; after the last process comes the first again. Also: multiplayer turns, circular buffers, music playlists on repeat."}]}]}},"revision":1},{"id":"81dfdcf3-86eb-73c4-a90b-d4f71ee98d65","type":"callout","position":"aF","content":{"variant":"note","title":"O(1) at both ends with one pointer","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Keep a reference to the "},{"type":"text","text":"tail","marks":[{"type":"bold"}]},{"type":"text","text":": the head is "},{"type":"text","text":"tail.next","marks":[{"type":"code"}]},{"type":"text","text":", so insert at the beginning, insert at the end and delete the head are all O(1)."}]}]}},"revision":1},{"id":"a0002803-4d53-7d2a-931a-4601460b6369","type":"callout","position":"aG","content":{"variant":"note","title":"More complex code","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every operation must handle the empty list, the one-node list (which points at itself) and the wrap-around; an off-by-one gives an infinite loop instead of a crash."}]}]}},"revision":1},{"id":"39273334-6c2c-7d64-8d53-0275a0ab8f2b","type":"table","position":"aH","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Operation (holding "},{"type":"text","text":"head","marks":[{"type":"code"}]},{"type":"text","text":" only)"}],[{"type":"text","text":"Naive"}],[{"type":"text","text":"Efficient trick"}],[{"type":"text","text":"Holding "},{"type":"text","text":"tail","marks":[{"type":"code"}]},{"type":"text","text":" instead"}]],[[{"type":"text","text":"Insert at beginning"}],[{"type":"text","text":"O(n): walk to the last node to fix its "},{"type":"text","text":"next","marks":[{"type":"code"}]}],[{"type":"text","text":"O(1): insert "},{"type":"text","text":"after","marks":[{"type":"italic"}]},{"type":"text","text":" head and swap data"}],[{"type":"text","text":"O(1)"}]],[[{"type":"text","text":"Insert at end"}],[{"type":"text","text":"O(n): walk to the last node"}],[{"type":"text","text":"O(1): same trick, return the new node as head"}],[{"type":"text","text":"O(1)"}]],[[{"type":"text","text":"Delete head"}],[{"type":"text","text":"O(n): walk to the last node to re-point it"}],[{"type":"text","text":"O(1): copy "},{"type":"text","text":"head.next","marks":[{"type":"code"}]},{"type":"text","text":" into head and unlink "},{"type":"text","text":"head.next","marks":[{"type":"code"}]}],[{"type":"text","text":"O(1)"}]],[[{"type":"text","text":"Delete k-th node"}],[{"type":"text","text":"O(k)"}],[{"type":"text","text":"—"}],[{"type":"text","text":"O(k)"}]],[[{"type":"text","text":"Search"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"—"}],[{"type":"text","text":"O(n)"}]]]},"revision":1},{"id":"7da8b1ec-d0c3-7562-840e-9cdbf0e284c7","type":"heading","position":"aI","content":{"level":1,"content":[{"type":"text","text":"Insert at the beginning"}]},"revision":1},{"id":"7be2bfc9-29eb-7dda-aead-c68174f9b485","type":"callout","position":"aJ","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = 10 -> 5 -> 20 -> 15 (circular), insert 25 at the beginning","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"25 -> 10 -> 5 -> 20 -> 15 -> (back to 25)","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"f8949a68-00c1-7299-8457-775385e9d463","type":"text","position":"aK","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Naive, O(n).","marks":[{"type":"bold"}]},{"type":"text","text":" The last node must point at the new head, and the only way to reach the last node is to walk the whole circle."}]}]}},"revision":1},{"id":"26f84fc6-2797-710e-8c5b-c853adde948d","type":"code","position":"aL","content":{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef insert_beginning_naive(head, x):\n    temp = Node(x)\n    if head is None:\n        temp.next = temp               # one node points at itself\n        return temp\n    curr = head\n    while curr.next != head:           # O(n) walk to the last node\n        curr = curr.next\n    curr.next = temp                   # last node → new node\n    temp.next = head                   # new node → old head\n    return temp\n\ndef print_circular(head):\n    parts, curr = [str(head.data)], head.next\n    while curr != head:\n        parts.append(str(curr.data)); curr = curr.next\n    print(\" -> \".join(parts), f\"-> (back to {head.data})\")\n\nhead = Node(10); head.next = Node(5); head.next.next = Node(20); head.next.next.next = Node(15)\nhead.next.next.next.next = head\nhead = insert_beginning_naive(head, 25)\nprint_circular(head)","filename":"Python"},"revision":1},{"id":"a1c21f09-c09a-7f8d-a294-b984e60b30b9","type":"code","position":"aM","content":{"language":"text","code":"25 -> 10 -> 5 -> 20 -> 15 -> (back to 25)","filename":"Output"},"revision":1},{"id":"0de3e984-d200-7561-be21-d726355893c8","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(1)"}]}]}},"revision":1},{"id":"af11ae1d-9a1c-7e4a-9cdd-2193e284b55e","type":"callout","position":"aO","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Efficient, O(1).","marks":[{"type":"bold"}]},{"type":"text","text":" Insert the new node "},{"type":"text","text":"right after","marks":[{"type":"italic"}]},{"type":"text","text":" the head (two pointer changes — no walk) and then "},{"type":"text","text":"swap the data","marks":[{"type":"bold"}]},{"type":"text","text":" of the head and the new node. The head node now carries the new value and the old head value sits in second position: exactly the result of inserting at the front. The head reference does not even change."}]}]}},"revision":1},{"id":"eaf53978-07b1-70ba-81b4-b021cd9bd9e1","type":"code","position":"aP","content":{"language":"text","code":"before:          head ──▶ [10] ──▶ [5] ──▶ [20] ──▶ [15] ──▶ back to 10\ninsert after head:   head ──▶ [10] ──▶ [25] ──▶ [5] ──▶ [20] ──▶ [15] ──▶ back to 10\nswap data:           head ──▶ [25] ──▶ [10] ──▶ [5] ──▶ [20] ──▶ [15] ──▶ back to 25","filename":"Insert at the beginning in O(1): insert after the head, then swap the two values"},"revision":1},{"id":"ca5bd19a-b3e0-7d5d-b688-7264fd9bb9dc","type":"code","position":"aQ","content":{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef insert_beginning(head, x):\n    temp = Node(x)\n    if head is None:\n        temp.next = temp                             # one node points at itself\n        return temp\n    temp.next = head.next                            # insert temp right after head\n    head.next = temp\n    head.data, temp.data = temp.data, head.data      # swap values: head now holds x\n    return head\n\ndef print_circular(head):\n    parts, curr = [str(head.data)], head.next\n    while curr != head:\n        parts.append(str(curr.data)); curr = curr.next\n    print(\" -> \".join(parts), f\"-> (back to {head.data})\")\n\nhead = Node(10); head.next = Node(5); head.next.next = Node(20); head.next.next.next = Node(15)\nhead.next.next.next.next = head\nhead = insert_beginning(head, 25); print_circular(head)\nhead = insert_beginning(head, 30); print_circular(head)","filename":"Python"},"revision":1},{"id":"5280ae1e-7970-7e9a-9590-92213e6f670a","type":"code","position":"aR","content":{"language":"cpp","code":"#include <iostream>\n#include <utility>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nNode* insertBeginning(Node* head, int x) {\n    Node* temp = new Node(x);\n    if (!head) { temp->next = temp; return temp; }   // one node points at itself\n    temp->next = head->next;                         // insert temp right after head\n    head->next = temp;\n    swap(head->data, temp->data);                    // swap values: head now holds x\n    return head;\n}\n\nvoid printCircular(Node* head) {\n    cout << head->data;\n    for (Node* curr = head->next; curr != head; curr = curr->next) cout << \" -> \" << curr->data;\n    cout << \" -> (back to \" << head->data << \")\\n\";\n}\n\nint main() {\n    Node* head = new Node(10); head->next = new Node(5); head->next->next = new Node(20);\n    head->next->next->next = new Node(15); head->next->next->next->next = head;\n    head = insertBeginning(head, 25); printCircular(head);\n    head = insertBeginning(head, 30); printCircular(head);\n}","filename":"C++"},"revision":1},{"id":"df435b14-f210-7e1c-98dd-2130fb6d7b1b","type":"code","position":"aS","content":{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static Node insertBeginning(Node head, int x) {\n        Node temp = new Node(x);\n        if (head == null) { temp.next = temp; return temp; }   // one node points at itself\n        temp.next = head.next;                                  // insert temp right after head\n        head.next = temp;\n        int t = head.data; head.data = temp.data; temp.data = t; // swap values: head now holds x\n        return head;\n    }\n\n    static void printCircular(Node head) {\n        StringBuilder sb = new StringBuilder().append(head.data);\n        for (Node curr = head.next; curr != head; curr = curr.next) sb.append(\" -> \").append(curr.data);\n        System.out.println(sb + \" -> (back to \" + head.data + \")\");\n    }\n\n    public static void main(String[] args) {\n        Node head = new Node(10); head.next = new Node(5); head.next.next = new Node(20);\n        head.next.next.next = new Node(15); head.next.next.next.next = head;\n        head = insertBeginning(head, 25); printCircular(head);\n        head = insertBeginning(head, 30); printCircular(head);\n    }\n}","filename":"Java"},"revision":1},{"id":"3809b15a-2a0c-73f5-83b6-0705a1ba6a5d","type":"code","position":"aT","content":{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction insertBeginning(head, x) {\n    const temp = new Node(x);\n    if (head === null) { temp.next = temp; return temp; }   // one node points at itself\n    temp.next = head.next;                                   // insert temp right after head\n    head.next = temp;\n    [head.data, temp.data] = [temp.data, head.data];         // swap values: head now holds x\n    return head;\n}\n\nfunction printCircular(head) {\n    const parts = [head.data];\n    for (let curr = head.next; curr !== head; curr = curr.next) parts.push(curr.data);\n    console.log(parts.join(\" -> \"), `-> (back to ${head.data})`);\n}\n\nlet head = new Node(10); head.next = new Node(5); head.next.next = new Node(20);\nhead.next.next.next = new Node(15); head.next.next.next.next = head;\nhead = insertBeginning(head, 25); printCircular(head);\nhead = insertBeginning(head, 30); printCircular(head);","filename":"JavaScript"},"revision":1},{"id":"f0b4f160-2e00-7bfe-a31e-fa6580684d45","type":"code","position":"aU","content":{"language":"text","code":"25 -> 10 -> 5 -> 20 -> 15 -> (back to 25)\n30 -> 25 -> 10 -> 5 -> 20 -> 15 -> (back to 30)","filename":"Output"},"revision":1},{"id":"c9919c7a-e624-76ed-93b4-5f19c5358deb","type":"text","position":"aV","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(1) · Space O(1)"}]}]}},"revision":1},{"id":"a8e7b663-aa6d-745e-82c7-5e589a854562","type":"callout","position":"aW","content":{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The swap trick moves a "},{"type":"text","text":"value","marks":[{"type":"italic"}]},{"type":"text","text":" into a different node. If other code holds references to specific nodes (or the data is large/expensive to copy), use the tail-pointer design instead: with "},{"type":"text","text":"tail","marks":[{"type":"code"}]},{"type":"text","text":" known, "},{"type":"text","text":"head = tail.next","marks":[{"type":"code"}]},{"type":"text","text":" and both ends are O(1) without any swapping."}]}]}},"revision":1},{"id":"b89c666f-a477-7f84-93ca-07b5d5a6e665","type":"heading","position":"aX","content":{"level":1,"content":[{"type":"text","text":"Insert at the end"}]},"revision":1},{"id":"5db0425a-1744-7570-b5a9-9af25f8ecf02","type":"callout","position":"aY","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = 10 -> 5 -> 20 -> 15 (circular), insert 35 at the end","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 -> 5 -> 20 -> 15 -> 35 -> (back to 10)","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"2b49be86-07f5-715b-99da-2978020f5d88","type":"text","position":"aZ","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Naive, O(n).","marks":[{"type":"bold"}]},{"type":"text","text":" Walk to the last node, link it to the new node and link the new node back to the head."}]}]}},"revision":1},{"id":"609bc93e-5711-79b3-a0cf-6642a853ed44","type":"code","position":"aa","content":{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef insert_end_naive(head, x):\n    temp = Node(x)\n    if head is None:\n        temp.next = temp\n        return temp\n    curr = head\n    while curr.next != head:           # O(n) walk to the last node\n        curr = curr.next\n    curr.next = temp                   # last → new\n    temp.next = head                   # new → head\n    return head\n\ndef print_circular(head):\n    parts, curr = [str(head.data)], head.next\n    while curr != head:\n        parts.append(str(curr.data)); curr = curr.next\n    print(\" -> \".join(parts), f\"-> (back to {head.data})\")\n\nhead = Node(10); head.next = Node(5); head.next.next = Node(20); head.next.next.next = Node(15)\nhead.next.next.next.next = head\nhead = insert_end_naive(head, 35)\nprint_circular(head)","filename":"Python"},"revision":1},{"id":"d405b294-fc89-720b-b263-a8221d1006fd","type":"code","position":"ab","content":{"language":"text","code":"10 -> 5 -> 20 -> 15 -> 35 -> (back to 10)","filename":"Output"},"revision":1},{"id":"a6f6a180-5329-71e4-8538-17c7f20db90b","type":"text","position":"ac","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(1)"}]}]}},"revision":1},{"id":"4a9da999-84ca-774c-8423-97f6f8dfc225","type":"callout","position":"ad","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Efficient, O(1).","marks":[{"type":"bold"}]},{"type":"text","text":" Same trick as before — insert the new node after the head and swap the values — but now "},{"type":"text","text":"return the new node as the head","marks":[{"type":"bold"}]},{"type":"text","text":". Reading the circle from that node gives the old sequence first and the new value last: the head node (which now holds "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":") comes just before it."}]}]}},"revision":1},{"id":"fc583264-3bef-7999-a210-b634402e24d3","type":"code","position":"ae","content":{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef insert_end(head, x):\n    temp = Node(x)\n    if head is None:\n        temp.next = temp\n        return temp\n    temp.next = head.next                            # insert temp right after head\n    head.next = temp\n    head.data, temp.data = temp.data, head.data      # old head value moves to temp\n    return temp                                      # temp is the new head; x sits just before it\n\ndef print_circular(head):\n    parts, curr = [str(head.data)], head.next\n    while curr != head:\n        parts.append(str(curr.data)); curr = curr.next\n    print(\" -> \".join(parts), f\"-> (back to {head.data})\")\n\nhead = Node(10); head.next = Node(5); head.next.next = Node(20); head.next.next.next = Node(15)\nhead.next.next.next.next = head\nhead = insert_end(head, 35); print_circular(head)\nhead = insert_end(head, 40); print_circular(head)","filename":"Python"},"revision":1},{"id":"dbc4d4f4-9af9-7469-bffc-cb059fa13f09","type":"code","position":"af","content":{"language":"cpp","code":"#include <iostream>\n#include <utility>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nNode* insertEnd(Node* head, int x) {\n    Node* temp = new Node(x);\n    if (!head) { temp->next = temp; return temp; }\n    temp->next = head->next;                         // insert temp right after head\n    head->next = temp;\n    swap(head->data, temp->data);                    // old head value moves to temp\n    return temp;                                     // temp is the new head; x sits just before it\n}\n\nvoid printCircular(Node* head) {\n    cout << head->data;\n    for (Node* curr = head->next; curr != head; curr = curr->next) cout << \" -> \" << curr->data;\n    cout << \" -> (back to \" << head->data << \")\\n\";\n}\n\nint main() {\n    Node* head = new Node(10); head->next = new Node(5); head->next->next = new Node(20);\n    head->next->next->next = new Node(15); head->next->next->next->next = head;\n    head = insertEnd(head, 35); printCircular(head);\n    head = insertEnd(head, 40); printCircular(head);\n}","filename":"C++"},"revision":1},{"id":"4aaa20d5-bf1d-777f-b221-9b7d65288c01","type":"code","position":"ag","content":{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static Node insertEnd(Node head, int x) {\n        Node temp = new Node(x);\n        if (head == null) { temp.next = temp; return temp; }\n        temp.next = head.next;                                   // insert temp right after head\n        head.next = temp;\n        int t = head.data; head.data = temp.data; temp.data = t;  // old head value moves to temp\n        return temp;                                             // temp is the new head; x sits just before it\n    }\n\n    static void printCircular(Node head) {\n        StringBuilder sb = new StringBuilder().append(head.data);\n        for (Node curr = head.next; curr != head; curr = curr.next) sb.append(\" -> \").append(curr.data);\n        System.out.println(sb + \" -> (back to \" + head.data + \")\");\n    }\n\n    public static void main(String[] args) {\n        Node head = new Node(10); head.next = new Node(5); head.next.next = new Node(20);\n        head.next.next.next = new Node(15); head.next.next.next.next = head;\n        head = insertEnd(head, 35); printCircular(head);\n        head = insertEnd(head, 40); printCircular(head);\n    }\n}","filename":"Java"},"revision":1},{"id":"c4a11dda-f314-788f-8f5b-aeb2bca3dc87","type":"code","position":"ah","content":{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction insertEnd(head, x) {\n    const temp = new Node(x);\n    if (head === null) { temp.next = temp; return temp; }\n    temp.next = head.next;                                   // insert temp right after head\n    head.next = temp;\n    [head.data, temp.data] = [temp.data, head.data];         // old head value moves to temp\n    return temp;                                             // temp is the new head; x sits just before it\n}\n\nfunction printCircular(head) {\n    const parts = [head.data];\n    for (let curr = head.next; curr !== head; curr = curr.next) parts.push(curr.data);\n    console.log(parts.join(\" -> \"), `-> (back to ${head.data})`);\n}\n\nlet head = new Node(10); head.next = new Node(5); head.next.next = new Node(20);\nhead.next.next.next = new Node(15); head.next.next.next.next = head;\nhead = insertEnd(head, 35); printCircular(head);\nhead = insertEnd(head, 40); printCircular(head);","filename":"JavaScript"},"revision":1},{"id":"af1492b1-2c39-7311-85f3-36b803ccbc36","type":"code","position":"ai","content":{"language":"text","code":"10 -> 5 -> 20 -> 15 -> 35 -> (back to 10)\n10 -> 5 -> 20 -> 15 -> 35 -> 40 -> (back to 10)","filename":"Output"},"revision":1},{"id":"9075ed5e-3425-7ea3-aa34-79492ed16e66","type":"text","position":"aj","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(1) · Space O(1)"}]}]}},"revision":1},{"id":"d51e0f0a-54d4-795d-bba3-f9e349967c30","type":"heading","position":"ak","content":{"level":1,"content":[{"type":"text","text":"Delete the head"}]},"revision":1},{"id":"fbf2f38e-5fef-7ef6-9943-f2cdf72c2fb8","type":"callout","position":"al","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = 10 -> 5 -> 20 -> 15 (circular)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"5 -> 20 -> 15 -> (back to 5)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = 10 (one node)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"empty","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"38b2aa92-a6ee-7420-acb4-71fe1eeeb69d","type":"text","position":"am","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Naive, O(n).","marks":[{"type":"bold"}]},{"type":"text","text":" The last node points at the head, so after removing the head the last node must be found and re-pointed at the second node — a full walk."}]}]}},"revision":1},{"id":"36a10c78-a1c0-746d-9268-aa79c240ae50","type":"code","position":"an","content":{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef delete_head_naive(head):\n    if head is None or head.next == head:   # empty or single node → empty\n        return None\n    curr = head\n    while curr.next != head:                # O(n) walk to the last node\n        curr = curr.next\n    curr.next = head.next                   # last → second node\n    return curr.next                        # second node is the new head\n\ndef print_circular(head):\n    parts, curr = [str(head.data)], head.next\n    while curr != head:\n        parts.append(str(curr.data)); curr = curr.next\n    print(\" -> \".join(parts), f\"-> (back to {head.data})\")\n\nhead = Node(10); head.next = Node(5); head.next.next = Node(20); head.next.next.next = Node(15)\nhead.next.next.next.next = head\nhead = delete_head_naive(head)\nprint_circular(head)","filename":"Python"},"revision":1},{"id":"0b9a26c8-5a34-707d-b34f-3f57515a9c84","type":"code","position":"ao","content":{"language":"text","code":"5 -> 20 -> 15 -> (back to 5)","filename":"Output"},"revision":1},{"id":"ca769a18-d9b9-7451-a579-6f2e26a134a6","type":"text","position":"ap","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(1)"}]}]}},"revision":1},{"id":"d2a37a35-e1e6-70fe-830c-f1f2a27a6ba6","type":"callout","position":"aq","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Efficient, O(1).","marks":[{"type":"bold"}]},{"type":"text","text":" Instead of removing the head node, "},{"type":"text","text":"copy the second node''s value into it","marks":[{"type":"bold"}]},{"type":"text","text":" and unlink the second node. The head node object survives, so the last node''s back-pointer stays valid without any walk."}]}]}},"revision":1},{"id":"eab0cd55-33c6-79d8-aaec-977ce72f81fa","type":"code","position":"ar","content":{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef delete_head(head):\n    if head is None or head.next == head:   # empty or single node → empty\n        return None\n    head.data = head.next.data               # pull the second value into the head node\n    head.next = head.next.next               # unlink the second node\n    return head\n\ndef print_circular(head):\n    if head is None:\n        print(\"empty\"); return\n    parts, curr = [str(head.data)], head.next\n    while curr != head:\n        parts.append(str(curr.data)); curr = curr.next\n    print(\" -> \".join(parts), f\"-> (back to {head.data})\")\n\nhead = Node(10); head.next = Node(5); head.next.next = Node(20); head.next.next.next = Node(15)\nhead.next.next.next.next = head\nfor _ in range(4):\n    head = delete_head(head)\n    print_circular(head)","filename":"Python"},"revision":1},{"id":"f432d38e-b7ac-78c4-98a6-f7ba0566711e","type":"code","position":"as","content":{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nNode* deleteHead(Node* head) {\n    if (!head) return nullptr;\n    if (head->next == head) { delete head; return nullptr; }   // single node → empty\n    Node* second = head->next;\n    head->data = second->data;               // pull the second value into the head node\n    head->next = second->next;               // unlink the second node\n    delete second;\n    return head;\n}\n\nvoid printCircular(Node* head) {\n    if (!head) { cout << \"empty\\n\"; return; }\n    cout << head->data;\n    for (Node* curr = head->next; curr != head; curr = curr->next) cout << \" -> \" << curr->data;\n    cout << \" -> (back to \" << head->data << \")\\n\";\n}\n\nint main() {\n    Node* head = new Node(10); head->next = new Node(5); head->next->next = new Node(20);\n    head->next->next->next = new Node(15); head->next->next->next->next = head;\n    for (int i = 0; i < 4; i++) {\n        head = deleteHead(head);\n        printCircular(head);\n    }\n}","filename":"C++"},"revision":1},{"id":"610b6e84-7c9b-7b74-bb9d-b83dea1a52c9","type":"code","position":"at","content":{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static Node deleteHead(Node head) {\n        if (head == null || head.next == head) return null;   // empty or single node → empty\n        head.data = head.next.data;              // pull the second value into the head node\n        head.next = head.next.next;              // unlink the second node\n        return head;\n    }\n\n    static void printCircular(Node head) {\n        if (head == null) { System.out.println(\"empty\"); return; }\n        StringBuilder sb = new StringBuilder().append(head.data);\n        for (Node curr = head.next; curr != head; curr = curr.next) sb.append(\" -> \").append(curr.data);\n        System.out.println(sb + \" -> (back to \" + head.data + \")\");\n    }\n\n    public static void main(String[] args) {\n        Node head = new Node(10); head.next = new Node(5); head.next.next = new Node(20);\n        head.next.next.next = new Node(15); head.next.next.next.next = head;\n        for (int i = 0; i < 4; i++) {\n            head = deleteHead(head);\n            printCircular(head);\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"1165af50-97e5-773a-8308-fb3dad19af47","type":"code","position":"au","content":{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction deleteHead(head) {\n    if (head === null || head.next === head) return null;    // empty or single node → empty\n    head.data = head.next.data;                  // pull the second value into the head node\n    head.next = head.next.next;                  // unlink the second node\n    return head;\n}\n\nfunction printCircular(head) {\n    if (head === null) { console.log(\"empty\"); return; }\n    const parts = [head.data];\n    for (let curr = head.next; curr !== head; curr = curr.next) parts.push(curr.data);\n    console.log(parts.join(\" -> \"), `-> (back to ${head.data})`);\n}\n\nlet head = new Node(10); head.next = new Node(5); head.next.next = new Node(20);\nhead.next.next.next = new Node(15); head.next.next.next.next = head;\nfor (let i = 0; i < 4; i++) {\n    head = deleteHead(head);\n    printCircular(head);\n}","filename":"JavaScript"},"revision":1},{"id":"9708112c-5b2d-7683-81ee-3e42bf467a64","type":"code","position":"av","content":{"language":"text","code":"5 -> 20 -> 15 -> (back to 5)\n20 -> 15 -> (back to 20)\n15 -> (back to 15)\nempty","filename":"Output"},"revision":1},{"id":"660aa3bb-cf3a-711d-9160-8e9eef340403","type":"text","position":"aw","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(1) · Space O(1)"}]}]}},"revision":1},{"id":"1cdbdfb9-fd8b-7cd4-922b-570f8b838c86","type":"heading","position":"ax","content":{"level":1,"content":[{"type":"text","text":"Delete the k-th node"}]},"revision":1},{"id":"b8152049-de39-7266-8b6c-70db25b9d9fe","type":"callout","position":"ay","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = 10 -> 5 -> 20 -> 15 (circular), k = 2","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 -> 20 -> 15 -> (back to 10)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"k = 1","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"5 -> 20 -> 15 -> (back to 5)","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"ef0ab233-7617-76d8-b851-ff72743ac48e","type":"callout","position":"az","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"k = 1","marks":[{"type":"code"}]},{"type":"text","text":" is the head — reuse "},{"type":"text","text":"delete_head","marks":[{"type":"code"}]},{"type":"text","text":". Otherwise walk to the "},{"type":"text","text":"(k-1)","marks":[{"type":"code"}]},{"type":"text","text":"-th node, which takes "},{"type":"text","text":"k - 2","marks":[{"type":"code"}]},{"type":"text","text":" steps from the head, and bypass its successor: "},{"type":"text","text":"curr.next = curr.next.next","marks":[{"type":"code"}]},{"type":"text","text":". The circle stays closed because the bypassed node''s "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" is reused."}]}]}},"revision":1},{"id":"b6f96d1d-4e47-7eb7-a87a-9248ed18c9cc","type":"text","position":"b00","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Empty list","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Return "},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"k == 1","marks":[{"type":"code"},{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Return "},{"type":"text","text":"delete_head(head)","marks":[{"type":"code"}]},{"type":"text","text":" — the O(1) version above."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Walk","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"curr = head","marks":[{"type":"code"}]},{"type":"text","text":"; move "},{"type":"text","text":"k - 2","marks":[{"type":"code"}]},{"type":"text","text":" times → "},{"type":"text","text":"curr","marks":[{"type":"code"}]},{"type":"text","text":" is the "},{"type":"text","text":"(k-1)","marks":[{"type":"code"}]},{"type":"text","text":"-th node."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Bypass","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"curr.next = curr.next.next","marks":[{"type":"code"}]},{"type":"text","text":" removes the "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":"-th node."}]}]}]}]}},"revision":1},{"id":"e3093f25-b9ad-7036-a53b-39e934f4f96e","type":"code","position":"b01","content":{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef delete_head(head):\n    if head is None or head.next == head:\n        return None\n    head.data = head.next.data\n    head.next = head.next.next\n    return head\n\ndef delete_kth(head, k):\n    if head is None:\n        return None\n    if k == 1:\n        return delete_head(head)\n    curr = head\n    for _ in range(k - 2):                   # k-2 steps reach the (k-1)-th node\n        curr = curr.next\n    curr.next = curr.next.next               # bypass the k-th node\n    return head\n\ndef print_circular(head):\n    parts, curr = [str(head.data)], head.next\n    while curr != head:\n        parts.append(str(curr.data)); curr = curr.next\n    print(\" -> \".join(parts), f\"-> (back to {head.data})\")\n\nhead = Node(10); head.next = Node(5); head.next.next = Node(20); head.next.next.next = Node(15)\nhead.next.next.next.next = head\nprint_circular(head)\nfor k, label in ((2, \"2nd\"), (3, \"3rd\"), (1, \"1st\")):\n    head = delete_kth(head, k)\n    print(f\"delete {label}: \", end=\"\"); print_circular(head)","filename":"Python"},"revision":1},{"id":"f55d0feb-e44d-76c4-9211-7ef8e8f0edd2","type":"code","position":"b02","content":{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nNode* deleteHead(Node* head) {\n    if (!head) return nullptr;\n    if (head->next == head) { delete head; return nullptr; }\n    Node* second = head->next;\n    head->data = second->data; head->next = second->next;\n    delete second;\n    return head;\n}\n\nNode* deleteKth(Node* head, int k) {\n    if (!head) return nullptr;\n    if (k == 1) return deleteHead(head);\n    Node* curr = head;\n    for (int i = 0; i < k - 2; i++) curr = curr->next;   // k-2 steps reach the (k-1)-th node\n    Node* victim = curr->next;\n    curr->next = victim->next;                           // bypass the k-th node\n    delete victim;\n    return head;\n}\n\nvoid printCircular(Node* head) {\n    cout << head->data;\n    for (Node* curr = head->next; curr != head; curr = curr->next) cout << \" -> \" << curr->data;\n    cout << \" -> (back to \" << head->data << \")\\n\";\n}\n\nint main() {\n    Node* head = new Node(10); head->next = new Node(5); head->next->next = new Node(20);\n    head->next->next->next = new Node(15); head->next->next->next->next = head;\n    printCircular(head);\n    int ks[] = {2, 3, 1}; const char* labels[] = {\"2nd\", \"3rd\", \"1st\"};\n    for (int i = 0; i < 3; i++) {\n        head = deleteKth(head, ks[i]);\n        cout << \"delete \" << labels[i] << \": \"; printCircular(head);\n    }\n}","filename":"C++"},"revision":1},{"id":"7f4dda16-5b5c-7caf-b0b8-747c94f7903c","type":"code","position":"b03","content":{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static Node deleteHead(Node head) {\n        if (head == null || head.next == head) return null;\n        head.data = head.next.data; head.next = head.next.next;\n        return head;\n    }\n\n    static Node deleteKth(Node head, int k) {\n        if (head == null) return null;\n        if (k == 1) return deleteHead(head);\n        Node curr = head;\n        for (int i = 0; i < k - 2; i++) curr = curr.next;   // k-2 steps reach the (k-1)-th node\n        curr.next = curr.next.next;                         // bypass the k-th node\n        return head;\n    }\n\n    static void printCircular(Node head) {\n        StringBuilder sb = new StringBuilder().append(head.data);\n        for (Node curr = head.next; curr != head; curr = curr.next) sb.append(\" -> \").append(curr.data);\n        System.out.println(sb + \" -> (back to \" + head.data + \")\");\n    }\n\n    public static void main(String[] args) {\n        Node head = new Node(10); head.next = new Node(5); head.next.next = new Node(20);\n        head.next.next.next = new Node(15); head.next.next.next.next = head;\n        printCircular(head);\n        int[] ks = {2, 3, 1}; String[] labels = {\"2nd\", \"3rd\", \"1st\"};\n        for (int i = 0; i < 3; i++) {\n            head = deleteKth(head, ks[i]);\n            System.out.print(\"delete \" + labels[i] + \": \"); printCircular(head);\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"3336374e-a5b5-762e-b1fe-0b70b6f75965","type":"code","position":"b04","content":{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction deleteHead(head) {\n    if (head === null || head.next === head) return null;\n    head.data = head.next.data; head.next = head.next.next;\n    return head;\n}\n\nfunction deleteKth(head, k) {\n    if (head === null) return null;\n    if (k === 1) return deleteHead(head);\n    let curr = head;\n    for (let i = 0; i < k - 2; i++) curr = curr.next;   // k-2 steps reach the (k-1)-th node\n    curr.next = curr.next.next;                         // bypass the k-th node\n    return head;\n}\n\nfunction printCircular(head) {\n    const parts = [head.data];\n    for (let curr = head.next; curr !== head; curr = curr.next) parts.push(curr.data);\n    console.log(parts.join(\" -> \"), `-> (back to ${head.data})`);\n}\n\nlet head = new Node(10); head.next = new Node(5); head.next.next = new Node(20);\nhead.next.next.next = new Node(15); head.next.next.next.next = head;\nprintCircular(head);\nfor (const [k, label] of [[2, \"2nd\"], [3, \"3rd\"], [1, \"1st\"]]) {\n    head = deleteKth(head, k);\n    process.stdout.write(`delete ${label}: `); printCircular(head);\n}","filename":"JavaScript"},"revision":1},{"id":"f0e220e9-e134-7f2f-a356-6dd5cbe97c1e","type":"code","position":"b05","content":{"language":"text","code":"10 -> 5 -> 20 -> 15 -> (back to 10)\ndelete 2nd: 10 -> 20 -> 15 -> (back to 10)\ndelete 3rd: 10 -> 20 -> (back to 10)\ndelete 1st: 20 -> (back to 20)","filename":"Output"},"revision":1},{"id":"e9b952ab-fee5-77f6-b718-f0b75408adfe","type":"text","position":"b06","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(k) · Space O(1)"}]}]}},"revision":1},{"id":"db1333a8-c6e1-7319-8b11-42de888ee83b","type":"callout","position":"b07","content":{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The original notes looped "},{"type":"text","text":"for i in range(1, k-2)","marks":[{"type":"code"}]},{"type":"text","text":", which takes "},{"type":"text","text":"k - 3","marks":[{"type":"code"}]},{"type":"text","text":" steps and deletes the wrong node for every "},{"type":"text","text":"k > 2","marks":[{"type":"code"}]},{"type":"text","text":". Count the steps on paper: from node 1, reaching node "},{"type":"text","text":"k-1","marks":[{"type":"code"}]},{"type":"text","text":" is exactly "},{"type":"text","text":"k - 2","marks":[{"type":"code"}]},{"type":"text","text":" hops. The code also assumes "},{"type":"text","text":"k ≤ length","marks":[{"type":"code"}]},{"type":"text","text":"; add a length check (or stop when "},{"type":"text","text":"curr.next == head","marks":[{"type":"code"}]},{"type":"text","text":") for untrusted input."}]}]}},"revision":1},{"id":"e504c8cc-6b02-758d-ae34-01c43a967f72","type":"heading","position":"b08","content":{"level":1,"content":[{"type":"text","text":"Interview Q&A"}]},"revision":1},{"id":"3da4927c-b726-7e32-a6b1-55a2b88e76b8","type":"question","position":"b09","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you detect that a linked list is circular?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Traverse with a "},{"type":"text","text":"fast","marks":[{"type":"code"}]},{"type":"text","text":" pointer moving two steps and a "},{"type":"text","text":"slow","marks":[{"type":"code"}]},{"type":"text","text":" pointer moving one (Floyd''s cycle detection). In a circular list they eventually meet; in a normal list "},{"type":"text","text":"fast","marks":[{"type":"code"}]},{"type":"text","text":" reaches "},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":". O(n) time, O(1) space — a visited-set would also work but costs O(n) memory."}]}]}},"revision":1},{"id":"ad68eb2a-8764-7e7f-b299-3d87ac8e893e","type":"question","position":"b0A","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why keep a tail pointer rather than a head pointer in a circular list?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Because "},{"type":"text","text":"tail.next","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"is","marks":[{"type":"italic"}]},{"type":"text","text":" the head. With the tail you can insert at the front ("},{"type":"text","text":"new.next = tail.next; tail.next = new","marks":[{"type":"code"}]},{"type":"text","text":"), insert at the back (same, then "},{"type":"text","text":"tail = new","marks":[{"type":"code"}]},{"type":"text","text":") and delete the front, all in O(1), without the value-swapping trick. Queues built on circular lists do exactly this."}]}]}},"revision":1},{"id":"ae26c161-1456-7c7d-9f9d-8074ce168963","type":"question","position":"b0B","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Where are circular linked lists used in practice?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Round-robin CPU scheduling, turn order in games, circular buffers for streaming data, Fibonacci heaps (the root list is circular doubly linked), and the Josephus problem — every k-th person around a circle is eliminated until one remains."}]}]}},"revision":1},{"id":"6df75917-39f3-74cd-a681-49abcc4924f2","type":"question","position":"b0C","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What goes wrong if you forget the single-node case?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A one-node circular list has "},{"type":"text","text":"head.next == head","marks":[{"type":"code"}]},{"type":"text","text":". A "},{"type":"text","text":"delete_head","marks":[{"type":"code"}]},{"type":"text","text":" that does "},{"type":"text","text":"head.next = head.next.next","marks":[{"type":"code"}]},{"type":"text","text":" would leave the node pointing at itself and return it — the list never becomes empty. Always test the empty, one-node and two-node lists."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = 'ff7fcd47-1dc4-726e-a6a4-c5f556ff5ad6' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
ON CONFLICT DO NOTHING;

INSERT INTO "notes"."Card" ("id", "noteId", "position", "type", "content", "revision", "createdAt", "updatedAt")
SELECT c.id::uuid, 'ff7fcd47-1dc4-726e-a6a4-c5f556ff5ad6', c.position, c.type::"notes"."CardType", c.content::jsonb, 1, TIMESTAMPTZ '2026-10-07 03:23:53+00', TIMESTAMPTZ '2026-10-07 03:23:53+00'
FROM (VALUES
  ('b1b60f09-2195-746f-96a5-f52f1d6fb757', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A circular linked list is a singly linked list whose "},{"type":"text","text":"last node points back to the head","marks":[{"type":"bold"}]},{"type":"text","text":" instead of to "},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":". There is no end, so the list can be traversed from any node, and keeping a single pointer gives O(1) access to both the first and the last element."}]}]}}'),
  ('c2ce39ed-5b91-7c82-b076-5d8730be09e3', 'a1', 'callout', '{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Circular linked list","marks":[{"type":"bold"}]},{"type":"text","text":" — a linked list in which the "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" of the last node refers to the first node. A one-node list points to itself. Traversal stops when we return to the node where we started, not when "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":" — because it never is."}]}]}}'),
  ('c9a93f5d-0f53-77d5-96bf-d00ab1521e99', 'a2', 'code', '{"language":"text","code":"head\n ↓\n┌──────┬────┐    ┌──────┬────┐    ┌──────┬────┐    ┌──────┬────┐\n│  10  │ ●──┼───▶│   5  │ ●──┼───▶│  20  │ ●──┼───▶│  15  │ ●──┼──┐\n└──────┴────┘    └──────┴────┘    └──────┴────┘    └──────┴────┘  │\n  ▲                                                               │\n  └───────────────────────────────────────────────────────────────┘\n                the last node links back to the head","filename":"10 → 5 → 20 → 15 → back to 10"}'),
  ('8f37bd5d-3085-7e75-b383-a311ee11842b', 'a3', 'heading', '{"level":1,"content":[{"type":"text","text":"Building and traversing"}]}'),
  ('b51c7baf-9e84-7578-9d4f-2c82157524b9', 'a4', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The nodes are the same as in a singly linked list; only the last link differs. Traversal must "},{"type":"text","text":"stop when it comes back to the head","marks":[{"type":"bold"}]},{"type":"text","text":", so the loop prints the head first and then walks until "},{"type":"text","text":"curr == head","marks":[{"type":"code"}]},{"type":"text","text":" again. A "},{"type":"text","text":"while curr.next != head","marks":[{"type":"code"}]},{"type":"text","text":" loop (as in the original notes) also works but needs the last node printed separately."}]}]}}'),
  ('0af73eb2-3c68-7ce5-9637-c6a565d65c86', 'a5', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef print_circular(head):\n    if head is None:\n        print(\"empty\")\n        return\n    parts = [str(head.data)]\n    curr = head.next\n    while curr != head:              # stop when we are back at the start\n        parts.append(str(curr.data))\n        curr = curr.next\n    print(\" -> \".join(parts), f\"-> (back to {head.data})\")\n\nhead = Node(10)\nhead.next = Node(5)\nhead.next.next = Node(20)\nhead.next.next.next = Node(15)\nhead.next.next.next.next = head      # close the circle\nprint_circular(head)","filename":"Python"}'),
  ('f6d849d9-220b-7b8f-ba05-69a5578f0bfa', 'a6', 'code', '{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nvoid printCircular(Node* head) {\n    if (!head) { cout << \"empty\\n\"; return; }\n    cout << head->data;\n    for (Node* curr = head->next; curr != head; curr = curr->next)   // stop when back at the start\n        cout << \" -> \" << curr->data;\n    cout << \" -> (back to \" << head->data << \")\\n\";\n}\n\nint main() {\n    Node* head = new Node(10);\n    head->next = new Node(5);\n    head->next->next = new Node(20);\n    head->next->next->next = new Node(15);\n    head->next->next->next->next = head;    // close the circle\n    printCircular(head);\n}","filename":"C++"}'),
  ('94901317-72e7-7dc8-9d1e-66620d241031', 'a7', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static void printCircular(Node head) {\n        if (head == null) { System.out.println(\"empty\"); return; }\n        StringBuilder sb = new StringBuilder().append(head.data);\n        for (Node curr = head.next; curr != head; curr = curr.next)   // stop when back at the start\n            sb.append(\" -> \").append(curr.data);\n        System.out.println(sb + \" -> (back to \" + head.data + \")\");\n    }\n\n    public static void main(String[] args) {\n        Node head = new Node(10);\n        head.next = new Node(5);\n        head.next.next = new Node(20);\n        head.next.next.next = new Node(15);\n        head.next.next.next.next = head;    // close the circle\n        printCircular(head);\n    }\n}","filename":"Java"}'),
  ('e2ec9b4d-0970-7879-bc65-b830bd4ee045', 'a8', 'code', '{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction printCircular(head) {\n    if (head === null) { console.log(\"empty\"); return; }\n    const parts = [head.data];\n    for (let curr = head.next; curr !== head; curr = curr.next)   // stop when back at the start\n        parts.push(curr.data);\n    console.log(parts.join(\" -> \"), `-> (back to ${head.data})`);\n}\n\nconst head = new Node(10);\nhead.next = new Node(5);\nhead.next.next = new Node(20);\nhead.next.next.next = new Node(15);\nhead.next.next.next.next = head;        // close the circle\nprintCircular(head);","filename":"JavaScript"}'),
  ('5e754619-5153-7bc8-bb2a-f701c25a15c5', 'a9', 'code', '{"language":"text","code":"10 -> 5 -> 20 -> 15 -> (back to 10)","filename":"Output"}'),
  ('a5010df4-1a98-762c-979c-f12935e68d14', 'aA', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) traversal · Space O(1)"}]}]}}'),
  ('37b70512-c800-71fc-84aa-854be67a7c4b', 'aB', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"while curr is not None","marks":[{"type":"code"}]},{"type":"text","text":" loop never terminates on a circular list. Every traversal must remember where it started and stop there."}]}]}}'),
  ('02bae07a-0511-74db-92e6-389fbca84099', 'aC', 'heading', '{"level":1,"content":[{"type":"text","text":"Advantages and disadvantages"}]}'),
  ('584a69af-1f76-74c9-aebb-7a5c3e57ce46', 'aD', 'callout', '{"variant":"note","title":"Traverse from any node","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Starting anywhere, following "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" visits every node — no need to find the head first."}]}]}}'),
  ('b79b88ad-e7a5-7daf-af33-3324869f662c', 'aE', 'callout', '{"variant":"note","title":"Round-robin scheduling","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The OS gives each process a time slice and moves to "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":"; after the last process comes the first again. Also: multiplayer turns, circular buffers, music playlists on repeat."}]}]}}'),
  ('81dfdcf3-86eb-73c4-a90b-d4f71ee98d65', 'aF', 'callout', '{"variant":"note","title":"O(1) at both ends with one pointer","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Keep a reference to the "},{"type":"text","text":"tail","marks":[{"type":"bold"}]},{"type":"text","text":": the head is "},{"type":"text","text":"tail.next","marks":[{"type":"code"}]},{"type":"text","text":", so insert at the beginning, insert at the end and delete the head are all O(1)."}]}]}}'),
  ('a0002803-4d53-7d2a-931a-4601460b6369', 'aG', 'callout', '{"variant":"note","title":"More complex code","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every operation must handle the empty list, the one-node list (which points at itself) and the wrap-around; an off-by-one gives an infinite loop instead of a crash."}]}]}}'),
  ('39273334-6c2c-7d64-8d53-0275a0ab8f2b', 'aH', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Operation (holding "},{"type":"text","text":"head","marks":[{"type":"code"}]},{"type":"text","text":" only)"}],[{"type":"text","text":"Naive"}],[{"type":"text","text":"Efficient trick"}],[{"type":"text","text":"Holding "},{"type":"text","text":"tail","marks":[{"type":"code"}]},{"type":"text","text":" instead"}]],[[{"type":"text","text":"Insert at beginning"}],[{"type":"text","text":"O(n): walk to the last node to fix its "},{"type":"text","text":"next","marks":[{"type":"code"}]}],[{"type":"text","text":"O(1): insert "},{"type":"text","text":"after","marks":[{"type":"italic"}]},{"type":"text","text":" head and swap data"}],[{"type":"text","text":"O(1)"}]],[[{"type":"text","text":"Insert at end"}],[{"type":"text","text":"O(n): walk to the last node"}],[{"type":"text","text":"O(1): same trick, return the new node as head"}],[{"type":"text","text":"O(1)"}]],[[{"type":"text","text":"Delete head"}],[{"type":"text","text":"O(n): walk to the last node to re-point it"}],[{"type":"text","text":"O(1): copy "},{"type":"text","text":"head.next","marks":[{"type":"code"}]},{"type":"text","text":" into head and unlink "},{"type":"text","text":"head.next","marks":[{"type":"code"}]}],[{"type":"text","text":"O(1)"}]],[[{"type":"text","text":"Delete k-th node"}],[{"type":"text","text":"O(k)"}],[{"type":"text","text":"—"}],[{"type":"text","text":"O(k)"}]],[[{"type":"text","text":"Search"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"—"}],[{"type":"text","text":"O(n)"}]]]}'),
  ('7da8b1ec-d0c3-7562-840e-9cdbf0e284c7', 'aI', 'heading', '{"level":1,"content":[{"type":"text","text":"Insert at the beginning"}]}'),
  ('7be2bfc9-29eb-7dda-aead-c68174f9b485', 'aJ', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = 10 -> 5 -> 20 -> 15 (circular), insert 25 at the beginning","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"25 -> 10 -> 5 -> 20 -> 15 -> (back to 25)","marks":[{"type":"code"}]}]}]}}'),
  ('f8949a68-00c1-7299-8457-775385e9d463', 'aK', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Naive, O(n).","marks":[{"type":"bold"}]},{"type":"text","text":" The last node must point at the new head, and the only way to reach the last node is to walk the whole circle."}]}]}}'),
  ('26f84fc6-2797-710e-8c5b-c853adde948d', 'aL', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef insert_beginning_naive(head, x):\n    temp = Node(x)\n    if head is None:\n        temp.next = temp               # one node points at itself\n        return temp\n    curr = head\n    while curr.next != head:           # O(n) walk to the last node\n        curr = curr.next\n    curr.next = temp                   # last node → new node\n    temp.next = head                   # new node → old head\n    return temp\n\ndef print_circular(head):\n    parts, curr = [str(head.data)], head.next\n    while curr != head:\n        parts.append(str(curr.data)); curr = curr.next\n    print(\" -> \".join(parts), f\"-> (back to {head.data})\")\n\nhead = Node(10); head.next = Node(5); head.next.next = Node(20); head.next.next.next = Node(15)\nhead.next.next.next.next = head\nhead = insert_beginning_naive(head, 25)\nprint_circular(head)","filename":"Python"}'),
  ('a1c21f09-c09a-7f8d-a294-b984e60b30b9', 'aM', 'code', '{"language":"text","code":"25 -> 10 -> 5 -> 20 -> 15 -> (back to 25)","filename":"Output"}'),
  ('0de3e984-d200-7561-be21-d726355893c8', 'aN', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(1)"}]}]}}'),
  ('af11ae1d-9a1c-7e4a-9cdd-2193e284b55e', 'aO', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Efficient, O(1).","marks":[{"type":"bold"}]},{"type":"text","text":" Insert the new node "},{"type":"text","text":"right after","marks":[{"type":"italic"}]},{"type":"text","text":" the head (two pointer changes — no walk) and then "},{"type":"text","text":"swap the data","marks":[{"type":"bold"}]},{"type":"text","text":" of the head and the new node. The head node now carries the new value and the old head value sits in second position: exactly the result of inserting at the front. The head reference does not even change."}]}]}}'),
  ('eaf53978-07b1-70ba-81b4-b021cd9bd9e1', 'aP', 'code', '{"language":"text","code":"before:          head ──▶ [10] ──▶ [5] ──▶ [20] ──▶ [15] ──▶ back to 10\ninsert after head:   head ──▶ [10] ──▶ [25] ──▶ [5] ──▶ [20] ──▶ [15] ──▶ back to 10\nswap data:           head ──▶ [25] ──▶ [10] ──▶ [5] ──▶ [20] ──▶ [15] ──▶ back to 25","filename":"Insert at the beginning in O(1): insert after the head, then swap the two values"}'),
  ('ca5bd19a-b3e0-7d5d-b688-7264fd9bb9dc', 'aQ', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef insert_beginning(head, x):\n    temp = Node(x)\n    if head is None:\n        temp.next = temp                             # one node points at itself\n        return temp\n    temp.next = head.next                            # insert temp right after head\n    head.next = temp\n    head.data, temp.data = temp.data, head.data      # swap values: head now holds x\n    return head\n\ndef print_circular(head):\n    parts, curr = [str(head.data)], head.next\n    while curr != head:\n        parts.append(str(curr.data)); curr = curr.next\n    print(\" -> \".join(parts), f\"-> (back to {head.data})\")\n\nhead = Node(10); head.next = Node(5); head.next.next = Node(20); head.next.next.next = Node(15)\nhead.next.next.next.next = head\nhead = insert_beginning(head, 25); print_circular(head)\nhead = insert_beginning(head, 30); print_circular(head)","filename":"Python"}'),
  ('5280ae1e-7970-7e9a-9590-92213e6f670a', 'aR', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <utility>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nNode* insertBeginning(Node* head, int x) {\n    Node* temp = new Node(x);\n    if (!head) { temp->next = temp; return temp; }   // one node points at itself\n    temp->next = head->next;                         // insert temp right after head\n    head->next = temp;\n    swap(head->data, temp->data);                    // swap values: head now holds x\n    return head;\n}\n\nvoid printCircular(Node* head) {\n    cout << head->data;\n    for (Node* curr = head->next; curr != head; curr = curr->next) cout << \" -> \" << curr->data;\n    cout << \" -> (back to \" << head->data << \")\\n\";\n}\n\nint main() {\n    Node* head = new Node(10); head->next = new Node(5); head->next->next = new Node(20);\n    head->next->next->next = new Node(15); head->next->next->next->next = head;\n    head = insertBeginning(head, 25); printCircular(head);\n    head = insertBeginning(head, 30); printCircular(head);\n}","filename":"C++"}'),
  ('df435b14-f210-7e1c-98dd-2130fb6d7b1b', 'aS', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static Node insertBeginning(Node head, int x) {\n        Node temp = new Node(x);\n        if (head == null) { temp.next = temp; return temp; }   // one node points at itself\n        temp.next = head.next;                                  // insert temp right after head\n        head.next = temp;\n        int t = head.data; head.data = temp.data; temp.data = t; // swap values: head now holds x\n        return head;\n    }\n\n    static void printCircular(Node head) {\n        StringBuilder sb = new StringBuilder().append(head.data);\n        for (Node curr = head.next; curr != head; curr = curr.next) sb.append(\" -> \").append(curr.data);\n        System.out.println(sb + \" -> (back to \" + head.data + \")\");\n    }\n\n    public static void main(String[] args) {\n        Node head = new Node(10); head.next = new Node(5); head.next.next = new Node(20);\n        head.next.next.next = new Node(15); head.next.next.next.next = head;\n        head = insertBeginning(head, 25); printCircular(head);\n        head = insertBeginning(head, 30); printCircular(head);\n    }\n}","filename":"Java"}'),
  ('3809b15a-2a0c-73f5-83b6-0705a1ba6a5d', 'aT', 'code', '{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction insertBeginning(head, x) {\n    const temp = new Node(x);\n    if (head === null) { temp.next = temp; return temp; }   // one node points at itself\n    temp.next = head.next;                                   // insert temp right after head\n    head.next = temp;\n    [head.data, temp.data] = [temp.data, head.data];         // swap values: head now holds x\n    return head;\n}\n\nfunction printCircular(head) {\n    const parts = [head.data];\n    for (let curr = head.next; curr !== head; curr = curr.next) parts.push(curr.data);\n    console.log(parts.join(\" -> \"), `-> (back to ${head.data})`);\n}\n\nlet head = new Node(10); head.next = new Node(5); head.next.next = new Node(20);\nhead.next.next.next = new Node(15); head.next.next.next.next = head;\nhead = insertBeginning(head, 25); printCircular(head);\nhead = insertBeginning(head, 30); printCircular(head);","filename":"JavaScript"}'),
  ('f0b4f160-2e00-7bfe-a31e-fa6580684d45', 'aU', 'code', '{"language":"text","code":"25 -> 10 -> 5 -> 20 -> 15 -> (back to 25)\n30 -> 25 -> 10 -> 5 -> 20 -> 15 -> (back to 30)","filename":"Output"}'),
  ('c9919c7a-e624-76ed-93b4-5f19c5358deb', 'aV', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(1) · Space O(1)"}]}]}}'),
  ('a8e7b663-aa6d-745e-82c7-5e589a854562', 'aW', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The swap trick moves a "},{"type":"text","text":"value","marks":[{"type":"italic"}]},{"type":"text","text":" into a different node. If other code holds references to specific nodes (or the data is large/expensive to copy), use the tail-pointer design instead: with "},{"type":"text","text":"tail","marks":[{"type":"code"}]},{"type":"text","text":" known, "},{"type":"text","text":"head = tail.next","marks":[{"type":"code"}]},{"type":"text","text":" and both ends are O(1) without any swapping."}]}]}}'),
  ('b89c666f-a477-7f84-93ca-07b5d5a6e665', 'aX', 'heading', '{"level":1,"content":[{"type":"text","text":"Insert at the end"}]}'),
  ('5db0425a-1744-7570-b5a9-9af25f8ecf02', 'aY', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = 10 -> 5 -> 20 -> 15 (circular), insert 35 at the end","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 -> 5 -> 20 -> 15 -> 35 -> (back to 10)","marks":[{"type":"code"}]}]}]}}'),
  ('2b49be86-07f5-715b-99da-2978020f5d88', 'aZ', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Naive, O(n).","marks":[{"type":"bold"}]},{"type":"text","text":" Walk to the last node, link it to the new node and link the new node back to the head."}]}]}}'),
  ('609bc93e-5711-79b3-a0cf-6642a853ed44', 'aa', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef insert_end_naive(head, x):\n    temp = Node(x)\n    if head is None:\n        temp.next = temp\n        return temp\n    curr = head\n    while curr.next != head:           # O(n) walk to the last node\n        curr = curr.next\n    curr.next = temp                   # last → new\n    temp.next = head                   # new → head\n    return head\n\ndef print_circular(head):\n    parts, curr = [str(head.data)], head.next\n    while curr != head:\n        parts.append(str(curr.data)); curr = curr.next\n    print(\" -> \".join(parts), f\"-> (back to {head.data})\")\n\nhead = Node(10); head.next = Node(5); head.next.next = Node(20); head.next.next.next = Node(15)\nhead.next.next.next.next = head\nhead = insert_end_naive(head, 35)\nprint_circular(head)","filename":"Python"}'),
  ('d405b294-fc89-720b-b263-a8221d1006fd', 'ab', 'code', '{"language":"text","code":"10 -> 5 -> 20 -> 15 -> 35 -> (back to 10)","filename":"Output"}'),
  ('a6f6a180-5329-71e4-8538-17c7f20db90b', 'ac', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(1)"}]}]}}'),
  ('4a9da999-84ca-774c-8423-97f6f8dfc225', 'ad', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Efficient, O(1).","marks":[{"type":"bold"}]},{"type":"text","text":" Same trick as before — insert the new node after the head and swap the values — but now "},{"type":"text","text":"return the new node as the head","marks":[{"type":"bold"}]},{"type":"text","text":". Reading the circle from that node gives the old sequence first and the new value last: the head node (which now holds "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":") comes just before it."}]}]}}'),
  ('fc583264-3bef-7999-a210-b634402e24d3', 'ae', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef insert_end(head, x):\n    temp = Node(x)\n    if head is None:\n        temp.next = temp\n        return temp\n    temp.next = head.next                            # insert temp right after head\n    head.next = temp\n    head.data, temp.data = temp.data, head.data      # old head value moves to temp\n    return temp                                      # temp is the new head; x sits just before it\n\ndef print_circular(head):\n    parts, curr = [str(head.data)], head.next\n    while curr != head:\n        parts.append(str(curr.data)); curr = curr.next\n    print(\" -> \".join(parts), f\"-> (back to {head.data})\")\n\nhead = Node(10); head.next = Node(5); head.next.next = Node(20); head.next.next.next = Node(15)\nhead.next.next.next.next = head\nhead = insert_end(head, 35); print_circular(head)\nhead = insert_end(head, 40); print_circular(head)","filename":"Python"}'),
  ('dbc4d4f4-9af9-7469-bffc-cb059fa13f09', 'af', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <utility>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nNode* insertEnd(Node* head, int x) {\n    Node* temp = new Node(x);\n    if (!head) { temp->next = temp; return temp; }\n    temp->next = head->next;                         // insert temp right after head\n    head->next = temp;\n    swap(head->data, temp->data);                    // old head value moves to temp\n    return temp;                                     // temp is the new head; x sits just before it\n}\n\nvoid printCircular(Node* head) {\n    cout << head->data;\n    for (Node* curr = head->next; curr != head; curr = curr->next) cout << \" -> \" << curr->data;\n    cout << \" -> (back to \" << head->data << \")\\n\";\n}\n\nint main() {\n    Node* head = new Node(10); head->next = new Node(5); head->next->next = new Node(20);\n    head->next->next->next = new Node(15); head->next->next->next->next = head;\n    head = insertEnd(head, 35); printCircular(head);\n    head = insertEnd(head, 40); printCircular(head);\n}","filename":"C++"}'),
  ('4aaa20d5-bf1d-777f-b221-9b7d65288c01', 'ag', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static Node insertEnd(Node head, int x) {\n        Node temp = new Node(x);\n        if (head == null) { temp.next = temp; return temp; }\n        temp.next = head.next;                                   // insert temp right after head\n        head.next = temp;\n        int t = head.data; head.data = temp.data; temp.data = t;  // old head value moves to temp\n        return temp;                                             // temp is the new head; x sits just before it\n    }\n\n    static void printCircular(Node head) {\n        StringBuilder sb = new StringBuilder().append(head.data);\n        for (Node curr = head.next; curr != head; curr = curr.next) sb.append(\" -> \").append(curr.data);\n        System.out.println(sb + \" -> (back to \" + head.data + \")\");\n    }\n\n    public static void main(String[] args) {\n        Node head = new Node(10); head.next = new Node(5); head.next.next = new Node(20);\n        head.next.next.next = new Node(15); head.next.next.next.next = head;\n        head = insertEnd(head, 35); printCircular(head);\n        head = insertEnd(head, 40); printCircular(head);\n    }\n}","filename":"Java"}'),
  ('c4a11dda-f314-788f-8f5b-aeb2bca3dc87', 'ah', 'code', '{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction insertEnd(head, x) {\n    const temp = new Node(x);\n    if (head === null) { temp.next = temp; return temp; }\n    temp.next = head.next;                                   // insert temp right after head\n    head.next = temp;\n    [head.data, temp.data] = [temp.data, head.data];         // old head value moves to temp\n    return temp;                                             // temp is the new head; x sits just before it\n}\n\nfunction printCircular(head) {\n    const parts = [head.data];\n    for (let curr = head.next; curr !== head; curr = curr.next) parts.push(curr.data);\n    console.log(parts.join(\" -> \"), `-> (back to ${head.data})`);\n}\n\nlet head = new Node(10); head.next = new Node(5); head.next.next = new Node(20);\nhead.next.next.next = new Node(15); head.next.next.next.next = head;\nhead = insertEnd(head, 35); printCircular(head);\nhead = insertEnd(head, 40); printCircular(head);","filename":"JavaScript"}'),
  ('af1492b1-2c39-7311-85f3-36b803ccbc36', 'ai', 'code', '{"language":"text","code":"10 -> 5 -> 20 -> 15 -> 35 -> (back to 10)\n10 -> 5 -> 20 -> 15 -> 35 -> 40 -> (back to 10)","filename":"Output"}'),
  ('9075ed5e-3425-7ea3-aa34-79492ed16e66', 'aj', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(1) · Space O(1)"}]}]}}'),
  ('d51e0f0a-54d4-795d-bba3-f9e349967c30', 'ak', 'heading', '{"level":1,"content":[{"type":"text","text":"Delete the head"}]}'),
  ('fbf2f38e-5fef-7ef6-9943-f2cdf72c2fb8', 'al', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = 10 -> 5 -> 20 -> 15 (circular)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"5 -> 20 -> 15 -> (back to 5)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = 10 (one node)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"empty","marks":[{"type":"code"}]}]}]}}'),
  ('38b2aa92-a6ee-7420-acb4-71fe1eeeb69d', 'am', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Naive, O(n).","marks":[{"type":"bold"}]},{"type":"text","text":" The last node points at the head, so after removing the head the last node must be found and re-pointed at the second node — a full walk."}]}]}}'),
  ('36a10c78-a1c0-746d-9268-aa79c240ae50', 'an', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef delete_head_naive(head):\n    if head is None or head.next == head:   # empty or single node → empty\n        return None\n    curr = head\n    while curr.next != head:                # O(n) walk to the last node\n        curr = curr.next\n    curr.next = head.next                   # last → second node\n    return curr.next                        # second node is the new head\n\ndef print_circular(head):\n    parts, curr = [str(head.data)], head.next\n    while curr != head:\n        parts.append(str(curr.data)); curr = curr.next\n    print(\" -> \".join(parts), f\"-> (back to {head.data})\")\n\nhead = Node(10); head.next = Node(5); head.next.next = Node(20); head.next.next.next = Node(15)\nhead.next.next.next.next = head\nhead = delete_head_naive(head)\nprint_circular(head)","filename":"Python"}'),
  ('0b9a26c8-5a34-707d-b34f-3f57515a9c84', 'ao', 'code', '{"language":"text","code":"5 -> 20 -> 15 -> (back to 5)","filename":"Output"}'),
  ('ca769a18-d9b9-7451-a579-6f2e26a134a6', 'ap', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(1)"}]}]}}'),
  ('d2a37a35-e1e6-70fe-830c-f1f2a27a6ba6', 'aq', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Efficient, O(1).","marks":[{"type":"bold"}]},{"type":"text","text":" Instead of removing the head node, "},{"type":"text","text":"copy the second node''s value into it","marks":[{"type":"bold"}]},{"type":"text","text":" and unlink the second node. The head node object survives, so the last node''s back-pointer stays valid without any walk."}]}]}}'),
  ('eab0cd55-33c6-79d8-aaec-977ce72f81fa', 'ar', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef delete_head(head):\n    if head is None or head.next == head:   # empty or single node → empty\n        return None\n    head.data = head.next.data               # pull the second value into the head node\n    head.next = head.next.next               # unlink the second node\n    return head\n\ndef print_circular(head):\n    if head is None:\n        print(\"empty\"); return\n    parts, curr = [str(head.data)], head.next\n    while curr != head:\n        parts.append(str(curr.data)); curr = curr.next\n    print(\" -> \".join(parts), f\"-> (back to {head.data})\")\n\nhead = Node(10); head.next = Node(5); head.next.next = Node(20); head.next.next.next = Node(15)\nhead.next.next.next.next = head\nfor _ in range(4):\n    head = delete_head(head)\n    print_circular(head)","filename":"Python"}'),
  ('f432d38e-b7ac-78c4-98a6-f7ba0566711e', 'as', 'code', '{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nNode* deleteHead(Node* head) {\n    if (!head) return nullptr;\n    if (head->next == head) { delete head; return nullptr; }   // single node → empty\n    Node* second = head->next;\n    head->data = second->data;               // pull the second value into the head node\n    head->next = second->next;               // unlink the second node\n    delete second;\n    return head;\n}\n\nvoid printCircular(Node* head) {\n    if (!head) { cout << \"empty\\n\"; return; }\n    cout << head->data;\n    for (Node* curr = head->next; curr != head; curr = curr->next) cout << \" -> \" << curr->data;\n    cout << \" -> (back to \" << head->data << \")\\n\";\n}\n\nint main() {\n    Node* head = new Node(10); head->next = new Node(5); head->next->next = new Node(20);\n    head->next->next->next = new Node(15); head->next->next->next->next = head;\n    for (int i = 0; i < 4; i++) {\n        head = deleteHead(head);\n        printCircular(head);\n    }\n}","filename":"C++"}'),
  ('610b6e84-7c9b-7b74-bb9d-b83dea1a52c9', 'at', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static Node deleteHead(Node head) {\n        if (head == null || head.next == head) return null;   // empty or single node → empty\n        head.data = head.next.data;              // pull the second value into the head node\n        head.next = head.next.next;              // unlink the second node\n        return head;\n    }\n\n    static void printCircular(Node head) {\n        if (head == null) { System.out.println(\"empty\"); return; }\n        StringBuilder sb = new StringBuilder().append(head.data);\n        for (Node curr = head.next; curr != head; curr = curr.next) sb.append(\" -> \").append(curr.data);\n        System.out.println(sb + \" -> (back to \" + head.data + \")\");\n    }\n\n    public static void main(String[] args) {\n        Node head = new Node(10); head.next = new Node(5); head.next.next = new Node(20);\n        head.next.next.next = new Node(15); head.next.next.next.next = head;\n        for (int i = 0; i < 4; i++) {\n            head = deleteHead(head);\n            printCircular(head);\n        }\n    }\n}","filename":"Java"}'),
  ('1165af50-97e5-773a-8308-fb3dad19af47', 'au', 'code', '{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction deleteHead(head) {\n    if (head === null || head.next === head) return null;    // empty or single node → empty\n    head.data = head.next.data;                  // pull the second value into the head node\n    head.next = head.next.next;                  // unlink the second node\n    return head;\n}\n\nfunction printCircular(head) {\n    if (head === null) { console.log(\"empty\"); return; }\n    const parts = [head.data];\n    for (let curr = head.next; curr !== head; curr = curr.next) parts.push(curr.data);\n    console.log(parts.join(\" -> \"), `-> (back to ${head.data})`);\n}\n\nlet head = new Node(10); head.next = new Node(5); head.next.next = new Node(20);\nhead.next.next.next = new Node(15); head.next.next.next.next = head;\nfor (let i = 0; i < 4; i++) {\n    head = deleteHead(head);\n    printCircular(head);\n}","filename":"JavaScript"}'),
  ('9708112c-5b2d-7683-81ee-3e42bf467a64', 'av', 'code', '{"language":"text","code":"5 -> 20 -> 15 -> (back to 5)\n20 -> 15 -> (back to 20)\n15 -> (back to 15)\nempty","filename":"Output"}'),
  ('660aa3bb-cf3a-711d-9160-8e9eef340403', 'aw', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(1) · Space O(1)"}]}]}}'),
  ('1cdbdfb9-fd8b-7cd4-922b-570f8b838c86', 'ax', 'heading', '{"level":1,"content":[{"type":"text","text":"Delete the k-th node"}]}'),
  ('b8152049-de39-7266-8b6c-70db25b9d9fe', 'ay', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = 10 -> 5 -> 20 -> 15 (circular), k = 2","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 -> 20 -> 15 -> (back to 10)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"k = 1","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"5 -> 20 -> 15 -> (back to 5)","marks":[{"type":"code"}]}]}]}}'),
  ('ef0ab233-7617-76d8-b851-ff72743ac48e', 'az', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"k = 1","marks":[{"type":"code"}]},{"type":"text","text":" is the head — reuse "},{"type":"text","text":"delete_head","marks":[{"type":"code"}]},{"type":"text","text":". Otherwise walk to the "},{"type":"text","text":"(k-1)","marks":[{"type":"code"}]},{"type":"text","text":"-th node, which takes "},{"type":"text","text":"k - 2","marks":[{"type":"code"}]},{"type":"text","text":" steps from the head, and bypass its successor: "},{"type":"text","text":"curr.next = curr.next.next","marks":[{"type":"code"}]},{"type":"text","text":". The circle stays closed because the bypassed node''s "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" is reused."}]}]}}'),
  ('b6f96d1d-4e47-7eb7-a87a-9248ed18c9cc', 'b00', 'text', '{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Empty list","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Return "},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"k == 1","marks":[{"type":"code"},{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Return "},{"type":"text","text":"delete_head(head)","marks":[{"type":"code"}]},{"type":"text","text":" — the O(1) version above."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Walk","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"curr = head","marks":[{"type":"code"}]},{"type":"text","text":"; move "},{"type":"text","text":"k - 2","marks":[{"type":"code"}]},{"type":"text","text":" times → "},{"type":"text","text":"curr","marks":[{"type":"code"}]},{"type":"text","text":" is the "},{"type":"text","text":"(k-1)","marks":[{"type":"code"}]},{"type":"text","text":"-th node."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Bypass","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"curr.next = curr.next.next","marks":[{"type":"code"}]},{"type":"text","text":" removes the "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":"-th node."}]}]}]}]}}'),
  ('e3093f25-b9ad-7036-a53b-39e934f4f96e', 'b01', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef delete_head(head):\n    if head is None or head.next == head:\n        return None\n    head.data = head.next.data\n    head.next = head.next.next\n    return head\n\ndef delete_kth(head, k):\n    if head is None:\n        return None\n    if k == 1:\n        return delete_head(head)\n    curr = head\n    for _ in range(k - 2):                   # k-2 steps reach the (k-1)-th node\n        curr = curr.next\n    curr.next = curr.next.next               # bypass the k-th node\n    return head\n\ndef print_circular(head):\n    parts, curr = [str(head.data)], head.next\n    while curr != head:\n        parts.append(str(curr.data)); curr = curr.next\n    print(\" -> \".join(parts), f\"-> (back to {head.data})\")\n\nhead = Node(10); head.next = Node(5); head.next.next = Node(20); head.next.next.next = Node(15)\nhead.next.next.next.next = head\nprint_circular(head)\nfor k, label in ((2, \"2nd\"), (3, \"3rd\"), (1, \"1st\")):\n    head = delete_kth(head, k)\n    print(f\"delete {label}: \", end=\"\"); print_circular(head)","filename":"Python"}'),
  ('f55d0feb-e44d-76c4-9211-7ef8e8f0edd2', 'b02', 'code', '{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nNode* deleteHead(Node* head) {\n    if (!head) return nullptr;\n    if (head->next == head) { delete head; return nullptr; }\n    Node* second = head->next;\n    head->data = second->data; head->next = second->next;\n    delete second;\n    return head;\n}\n\nNode* deleteKth(Node* head, int k) {\n    if (!head) return nullptr;\n    if (k == 1) return deleteHead(head);\n    Node* curr = head;\n    for (int i = 0; i < k - 2; i++) curr = curr->next;   // k-2 steps reach the (k-1)-th node\n    Node* victim = curr->next;\n    curr->next = victim->next;                           // bypass the k-th node\n    delete victim;\n    return head;\n}\n\nvoid printCircular(Node* head) {\n    cout << head->data;\n    for (Node* curr = head->next; curr != head; curr = curr->next) cout << \" -> \" << curr->data;\n    cout << \" -> (back to \" << head->data << \")\\n\";\n}\n\nint main() {\n    Node* head = new Node(10); head->next = new Node(5); head->next->next = new Node(20);\n    head->next->next->next = new Node(15); head->next->next->next->next = head;\n    printCircular(head);\n    int ks[] = {2, 3, 1}; const char* labels[] = {\"2nd\", \"3rd\", \"1st\"};\n    for (int i = 0; i < 3; i++) {\n        head = deleteKth(head, ks[i]);\n        cout << \"delete \" << labels[i] << \": \"; printCircular(head);\n    }\n}","filename":"C++"}'),
  ('7f4dda16-5b5c-7caf-b0b8-747c94f7903c', 'b03', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static Node deleteHead(Node head) {\n        if (head == null || head.next == head) return null;\n        head.data = head.next.data; head.next = head.next.next;\n        return head;\n    }\n\n    static Node deleteKth(Node head, int k) {\n        if (head == null) return null;\n        if (k == 1) return deleteHead(head);\n        Node curr = head;\n        for (int i = 0; i < k - 2; i++) curr = curr.next;   // k-2 steps reach the (k-1)-th node\n        curr.next = curr.next.next;                         // bypass the k-th node\n        return head;\n    }\n\n    static void printCircular(Node head) {\n        StringBuilder sb = new StringBuilder().append(head.data);\n        for (Node curr = head.next; curr != head; curr = curr.next) sb.append(\" -> \").append(curr.data);\n        System.out.println(sb + \" -> (back to \" + head.data + \")\");\n    }\n\n    public static void main(String[] args) {\n        Node head = new Node(10); head.next = new Node(5); head.next.next = new Node(20);\n        head.next.next.next = new Node(15); head.next.next.next.next = head;\n        printCircular(head);\n        int[] ks = {2, 3, 1}; String[] labels = {\"2nd\", \"3rd\", \"1st\"};\n        for (int i = 0; i < 3; i++) {\n            head = deleteKth(head, ks[i]);\n            System.out.print(\"delete \" + labels[i] + \": \"); printCircular(head);\n        }\n    }\n}","filename":"Java"}'),
  ('3336374e-a5b5-762e-b1fe-0b70b6f75965', 'b04', 'code', '{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction deleteHead(head) {\n    if (head === null || head.next === head) return null;\n    head.data = head.next.data; head.next = head.next.next;\n    return head;\n}\n\nfunction deleteKth(head, k) {\n    if (head === null) return null;\n    if (k === 1) return deleteHead(head);\n    let curr = head;\n    for (let i = 0; i < k - 2; i++) curr = curr.next;   // k-2 steps reach the (k-1)-th node\n    curr.next = curr.next.next;                         // bypass the k-th node\n    return head;\n}\n\nfunction printCircular(head) {\n    const parts = [head.data];\n    for (let curr = head.next; curr !== head; curr = curr.next) parts.push(curr.data);\n    console.log(parts.join(\" -> \"), `-> (back to ${head.data})`);\n}\n\nlet head = new Node(10); head.next = new Node(5); head.next.next = new Node(20);\nhead.next.next.next = new Node(15); head.next.next.next.next = head;\nprintCircular(head);\nfor (const [k, label] of [[2, \"2nd\"], [3, \"3rd\"], [1, \"1st\"]]) {\n    head = deleteKth(head, k);\n    process.stdout.write(`delete ${label}: `); printCircular(head);\n}","filename":"JavaScript"}'),
