  ('db1333a8-c6e1-7319-8b11-42de888ee83b', 'b07', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The original notes looped "},{"type":"text","text":"for i in range(1, k-2)","marks":[{"type":"code"}]},{"type":"text","text":", which takes "},{"type":"text","text":"k - 3","marks":[{"type":"code"}]},{"type":"text","text":" steps and deletes the wrong node for every "},{"type":"text","text":"k > 2","marks":[{"type":"code"}]},{"type":"text","text":". Count the steps on paper: from node 1, reaching node "},{"type":"text","text":"k-1","marks":[{"type":"code"}]},{"type":"text","text":" is exactly "},{"type":"text","text":"k - 2","marks":[{"type":"code"}]},{"type":"text","text":" hops. The code also assumes "},{"type":"text","text":"k ≤ length","marks":[{"type":"code"}]},{"type":"text","text":"; add a length check (or stop when "},{"type":"text","text":"curr.next == head","marks":[{"type":"code"}]},{"type":"text","text":") for untrusted input."}]}]}}'),
