SELECT 'ff7fcd47-1dc4-726e-a6a4-c5f556ff5ad6', '55f9d114-44dc-73f6-ba97-7a0a8af73629', 'Circular Linked List', 'Circular Linked List', 'A circular linked list is a singly linked list whose last node points back to the head instead of to None. There is no end, so the list can be traversed from any node, and keeping a single pointer gives O(1) access to both the first and the last element.
Circular linked list — a linked list in which the next of the last node refers to the first node. A one-node list points to itself. Traversal stops when we return to the node where we started, not when next is None — because it never is.
head
 ↓
┌──────┬────┐    ┌──────┬────┐    ┌──────┬────┐    ┌──────┬────┐
│  10  │ ●──┼───▶│   5  │ ●──┼───▶│  20  │ ●──┼───▶│  15  │ ●──┼──┐
└──────┴────┘    └──────┴────┘    └──────┴────┘    └──────┴────┘  │
  ▲                                                               │
  └───────────────────────────────────────────────────────────────┘
                the last node links back to the head
Building and traversing
The nodes are the same as in a singly linked list; only the last link differs. Traversal must stop when it comes back to the head, so the loop prints the head first and then walks until curr == head again. A while curr.next != head loop (as in the original notes) also works but needs the last node printed separately.
class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

def print_circular(head):
    if head is None:
        print("empty")
        return
    parts = [str(head.data)]
    curr = head.next
    while curr != head:              # stop when we are back at the start
        parts.append(str(curr.data))
        curr = curr.next
    print(" -> ".join(parts), f"-> (back to {head.data})")

head = Node(10)
head.next = Node(5)
head.next.next = Node(20)
head.next.next.next = Node(15)
head.next.next.next.next = head      # close the circle
print_circular(head)
#include <iostream>
using namespace std;

struct Node {
    int data; Node* next;
    Node(int d) : data(d), next(nullptr) {}
};

void printCircular(Node* head) {
    if (!head) { cout << "empty\n"; return; }
    cout << head->data;
    for (Node* curr = head->next; curr != head; curr = curr->next)   // stop when back at the start
        cout << " -> " << curr->data;
    cout << " -> (back to " << head->data << ")\n";
}

int main() {
    Node* head = new Node(10);
    head->next = new Node(5);
    head->next->next = new Node(20);
    head->next->next->next = new Node(15);
    head->next->next->next->next = head;    // close the circle
    printCircular(head);
}
public class Main {
    static class Node {
        int data; Node next;
        Node(int d) { data = d; }
    }

    static void printCircular(Node head) {
        if (head == null) { System.out.println("empty"); return; }
        StringBuilder sb = new StringBuilder().append(head.data);
        for (Node curr = head.next; curr != head; curr = curr.next)   // stop when back at the start
            sb.append(" -> ").append(curr.data);
        System.out.println(sb + " -> (back to " + head.data + ")");
    }

    public static void main(String[] args) {
        Node head = new Node(10);
        head.next = new Node(5);
        head.next.next = new Node(20);
        head.next.next.next = new Node(15);
        head.next.next.next.next = head;    // close the circle
        printCircular(head);
    }
}
class Node {
    constructor(data) { this.data = data; this.next = null; }
}

function printCircular(head) {
    if (head === null) { console.log("empty"); return; }
    const parts = [head.data];
    for (let curr = head.next; curr !== head; curr = curr.next)   // stop when back at the start
        parts.push(curr.data);
    console.log(parts.join(" -> "), `-> (back to ${head.data})`);
}

