INSERT INTO "notes"."Card" ("id", "noteId", "position", "type", "content", "revision", "createdAt", "updatedAt")
SELECT c.id::uuid, '8f223471-bbf0-70a7-9be4-e7af852b5e9f', c.position, c.type::"notes"."CardType", c.content::jsonb, 1, TIMESTAMPTZ '2026-10-07 03:23:53+00', TIMESTAMPTZ '2026-10-07 03:23:53+00'
FROM (VALUES
  ('d7cd54a5-98d0-7b08-ad8a-7c77593bc82c', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A dictionary (hash map) stores "},{"type":"text","text":"key → value","marks":[{"type":"bold"}]},{"type":"text","text":" pairs and finds the value for any key in O(1) on average. It is the most used data structure in practice: counting, grouping, caching and indexing are all one hash lookup away."}]}]}}'),
  ('8e616e55-d6ed-7557-8573-3a998dab02a9', 'a1', 'callout', '{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Dictionary / hash map","marks":[{"type":"bold"}]},{"type":"text","text":" — a collection of key–value pairs with "},{"type":"text","text":"distinct keys","marks":[{"type":"bold"}]},{"type":"text","text":", backed by a hash table: the key is hashed to a slot and the value is stored alongside it. Python "},{"type":"text","text":"dict","marks":[{"type":"code"}]},{"type":"text","text":", C++ "},{"type":"text","text":"unordered_map","marks":[{"type":"code"}]},{"type":"text","text":", Java "},{"type":"text","text":"HashMap","marks":[{"type":"code"}]},{"type":"text","text":", JavaScript "},{"type":"text","text":"Map","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('f9b6d3fc-6e7b-7a3e-b56d-f440c85b887a', 'a2', 'code', '{"language":"text","code":"d = {110: ''xyz'', 101: ''abc'', 105: ''pqr''}     with  h(key) = key % 4\n\nslot 0 │            │\nslot 1 │ 101 → abc  │──▶│ 105 → pqr │     101 % 4 = 1 and 105 % 4 = 1 collide → chained\nslot 2 │ 110 → xyz  │\nslot 3 │            │\n\nlookup d[105]: h(105) = 1 → walk slot 1: 101? no, 105? yes → ''pqr''","filename":"A hash map is a hash table whose slots hold key–value pairs"}'),
  ('50aa9be6-051c-7724-8bb1-95114650d74e', 'a3', 'heading', '{"level":1,"content":[{"type":"text","text":"Properties of a dictionary"}]}'),
  ('7f802f28-de6e-70db-81ca-6b338095f09b', 'a4', 'callout', '{"variant":"note","title":"Key–value pairs","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Each entry maps a key to exactly one value: "},{"type":"text","text":"d[110] = ''xyz''","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('d6a91613-2fc3-7ecf-8dcb-202a3cc6a1c6', 'a5', 'callout', '{"variant":"note","title":"Distinct keys","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Assigning to an existing key "},{"type":"text","text":"replaces","marks":[{"type":"bold"}]},{"type":"text","text":" its value; there are never two entries with the same key."}]}]}}'),
  ('b6f0cfc8-c147-7c90-a720-7c4079bff957', 'a6', 'callout', '{"variant":"note","title":"Values may repeat","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Many keys can map to the same value — only keys are unique."}]}]}}'),
  ('43cb714b-9e56-70f2-88b7-033c53e2c7af', 'a7', 'callout', '{"variant":"note","title":"Unordered (conceptually)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Entries live in hash slots. Python 3.7+ and JavaScript additionally remember insertion order; C++ and Java do not."}]}]}}'),
  ('7e7f0fb4-59cc-7a78-b5a6-b6d31e49ea30', 'a8', 'callout', '{"variant":"note","title":"Hashing internally","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every lookup hashes the key — O(1) average, O(n) worst case."}]}]}}'),
  ('df737179-98f8-78a8-bcde-f3db3bee8888', 'a9', 'callout', '{"variant":"note","title":"Hashable keys","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Keys must be immutable with a stable hash (numbers, strings, tuples). Values can be anything."}]}]}}'),
  ('8bf0ce5e-bf91-7519-a164-551e61d41439', 'aA', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Operation"}],[{"type":"text","text":"Python"}],[{"type":"text","text":"Average"}],[{"type":"text","text":"Why"}]],[[{"type":"text","text":"insert / update"}],[{"type":"text","text":"d[k] = v","marks":[{"type":"code"}]}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"Hash "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":"; store or overwrite in its slot"}]],[[{"type":"text","text":"lookup"}],[{"type":"text","text":"d[k]","marks":[{"type":"code"}]},{"type":"text","text":" (KeyError if missing) / "},{"type":"text","text":"d.get(k, default)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"Hash "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":"; compare keys in that one slot"}]],[[{"type":"text","text":"membership"}],[{"type":"text","text":"k in d","marks":[{"type":"code"}]}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"Same lookup, returns a boolean"}]],[[{"type":"text","text":"delete"}],[{"type":"text","text":"del d[k]","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"d.pop(k)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"Hash "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":"; unlink the entry"}]],[[{"type":"text","text":"size"}],[{"type":"text","text":"len(d)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"A stored counter"}]],[[{"type":"text","text":"iterate"}],[{"type":"text","text":"for k, v in d.items()","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"Walk every slot"}]]]}'),
  ('6c8457c4-0e0f-73db-adf5-cffdd33ba029', 'aB', 'heading', '{"level":1,"content":[{"type":"text","text":"Map containers in the four languages"}]}'),
  ('dd844dc7-d1dd-78d0-80bb-41dd191f9bcd', 'aC', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Language"}],[{"type":"text","text":"Hash map (unordered, O(1) avg)"}],[{"type":"text","text":"Ordered map (sorted keys, O(log n))"}]],[[{"type":"text","text":"Python"}],[{"type":"text","text":"dict","marks":[{"type":"code"}]},{"type":"text","text":" (insertion-ordered since 3.7); "},{"type":"text","text":"collections.Counter","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"defaultdict","marks":[{"type":"code"}]}],[{"type":"text","text":"— (use "},{"type":"text","text":"sorted(d)","marks":[{"type":"code"}]},{"type":"text","text":"; "},{"type":"text","text":"sortedcontainers","marks":[{"type":"code"}]},{"type":"text","text":" third-party)"}]],[[{"type":"text","text":"C++"}],[{"type":"text","text":"std::unordered_map","marks":[{"type":"code"}]}],[{"type":"text","text":"std::map","marks":[{"type":"code"}]},{"type":"text","text":" (red-black tree)"}]],[[{"type":"text","text":"Java"}],[{"type":"text","text":"HashMap","marks":[{"type":"code"}]},{"type":"text","text":"; "},{"type":"text","text":"LinkedHashMap","marks":[{"type":"code"}]},{"type":"text","text":" keeps insertion order"}],[{"type":"text","text":"TreeMap","marks":[{"type":"code"}]},{"type":"text","text":" (red-black tree)"}]],[[{"type":"text","text":"JavaScript"}],[{"type":"text","text":"Map","marks":[{"type":"code"}]},{"type":"text","text":" (insertion-ordered); plain objects "},{"type":"text","text":"{}","marks":[{"type":"code"}]},{"type":"text","text":" for string keys only"}],[{"type":"text","text":"— (sort the keys)"}]]]}'),
  ('37ac2793-fc0c-7051-a8a5-49133cf8c190', 'aD', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"JavaScript objects "},{"type":"text","text":"{}","marks":[{"type":"code"}]},{"type":"text","text":" convert every key to a string ("},{"type":"text","text":"obj[1]","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"obj[\"1\"]","marks":[{"type":"code"}]},{"type":"text","text":" are the same key). Use "},{"type":"text","text":"Map","marks":[{"type":"code"}]},{"type":"text","text":" when keys are numbers, objects or mixed types, and whenever you need "},{"type":"text","text":"size","marks":[{"type":"code"}]},{"type":"text","text":" without "},{"type":"text","text":"Object.keys(...).length","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('4ea0a044-a27c-7ee3-9798-a887b22d7d60', 'aE', 'heading', '{"level":1,"content":[{"type":"text","text":"Creating a dictionary, adding and reading entries"}]}'),
  ('9b63d989-2eff-709f-8641-3d07ac89d5ed', 'aF', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A dictionary is created from a literal or built up one assignment at a time. Reading "},{"type":"text","text":"d[key]","marks":[{"type":"code"}]},{"type":"text","text":" returns the value; "},{"type":"text","text":"keys()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"values()","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"items()","marks":[{"type":"code"}]},{"type":"text","text":" give the three views. Below, the keys are "},{"type":"text","text":"sorted","marks":[{"type":"bold"}]},{"type":"text","text":" before printing because iteration order differs between languages."}]}]}}'),
  ('9b0c5286-b0ce-76b4-9743-4245e5cf607f', 'aG', 'code', '{"language":"python","code":"d = {}                       # same as {110: ''xyz'', 101: ''abc'', 105: ''pqr''}\nd[110] = ''xyz''\nd[101] = ''abc''\nd[105] = ''pqr''\nprint(\"size:\", len(d))\nprint(\"d[101] =\", d[101])                        # O(1) lookup\nprint(\"keys:\", *sorted(d.keys()))\nprint(\"values:\", *[d[k] for k in sorted(d)])\nprint(\"items:\", *[f\"{k}={d[k]}\" for k in sorted(d)])\nd[101] = ''ABC''                                   # existing key → value replaced\nprint(\"after d[101] = ''ABC'':\", *[f\"{k}={d[k]}\" for k in sorted(d)])","filename":"Python"}'),
  ('066facdb-c4aa-714c-a853-6e160e7775e6', 'aH', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <unordered_map>\n#include <vector>\n#include <string>\n#include <algorithm>\nusing namespace std;\n\nvector<int> sortedKeys(const unordered_map<int, string>& d) {\n    vector<int> keys;\n    for (auto& kv : d) keys.push_back(kv.first);\n    sort(keys.begin(), keys.end());\n    return keys;\n}\n\nint main() {\n    unordered_map<int, string> d;    // same as {{110, \"xyz\"}, {101, \"abc\"}, {105, \"pqr\"}}\n    d[110] = \"xyz\";\n    d[101] = \"abc\";\n    d[105] = \"pqr\";\n    cout << \"size: \" << d.size() << \"\\n\";\n    cout << \"d[101] = \" << d[101] << \"\\n\";                 // O(1) lookup\n    cout << \"keys:\"; for (int k : sortedKeys(d)) cout << \" \" << k; cout << \"\\n\";\n    cout << \"values:\"; for (int k : sortedKeys(d)) cout << \" \" << d[k]; cout << \"\\n\";\n    cout << \"items:\"; for (int k : sortedKeys(d)) cout << \" \" << k << \"=\" << d[k]; cout << \"\\n\";\n    d[101] = \"ABC\";                                          // existing key → value replaced\n    cout << \"after d[101] = ''ABC'':\"; for (int k : sortedKeys(d)) cout << \" \" << k << \"=\" << d[k]; cout << \"\\n\";\n}","filename":"C++"}'),
  ('91500425-80e2-760a-aa28-f29d51fac751', 'aI', 'code', '{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    static String items(Map<Integer, String> d) {\n        StringBuilder sb = new StringBuilder();\n        for (int k : new TreeSet<>(d.keySet())) sb.append(\" \").append(k).append(\"=\").append(d.get(k));\n        return sb.toString();\n    }\n\n    public static void main(String[] args) {\n        Map<Integer, String> d = new HashMap<>();   // same as Map.of(110, \"xyz\", 101, \"abc\", 105, \"pqr\")\n        d.put(110, \"xyz\");\n        d.put(101, \"abc\");\n        d.put(105, \"pqr\");\n        System.out.println(\"size: \" + d.size());\n        System.out.println(\"d[101] = \" + d.get(101));          // O(1) lookup\n        TreeSet<Integer> keys = new TreeSet<>(d.keySet());\n        StringBuilder ks = new StringBuilder(\"keys:\"), vs = new StringBuilder(\"values:\");\n        for (int k : keys) { ks.append(\" \").append(k); vs.append(\" \").append(d.get(k)); }\n        System.out.println(ks);\n        System.out.println(vs);\n        System.out.println(\"items:\" + items(d));\n        d.put(101, \"ABC\");                                      // existing key → value replaced\n        System.out.println(\"after d[101] = ''ABC'':\" + items(d));\n    }\n}","filename":"Java"}'),
  ('5074c09d-5a4a-7335-b359-b4c4d79bdc98', 'aJ', 'code', '{"language":"javascript","code":"const d = new Map();          // same as new Map([[110, ''xyz''], [101, ''abc''], [105, ''pqr'']])\nd.set(110, ''xyz'');\nd.set(101, ''abc'');\nd.set(105, ''pqr'');\nconst sortedKeys = () => [...d.keys()].sort((a, b) => a - b);\nconst items = () => sortedKeys().map(k => `${k}=${d.get(k)}`).join(\" \");\n\nconsole.log(\"size:\", d.size);\nconsole.log(\"d[101] =\", d.get(101));                 // O(1) lookup\nconsole.log(\"keys:\", sortedKeys().join(\" \"));\nconsole.log(\"values:\", sortedKeys().map(k => d.get(k)).join(\" \"));\nconsole.log(\"items:\", items());\nd.set(101, ''ABC'');                                    // existing key → value replaced\nconsole.log(\"after d[101] = ''ABC'':\", items());","filename":"JavaScript"}'),
  ('0c86db1c-515a-74da-8485-d46c775f35af', 'aK', 'code', '{"language":"text","code":"size: 3\nd[101] = abc\nkeys: 101 105 110\nvalues: abc pqr xyz\nitems: 101=abc 105=pqr 110=xyz\nafter d[101] = ''ABC'': 101=ABC 105=pqr 110=xyz","filename":"Output"}'),
  ('d4369628-b9f5-7f56-88db-62d8a5e87989', 'aL', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(1) average per insert / lookup · Space O(n)"}]}]}}'),
  ('a9257c18-3d1c-7d3e-8652-4087e325a70c', 'aM', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In C++ "},{"type":"text","text":"d[key]","marks":[{"type":"code"}]},{"type":"text","text":" on a "},{"type":"text","text":"missing","marks":[{"type":"bold"}]},{"type":"text","text":" key silently "},{"type":"text","text":"inserts","marks":[{"type":"italic"}]},{"type":"text","text":" a default value (empty string, 0) and returns it. Use "},{"type":"text","text":"d.find(key)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"d.count(key)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"d.contains(key)","marks":[{"type":"code"}]},{"type":"text","text":" (C++20) or "},{"type":"text","text":"d.at(key)","marks":[{"type":"code"}]},{"type":"text","text":" (throws) when you only want to read."}]}]}}'),
  ('91c3464d-0823-74af-9595-0d02eeaa2b6b', 'aN', 'heading', '{"level":1,"content":[{"type":"text","text":"Missing keys and default values"}]}'),
  ('7cc3efd4-9b05-75ed-8a2d-7fa2ce5bed27', 'aO', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What happens when the key is absent is where the languages differ most, and the source of most dictionary bugs:"}]}]}}'),
  ('e2a74516-80e0-7dd7-b920-61d40d54ebe8', 'aP', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Language"}],[{"type":"text","text":"Read of a missing key"}],[{"type":"text","text":"Safe read with default"}],[{"type":"text","text":"Membership"}]],[[{"type":"text","text":"Python"}],[{"type":"text","text":"d[k]","marks":[{"type":"code"}]},{"type":"text","text":" raises "},{"type":"text","text":"KeyError","marks":[{"type":"code"}]}],[{"type":"text","text":"d.get(k, default)","marks":[{"type":"code"}]},{"type":"text","text":"; "},{"type":"text","text":"d.setdefault(k, default)","marks":[{"type":"code"}]},{"type":"text","text":" also inserts"}],[{"type":"text","text":"k in d","marks":[{"type":"code"}]}]],[[{"type":"text","text":"C++"}],[{"type":"text","text":"d[k]","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"inserts","marks":[{"type":"bold"}]},{"type":"text","text":" a default and returns it; "},{"type":"text","text":"d.at(k)","marks":[{"type":"code"}]},{"type":"text","text":" throws"}],[{"type":"text","text":"auto it = d.find(k); it != d.end() ? it->second : default","marks":[{"type":"code"}]}],[{"type":"text","text":"d.count(k)","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"d.contains(k)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Java"}],[{"type":"text","text":"d.get(k)","marks":[{"type":"code"}]},{"type":"text","text":" returns "},{"type":"text","text":"null","marks":[{"type":"code"}]}],[{"type":"text","text":"d.getOrDefault(k, default)","marks":[{"type":"code"}]}],[{"type":"text","text":"d.containsKey(k)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"JavaScript"}],[{"type":"text","text":"d.get(k)","marks":[{"type":"code"}]},{"type":"text","text":" returns "},{"type":"text","text":"undefined","marks":[{"type":"code"}]}],[{"type":"text","text":"d.get(k) ?? default","marks":[{"type":"code"}]}],[{"type":"text","text":"d.has(k)","marks":[{"type":"code"}]}]]]}'),
  ('45ba86a8-2ced-7ca1-8581-10f49cc166c9', 'aQ', 'code', '{"language":"python","code":"d = {110: ''xyz'', 101: ''abc'', 105: ''pqr''}\nprint(\"get 101:\", d.get(101))\nprint(\"get 999:\", d.get(999, \"none\"))           # no KeyError\nprint(\"999 in d:\", \"true\" if 999 in d else \"false\")\n\ncounts = {}\ncounts[''abc''] = counts.get(''abc'', 0) + 1       # the counting idiom\nprint(\"count of ''abc'' with default 0 →\", counts[''abc''])","filename":"Python"}'),
  ('5dbd841c-0626-7e97-8a20-698993107900', 'aR', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <unordered_map>\n#include <string>\nusing namespace std;\n\nstring getOr(const unordered_map<int, string>& d, int k, const string& def) {\n    auto it = d.find(k);                          // find does not insert\n    return it != d.end() ? it->second : def;\n}\n\nint main() {\n    unordered_map<int, string> d = {{110, \"xyz\"}, {101, \"abc\"}, {105, \"pqr\"}};\n    cout << \"get 101: \" << getOr(d, 101, \"none\") << \"\\n\";\n    cout << \"get 999: \" << getOr(d, 999, \"none\") << \"\\n\";\n    cout << \"999 in d: \" << (d.contains(999) ? \"true\" : \"false\") << \"\\n\";\n\n    unordered_map<string, int> counts;\n    counts[\"abc\"]++;                              // operator[] inserts 0 then increments — the counting idiom\n    cout << \"count of ''abc'' with default 0 → \" << counts[\"abc\"] << \"\\n\";\n}","filename":"C++"}'),
  ('68499b48-6423-796d-940e-6ae6afd88177', 'aS', 'code', '{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Map<Integer, String> d = new HashMap<>(Map.of(110, \"xyz\", 101, \"abc\", 105, \"pqr\"));\n        System.out.println(\"get 101: \" + d.get(101));\n        System.out.println(\"get 999: \" + d.getOrDefault(999, \"none\"));   // get(999) alone would be null\n        System.out.println(\"999 in d: \" + d.containsKey(999));\n\n        Map<String, Integer> counts = new HashMap<>();\n        counts.merge(\"abc\", 1, Integer::sum);           // the counting idiom\n        System.out.println(\"count of ''abc'' with default 0 → \" + counts.get(\"abc\"));\n    }\n}","filename":"Java"}'),
  ('1cc5bbe3-6ab8-71e5-9ed0-395a16c80f9a', 'aT', 'code', '{"language":"javascript","code":"const d = new Map([[110, ''xyz''], [101, ''abc''], [105, ''pqr'']]);\nconsole.log(\"get 101:\", d.get(101));\nconsole.log(\"get 999:\", d.get(999) ?? \"none\");        // get(999) alone would be undefined\nconsole.log(\"999 in d:\", d.has(999));\n\nconst counts = new Map();\ncounts.set(''abc'', (counts.get(''abc'') ?? 0) + 1);     // the counting idiom\nconsole.log(\"count of ''abc'' with default 0 →\", counts.get(''abc''));","filename":"JavaScript"}'),
  ('cf8541ec-0f88-7437-aae1-5d6305f707d6', 'aU', 'code', '{"language":"text","code":"get 101: abc\nget 999: none\n999 in d: false\ncount of ''abc'' with default 0 → 1","filename":"Output"}'),
  ('0358ae59-e368-7229-8b8a-f15ea64025b0', 'aV', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(1) average · Space O(1)"}]}]}}'),
  ('593183ed-0f8d-73f2-bd3d-a5353c810549', 'aW', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Python''s "},{"type":"text","text":"collections.defaultdict(int)","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"Counter","marks":[{"type":"code"}]},{"type":"text","text":" build the default-value idiom into the container: "},{"type":"text","text":"counts[x] += 1","marks":[{"type":"code"}]},{"type":"text","text":" just works. "},{"type":"text","text":"Counter(arr).most_common(k)","marks":[{"type":"code"}]},{"type":"text","text":" is the one-liner for top-k frequency questions."}]}]}}'),
  ('040ed1d6-8a0c-70ad-89d6-0a81d6d24f31', 'aX', 'heading', '{"level":1,"content":[{"type":"text","text":"Removing entries"}]}'),
  ('62ac189d-b3be-7793-bff7-8854db36b20a', 'aY', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"pop(key)","marks":[{"type":"code"}]},{"type":"text","text":" removes an entry "},{"type":"text","text":"and returns its value","marks":[{"type":"bold"}]},{"type":"text","text":" (Python, and the same shape in Java''s "},{"type":"text","text":"remove","marks":[{"type":"code"}]},{"type":"text","text":"); "},{"type":"text","text":"del d[key]","marks":[{"type":"code"}]},{"type":"text","text":" just removes it. Python''s "},{"type":"text","text":"popitem()","marks":[{"type":"code"}]},{"type":"text","text":" removes and returns the "},{"type":"text","text":"last inserted","marks":[{"type":"bold"}]},{"type":"text","text":" pair — handy as a stack of pairs — and has no equivalent in the other languages."}]}]}}'),
  ('0c948808-2e77-7d67-afa0-ac4b2d70c945', 'aZ', 'code', '{"language":"python","code":"d = {110: ''xyz'', 101: ''abc'', 105: ''pqr''}\ndef show(): print(\"remaining:\", *[f\"{k}={d[k]}\" for k in sorted(d)])\n\nprint(\"pop 101 →\", d.pop(101))             # removes and returns the value\nshow()\nprint(\"delete 105:\", \"true\" if d.pop(105, None) is not None else \"false\")\nprint(\"delete 999:\", \"true\" if d.pop(999, None) is not None else \"false\")   # default avoids KeyError\nshow()","filename":"Python"}'),
  ('8abfbb6b-aad9-7219-82c4-897749904050', 'aa', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <unordered_map>\n#include <vector>\n#include <string>\n#include <algorithm>\nusing namespace std;\n\nunordered_map<int, string> d = {{110, \"xyz\"}, {101, \"abc\"}, {105, \"pqr\"}};\n\nvoid show() {\n    vector<int> keys;\n    for (auto& kv : d) keys.push_back(kv.first);\n    sort(keys.begin(), keys.end());\n    cout << \"remaining:\";\n    for (int k : keys) cout << \" \" << k << \"=\" << d[k];\n    cout << \"\\n\";\n}\n\nint main() {\n    string v = d.at(101); d.erase(101);        // read, then erase — erase itself returns a count\n    cout << \"pop 101 → \" << v << \"\\n\";\n    show();\n    cout << \"delete 105: \" << (d.erase(105) ? \"true\" : \"false\") << \"\\n\";\n    cout << \"delete 999: \" << (d.erase(999) ? \"true\" : \"false\") << \"\\n\";\n    show();\n}","filename":"C++"}'),
  ('2e8ca4ff-13e9-7c8f-93fa-5c8e763382e9', 'ab', 'code', '{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    static Map<Integer, String> d = new HashMap<>(Map.of(110, \"xyz\", 101, \"abc\", 105, \"pqr\"));\n\n    static void show() {\n        StringBuilder sb = new StringBuilder(\"remaining:\");\n        for (int k : new TreeSet<>(d.keySet())) sb.append(\" \").append(k).append(\"=\").append(d.get(k));\n        System.out.println(sb);\n    }\n\n    public static void main(String[] args) {\n        System.out.println(\"pop 101 → \" + d.remove(101));      // removes and returns the value (null if absent)\n        show();\n        System.out.println(\"delete 105: \" + (d.remove(105) != null));\n        System.out.println(\"delete 999: \" + (d.remove(999) != null));\n        show();\n    }\n}","filename":"Java"}'),
  ('45361347-52f9-72f5-91fc-c4b27a394af0', 'ac', 'code', '{"language":"javascript","code":"const d = new Map([[110, ''xyz''], [101, ''abc''], [105, ''pqr'']]);\nconst show = () => console.log(\"remaining:\", [...d.keys()].sort((a, b) => a - b).map(k => `${k}=${d.get(k)}`).join(\" \"));\n\nconst v = d.get(101); d.delete(101);        // read, then delete — delete returns a boolean\nconsole.log(\"pop 101 →\", v);\nshow();\nconsole.log(\"delete 105:\", d.delete(105));\nconsole.log(\"delete 999:\", d.delete(999));\nshow();","filename":"JavaScript"}'),
  ('25ce5b98-8f0d-72d1-bf44-270ebbe6d4a8', 'ad', 'code', '{"language":"text","code":"pop 101 → abc\nremaining: 105=pqr 110=xyz\ndelete 105: true\ndelete 999: false\nremaining: 110=xyz","filename":"Output"}'),
  ('0823c92b-ecc3-73d0-bb59-958d6be19fbc', 'ae', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(1) average per removal · Space O(1)"}]}]}}'),
  ('12095d91-325a-789d-b01a-6f7601e3669f', 'af', 'code', '{"language":"python","code":"d = {110: ''xyz'', 101: ''abc'', 105: ''pqr''}\nprint(d.popitem())      # last inserted pair, LIFO (Python 3.7+)\nprint(d.popitem())\nprint(d)","filename":"Python"}'),
  ('d1a27dd7-38fe-75c7-90c1-0ba1f911bd8f', 'ag', 'code', '{"language":"text","code":"(105, ''pqr'')\n(101, ''abc'')\n{110: ''xyz''}","filename":"Output"}'),
  ('704cf274-f893-7039-85e0-039ad36c4e33', 'ah', 'heading', '{"level":1,"content":[{"type":"text","text":"Iteration order"}]}'),
  ('3e34ecaa-ec9e-786d-beab-9464c8516afd', 'ai', 'callout', '{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Conceptually a hash map has "},{"type":"text","text":"no order","marks":[{"type":"bold"}]},{"type":"text","text":". Two of the four languages guarantee insertion order anyway, two do not — code that works in Python and breaks in Java or C++ is a classic porting bug."}]}]}}'),
  ('e015a2db-294f-75b4-be6e-d872d5b04576', 'aj', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Container"}],[{"type":"text","text":"Iteration order"}]],[[{"type":"text","text":"Python "},{"type":"text","text":"dict","marks":[{"type":"code"}]}],[{"type":"text","text":"Insertion order","marks":[{"type":"bold"}]},{"type":"text","text":" (guaranteed since 3.7)"}]],[[{"type":"text","text":"C++ "},{"type":"text","text":"unordered_map","marks":[{"type":"code"}]}],[{"type":"text","text":"Arbitrary; "},{"type":"text","text":"std::map","marks":[{"type":"code"}]},{"type":"text","text":" = sorted by key"}]],[[{"type":"text","text":"Java "},{"type":"text","text":"HashMap","marks":[{"type":"code"}]}],[{"type":"text","text":"Arbitrary; "},{"type":"text","text":"LinkedHashMap","marks":[{"type":"code"}]},{"type":"text","text":" = insertion order; "},{"type":"text","text":"TreeMap","marks":[{"type":"code"}]},{"type":"text","text":" = sorted by key"}]],[[{"type":"text","text":"JavaScript "},{"type":"text","text":"Map","marks":[{"type":"code"}]}],[{"type":"text","text":"Insertion order","marks":[{"type":"bold"}]},{"type":"text","text":"; plain objects list integer-like keys first in ascending order, then string keys in insertion order"}]]]}'),
  ('91563252-5e4e-7ae0-8d51-a6d495f2d9c5', 'ak', 'callout', '{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Need sorted output? Sort the keys explicitly ("},{"type":"text","text":"for k in sorted(d)","marks":[{"type":"code"}]},{"type":"text","text":") or use a tree map. Need first-seen order in C++/Java? Keep a separate vector/list of keys in insertion order or use "},{"type":"text","text":"LinkedHashMap","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('b45697ad-9e7f-78cb-bc46-c774a1f36b64', 'al', 'heading', '{"level":1,"content":[{"type":"text","text":"Typical uses"}]}'),
  ('702044cf-0a65-7d3b-892b-b221281e9616', 'am', 'callout', '{"variant":"note","title":"Frequency counting","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"count[x] += 1","marks":[{"type":"code"}]},{"type":"text","text":" over an array or text — then answer "},{"type":"text","text":"most frequent","marks":[{"type":"italic"}]},{"type":"text","text":", "},{"type":"text","text":"appears exactly once","marks":[{"type":"italic"}]},{"type":"text","text":", "},{"type":"text","text":"anagram check","marks":[{"type":"italic"}]},{"type":"text","text":"."}]}]}}'),
  ('073c5b99-ae15-7cf0-af47-81fb0a8d25dc', 'an', 'callout', '{"variant":"note","title":"Lookup tables","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"id → record, name → phone number, word → definition. A database index in miniature."}]}]}}'),
  ('b801c14b-d895-7d56-b4a8-1a8de3c3fa15', 'ao', 'callout', '{"variant":"note","title":"Memoisation / caching","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"key = function arguments, value = result; dynamic programming top-down uses exactly this."}]}]}}'),
  ('30d34468-c276-7aae-bd10-80d69df3b41c', 'ap', 'callout', '{"variant":"note","title":"Grouping","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"key = group label (first letter, sorted letters, remainder), value = list of members."}]}]}}'),
  ('e36a723c-5a4a-7257-b8f5-7976bae432db', 'aq', 'callout', '{"variant":"note","title":"Pair problems","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two-sum: for each "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":", has "},{"type":"text","text":"target - x","marks":[{"type":"code"}]},{"type":"text","text":" been seen? Store value → index."}]}]}}'),
  ('40050921-5fa7-7699-9c0f-e14272f887ec', 'ar', 'callout', '{"variant":"note","title":"Graphs","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Adjacency lists for sparse graphs with arbitrary vertex labels: "},{"type":"text","text":"adj[u] = [v, …]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('6113485b-119a-7520-aa3f-b6e95dbe0192', 'as', 'heading', '{"level":1,"content":[{"type":"text","text":"Problem: word frequencies"}]}'),
  ('497036d7-c0e4-7d5f-89f9-4e76c6b11b0b', 'at', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"text = \"the cat and the hat and the bat\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"and 2 / bat 1 / cat 1 / hat 1 / the 3","marks":[{"type":"code"}]}]}]}}'),
  ('fa83845d-46bf-71ee-84b5-803068681735', 'au', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Split into words and do "},{"type":"text","text":"freq[word] += 1","marks":[{"type":"code"}]},{"type":"text","text":" for each — a hash map update is O(1) on average, so the whole text costs O(n). Print the keys in sorted order so the result does not depend on the language''s iteration order."}]}]}}'),
  ('c1c1b521-5049-7e85-a041-99b54db97c8e', 'av', 'code', '{"language":"python","code":"def word_freq(text):\n    freq = {}\n    for w in text.split():\n        freq[w] = freq.get(w, 0) + 1      # O(1) average\n    for w in sorted(freq):\n        print(w, freq[w])\n\nword_freq(\"the cat and the hat and the bat\")","filename":"Python"}'),
  ('ad24b51f-a641-7d3a-988d-c6d76508e98c', 'aw', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <sstream>\n#include <string>\n#include <unordered_map>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nvoid wordFreq(const string& text) {\n    unordered_map<string, int> freq;\n    istringstream in(text);\n    string w;\n    while (in >> w) freq[w]++;            // O(1) average\n    vector<string> words;\n    for (auto& kv : freq) words.push_back(kv.first);\n    sort(words.begin(), words.end());\n    for (const string& x : words) cout << x << \" \" << freq[x] << \"\\n\";\n}\n\nint main() {\n    wordFreq(\"the cat and the hat and the bat\");\n}","filename":"C++"}'),
  ('e82276b4-b63b-704f-a166-81dd04ee9f0b', 'ax', 'code', '{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    static void wordFreq(String text) {\n        Map<String, Integer> freq = new HashMap<>();\n        for (String w : text.split(\" \")) freq.merge(w, 1, Integer::sum);   // O(1) average\n        for (String w : new TreeSet<>(freq.keySet()))\n            System.out.println(w + \" \" + freq.get(w));\n    }\n\n    public static void main(String[] args) {\n        wordFreq(\"the cat and the hat and the bat\");\n    }\n}","filename":"Java"}'),
  ('ff1fd95d-f57f-7801-8850-9081462e632c', 'ay', 'code', '{"language":"javascript","code":"function wordFreq(text) {\n    const freq = new Map();\n    for (const w of text.split(\" \")) freq.set(w, (freq.get(w) ?? 0) + 1);   // O(1) average\n    for (const w of [...freq.keys()].sort()) console.log(w, freq.get(w));\n}\n\nwordFreq(\"the cat and the hat and the bat\");","filename":"JavaScript"}'),
  ('10845e57-fb2b-7084-962a-3b9417b511b4', 'az', 'code', '{"language":"text","code":"and 2\nbat 1\ncat 1\nhat 1\nthe 3","filename":"Output"}'),
  ('1a9d084b-7a3f-7c01-961c-441b7cb32667', 'b00', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) average (+ O(k log k) to sort k distinct words) · Space O(k)"}]}]}}'),
  ('a6967142-37a8-7d2f-b11a-2c8d962d3fa1', 'b01', 'heading', '{"level":1,"content":[{"type":"text","text":"Problem: two sum with a hash map"}]}'),
  ('40969fb3-e1c2-7e8d-909a-26233b1f4707', 'b02', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"arr = [8, 3, 5, 11, 2], target = 13","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"8 + 5 = 13","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"arr = [1, 2, 3], target = 10","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"no pair","marks":[{"type":"code"}]}]}]}}'),
  ('4c0a3236-63d1-7a52-9ae9-fb1378bef593', 'b03', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Scan once. For each "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":", the partner we need is "},{"type":"text","text":"target - x","marks":[{"type":"code"}]},{"type":"text","text":"; if it has already been "},{"type":"text","text":"seen","marks":[{"type":"bold"}]},{"type":"text","text":", we are done, otherwise record "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":". One hash lookup per element replaces the inner loop of the O(n²) brute force."}]}]}}'),
  ('30e6822c-7242-7d07-ac3f-d390903053ad', 'b04', 'text', '{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Create an empty map","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"seen","marks":[{"type":"code"}]},{"type":"text","text":" maps a value to its index (a set suffices if indices are not needed)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"For each element ","marks":[{"type":"bold"}]},{"type":"text","text":"x","marks":[{"type":"code"},{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Compute "},{"type":"text","text":"need = target - x","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Check the map","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"If "},{"type":"text","text":"need","marks":[{"type":"code"}]},{"type":"text","text":" is in "},{"type":"text","text":"seen","marks":[{"type":"code"}]},{"type":"text","text":", report the pair "},{"type":"text","text":"(need, x)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Record","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Otherwise store "},{"type":"text","text":"seen[x] = index","marks":[{"type":"code"}]},{"type":"text","text":" and continue."}]}]}]}]}}'),
  ('714c38a6-654b-7e69-9efb-9d4fd2d26a52', 'b05', 'code', '{"language":"python","code":"def two_sum(arr, target):\n    seen = {}                               # value → index\n    for i, x in enumerate(arr):\n        need = target - x\n        if need in seen:                    # O(1) instead of an inner loop\n            return seen[need], i\n        seen[x] = i\n    return None\n\nfor arr, target in (([8, 3, 5, 11, 2], 13), ([1, 2, 3], 10)):\n    res = two_sum(arr, target)\n    label = f\"[{'' ''.join(map(str, arr))}] target {target} →\"\n    if res is None:\n        print(label, \"no pair\")\n    else:\n        i, j = res\n        print(label, f\"{arr[i]} + {arr[j]} = {target} (indices {i}, {j})\")","filename":"Python"}'),
  ('cb6d0dd6-8237-778b-89ae-33ac80290c71', 'b06', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <vector>\n#include <unordered_map>\n#include <string>\nusing namespace std;\n\nbool twoSum(const vector<int>& arr, int target, int& i, int& j) {\n    unordered_map<int, int> seen;           // value → index\n    int n = arr.size();\n    for (int k = 0; k < n; k++) {\n        int need = target - arr[k];\n        auto it = seen.find(need);          // O(1) instead of an inner loop\n        if (it != seen.end()) { i = it->second; j = k; return true; }\n        seen[arr[k]] = k;\n    }\n    return false;\n}\n\nint main() {\n    vector<pair<vector<int>, int>> tests = {{{8, 3, 5, 11, 2}, 13}, {{1, 2, 3}, 10}};\n    for (auto& [arr, target] : tests) {\n        cout << \"[\";\n        for (int k = 0; k < (int)arr.size(); k++) cout << (k ? \" \" : \"\") << arr[k];\n        cout << \"] target \" << target << \" → \";\n        int i, j;\n        if (twoSum(arr, target, i, j))\n            cout << arr[i] << \" + \" << arr[j] << \" = \" << target << \" (indices \" << i << \", \" << j << \")\\n\";\n        else\n            cout << \"no pair\\n\";\n    }\n}","filename":"C++"}'),
  ('036ec99f-a7b0-7327-9f33-c8c8b551da39', 'b07', 'code', '{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    static int[] twoSum(int[] arr, int target) {\n        Map<Integer, Integer> seen = new HashMap<>();   // value → index\n        for (int k = 0; k < arr.length; k++) {\n            int need = target - arr[k];\n            if (seen.containsKey(need))                 // O(1) instead of an inner loop\n                return new int[]{seen.get(need), k};\n            seen.put(arr[k], k);\n        }\n        return null;\n    }\n\n    public static void main(String[] args) {\n        int[][] arrays = {{8, 3, 5, 11, 2}, {1, 2, 3}};\n        int[] targets = {13, 10};\n        for (int t = 0; t < arrays.length; t++) {\n            int[] arr = arrays[t];\n            StringBuilder sb = new StringBuilder(\"[\");\n            for (int k = 0; k < arr.length; k++) sb.append(k > 0 ? \" \" : \"\").append(arr[k]);\n            sb.append(\"] target \").append(targets[t]).append(\" → \");\n            int[] res = twoSum(arr, targets[t]);\n            if (res == null) sb.append(\"no pair\");\n            else sb.append(arr[res[0]]).append(\" + \").append(arr[res[1]]).append(\" = \").append(targets[t])\n                   .append(\" (indices \").append(res[0]).append(\", \").append(res[1]).append(\")\");\n            System.out.println(sb);\n        }\n    }\n}","filename":"Java"}'),
  ('be961209-492c-7fe1-bb7a-bbc25c57c336', 'b08', 'code', '{"language":"javascript","code":"function twoSum(arr, target) {\n    const seen = new Map();                   // value → index\n    for (let k = 0; k < arr.length; k++) {\n        const need = target - arr[k];\n        if (seen.has(need)) return [seen.get(need), k];   // O(1) instead of an inner loop\n        seen.set(arr[k], k);\n    }\n    return null;\n}\n\nfor (const [arr, target] of [[[8, 3, 5, 11, 2], 13], [[1, 2, 3], 10]]) {\n    const label = `[${arr.join(\" \")}] target ${target} →`;\n    const res = twoSum(arr, target);\n    if (res === null) console.log(label, \"no pair\");\n    else console.log(label, `${arr[res[0]]} + ${arr[res[1]]} = ${target} (indices ${res[0]}, ${res[1]})`);\n}","filename":"JavaScript"}'),
  ('ba5dc945-e94c-794c-92b5-234b82c0865e', 'b09', 'code', '{"language":"text","code":"[8 3 5 11 2] target 13 → 8 + 5 = 13 (indices 0, 2)\n[1 2 3] target 10 → no pair","filename":"Output"}'),
  ('30653299-8227-7153-8dbb-8badbf281659', 'b0A', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) average · Space O(n)"}]}]}}'),
  ('26a8ee9e-e231-73b2-934b-bb009c6c1668', 'b0B', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Insert "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":" into the map "},{"type":"text","text":"after","marks":[{"type":"bold"}]},{"type":"text","text":" checking for its partner, not before — otherwise "},{"type":"text","text":"target = 2x","marks":[{"type":"code"}]},{"type":"text","text":" would match an element with itself ("},{"type":"text","text":"[5]","marks":[{"type":"code"}]},{"type":"text","text":", target 10 → \"5 + 5\")."}]}]}}'),
  ('67162dbf-cf39-7a5d-b881-94d8d1459bce', 'b0C', 'heading', '{"level":1,"content":[{"type":"text","text":"Interview Q&A"}]}'),
  ('9826e633-55d6-7580-9935-0b152cef7502', 'b0D', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How does a dictionary achieve O(1) lookup?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The key is hashed to an array index; the value sits in that slot (or in a short chain / probe sequence starting there). No scanning, no comparisons with unrelated keys. The cost is O(1) "},{"type":"text","text":"average","marks":[{"type":"italic"}]},{"type":"text","text":": a bad hash function or an overfull table lengthens chains, and rehashing keeps the load factor bounded."}]}]}}'),
  ('da2eb0d8-dce4-75cd-8089-ff6aa8ea58f4', 'b0E', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Dictionary vs set — when do you need which?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Both are hash tables with distinct keys. A set answers "},{"type":"text","text":"is ","marks":[{"type":"italic"}]},{"type":"text","text":"x","marks":[{"type":"italic"},{"type":"code"}]},{"type":"text","text":" present?","marks":[{"type":"italic"}]},{"type":"text","text":"; a dictionary additionally attaches a value to each key — a count, an index, a list of members. If you catch yourself using a dictionary with all values "},{"type":"text","text":"True","marks":[{"type":"code"}]},{"type":"text","text":", you want a set."}]}]}}'),
