INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT 'b11c752e-b045-7927-bc68-47d03f454b01', '5a903e95-d6d6-74d6-a91d-ebc1ab4a364e', 1, 'PUBLISHED', 'Doubly Linked List', '[{"id":"fa53d542-b1d2-780e-bb41-596107af3f39","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A doubly linked list gives every node a "},{"type":"text","text":"prev","marks":[{"type":"bold"},{"type":"code"}]},{"type":"text","text":" pointer in addition to "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":", so the list can be walked in both directions and any node can be removed in O(1) given only a reference to it. It costs one extra pointer per node and a little more bookkeeping."}]}]}},"revision":1},{"id":"a6a21e0a-499c-7c40-b5a6-b2b9504eb589","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Doubly linked list","marks":[{"type":"bold"}]},{"type":"text","text":" — a linked list whose nodes hold "},{"type":"text","text":"data","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" (the following node) and "},{"type":"text","text":"prev","marks":[{"type":"code"}]},{"type":"text","text":" (the preceding node). The head''s "},{"type":"text","text":"prev","marks":[{"type":"code"}]},{"type":"text","text":" and the tail''s "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" are "},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":". Every link is mirrored: "},{"type":"text","text":"a.next == b","marks":[{"type":"code"}]},{"type":"text","text":" always implies "},{"type":"text","text":"b.prev == a","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"da5bbc87-0638-7fd2-b19c-f5e77a350783","type":"code","position":"a2","content":{"language":"text","code":"         head                                                   tail\n          ↓                                                       ↓\n     ┌────┬──────┬────┐     ┌────┬──────┬────┐     ┌────┬──────┬────┐\n∅ ◀──┼ ●  │  10  │ ●──┼────▶│ ●  │  20  │ ●──┼────▶│ ●  │  30  │ ●──┼──▶ ∅\n     └────┴──────┴────┘◀────┼─●  │      │    │◀────┼─●  │      │    │\n      prev  data  next      └────┴──────┴────┘     └────┴──────┴────┘\n\nNone <-> 10 <-> 20 <-> 30 <-> None","filename":"A doubly linked list: every node knows both its neighbours"},"revision":1},{"id":"d561196c-25c0-75b3-a870-66fff959fcd6","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Structure of a node and traversal in both directions"}]},"revision":1},{"id":"4ee0667a-5678-7053-8870-875f89c3ef61","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Linking two nodes now means setting "},{"type":"text","text":"two","marks":[{"type":"bold"}]},{"type":"text","text":" pointers: "},{"type":"text","text":"a.next = b","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"and","marks":[{"type":"italic"}]},{"type":"text","text":" "},{"type":"text","text":"b.prev = a","marks":[{"type":"code"}]},{"type":"text","text":". Forgetting one of them is the classic doubly-linked bug — the list looks fine going forward and breaks going backward. Traversal backwards starts from the last node and follows "},{"type":"text","text":"prev","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"57ccd750-45f2-740d-95aa-5b5f2f1e1e63","type":"code","position":"a5","content":{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.prev = None\n        self.next = None\n\ndef show(head):\n    parts, curr, last = [], head, None\n    while curr is not None:\n        parts.append(str(curr.data))\n        last = curr                          # remember the tail for the way back\n        curr = curr.next\n    print(\"forward:\", \" <-> \".join(parts))\n    parts, curr = [], last\n    while curr is not None:                  # walk back along prev\n        parts.append(str(curr.data))\n        curr = curr.prev\n    print(\"backward:\", \" <-> \".join(parts))\n\nhead = Node(10); temp1 = Node(20); temp2 = Node(30)\nhead.next = temp1;  temp1.prev = head        # every link is set in both directions\ntemp1.next = temp2; temp2.prev = temp1\nshow(head)","filename":"Python"},"revision":1},{"id":"8e57ead4-e502-7c40-8339-fe3a21d217cb","type":"code","position":"a6","content":{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int data; Node* prev; Node* next;\n    Node(int d) : data(d), prev(nullptr), next(nullptr) {}\n};\n\nvoid show(Node* head) {\n    Node* last = nullptr;\n    cout << \"forward:\";\n    for (Node* curr = head; curr; curr = curr->next) {\n        cout << (curr == head ? \" \" : \" <-> \") << curr->data;\n        last = curr;                             // remember the tail for the way back\n    }\n    cout << \"\\nbackward:\";\n    for (Node* curr = last; curr; curr = curr->prev)   // walk back along prev\n        cout << (curr == last ? \" \" : \" <-> \") << curr->data;\n    cout << \"\\n\";\n}\n\nint main() {\n    Node* head = new Node(10); Node* temp1 = new Node(20); Node* temp2 = new Node(30);\n    head->next = temp1;  temp1->prev = head;     // every link is set in both directions\n    temp1->next = temp2; temp2->prev = temp1;\n    show(head);\n}","filename":"C++"},"revision":1},{"id":"083c2a84-79d8-7a38-806f-fbe4e18a49fa","type":"code","position":"a7","content":{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node prev, next;\n        Node(int d) { data = d; }\n    }\n\n    static void show(Node head) {\n        StringBuilder sb = new StringBuilder(\"forward:\");\n        Node last = null;\n        for (Node curr = head; curr != null; curr = curr.next) {\n            sb.append(curr == head ? \" \" : \" <-> \").append(curr.data);\n            last = curr;                             // remember the tail for the way back\n        }\n        System.out.println(sb);\n        sb = new StringBuilder(\"backward:\");\n        for (Node curr = last; curr != null; curr = curr.prev)   // walk back along prev\n            sb.append(curr == last ? \" \" : \" <-> \").append(curr.data);\n        System.out.println(sb);\n    }\n\n    public static void main(String[] args) {\n        Node head = new Node(10), temp1 = new Node(20), temp2 = new Node(30);\n        head.next = temp1;  temp1.prev = head;       // every link is set in both directions\n        temp1.next = temp2; temp2.prev = temp1;\n        show(head);\n    }\n}","filename":"Java"},"revision":1},{"id":"51366be3-8429-77c9-8129-db4ab9c785a2","type":"code","position":"a8","content":{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.prev = null; this.next = null; }\n}\n\nfunction show(head) {\n    const parts = [];\n    let last = null;\n    for (let curr = head; curr !== null; curr = curr.next) {\n        parts.push(curr.data);\n        last = curr;                                 // remember the tail for the way back\n    }\n    console.log(\"forward:\", parts.join(\" <-> \"));\n    const back = [];\n    for (let curr = last; curr !== null; curr = curr.prev)   // walk back along prev\n        back.push(curr.data);\n    console.log(\"backward:\", back.join(\" <-> \"));\n}\n\nconst head = new Node(10), temp1 = new Node(20), temp2 = new Node(30);\nhead.next = temp1;  temp1.prev = head;               // every link is set in both directions\ntemp1.next = temp2; temp2.prev = temp1;\nshow(head);","filename":"JavaScript"},"revision":1},{"id":"eafc01ea-044b-758a-ad58-91eac74dcced","type":"code","position":"a9","content":{"language":"text","code":"forward: 10 <-> 20 <-> 30\nbackward: 30 <-> 20 <-> 10","filename":"Output"},"revision":1},{"id":"09f9d84f-25b2-786f-b6a3-47ca3337de4c","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) traversal · Space O(n) for n nodes"}]}]}},"revision":1},{"id":"d65358b1-98f7-7cbb-a648-c7c483a833a1","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Advantages and disadvantages"}]},"revision":1},{"id":"35f85fcc-2856-75e7-bef4-c81c30940c4a","type":"callout","position":"aC","content":{"variant":"note","title":"Traversal in both directions","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Walk forward with "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":", backward with "},{"type":"text","text":"prev","marks":[{"type":"code"}]},{"type":"text","text":" — browsers'' back/forward history, text editor cursors, undo/redo."}]}]}},"revision":1},{"id":"65fa8046-aaf3-78fd-b807-e3f58c442d99","type":"callout","position":"aD","content":{"variant":"note","title":"Delete a node in O(1) given its reference","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"node.prev.next = node.next; node.next.prev = node.prev","marks":[{"type":"code"}]},{"type":"text","text":". A singly linked list would first need an O(n) walk to find the predecessor."}]}]}},"revision":1},{"id":"0fcd6a72-1d6d-7b11-a636-1c845b42aab6","type":"callout","position":"aE","content":{"variant":"note","title":"Insert / delete before a given node","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The predecessor is one pointer away, so inserting "},{"type":"text","text":"before","marks":[{"type":"italic"}]},{"type":"text","text":" is as cheap as inserting after."}]}]}},"revision":1},{"id":"b051f978-72b4-79a1-9f30-be8c46cd8798","type":"callout","position":"aF","content":{"variant":"note","title":"O(1) at both ends with a tail","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Keeping "},{"type":"text","text":"tail","marks":[{"type":"code"}]},{"type":"text","text":" makes insert and delete at "},{"type":"text","text":"both","marks":[{"type":"bold"}]},{"type":"text","text":" ends O(1) — the basis of "},{"type":"text","text":"deque","marks":[{"type":"code"}]},{"type":"text","text":" and the LRU cache."}]}]}},"revision":1},{"id":"d687618c-b3c4-71f1-8350-d7fa318a911b","type":"callout","position":"aG","content":{"variant":"note","title":"Extra space","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A second pointer per node: 16 bytes of links per element on a 64-bit machine."}]}]}},"revision":1},{"id":"0326a2a9-d4b5-718d-a6ff-7adf506dcb89","type":"callout","position":"aH","content":{"variant":"note","title":"More complex code","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every operation updates up to four pointers and must keep "},{"type":"text","text":"prev","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" consistent; more special cases for the head and tail."}]}]}},"revision":1},{"id":"e3a1aade-23cd-72cf-8c74-9bfd90179710","type":"table","position":"aI","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Operation"}],[{"type":"text","text":"Singly linked"}],[{"type":"text","text":"Doubly linked"}],[{"type":"text","text":"Why the difference"}]],[[{"type":"text","text":"Insert at beginning"}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"Both just re-point the head; doubly also sets the old head''s "},{"type":"text","text":"prev","marks":[{"type":"code"}]},{"type":"text","text":"."}]],[[{"type":"text","text":"Insert at end"}],[{"type":"text","text":"O(n) / O(1) with tail"}],[{"type":"text","text":"O(n) / O(1) with tail"}],[{"type":"text","text":"Same walk unless a tail is kept."}]],[[{"type":"text","text":"Delete head"}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"Doubly also clears the new head''s "},{"type":"text","text":"prev","marks":[{"type":"code"}]},{"type":"text","text":"."}]],[[{"type":"text","text":"Delete last"}],[{"type":"text","text":"O(n) even with tail"}],[{"type":"text","text":"O(1) with tail","marks":[{"type":"bold"}]}],[{"type":"text","text":"The tail''s "},{"type":"text","text":"prev","marks":[{"type":"code"}]},{"type":"text","text":" gives the new last node for free."}]],[[{"type":"text","text":"Delete a given node"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"O(1)","marks":[{"type":"bold"}]}],[{"type":"text","text":"The predecessor is "},{"type":"text","text":"node.prev","marks":[{"type":"code"}]},{"type":"text","text":"; singly must search for it."}]],[[{"type":"text","text":"Insert before a given node"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"O(1)","marks":[{"type":"bold"}]}],[{"type":"text","text":"Same reason."}]],[[{"type":"text","text":"Reverse"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"Doubly: swap "},{"type":"text","text":"prev","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" in every node."}]]]},"revision":1},{"id":"acc18966-3924-7251-92cc-46dc72b1e7b5","type":"heading","position":"aJ","content":{"level":1,"content":[{"type":"text","text":"Insert at the beginning"}]},"revision":1},{"id":"76af5772-2d77-74a4-b227-a51a96c6cdf0","type":"callout","position":"aK","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = 10 <-> 20 <-> 30, insert 5 at the beginning","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"5 <-> 10 <-> 20 <-> 30","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"19ef8f3b-3640-768e-81dd-f8387e89d8c5","type":"callout","position":"aL","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Point the new node''s "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" at the old head, point the old head''s "},{"type":"text","text":"prev","marks":[{"type":"code"}]},{"type":"text","text":" back at the new node, and return the new node as head. Two pointer writes — O(1). The empty list needs a guard: there is no old head whose "},{"type":"text","text":"prev","marks":[{"type":"code"}]},{"type":"text","text":" could be set (the original notes crashed on this case)."}]}]}},"revision":1},{"id":"46fbfc09-04c3-765d-9eaf-f4b4fc24d13e","type":"code","position":"aM","content":{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.prev = None\n        self.next = None\n\ndef insert_at_beginning(head, data):\n    temp = Node(data)\n    temp.next = head                 # new → old head\n    if head is not None:\n        head.prev = temp             # old head → new (guard the empty list)\n    return temp\n\ndef show(head):\n    parts = []\n    while head:\n        parts.append(str(head.data)); head = head.next\n    print(\" <-> \".join(parts))\n\nhead = Node(10); t1 = Node(20); t2 = Node(30)\nhead.next = t1; t1.prev = head; t1.next = t2; t2.prev = t1\nshow(head)\nhead = insert_at_beginning(head, 5); show(head)\nhead = insert_at_beginning(head, 1); show(head)","filename":"Python"},"revision":1},{"id":"f50c0028-3d3d-7722-8d53-e59a32fcba2d","type":"code","position":"aN","content":{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int data; Node* prev; Node* next;\n    Node(int d) : data(d), prev(nullptr), next(nullptr) {}\n};\n\nNode* insertAtBeginning(Node* head, int data) {\n    Node* temp = new Node(data);\n    temp->next = head;               // new → old head\n    if (head) head->prev = temp;     // old head → new (guard the empty list)\n    return temp;\n}\n\nvoid show(Node* head) {\n    for (; head; head = head->next) cout << head->data << (head->next ? \" <-> \" : \"\\n\");\n}\n\nint main() {\n    Node* head = new Node(10); Node* t1 = new Node(20); Node* t2 = new Node(30);\n    head->next = t1; t1->prev = head; t1->next = t2; t2->prev = t1;\n    show(head);\n    head = insertAtBeginning(head, 5); show(head);\n    head = insertAtBeginning(head, 1); show(head);\n}","filename":"C++"},"revision":1},{"id":"e3e2af79-734e-75ca-b68d-9ef73da98438","type":"code","position":"aO","content":{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node prev, next;\n        Node(int d) { data = d; }\n    }\n\n    static Node insertAtBeginning(Node head, int data) {\n        Node temp = new Node(data);\n        temp.next = head;                    // new → old head\n        if (head != null) head.prev = temp;  // old head → new (guard the empty list)\n        return temp;\n    }\n\n    static void show(Node head) {\n        StringBuilder sb = new StringBuilder();\n        for (; head != null; head = head.next) sb.append(head.data).append(head.next != null ? \" <-> \" : \"\");\n        System.out.println(sb);\n    }\n\n    public static void main(String[] args) {\n        Node head = new Node(10), t1 = new Node(20), t2 = new Node(30);\n        head.next = t1; t1.prev = head; t1.next = t2; t2.prev = t1;\n        show(head);\n        head = insertAtBeginning(head, 5); show(head);\n        head = insertAtBeginning(head, 1); show(head);\n    }\n}","filename":"Java"},"revision":1},{"id":"485976e9-919b-72b4-93a4-448e48e0193b","type":"code","position":"aP","content":{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.prev = null; this.next = null; }\n}\n\nfunction insertAtBeginning(head, data) {\n    const temp = new Node(data);\n    temp.next = head;                        // new → old head\n    if (head !== null) head.prev = temp;     // old head → new (guard the empty list)\n    return temp;\n}\n\nfunction show(head) {\n    const parts = [];\n    for (; head !== null; head = head.next) parts.push(head.data);\n    console.log(parts.join(\" <-> \"));\n}\n\nlet head = new Node(10), t1 = new Node(20), t2 = new Node(30);\nhead.next = t1; t1.prev = head; t1.next = t2; t2.prev = t1;\nshow(head);\nhead = insertAtBeginning(head, 5); show(head);\nhead = insertAtBeginning(head, 1); show(head);","filename":"JavaScript"},"revision":1},{"id":"f64f21ea-9c85-7e8f-ad07-b8f47feab877","type":"code","position":"aQ","content":{"language":"text","code":"10 <-> 20 <-> 30\n5 <-> 10 <-> 20 <-> 30\n1 <-> 5 <-> 10 <-> 20 <-> 30","filename":"Output"},"revision":1},{"id":"9f8d2950-0742-76b5-8c5f-76c7c52b6689","type":"text","position":"aR","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(1) · Space O(1)"}]}]}},"revision":1},{"id":"076d9f2c-b2a1-7c81-bccb-34286783da85","type":"heading","position":"aS","content":{"level":1,"content":[{"type":"text","text":"Insert at the end"}]},"revision":1},{"id":"aa97c0ea-085f-7f87-856b-67bee33bcd4b","type":"callout","position":"aT","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = 10 <-> 20 <-> 30, insert 40 at the end","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 <-> 20 <-> 30 <-> 40","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = empty, insert 40","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"40","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"991c25ad-b61e-7796-a965-141628b4b05a","type":"callout","position":"aU","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Walk to the last node, link it forward to the new node and link the new node back with "},{"type":"text","text":"prev","marks":[{"type":"code"}]},{"type":"text","text":". O(n) because of the walk; a class that stores "},{"type":"text","text":"tail","marks":[{"type":"code"}]},{"type":"text","text":" does the same two writes in O(1)."}]}]}},"revision":1},{"id":"5c4e7686-079e-7b1f-9f70-462a429bd2d3","type":"code","position":"aV","content":{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.prev = None\n        self.next = None\n\ndef insert_end(head, x):\n    temp = Node(x)\n    if head is None:\n        return temp                      # empty list: new node is the head\n    curr = head\n    while curr.next is not None:         # O(n) walk to the last node\n        curr = curr.next\n    curr.next = temp                     # last → new\n    temp.prev = curr                     # new → last\n    return head\n\ndef show(head):\n    parts = []\n    while head:\n        parts.append(str(head.data)); head = head.next\n    print(\" <-> \".join(parts))\n\nhead = Node(10); t1 = Node(20); t2 = Node(30)\nhead.next = t1; t1.prev = head; t1.next = t2; t2.prev = t1\nhead = insert_end(head, 40); show(head)\nempty = insert_end(None, 40); show(empty)","filename":"Python"},"revision":1},{"id":"6060a7ee-a389-77ff-99a2-28d833f0c268","type":"code","position":"aW","content":{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int data; Node* prev; Node* next;\n    Node(int d) : data(d), prev(nullptr), next(nullptr) {}\n};\n\nNode* insertEnd(Node* head, int x) {\n    Node* temp = new Node(x);\n    if (!head) return temp;                  // empty list: new node is the head\n    Node* curr = head;\n    while (curr->next) curr = curr->next;    // O(n) walk to the last node\n    curr->next = temp;                       // last → new\n    temp->prev = curr;                       // new → last\n    return head;\n}\n\nvoid show(Node* head) {\n    for (; head; head = head->next) cout << head->data << (head->next ? \" <-> \" : \"\\n\");\n}\n\nint main() {\n    Node* head = new Node(10); Node* t1 = new Node(20); Node* t2 = new Node(30);\n    head->next = t1; t1->prev = head; t1->next = t2; t2->prev = t1;\n    head = insertEnd(head, 40); show(head);\n    Node* empty = insertEnd(nullptr, 40); show(empty);\n}","filename":"C++"},"revision":1},{"id":"3a1d7067-5212-736b-b4a9-4dd6da22ab73","type":"code","position":"aX","content":{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node prev, next;\n        Node(int d) { data = d; }\n    }\n\n    static Node insertEnd(Node head, int x) {\n        Node temp = new Node(x);\n        if (head == null) return temp;               // empty list: new node is the head\n        Node curr = head;\n        while (curr.next != null) curr = curr.next;  // O(n) walk to the last node\n        curr.next = temp;                            // last → new\n        temp.prev = curr;                            // new → last\n        return head;\n    }\n\n    static void show(Node head) {\n        StringBuilder sb = new StringBuilder();\n        for (; head != null; head = head.next) sb.append(head.data).append(head.next != null ? \" <-> \" : \"\");\n        System.out.println(sb);\n    }\n\n    public static void main(String[] args) {\n        Node head = new Node(10), t1 = new Node(20), t2 = new Node(30);\n        head.next = t1; t1.prev = head; t1.next = t2; t2.prev = t1;\n        head = insertEnd(head, 40); show(head);\n        Node empty = insertEnd(null, 40); show(empty);\n    }\n}","filename":"Java"},"revision":1},{"id":"242a03c7-e8b2-706a-82c9-464b5ce7f598","type":"code","position":"aY","content":{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.prev = null; this.next = null; }\n}\n\nfunction insertEnd(head, x) {\n    const temp = new Node(x);\n    if (head === null) return temp;                  // empty list: new node is the head\n    let curr = head;\n    while (curr.next !== null) curr = curr.next;     // O(n) walk to the last node\n    curr.next = temp;                                // last → new\n    temp.prev = curr;                                // new → last\n    return head;\n}\n\nfunction show(head) {\n    const parts = [];\n    for (; head !== null; head = head.next) parts.push(head.data);\n    console.log(parts.join(\" <-> \"));\n}\n\nlet head = new Node(10), t1 = new Node(20), t2 = new Node(30);\nhead.next = t1; t1.prev = head; t1.next = t2; t2.prev = t1;\nhead = insertEnd(head, 40); show(head);\nconst empty = insertEnd(null, 40); show(empty);","filename":"JavaScript"},"revision":1},{"id":"5f1b49b3-bc65-7d66-a58a-56f595e888a7","type":"code","position":"aZ","content":{"language":"text","code":"10 <-> 20 <-> 30 <-> 40\n40","filename":"Output"},"revision":1},{"id":"576c40d7-a57a-7ae4-8cce-6b74e7f6c26b","type":"text","position":"aa","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) — O(1) with a tail pointer · Space O(1)"}]}]}},"revision":1},{"id":"b6c0084d-7324-7fd1-8a15-60ed3530b531","type":"heading","position":"ab","content":{"level":1,"content":[{"type":"text","text":"Delete the head"}]},"revision":1},{"id":"6a17e161-140e-70f9-b152-5604c013903a","type":"callout","position":"ac","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = 10 <-> 20 <-> 30","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"20 <-> 30","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = 10","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"empty","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"7bb6a151-79dd-7c5f-89bb-7a1bc9cc8a82","type":"callout","position":"ad","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Move the head to the second node and clear its "},{"type":"text","text":"prev","marks":[{"type":"code"}]},{"type":"text","text":" — without that step the new head would still point back at a node that is no longer in the list. A one-node list becomes empty."}]}]}},"revision":1},{"id":"462bb23e-26a4-7453-ab63-0903fcda5036","type":"code","position":"ae","content":{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.prev = None\n        self.next = None\n\ndef delete_head(head):\n    if head is None or head.next is None:\n        return None                      # 0 or 1 node → empty\n    head = head.next\n    head.prev = None                     # the new head has no predecessor\n    return head\n\ndef show(head):\n    parts = []\n    while head:\n        parts.append(str(head.data)); head = head.next\n    print(\" <-> \".join(parts) if parts else \"empty\")\n\nhead = Node(10); t1 = Node(20); t2 = Node(30)\nhead.next = t1; t1.prev = head; t1.next = t2; t2.prev = t1\nfor _ in range(3):\n    head = delete_head(head)\n    print(\"after delete head: \", end=\"\"); show(head)","filename":"Python"},"revision":1},{"id":"7c440a57-6092-7095-978f-72d9a11a9942","type":"code","position":"af","content":{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int data; Node* prev; Node* next;\n    Node(int d) : data(d), prev(nullptr), next(nullptr) {}\n};\n\nNode* deleteHead(Node* head) {\n    if (!head) return nullptr;\n    if (!head->next) { delete head; return nullptr; }   // 1 node → empty\n    Node* newHead = head->next;\n    newHead->prev = nullptr;                 // the new head has no predecessor\n    delete head;\n    return newHead;\n}\n\nvoid show(Node* head) {\n    if (!head) { cout << \"empty\\n\"; return; }\n    for (; head; head = head->next) cout << head->data << (head->next ? \" <-> \" : \"\\n\");\n}\n\nint main() {\n    Node* head = new Node(10); Node* t1 = new Node(20); Node* t2 = new Node(30);\n    head->next = t1; t1->prev = head; t1->next = t2; t2->prev = t1;\n    for (int i = 0; i < 3; i++) {\n        head = deleteHead(head);\n        cout << \"after delete head: \"; show(head);\n    }\n}","filename":"C++"},"revision":1},{"id":"d249f007-3c4e-7492-9783-1498b7d19fb6","type":"code","position":"ag","content":{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node prev, next;\n        Node(int d) { data = d; }\n    }\n\n    static Node deleteHead(Node head) {\n        if (head == null || head.next == null) return null;   // 0 or 1 node → empty\n        head = head.next;\n        head.prev = null;                        // the new head has no predecessor\n        return head;\n    }\n\n    static void show(Node head) {\n        if (head == null) { System.out.println(\"empty\"); return; }\n        StringBuilder sb = new StringBuilder();\n        for (; head != null; head = head.next) sb.append(head.data).append(head.next != null ? \" <-> \" : \"\");\n        System.out.println(sb);\n    }\n\n    public static void main(String[] args) {\n        Node head = new Node(10), t1 = new Node(20), t2 = new Node(30);\n        head.next = t1; t1.prev = head; t1.next = t2; t2.prev = t1;\n        for (int i = 0; i < 3; i++) {\n            head = deleteHead(head);\n            System.out.print(\"after delete head: \"); show(head);\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"56f0c286-2d2a-7034-8b10-30c5bb9e2ea4","type":"code","position":"ah","content":{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.prev = null; this.next = null; }\n}\n\nfunction deleteHead(head) {\n    if (head === null || head.next === null) return null;    // 0 or 1 node → empty\n    head = head.next;\n    head.prev = null;                            // the new head has no predecessor\n    return head;\n}\n\nfunction show(head) {\n    const parts = [];\n    for (; head !== null; head = head.next) parts.push(head.data);\n    console.log(parts.length ? parts.join(\" <-> \") : \"empty\");\n}\n\nlet head = new Node(10), t1 = new Node(20), t2 = new Node(30);\nhead.next = t1; t1.prev = head; t1.next = t2; t2.prev = t1;\nfor (let i = 0; i < 3; i++) {\n    head = deleteHead(head);\n    process.stdout.write(\"after delete head: \"); show(head);\n}","filename":"JavaScript"},"revision":1},{"id":"452852fb-030c-72a6-a83f-d3fb9347462c","type":"code","position":"ai","content":{"language":"text","code":"after delete head: 20 <-> 30\nafter delete head: 30\nafter delete head: empty","filename":"Output"},"revision":1},{"id":"f689dc8f-21e8-7419-b6fb-97f5d19b6aa7","type":"text","position":"aj","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(1) · Space O(1)"}]}]}},"revision":1},{"id":"297e2324-325e-7889-9683-11671add947b","type":"heading","position":"ak","content":{"level":1,"content":[{"type":"text","text":"Delete the last node"}]},"revision":1},{"id":"07c7d2a8-8e90-73d5-8f0b-b21f888f631d","type":"callout","position":"al","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = 10 <-> 20 <-> 30","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 <-> 20","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = 10","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"empty","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"6aa61b78-d30a-7958-a737-756f5a8550cf","type":"callout","position":"am","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Walk to the last node and cut it off via "},{"type":"text","text":"last.prev.next = None","marks":[{"type":"code"}]},{"type":"text","text":". Thanks to "},{"type":"text","text":"prev","marks":[{"type":"code"}]},{"type":"text","text":" the predecessor is one hop away; the only O(n) part is reaching the last node, which disappears when a "},{"type":"text","text":"tail","marks":[{"type":"code"}]},{"type":"text","text":" pointer is kept — the operation a singly linked list cannot do in O(1) even with a tail."}]}]}},"revision":1},{"id":"30bf044a-2de7-79fc-a186-b3c7b3ba85ca","type":"code","position":"an","content":{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.prev = None\n        self.next = None\n\ndef delete_last(head):\n    if head is None or head.next is None:\n        return None                      # 0 or 1 node → empty\n    curr = head\n    while curr.next is not None:         # walk to the last node (O(1) with a tail pointer)\n        curr = curr.next\n    curr.prev.next = None                # predecessor is one hop away via prev\n    return head\n\ndef show(head):\n    parts = []\n    while head:\n        parts.append(str(head.data)); head = head.next\n    print(\" <-> \".join(parts) if parts else \"empty\")\n\nhead = Node(10); t1 = Node(20); t2 = Node(30)\nhead.next = t1; t1.prev = head; t1.next = t2; t2.prev = t1\nfor _ in range(3):\n    head = delete_last(head)\n    print(\"after delete last: \", end=\"\"); show(head)","filename":"Python"},"revision":1},{"id":"c10eaee5-ed8a-7ad3-aa40-330b367c5509","type":"code","position":"ao","content":{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int data; Node* prev; Node* next;\n    Node(int d) : data(d), prev(nullptr), next(nullptr) {}\n};\n\nNode* deleteLast(Node* head) {\n    if (!head) return nullptr;\n    if (!head->next) { delete head; return nullptr; }   // 1 node → empty\n    Node* curr = head;\n    while (curr->next) curr = curr->next;    // walk to the last node (O(1) with a tail pointer)\n    curr->prev->next = nullptr;              // predecessor is one hop away via prev\n    delete curr;\n    return head;\n}\n\nvoid show(Node* head) {\n    if (!head) { cout << \"empty\\n\"; return; }\n    for (; head; head = head->next) cout << head->data << (head->next ? \" <-> \" : \"\\n\");\n}\n\nint main() {\n    Node* head = new Node(10); Node* t1 = new Node(20); Node* t2 = new Node(30);\n    head->next = t1; t1->prev = head; t1->next = t2; t2->prev = t1;\n    for (int i = 0; i < 3; i++) {\n        head = deleteLast(head);\n        cout << \"after delete last: \"; show(head);\n    }\n}","filename":"C++"},"revision":1},{"id":"477fed52-96c6-7944-bcc9-389b5d6550a4","type":"code","position":"ap","content":{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node prev, next;\n        Node(int d) { data = d; }\n    }\n\n    static Node deleteLast(Node head) {\n        if (head == null || head.next == null) return null;   // 0 or 1 node → empty\n        Node curr = head;\n        while (curr.next != null) curr = curr.next;   // walk to the last node (O(1) with a tail pointer)\n        curr.prev.next = null;                        // predecessor is one hop away via prev\n        return head;\n    }\n\n    static void show(Node head) {\n        if (head == null) { System.out.println(\"empty\"); return; }\n        StringBuilder sb = new StringBuilder();\n        for (; head != null; head = head.next) sb.append(head.data).append(head.next != null ? \" <-> \" : \"\");\n        System.out.println(sb);\n    }\n\n    public static void main(String[] args) {\n        Node head = new Node(10), t1 = new Node(20), t2 = new Node(30);\n        head.next = t1; t1.prev = head; t1.next = t2; t2.prev = t1;\n        for (int i = 0; i < 3; i++) {\n            head = deleteLast(head);\n            System.out.print(\"after delete last: \"); show(head);\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"ba7e1c41-44a6-7465-9f36-69f2b35dc057","type":"code","position":"aq","content":{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.prev = null; this.next = null; }\n}\n\nfunction deleteLast(head) {\n    if (head === null || head.next === null) return null;    // 0 or 1 node → empty\n    let curr = head;\n    while (curr.next !== null) curr = curr.next;     // walk to the last node (O(1) with a tail pointer)\n    curr.prev.next = null;                           // predecessor is one hop away via prev\n    return head;\n}\n\nfunction show(head) {\n    const parts = [];\n    for (; head !== null; head = head.next) parts.push(head.data);\n    console.log(parts.length ? parts.join(\" <-> \") : \"empty\");\n}\n\nlet head = new Node(10), t1 = new Node(20), t2 = new Node(30);\nhead.next = t1; t1.prev = head; t1.next = t2; t2.prev = t1;\nfor (let i = 0; i < 3; i++) {\n    head = deleteLast(head);\n    process.stdout.write(\"after delete last: \"); show(head);\n}","filename":"JavaScript"},"revision":1},{"id":"a0e497fc-243d-7333-81a9-c4ab3621d92d","type":"code","position":"ar","content":{"language":"text","code":"after delete last: 10 <-> 20\nafter delete last: 10\nafter delete last: empty","filename":"Output"},"revision":1},{"id":"e2f179ca-b840-78a9-93a9-7cdd324b4233","type":"text","position":"as","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) — O(1) with a tail pointer · Space O(1)"}]}]}},"revision":1},{"id":"0bda5ff3-b85b-79b2-ad50-ae0c9ad752e3","type":"heading","position":"at","content":{"level":1,"content":[{"type":"text","text":"Delete a node given its reference"}]},"revision":1},{"id":"e54a2958-e879-71e6-95a1-ec1cf7364db8","type":"callout","position":"au","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = 10 <-> 20 <-> 30, node = the node holding 20","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 <-> 30","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"4d1a953e-4350-73d7-817a-03e4f84b09cb","type":"callout","position":"av","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"This is the operation that justifies the extra pointer. With "},{"type":"text","text":"node.prev","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"node.next","marks":[{"type":"code"}]},{"type":"text","text":" both known, unlink in O(1): the predecessor''s "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" skips to the successor and the successor''s "},{"type":"text","text":"prev","marks":[{"type":"code"}]},{"type":"text","text":" skips back to the predecessor. Guard the ends: if "},{"type":"text","text":"node","marks":[{"type":"code"}]},{"type":"text","text":" is the head there is no predecessor (the head moves), if it is the tail there is no successor."}]}]}},"revision":1},{"id":"c2d68810-fc49-72d5-9e25-df25289e8575","type":"code","position":"aw","content":{"language":"text","code":"before:   [10] ◀──▶ [20] ◀──▶ [30]\n                    node\n\nnode.prev.next = node.next     [10] ───────▶ [30]       (10''s next skips 20)\nnode.next.prev = node.prev     [10] ◀─────── [30]       (30''s prev skips 20)\n\nafter:    [10] ◀──▶ [30]","filename":"Deleting a node in O(1): two pointer writes on its neighbours"},"revision":1},{"id":"ba5e3d65-c19b-7445-a95f-889a6620252b","type":"code","position":"ax","content":{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.prev = None\n        self.next = None\n\ndef delete_node(head, node):\n    if node.prev is not None:\n        node.prev.next = node.next       # predecessor skips over node\n    else:\n        head = node.next                 # node was the head\n    if node.next is not None:\n        node.next.prev = node.prev       # successor skips back over node\n    return head\n\ndef show(head):\n    parts = []\n    while head:\n        parts.append(str(head.data)); head = head.next\n    print(\" <-> \".join(parts) if parts else \"empty\")\n\nhead = Node(10); t1 = Node(20); t2 = Node(30)\nhead.next = t1; t1.prev = head; t1.next = t2; t2.prev = t1\nshow(head)\nhead = delete_node(head, t1); print(\"delete node 20: \", end=\"\"); show(head)\nhead = delete_node(head, head); print(\"delete node 10 (head): \", end=\"\"); show(head)","filename":"Python"},"revision":1},{"id":"606d9746-7e16-7ecf-9ff2-2b39b14321dd","type":"code","position":"ay","content":{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int data; Node* prev; Node* next;\n    Node(int d) : data(d), prev(nullptr), next(nullptr) {}\n};\n\nNode* deleteNode(Node* head, Node* node) {\n    if (node->prev) node->prev->next = node->next;   // predecessor skips over node\n    else head = node->next;                          // node was the head\n    if (node->next) node->next->prev = node->prev;   // successor skips back over node\n    delete node;\n    return head;\n}\n\nvoid show(Node* head) {\n    if (!head) { cout << \"empty\\n\"; return; }\n    for (; head; head = head->next) cout << head->data << (head->next ? \" <-> \" : \"\\n\");\n}\n\nint main() {\n    Node* head = new Node(10); Node* t1 = new Node(20); Node* t2 = new Node(30);\n    head->next = t1; t1->prev = head; t1->next = t2; t2->prev = t1;\n    show(head);\n    head = deleteNode(head, t1); cout << \"delete node 20: \"; show(head);\n    head = deleteNode(head, head); cout << \"delete node 10 (head): \"; show(head);\n}","filename":"C++"},"revision":1},{"id":"73308575-329a-774e-affc-1ff7321e52d8","type":"code","position":"az","content":{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node prev, next;\n        Node(int d) { data = d; }\n    }\n\n    static Node deleteNode(Node head, Node node) {\n        if (node.prev != null) node.prev.next = node.next;   // predecessor skips over node\n        else head = node.next;                               // node was the head\n        if (node.next != null) node.next.prev = node.prev;   // successor skips back over node\n        return head;\n    }\n\n    static void show(Node head) {\n        if (head == null) { System.out.println(\"empty\"); return; }\n        StringBuilder sb = new StringBuilder();\n        for (; head != null; head = head.next) sb.append(head.data).append(head.next != null ? \" <-> \" : \"\");\n        System.out.println(sb);\n    }\n\n    public static void main(String[] args) {\n        Node head = new Node(10), t1 = new Node(20), t2 = new Node(30);\n        head.next = t1; t1.prev = head; t1.next = t2; t2.prev = t1;\n        show(head);\n        head = deleteNode(head, t1); System.out.print(\"delete node 20: \"); show(head);\n        head = deleteNode(head, head); System.out.print(\"delete node 10 (head): \"); show(head);\n    }\n}","filename":"Java"},"revision":1},{"id":"94e0bdf4-fc64-7783-be49-d0eb72abb576","type":"code","position":"b00","content":{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.prev = null; this.next = null; }\n}\n\nfunction deleteNode(head, node) {\n    if (node.prev !== null) node.prev.next = node.next;   // predecessor skips over node\n    else head = node.next;                                // node was the head\n    if (node.next !== null) node.next.prev = node.prev;   // successor skips back over node\n    return head;\n}\n\nfunction show(head) {\n    const parts = [];\n    for (; head !== null; head = head.next) parts.push(head.data);\n    console.log(parts.length ? parts.join(\" <-> \") : \"empty\");\n}\n\nlet head = new Node(10), t1 = new Node(20), t2 = new Node(30);\nhead.next = t1; t1.prev = head; t1.next = t2; t2.prev = t1;\nshow(head);\nhead = deleteNode(head, t1); process.stdout.write(\"delete node 20: \"); show(head);\nhead = deleteNode(head, head); process.stdout.write(\"delete node 10 (head): \"); show(head);","filename":"JavaScript"},"revision":1},{"id":"5ef577fd-a28e-7ae7-8518-a910ea9ef7a6","type":"code","position":"b01","content":{"language":"text","code":"10 <-> 20 <-> 30\ndelete node 20: 10 <-> 30\ndelete node 10 (head): 30","filename":"Output"},"revision":1},{"id":"d4bc1bbc-027e-720b-8bd2-35e58d31f012","type":"text","position":"b02","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(1) · Space O(1)"}]}]}},"revision":1},{"id":"09e34c8d-8f24-7e27-a71b-3e6b4adc79d0","type":"callout","position":"b03","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"This is exactly how an "},{"type":"text","text":"LRU cache","marks":[{"type":"bold"}]},{"type":"text","text":" evicts and promotes entries: a hash map gives the node for a key in O(1), and the doubly linked list moves that node to the front in O(1). Neither structure alone can do both."}]}]}},"revision":1},{"id":"6760906f-688a-7033-afb5-261d2e7d38cc","type":"heading","position":"b04","content":{"level":1,"content":[{"type":"text","text":"Reverse a doubly linked list"}]},"revision":1},{"id":"36818fe3-da19-7091-8ff6-f8e031d4f5e1","type":"callout","position":"b05","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = 10 <-> 20 <-> 30","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"30 <-> 20 <-> 10","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"a9c9e3bb-a7ff-7475-9e62-dd21b1c2636f","type":"callout","position":"b06","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Reversing means every node''s "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" becomes its "},{"type":"text","text":"prev","marks":[{"type":"code"}]},{"type":"text","text":" and vice versa — so "},{"type":"text","text":"swap the two pointers in each node","marks":[{"type":"bold"}]},{"type":"text","text":". After the swap, the "},{"type":"text","text":"old","marks":[{"type":"italic"}]},{"type":"text","text":" "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" is reachable as "},{"type":"text","text":"curr.prev","marks":[{"type":"code"}]},{"type":"text","text":", which is how the loop advances. The last node visited is the new head."}]}]}},"revision":1},{"id":"69d68981-5201-726e-bde7-a21b11c0d42a","type":"text","position":"b07","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Walk the list","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"curr = head","marks":[{"type":"code"}]},{"type":"text","text":", remembering the node just processed in "},{"type":"text","text":"prev","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Swap in place","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"curr.next, curr.prev = curr.prev, curr.next","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Advance","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"curr = curr.prev","marks":[{"type":"code"}]},{"type":"text","text":" — that field now holds the old "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Finish","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"When "},{"type":"text","text":"curr","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"prev","marks":[{"type":"code"}]},{"type":"text","text":" is the last node processed: the new head."}]}]}]}]}},"revision":1},{"id":"71e9e77e-8605-75fe-86a4-0710464ca084","type":"code","position":"b08","content":{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.prev = None\n        self.next = None\n\ndef reverse_dll(head):\n    prev, curr = None, head\n    while curr is not None:\n        prev = curr\n        curr.next, curr.prev = curr.prev, curr.next   # swap the two links\n        curr = curr.prev                              # old next now lives in prev\n    return prev                                       # last node processed = new head\n\ndef show(label, head):\n    parts = []\n    while head:\n        parts.append(str(head.data)); head = head.next\n    print(label + \":\", \" <-> \".join(parts))\n\nhead = Node(10); t1 = Node(20); t2 = Node(30)\nhead.next = t1; t1.prev = head; t1.next = t2; t2.prev = t1\nshow(\"forward\", head)\nhead = reverse_dll(head); show(\"reversed\", head)\nhead = reverse_dll(head); show(\"back again\", head)","filename":"Python"},"revision":1},{"id":"64e953f9-b7de-738b-8fa2-6da825459bc5","type":"code","position":"b09","content":{"language":"cpp","code":"#include <iostream>\n#include <utility>\nusing namespace std;\n\nstruct Node {\n    int data; Node* prev; Node* next;\n    Node(int d) : data(d), prev(nullptr), next(nullptr) {}\n};\n\nNode* reverseDLL(Node* head) {\n    Node* prev = nullptr;\n    for (Node* curr = head; curr; curr = curr->prev) {   // after the swap, prev holds the old next\n        prev = curr;\n        swap(curr->next, curr->prev);                      // swap the two links\n    }\n    return prev;                                           // last node processed = new head\n}\n\nvoid show(const char* label, Node* head) {\n    cout << label << \":\";\n    for (; head; head = head->next) cout << \" \" << head->data << (head->next ? \" <->\" : \"\");\n    cout << \"\\n\";\n}\n\nint main() {\n    Node* head = new Node(10); Node* t1 = new Node(20); Node* t2 = new Node(30);\n    head->next = t1; t1->prev = head; t1->next = t2; t2->prev = t1;\n    show(\"forward\", head);\n    head = reverseDLL(head); show(\"reversed\", head);\n    head = reverseDLL(head); show(\"back again\", head);\n}","filename":"C++"},"revision":1},{"id":"c3ed3616-3056-733c-8b29-68b37c1debce","type":"code","position":"b0A","content":{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node prev, next;\n        Node(int d) { data = d; }\n    }\n\n    static Node reverseDLL(Node head) {\n        Node prev = null;\n        for (Node curr = head; curr != null; curr = curr.prev) {   // after the swap, prev holds the old next\n            prev = curr;\n            Node t = curr.next; curr.next = curr.prev; curr.prev = t;   // swap the two links\n        }\n        return prev;                                               // last node processed = new head\n    }\n\n    static void show(String label, Node head) {\n        StringBuilder sb = new StringBuilder(label + \":\");\n        for (; head != null; head = head.next) sb.append(\" \").append(head.data).append(head.next != null ? \" <->\" : \"\");\n        System.out.println(sb);\n    }\n\n    public static void main(String[] args) {\n        Node head = new Node(10), t1 = new Node(20), t2 = new Node(30);\n        head.next = t1; t1.prev = head; t1.next = t2; t2.prev = t1;\n        show(\"forward\", head);\n        head = reverseDLL(head); show(\"reversed\", head);\n        head = reverseDLL(head); show(\"back again\", head);\n    }\n}","filename":"Java"},"revision":1},{"id":"7a6ee1cb-c8a2-7314-8072-5e6ed033a73b","type":"code","position":"b0B","content":{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.prev = null; this.next = null; }\n}\n\nfunction reverseDLL(head) {\n    let prev = null;\n    for (let curr = head; curr !== null; curr = curr.prev) {   // after the swap, prev holds the old next\n        prev = curr;\n        [curr.next, curr.prev] = [curr.prev, curr.next];        // swap the two links\n    }\n    return prev;                                                // last node processed = new head\n}\n\nfunction show(label, head) {\n    const parts = [];\n    for (; head !== null; head = head.next) parts.push(head.data);\n    console.log(label + \":\", parts.join(\" <-> \"));\n}\n\nlet head = new Node(10), t1 = new Node(20), t2 = new Node(30);\nhead.next = t1; t1.prev = head; t1.next = t2; t2.prev = t1;\nshow(\"forward\", head);\nhead = reverseDLL(head); show(\"reversed\", head);\nhead = reverseDLL(head); show(\"back again\", head);","filename":"JavaScript"},"revision":1},{"id":"5270cf87-1ece-716b-8160-4ce089e451c6","type":"code","position":"b0C","content":{"language":"text","code":"forward: 10 <-> 20 <-> 30\nreversed: 30 <-> 20 <-> 10\nback again: 10 <-> 20 <-> 30","filename":"Output"},"revision":1},{"id":"c681a6b3-ee51-7ce7-abe7-2480462910fd","type":"text","position":"b0D","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(1)"}]}]}},"revision":1},{"id":"5967bb8f-2d5c-78ad-8b0a-4718b24b7b62","type":"callout","position":"b0E","content":{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Advancing with "},{"type":"text","text":"curr = curr.next","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"after","marks":[{"type":"italic"}]},{"type":"text","text":" the swap walks backwards into the part already reversed and loops forever (or stops after one node). The old "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" is in "},{"type":"text","text":"curr.prev","marks":[{"type":"code"}]},{"type":"text","text":" once the swap has happened."}]}]}},"revision":1},{"id":"de48e687-8482-7210-9b7a-e06748628743","type":"heading","position":"b0F","content":{"level":1,"content":[{"type":"text","text":"Interview Q&A"}]},"revision":1},{"id":"165ac3e4-2919-7fa1-af7b-e1e6c082a5c5","type":"question","position":"b0G","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does the extra prev pointer buy you?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"O(1) deletion of a node you hold a reference to, O(1) insertion "},{"type":"text","text":"before","marks":[{"type":"italic"}]},{"type":"text","text":" a node, O(1) removal from the tail (with a tail pointer) and backward traversal. The price is one more pointer per node and twice as many links to keep consistent."}]}]}},"revision":1},{"id":"ded2ebaa-397e-7a79-86f6-a14f8a16ac9e","type":"question","position":"b0H","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How does an LRU cache use a doubly linked list?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Entries are nodes ordered from most to least recently used; a hash map points from each key to its node. On access, the node is unlinked in O(1) (possible only because of "},{"type":"text","text":"prev","marks":[{"type":"code"}]},{"type":"text","text":") and re-inserted at the front. On eviction the tail node is removed in O(1). All operations are O(1)."}]}]}},"revision":1},{"id":"385e90f8-9dc6-7f4a-942e-dad452fe4466","type":"question","position":"b0I","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Singly vs doubly linked list — how do you choose?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Singly when you only move forward and operate at the head (stacks, hash chains, adjacency lists) — it is smaller and simpler. Doubly when you need deletions in the middle by reference, both-end operations (deques) or backward iteration. Java''s "},{"type":"text","text":"LinkedList","marks":[{"type":"code"}]},{"type":"text","text":" and C++ "},{"type":"text","text":"std::list","marks":[{"type":"code"}]},{"type":"text","text":" are doubly linked; "},{"type":"text","text":"std::forward_list","marks":[{"type":"code"}]},{"type":"text","text":" is singly linked."}]}]}},"revision":1},{"id":"2f82bbb0-fd81-7b5a-917e-116a9982ff33","type":"question","position":"b0J","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How would you reverse a doubly linked list?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Swap "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"prev","marks":[{"type":"code"}]},{"type":"text","text":" in every node and return the last node visited. One pass, no extra memory. Because the old "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" ends up in "},{"type":"text","text":"prev","marks":[{"type":"code"}]},{"type":"text","text":", the loop advances with "},{"type":"text","text":"curr = curr.prev","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"18067bb0-d633-773d-bda6-40f9ef37985a","type":"question","position":"b0K","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is an XOR linked list?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A memory-saving trick: each node stores "},{"type":"text","text":"prev XOR next","marks":[{"type":"code"}]},{"type":"text","text":" in a single field. Walking forward from a known predecessor, "},{"type":"text","text":"next = stored XOR prev","marks":[{"type":"code"}]},{"type":"text","text":". It halves the pointer overhead but defeats garbage collectors and makes the code fragile — an interview curiosity rather than a production structure."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
