    console.log("Function 1 is called");
}

function fun2() {
    console.log("Before Function 1");
    fun1();                      // fun2 pauses here until fun1 returns
    console.log("After Function 1");
}

console.log("Before Function 2");
fun2();
console.log("After Function 2");
