SELECT '8a1d7458-b573-72f4-83bf-594ebada0864', 'd3209d54-ec11-7a12-bf6a-986f5f9b398e', 1, 'PUBLISHED', 'Linked List', '[{"id":"a9a63e51-2136-79cb-9268-eb08597543cb","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A linked list is a linear collection whose elements are "},{"type":"text","text":"not","marks":[{"type":"bold"}]},{"type":"text","text":" stored next to each other in memory: every node holds a value and a pointer to the next node. Insertion and deletion at a known position are O(1), at the price of O(n) access by index."}]}]}},"revision":1},{"id":"f9627ac7-4441-7b0d-a228-0c2484a28332","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Singly linked list","marks":[{"type":"bold"}]},{"type":"text","text":" — a sequence of "},{"type":"text","text":"nodes","marks":[{"type":"bold"}]},{"type":"text","text":", each containing a "},{"type":"text","text":"data","marks":[{"type":"code"}]},{"type":"text","text":" field and a "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" reference to the following node. The first node is the "},{"type":"text","text":"head","marks":[{"type":"bold"}]},{"type":"text","text":"; the list ends at the node whose "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":". Only the head is stored — everything else is reached by following "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" pointers."}]}]}},"revision":1},{"id":"8d0f39a9-5968-72db-ac49-98f07bd2eb83","type":"code","position":"a2","content":{"language":"text","code":"head\n ↓\n┌──────┬──────┐    ┌──────┬──────┐    ┌──────┬──────┐\n│  10  │  ●───┼───▶│  20  │  ●───┼───▶│  30  │  ∅   │\n└──────┴──────┘    └──────┴──────┘    └──────┴──────┘\n  data   next        data   next        data   next = None (end of list)","filename":"A singly linked list with three nodes — only the head reference is stored by the program"},"revision":1},{"id":"568c528c-7289-7b73-8144-25e6442ce3c6","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Structure of a node"}]},"revision":1},{"id":"d962beac-6aa3-7524-b6b0-b0390a57e416","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A node is a tiny object (or struct) with two fields. Nodes are allocated one at a time, so the list grows and shrinks without ever copying or resizing an array. Traversal starts at the head and follows "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" until it becomes "},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"4a515d18-6542-76d9-836c-0c80a3f46502","type":"code","position":"a5","content":{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None             # no next node yet\n\ndef show(head):\n    parts = []\n    curr = head\n    while curr is not None:          # traversal: follow next until the end\n        parts.append(str(curr.data))\n        curr = curr.next\n    print(\" -> \".join(parts))\n\ndef length(head):\n    n, curr = 0, head\n    while curr:\n        n += 1\n        curr = curr.next\n    return n\n\nhead = Node(10)                      # build by hand: 10 -> 20 -> 30\nhead.next = Node(20)\nhead.next.next = Node(30)\nshow(head)\nprint(\"length:\", length(head))","filename":"Python"},"revision":1},{"id":"b5a11d50-ea15-7699-a777-f9919225dbff","type":"code","position":"a6","content":{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int data;\n    Node* next;\n    Node(int d) : data(d), next(nullptr) {}   // no next node yet\n};\n\nvoid show(Node* head) {\n    for (Node* curr = head; curr; curr = curr->next) {   // traversal: follow next until null\n        cout << curr->data;\n        if (curr->next) cout << \" -> \";\n    }\n    cout << \"\\n\";\n}\n\nint length(Node* head) {\n    int n = 0;\n    for (Node* curr = head; curr; curr = curr->next) n++;\n    return n;\n}\n\nint main() {\n    Node* head = new Node(10);           // build by hand: 10 -> 20 -> 30\n    head->next = new Node(20);\n    head->next->next = new Node(30);\n    show(head);\n    cout << \"length: \" << length(head) << \"\\n\";\n}","filename":"C++"},"revision":1},{"id":"4f060f59-e955-7f7b-8901-4d632528b52c","type":"code","position":"a7","content":{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;              // next stays null until linked\n        Node(int d) { data = d; }\n    }\n\n    static void show(Node head) {\n        StringBuilder sb = new StringBuilder();\n        for (Node curr = head; curr != null; curr = curr.next) {   // traversal\n            sb.append(curr.data);\n            if (curr.next != null) sb.append(\" -> \");\n        }\n        System.out.println(sb);\n    }\n\n    static int length(Node head) {\n        int n = 0;\n        for (Node curr = head; curr != null; curr = curr.next) n++;\n        return n;\n    }\n\n    public static void main(String[] args) {\n        Node head = new Node(10);         // build by hand: 10 -> 20 -> 30\n        head.next = new Node(20);\n        head.next.next = new Node(30);\n        show(head);\n        System.out.println(\"length: \" + length(head));\n    }\n}","filename":"Java"},"revision":1},{"id":"87fb4bf9-7dfa-75b8-9491-d0fccbc66571","type":"code","position":"a8","content":{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }   // no next node yet\n}\n\nfunction show(head) {\n    const parts = [];\n    for (let curr = head; curr !== null; curr = curr.next)     // traversal\n        parts.push(curr.data);\n    console.log(parts.join(\" -> \"));\n}\n\nfunction length(head) {\n    let n = 0;\n    for (let curr = head; curr !== null; curr = curr.next) n++;\n    return n;\n}\n\nconst head = new Node(10);               // build by hand: 10 -> 20 -> 30\nhead.next = new Node(20);\nhead.next.next = new Node(30);\nshow(head);\nconsole.log(\"length:\", length(head));","filename":"JavaScript"},"revision":1},{"id":"f01834e1-59aa-7f14-bde5-22373b2ac3f3","type":"code","position":"a9","content":{"language":"text","code":"10 -> 20 -> 30\nlength: 3","filename":"Output"},"revision":1},{"id":"81141d09-fd57-79af-ad6b-4c54e48b431c","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) traversal · Space O(n) for n nodes"}]}]}},"revision":1},{"id":"df2a1c73-7d1e-7f1e-b807-807af593d80a","type":"callout","position":"aB","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The list has no "},{"type":"text","text":"size","marks":[{"type":"code"}]},{"type":"text","text":" unless you maintain a counter: "},{"type":"text","text":"length","marks":[{"type":"code"}]},{"type":"text","text":" walks all nodes in O(n). Real implementations wrap the head in a "},{"type":"text","text":"LinkedList","marks":[{"type":"code"}]},{"type":"text","text":" class that also stores "},{"type":"text","text":"size","marks":[{"type":"code"}]},{"type":"text","text":" (and often a "},{"type":"text","text":"tail","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"3e96d6fc-c1ca-7fde-b3fd-941db23daff3","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Why — and why not — a linked list"}]},"revision":1},{"id":"3a40a083-b8ae-7a67-9648-e76fedd9d61f","type":"callout","position":"aD","content":{"variant":"note","title":"Dynamic size","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Grows one node at a time; no capacity to guess, no O(n) resize copy."}]}]}},"revision":1},{"id":"cc05ded8-4fc0-7884-aeb9-79715ca2c637","type":"callout","position":"aE","content":{"variant":"note","title":"O(1) insert / delete at a known node","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Re-link two pointers. An array must shift every later element."}]}]}},"revision":1},{"id":"99cdb2fd-225e-7d16-b7f1-c9f13da55edc","type":"callout","position":"aF","content":{"variant":"note","title":"No contiguous block needed","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Nodes can live anywhere in memory — useful when large arrays cannot be allocated."}]}]}},"revision":1},{"id":"facdd8e8-1459-7593-9472-5a2472e73411","type":"callout","position":"aG","content":{"variant":"note","title":"No random access","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"list[i]","marks":[{"type":"code"}]},{"type":"text","text":" means walking "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" nodes: O(n). Binary search is impossible."}]}]}},"revision":1},{"id":"8614d472-f4e0-78d5-8b16-d8e091406c1c","type":"callout","position":"aH","content":{"variant":"note","title":"Extra memory","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"One pointer per element (8 bytes on 64-bit) — a list of small ints doubles its footprint."}]}]}},"revision":1},{"id":"8dd45efc-fddc-7fe0-b551-5a2ca4bf33ae","type":"callout","position":"aI","content":{"variant":"note","title":"Cache unfriendly","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Nodes are scattered; each "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" is a potential cache miss, so traversals are slower than over an array of the same size."}]}]}},"revision":1},{"id":"7b537f62-5ae3-7cec-add2-cd5561bedc28","type":"text","position":"aJ","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Linked lists are the building block of other structures: stacks and queues (O(1) at the ends), hash-table chains, adjacency lists in graphs, and the LRU cache (a doubly linked list plus a hash map)."}]}]}},"revision":1},{"id":"9be420e6-e005-7814-8929-fc3fb55e92bf","type":"heading","position":"aK","content":{"level":1,"content":[{"type":"text","text":"Operations and their cost"}]},"revision":1},{"id":"9f8da471-b201-7f6f-aa36-dd0297d1529d","type":"table","position":"aL","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Operation"}],[{"type":"text","text":"Time"}],[{"type":"text","text":"Why"}]],[[{"type":"text","text":"Insert at beginning"}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"New node points at the old head; the head reference moves. No traversal."}]],[[{"type":"text","text":"Insert at end"}],[{"type":"text","text":"O(n) — O(1) with a tail pointer"}],[{"type":"text","text":"Without a tail you must walk to the last node first."}]],[[{"type":"text","text":"Delete head"}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"Head moves to "},{"type":"text","text":"head.next","marks":[{"type":"code"}]},{"type":"text","text":"."}]],[[{"type":"text","text":"Delete last"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"Need the "},{"type":"text","text":"second-to-last","marks":[{"type":"italic"}]},{"type":"text","text":" node to clear its "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":"; a singly linked list cannot go backwards."}]],[[{"type":"text","text":"Insert / delete after a given node"}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"Only pointers of the given node and its neighbour change."}]],[[{"type":"text","text":"Search"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"Sequential scan; nothing better is possible without random access."}]],[[{"type":"text","text":"Access by index"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"Walk "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" links."}]]]},"revision":1},{"id":"d697423d-c90e-70b8-8a52-c43d0362fae6","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Insert at the beginning"}]},"revision":1},{"id":"c66dd88e-0d3d-7b73-90b8-e4ddfa282ce4","type":"callout","position":"aN","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = 20 -> 30, insert 10 at the beginning","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 -> 20 -> 30","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"5820f7b3-4ae0-797c-9264-2154f70e22a8","type":"callout","position":"aO","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Create the node, make it point at the current head, and return it as the new head. No node is visited, so it is O(1) regardless of the list length — the one place where a linked list beats an array outright."}]}]}},"revision":1},{"id":"2688deb0-df13-7c8a-9b6d-7ab340913f3e","type":"code","position":"aP","content":{"language":"text","code":"before:   head ──▶ [20] ──▶ [30] ──▶ ∅\n\nstep 1:   new = [10]           new.next = head        [10] ──▶ [20] ──▶ [30] ──▶ ∅\nstep 2:   head = new                                   head ──▶ [10] ──▶ [20] ──▶ [30] ──▶ ∅","filename":"Insert at the beginning: two pointer assignments"},"revision":1},{"id":"db9c8115-2764-7680-9433-d9a591f7b5b2","type":"code","position":"aQ","content":{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef insert_at_beginning(head, data):\n    new_node = Node(data)\n    new_node.next = head         # new node points at the old head\n    return new_node              # it is the new head — caller must store it\n\ndef show(head):\n    parts = []\n    while head:\n        parts.append(str(head.data))\n        head = head.next\n    print(\" -> \".join(parts))\n\nhead = None\nfor x in (30, 20, 10):           # insert in reverse to get 10 -> 20 -> 30\n    head = insert_at_beginning(head, x)\n    show(head)","filename":"Python"},"revision":1},{"id":"520ed815-f1de-7217-84be-222c803e84f7","type":"code","position":"aR","content":{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nNode* insertAtBeginning(Node* head, int data) {\n    Node* newNode = new Node(data);\n    newNode->next = head;        // new node points at the old head\n    return newNode;              // it is the new head — caller must store it\n}\n\nvoid show(Node* head) {\n    for (; head; head = head->next) cout << head->data << (head->next ? \" -> \" : \"\\n\");\n}\n\nint main() {\n    Node* head = nullptr;\n    for (int x : {30, 20, 10}) {     // insert in reverse to get 10 -> 20 -> 30\n        head = insertAtBeginning(head, x);\n        show(head);\n    }\n}","filename":"C++"},"revision":1},{"id":"6d1bd82d-356c-74ed-8363-3c1fbd6892eb","type":"code","position":"aS","content":{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static Node insertAtBeginning(Node head, int data) {\n        Node newNode = new Node(data);\n        newNode.next = head;         // new node points at the old head\n        return newNode;              // it is the new head — caller must store it\n    }\n\n    static void show(Node head) {\n        StringBuilder sb = new StringBuilder();\n        for (; head != null; head = head.next) sb.append(head.data).append(head.next != null ? \" -> \" : \"\");\n        System.out.println(sb);\n    }\n\n    public static void main(String[] args) {\n        Node head = null;\n        for (int x : new int[]{30, 20, 10}) {   // insert in reverse to get 10 -> 20 -> 30\n            head = insertAtBeginning(head, x);\n            show(head);\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"822ea3e2-52dd-7346-b8e7-4d084d5e445a","type":"code","position":"aT","content":{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction insertAtBeginning(head, data) {\n    const newNode = new Node(data);\n    newNode.next = head;             // new node points at the old head\n    return newNode;                  // it is the new head — caller must store it\n}\n\nfunction show(head) {\n    const parts = [];\n    for (; head !== null; head = head.next) parts.push(head.data);\n    console.log(parts.join(\" -> \"));\n}\n\nlet head = null;\nfor (const x of [30, 20, 10]) {      // insert in reverse to get 10 -> 20 -> 30\n    head = insertAtBeginning(head, x);\n    show(head);\n}","filename":"JavaScript"},"revision":1},{"id":"e3a792dd-cff4-7213-b64d-7571a6809b15","type":"code","position":"aU","content":{"language":"text","code":"30\n20 -> 30\n10 -> 20 -> 30","filename":"Output"},"revision":1},{"id":"83f529e4-1258-7d5a-8830-f8b056daca08","type":"text","position":"aV","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(1) · Space O(1)"}]}]}},"revision":1},{"id":"e8967130-7fe0-7288-a23b-ef87df3f235f","type":"callout","position":"aW","content":{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Functions that change the head must "},{"type":"text","text":"return the new head","marks":[{"type":"bold"}]},{"type":"text","text":" (or work on a wrapper object). Writing "},{"type":"text","text":"insert_at_beginning(head, 10)","marks":[{"type":"code"}]},{"type":"text","text":" without "},{"type":"text","text":"head = …","marks":[{"type":"code"}]},{"type":"text","text":" leaves the caller pointing at the old second node — the new node is lost."}]}]}},"revision":1},{"id":"6fc84ec6-587b-7e88-9b74-bfad10519b48","type":"heading","position":"aX","content":{"level":1,"content":[{"type":"text","text":"Insert at the end"}]},"revision":1},{"id":"b2240621-a479-7c68-a75a-47fa2fff1c03","type":"callout","position":"aY","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = 10 -> 20, insert 30 at the end","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 -> 20 -> 30","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = empty, insert 10","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"a2f8462c-5752-76b1-81be-6937ee59daf4","type":"callout","position":"aZ","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Walk to the last node (the one whose "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":") and hang the new node there. The walk makes it O(n); keeping a "},{"type":"text","text":"tail","marks":[{"type":"code"}]},{"type":"text","text":" pointer in a wrapper class makes it O(1). The empty list is a special case: the new node simply becomes the head."}]}]}},"revision":1},{"id":"02013739-b7de-73fc-9433-92c463421e66","type":"code","position":"aa","content":{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef insert_at_end(head, data):\n    new_node = Node(data)\n    if head is None:                 # empty list: the new node is the head\n        return new_node\n    current = head\n    while current.next is not None:  # O(n) walk to the last node\n        current = current.next\n    current.next = new_node\n    return head                      # head is unchanged\n\ndef show(head):\n    parts = []\n    while head:\n        parts.append(str(head.data))\n        head = head.next\n    print(\" -> \".join(parts))\n\nhead = None\nfor x in (10, 20, 30):\n    head = insert_at_end(head, x)\n    show(head)","filename":"Python"},"revision":1},{"id":"fcdcc2b9-407d-7c58-88ea-08c3661effca","type":"code","position":"ab","content":{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nNode* insertAtEnd(Node* head, int data) {\n    Node* newNode = new Node(data);\n    if (!head) return newNode;           // empty list: the new node is the head\n    Node* current = head;\n    while (current->next) current = current->next;   // O(n) walk to the last node\n    current->next = newNode;\n    return head;                         // head is unchanged\n}\n\nvoid show(Node* head) {\n    for (; head; head = head->next) cout << head->data << (head->next ? \" -> \" : \"\\n\");\n}\n\nint main() {\n    Node* head = nullptr;\n    for (int x : {10, 20, 30}) {\n        head = insertAtEnd(head, x);\n        show(head);\n    }\n}","filename":"C++"},"revision":1},{"id":"85ed502c-fe85-753e-a4b0-5d76108696f8","type":"code","position":"ac","content":{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static Node insertAtEnd(Node head, int data) {\n        Node newNode = new Node(data);\n        if (head == null) return newNode;    // empty list: the new node is the head\n        Node current = head;\n        while (current.next != null) current = current.next;   // O(n) walk to the last node\n        current.next = newNode;\n        return head;                         // head is unchanged\n    }\n\n    static void show(Node head) {\n        StringBuilder sb = new StringBuilder();\n        for (; head != null; head = head.next) sb.append(head.data).append(head.next != null ? \" -> \" : \"\");\n        System.out.println(sb);\n    }\n\n    public static void main(String[] args) {\n        Node head = null;\n        for (int x : new int[]{10, 20, 30}) {\n            head = insertAtEnd(head, x);\n            show(head);\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"bbabff3a-a049-7819-ae78-5f0c5891d7be","type":"code","position":"ad","content":{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction insertAtEnd(head, data) {\n    const newNode = new Node(data);\n    if (head === null) return newNode;       // empty list: the new node is the head\n    let current = head;\n    while (current.next !== null) current = current.next;   // O(n) walk to the last node\n    current.next = newNode;\n    return head;                             // head is unchanged\n}\n\nfunction show(head) {\n    const parts = [];\n    for (; head !== null; head = head.next) parts.push(head.data);\n    console.log(parts.join(\" -> \"));\n}\n\nlet head = null;\nfor (const x of [10, 20, 30]) {\n    head = insertAtEnd(head, x);\n    show(head);\n}","filename":"JavaScript"},"revision":1},{"id":"7fd1f333-36f8-7c85-bb2d-f18a96b4e953","type":"code","position":"ae","content":{"language":"text","code":"10\n10 -> 20\n10 -> 20 -> 30","filename":"Output"},"revision":1},{"id":"646e48c9-156f-755b-95bb-44ac9988c139","type":"text","position":"af","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) — O(1) with a tail pointer · Space O(1)"}]}]}},"revision":1},{"id":"0ac6e15f-f2ac-7d92-a51c-7607000aa624","type":"callout","position":"ag","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Building a list of "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" elements by repeated "},{"type":"text","text":"insert_at_end","marks":[{"type":"code"}]},{"type":"text","text":" costs O(n²) without a tail pointer. Either keep a tail, or insert at the beginning and reverse once at the end."}]}]}},"revision":1},{"id":"53dc18d6-340a-7bff-be47-b73b798b714f","type":"heading","position":"ah","content":{"level":1,"content":[{"type":"text","text":"Delete the head"}]},"revision":1},{"id":"f3200767-32a1-7a9e-9e5f-ca29d6f835da","type":"callout","position":"ai","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = 10 -> 20 -> 30","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"20 -> 30","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = 10","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"empty","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"dac76375-f5f4-7566-8402-e915c09c210a","type":"callout","position":"aj","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The second node becomes the head: return "},{"type":"text","text":"head.next","marks":[{"type":"code"}]},{"type":"text","text":". In C++ free the old node; in Python, Java and JavaScript the garbage collector reclaims it once nothing refers to it. An empty list stays empty."}]}]}},"revision":1},{"id":"8f6fb73c-c83c-758f-a795-032976d31d3c","type":"code","position":"ak","content":{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef delete_head(head):\n    if head is None:\n        return None                  # nothing to delete\n    return head.next                 # the old head is garbage-collected\n\ndef show(head):\n    parts = []\n    while head:\n        parts.append(str(head.data))\n        head = head.next\n    print(\" -> \".join(parts) if parts else \"empty\")\n\nhead = Node(10); head.next = Node(20); head.next.next = Node(30)\nshow(head)\nfor _ in range(4):\n    head = delete_head(head)\n    print(\"after delete head: \", end=\"\")\n    show(head)","filename":"Python"},"revision":1},{"id":"4051055f-b097-7c80-8984-94698199467b","type":"code","position":"al","content":{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nNode* deleteHead(Node* head) {\n    if (!head) return nullptr;           // nothing to delete\n    Node* next = head->next;\n    delete head;                         // free the old head\n    return next;\n}\n\nvoid show(Node* head) {\n    if (!head) { cout << \"empty\\n\"; return; }\n    for (; head; head = head->next) cout << head->data << (head->next ? \" -> \" : \"\\n\");\n}\n\nint main() {\n    Node* head = new Node(10); head->next = new Node(20); head->next->next = new Node(30);\n    show(head);\n    for (int i = 0; i < 4; i++) {\n        head = deleteHead(head);\n        cout << \"after delete head: \";\n        show(head);\n    }\n}","filename":"C++"},"revision":1},{"id":"76ad511e-3da9-785b-a67d-b6d90d29b0d7","type":"code","position":"am","content":{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static Node deleteHead(Node head) {\n        if (head == null) return null;       // nothing to delete\n        return head.next;                    // the old head is garbage-collected\n    }\n\n    static void show(Node head) {\n        if (head == null) { System.out.println(\"empty\"); return; }\n        StringBuilder sb = new StringBuilder();\n        for (; head != null; head = head.next) sb.append(head.data).append(head.next != null ? \" -> \" : \"\");\n        System.out.println(sb);\n    }\n\n    public static void main(String[] args) {\n        Node head = new Node(10); head.next = new Node(20); head.next.next = new Node(30);\n        show(head);\n        for (int i = 0; i < 4; i++) {\n            head = deleteHead(head);\n            System.out.print(\"after delete head: \");\n            show(head);\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"9efd7cef-b0da-7430-a4f1-75c93f48f1b3","type":"code","position":"an","content":{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction deleteHead(head) {\n    if (head === null) return null;          // nothing to delete\n    return head.next;                        // the old head is garbage-collected\n}\n\nfunction show(head) {\n    const parts = [];\n    for (; head !== null; head = head.next) parts.push(head.data);\n    console.log(parts.length ? parts.join(\" -> \") : \"empty\");\n}\n\nlet head = new Node(10); head.next = new Node(20); head.next.next = new Node(30);\nshow(head);\nfor (let i = 0; i < 4; i++) {\n    head = deleteHead(head);\n    process.stdout.write(\"after delete head: \");\n    show(head);\n}","filename":"JavaScript"},"revision":1},{"id":"0db06c2a-b477-730d-8c2c-2ee67f6a7e17","type":"code","position":"ao","content":{"language":"text","code":"10 -> 20 -> 30\nafter delete head: 20 -> 30\nafter delete head: 30\nafter delete head: empty\nafter delete head: empty","filename":"Output"},"revision":1},{"id":"4b5438a0-d87d-700c-ac20-e79ff6bd0639","type":"text","position":"ap","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(1) · Space O(1)"}]}]}},"revision":1},{"id":"9ef5c7c0-dace-7159-b0bf-5cb7f4c166a2","type":"heading","position":"aq","content":{"level":1,"content":[{"type":"text","text":"Delete the last node"}]},"revision":1},{"id":"ab405a02-cf5b-7b1c-a023-e8e3eeb0dde8","type":"callout","position":"ar","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = 10 -> 20 -> 30","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 -> 20","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = 10","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"empty","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"a7bf7acd-2db8-716d-a2ae-2fc90edeea1e","type":"callout","position":"as","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A singly linked list cannot step backwards, so to drop the last node we must stop at the "},{"type":"text","text":"second-to-last","marks":[{"type":"bold"}]},{"type":"text","text":" one ("},{"type":"text","text":"current.next.next is None","marks":[{"type":"code"}]},{"type":"text","text":") and clear its "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":". That walk is what makes the operation O(n), while deleting the head is O(1)."}]}]}},"revision":1},{"id":"558a6a84-5689-74c1-bfcc-51da204c3dae","type":"code","position":"at","content":{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef delete_last(head):\n    if head is None or head.next is None:\n        return None                          # 0 or 1 node → empty list\n    current = head\n    while current.next.next is not None:     # stop at the second-to-last node\n        current = current.next\n    current.next = None\n    return head\n\ndef show(head):\n    parts = []\n    while head:\n        parts.append(str(head.data))\n        head = head.next\n    print(\" -> \".join(parts) if parts else \"empty\")\n\nhead = Node(10); head.next = Node(20); head.next.next = Node(30)\nshow(head)\nfor _ in range(3):\n    head = delete_last(head)\n    print(\"after delete last: \", end=\"\")\n    show(head)","filename":"Python"},"revision":1},{"id":"3fd09aee-700d-7748-809f-e7c006f21dfb","type":"code","position":"au","content":{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nNode* deleteLast(Node* head) {\n    if (!head || !head->next) { delete head; return nullptr; }   // 0 or 1 node → empty list\n    Node* current = head;\n    while (current->next->next) current = current->next;        // stop at the second-to-last node\n    delete current->next;\n    current->next = nullptr;\n    return head;\n}\n\nvoid show(Node* head) {\n    if (!head) { cout << \"empty\\n\"; return; }\n    for (; head; head = head->next) cout << head->data << (head->next ? \" -> \" : \"\\n\");\n}\n\nint main() {\n    Node* head = new Node(10); head->next = new Node(20); head->next->next = new Node(30);\n    show(head);\n    for (int i = 0; i < 3; i++) {\n        head = deleteLast(head);\n        cout << \"after delete last: \";\n        show(head);\n    }\n}","filename":"C++"},"revision":1},{"id":"5b367ee6-a931-7041-9edb-d80767f27070","type":"code","position":"av","content":{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static Node deleteLast(Node head) {\n        if (head == null || head.next == null) return null;       // 0 or 1 node → empty list\n        Node current = head;\n        while (current.next.next != null) current = current.next; // stop at the second-to-last node\n        current.next = null;\n        return head;\n    }\n\n    static void show(Node head) {\n        if (head == null) { System.out.println(\"empty\"); return; }\n        StringBuilder sb = new StringBuilder();\n        for (; head != null; head = head.next) sb.append(head.data).append(head.next != null ? \" -> \" : \"\");\n        System.out.println(sb);\n    }\n\n    public static void main(String[] args) {\n        Node head = new Node(10); head.next = new Node(20); head.next.next = new Node(30);\n        show(head);\n        for (int i = 0; i < 3; i++) {\n            head = deleteLast(head);\n            System.out.print(\"after delete last: \");\n            show(head);\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"a8d08e69-dd3c-7c61-9ef1-9b9ebf7371e5","type":"code","position":"aw","content":{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction deleteLast(head) {\n    if (head === null || head.next === null) return null;        // 0 or 1 node → empty list\n    let current = head;\n    while (current.next.next !== null) current = current.next;   // stop at the second-to-last node\n    current.next = null;\n    return head;\n}\n\nfunction show(head) {\n    const parts = [];\n    for (; head !== null; head = head.next) parts.push(head.data);\n    console.log(parts.length ? parts.join(\" -> \") : \"empty\");\n}\n\nlet head = new Node(10); head.next = new Node(20); head.next.next = new Node(30);\nshow(head);\nfor (let i = 0; i < 3; i++) {\n    head = deleteLast(head);\n    process.stdout.write(\"after delete last: \");\n    show(head);\n}","filename":"JavaScript"},"revision":1},{"id":"6f60499c-f4cf-769c-aec5-2ae2580c1971","type":"code","position":"ax","content":{"language":"text","code":"10 -> 20 -> 30\nafter delete last: 10 -> 20\nafter delete last: 10\nafter delete last: empty","filename":"Output"},"revision":1},{"id":"500f4740-371a-7b9f-9b1b-56ee4d8d2e6a","type":"text","position":"ay","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(1)"}]}]}},"revision":1},{"id":"1b6198c1-d338-7865-91b9-b5cd29818468","type":"heading","position":"az","content":{"level":1,"content":[{"type":"text","text":"Search in a linked list"}]},"revision":1},{"id":"b0c6b46f-3bc4-7b53-a00c-d7188ab96c41","type":"callout","position":"b00","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = 10 -> 20 -> 30, target = 20","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"position 2","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"target = 40","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"-1","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"a5181f8e-f671-74e8-bb42-f221fb80ec5c","type":"callout","position":"b01","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Walk from the head comparing each node''s data with the target and counting positions (1-indexed). Return the position on a match, "},{"type":"text","text":"-1","marks":[{"type":"code"}]},{"type":"text","text":" after falling off the end. Without random access, a linear scan is the only option — even on a sorted list."}]}]}},"revision":1},{"id":"149391e3-dd18-7a4e-ab9a-b3f46176a561","type":"code","position":"b02","content":{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef search_list(head, target):\n    current, position = head, 1\n    while current is not None:\n        if current.data == target:\n            return position\n        current = current.next\n        position += 1\n    return -1                            # fell off the end\n\ndef report(head, x):\n    pos = search_list(head, x)\n    print(f\"search {x}:\", f\"position {pos}\" if pos != -1 else -1)\n\nhead = Node(10); head.next = Node(20); head.next.next = Node(30)\nfor x in (20, 10, 40):\n    report(head, x)","filename":"Python"},"revision":1},{"id":"89368610-2de5-764e-ba77-d888dfd52243","type":"code","position":"b03","content":{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nint searchList(Node* head, int target) {\n    int position = 1;\n    for (Node* current = head; current; current = current->next, position++)\n        if (current->data == target) return position;\n    return -1;                           // fell off the end\n}\n\nvoid report(Node* head, int x) {\n    int pos = searchList(head, x);\n    cout << \"search \" << x << \": \";\n    if (pos != -1) cout << \"position \" << pos << \"\\n\"; else cout << \"-1\\n\";\n}\n\nint main() {\n    Node* head = new Node(10); head->next = new Node(20); head->next->next = new Node(30);\n    for (int x : {20, 10, 40}) report(head, x);\n}","filename":"C++"},"revision":1},{"id":"3cebbce5-103f-7638-a426-fe4479beb357","type":"code","position":"b04","content":{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static int searchList(Node head, int target) {\n        int position = 1;\n        for (Node current = head; current != null; current = current.next, position++)\n            if (current.data == target) return position;\n        return -1;                           // fell off the end\n    }\n\n    static void report(Node head, int x) {\n        int pos = searchList(head, x);\n        System.out.println(\"search \" + x + \": \" + (pos != -1 ? \"position \" + pos : \"-1\"));\n    }\n\n    public static void main(String[] args) {\n        Node head = new Node(10); head.next = new Node(20); head.next.next = new Node(30);\n        for (int x : new int[]{20, 10, 40}) report(head, x);\n    }\n}","filename":"Java"},"revision":1},{"id":"b71cf1fb-9378-7195-8171-05134625d808","type":"code","position":"b05","content":{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction searchList(head, target) {\n    let position = 1;\n    for (let current = head; current !== null; current = current.next, position++)\n        if (current.data === target) return position;\n    return -1;                               // fell off the end\n}\n\nfunction report(head, x) {\n    const pos = searchList(head, x);\n    console.log(`search ${x}:`, pos !== -1 ? `position ${pos}` : -1);\n}\n\nconst head = new Node(10); head.next = new Node(20); head.next.next = new Node(30);\nfor (const x of [20, 10, 40]) report(head, x);","filename":"JavaScript"},"revision":1},{"id":"83a79662-b548-705d-a666-bb2dd4a9e73d","type":"code","position":"b06","content":{"language":"text","code":"search 20: position 2\nsearch 10: position 1\nsearch 40: -1","filename":"Output"},"revision":1},{"id":"c70bbcff-e188-718d-9eec-03d53c516e5a","type":"text","position":"b07","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(1)"}]}]}},"revision":1},{"id":"e58dab7e-b96f-7266-be9b-5d63a064a662","type":"heading","position":"b08","content":{"level":1,"content":[{"type":"text","text":"Array vs linked list"}]},"revision":1},{"id":"77955e2c-1c0c-7b37-9ec9-db5686f8c7b7","type":"table","position":"b09","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Operation"}],[{"type":"text","text":"Array / dynamic array (contiguous)"}],[{"type":"text","text":"Linked list (pointers)"}]],[[{"type":"text","text":"Access by index"}],[{"type":"text","text":"O(1) — address = base + i · size"}],[{"type":"text","text":"O(n) — walk "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" links"}]],[[{"type":"text","text":"Search (unsorted)"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"O(n)"}]],[[{"type":"text","text":"Search (sorted)"}],[{"type":"text","text":"O(log n) binary search"}],[{"type":"text","text":"O(n) — no random access, binary search impossible"}]],[[{"type":"text","text":"Insert / delete at start"}],[{"type":"text","text":"O(n) — shift every element"}],[{"type":"text","text":"O(1) — re-link the head"}]],[[{"type":"text","text":"Insert / delete at end"}],[{"type":"text","text":"O(1) amortised (occasional resize copy)"}],[{"type":"text","text":"O(n), or O(1) with a tail pointer (delete last stays O(n) for singly linked)"}]],[[{"type":"text","text":"Insert / delete in the middle (position known)"}],[{"type":"text","text":"O(n) — shift the tail"}],[{"type":"text","text":"O(1) — once you hold the previous node"}]],[[{"type":"text","text":"Extra memory"}],[{"type":"text","text":"None per element; unused capacity in dynamic arrays"}],[{"type":"text","text":"One "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" pointer per node"}]],[[{"type":"text","text":"Memory layout"}],[{"type":"text","text":"Contiguous — cache friendly, prefetchable"}],[{"type":"text","text":"Scattered — pointer chasing, cache misses"}]],[[{"type":"text","text":"Size"}],[{"type":"text","text":"Fixed, or resized by copying"}],[{"type":"text","text":"Grows node by node"}]]]},"revision":1},{"id":"582e72a8-f5e6-7327-b2e9-921c6b096bed","type":"callout","position":"b0A","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Default to an array / dynamic array: random access and cache locality win most of the time. Reach for a linked list when you need many O(1) insertions or deletions at known nodes (queues, LRU caches, adjacency lists, splicing lists together) or cannot afford resize copies."}]}]}},"revision":1},{"id":"2a3530aa-0eaf-7e17-9afa-991da619dae4","type":"heading","position":"b0B","content":{"level":1,"content":[{"type":"text","text":"Interview Q&A"}]},"revision":1},{"id":"302c2ae8-aa7d-7bd6-bd81-e12200090887","type":"question","position":"b0C","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is inserting at the front O(1) in a linked list but O(n) in an array?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An array keeps elements contiguous, so making room at index 0 means moving every existing element one slot right. A linked list has no positions — a new node just points at the old head and becomes the new head; nothing else moves."}]}]}},"revision":1},{"id":"05e961ca-b0e4-7075-8549-1fd2581ae9d2","type":"question","position":"b0D","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is binary search not possible on a linked list?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Binary search needs the middle element in O(1). In a linked list reaching the middle costs O(n/2) pointer hops, so every probe is O(n) and the search becomes O(n) overall — no better than a linear scan."}]}]}},"revision":1},{"id":"128403c2-2d87-7bb4-9b47-67cc56422856","type":"question","position":"b0E","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you find the middle of a linked list in one pass?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two pointers: "},{"type":"text","text":"slow","marks":[{"type":"code"}]},{"type":"text","text":" moves one node per step, "},{"type":"text","text":"fast","marks":[{"type":"code"}]},{"type":"text","text":" two. When "},{"type":"text","text":"fast","marks":[{"type":"code"}]},{"type":"text","text":" reaches the end, "},{"type":"text","text":"slow","marks":[{"type":"code"}]},{"type":"text","text":" is at the middle. The same trick (Floyd''s algorithm) detects a cycle: if "},{"type":"text","text":"fast","marks":[{"type":"code"}]},{"type":"text","text":" ever meets "},{"type":"text","text":"slow","marks":[{"type":"code"}]},{"type":"text","text":", the list loops."}]}]}},"revision":1},{"id":"4c0413f6-8c76-705e-83a8-d23cc8b7ca1a","type":"question","position":"b0F","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How would you reverse a singly linked list?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Iterate with three pointers "},{"type":"text","text":"prev","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"curr","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":": save "},{"type":"text","text":"next = curr.next","marks":[{"type":"code"}]},{"type":"text","text":", redirect "},{"type":"text","text":"curr.next = prev","marks":[{"type":"code"}]},{"type":"text","text":", then advance "},{"type":"text","text":"prev = curr","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"curr = next","marks":[{"type":"code"}]},{"type":"text","text":". When "},{"type":"text","text":"curr","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"prev","marks":[{"type":"code"}]},{"type":"text","text":" is the new head. O(n) time, O(1) space."}]}]}},"revision":1},{"id":"93283a3e-2f7d-7753-8a67-02b3bce74f4e","type":"question","position":"b0G","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When is a linked list a better choice than a dynamic array?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When the workload is dominated by inserts/deletes at the ends or at nodes you already hold (a queue, an LRU cache, merging sorted lists), when element moves are expensive, or when a guaranteed O(1) without occasional resize pauses matters. For index-heavy or cache-sensitive code, arrays win."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = 'd3209d54-ec11-7a12-bf6a-986f5f9b398e' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
ON CONFLICT DO NOTHING;

INSERT INTO "notes"."Card" ("id", "noteId", "position", "type", "content", "revision", "createdAt", "updatedAt")
SELECT c.id::uuid, 'd3209d54-ec11-7a12-bf6a-986f5f9b398e', c.position, c.type::"notes"."CardType", c.content::jsonb, 1, TIMESTAMPTZ '2026-10-07 03:23:53+00', TIMESTAMPTZ '2026-10-07 03:23:53+00'
FROM (VALUES
  ('a9a63e51-2136-79cb-9268-eb08597543cb', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A linked list is a linear collection whose elements are "},{"type":"text","text":"not","marks":[{"type":"bold"}]},{"type":"text","text":" stored next to each other in memory: every node holds a value and a pointer to the next node. Insertion and deletion at a known position are O(1), at the price of O(n) access by index."}]}]}}'),
  ('f9627ac7-4441-7b0d-a228-0c2484a28332', 'a1', 'callout', '{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Singly linked list","marks":[{"type":"bold"}]},{"type":"text","text":" — a sequence of "},{"type":"text","text":"nodes","marks":[{"type":"bold"}]},{"type":"text","text":", each containing a "},{"type":"text","text":"data","marks":[{"type":"code"}]},{"type":"text","text":" field and a "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" reference to the following node. The first node is the "},{"type":"text","text":"head","marks":[{"type":"bold"}]},{"type":"text","text":"; the list ends at the node whose "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":". Only the head is stored — everything else is reached by following "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" pointers."}]}]}}'),
  ('8d0f39a9-5968-72db-ac49-98f07bd2eb83', 'a2', 'code', '{"language":"text","code":"head\n ↓\n┌──────┬──────┐    ┌──────┬──────┐    ┌──────┬──────┐\n│  10  │  ●───┼───▶│  20  │  ●───┼───▶│  30  │  ∅   │\n└──────┴──────┘    └──────┴──────┘    └──────┴──────┘\n  data   next        data   next        data   next = None (end of list)","filename":"A singly linked list with three nodes — only the head reference is stored by the program"}'),
  ('568c528c-7289-7b73-8144-25e6442ce3c6', 'a3', 'heading', '{"level":1,"content":[{"type":"text","text":"Structure of a node"}]}'),
  ('d962beac-6aa3-7524-b6b0-b0390a57e416', 'a4', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A node is a tiny object (or struct) with two fields. Nodes are allocated one at a time, so the list grows and shrinks without ever copying or resizing an array. Traversal starts at the head and follows "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" until it becomes "},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('4a515d18-6542-76d9-836c-0c80a3f46502', 'a5', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None             # no next node yet\n\ndef show(head):\n    parts = []\n    curr = head\n    while curr is not None:          # traversal: follow next until the end\n        parts.append(str(curr.data))\n        curr = curr.next\n    print(\" -> \".join(parts))\n\ndef length(head):\n    n, curr = 0, head\n    while curr:\n        n += 1\n        curr = curr.next\n    return n\n\nhead = Node(10)                      # build by hand: 10 -> 20 -> 30\nhead.next = Node(20)\nhead.next.next = Node(30)\nshow(head)\nprint(\"length:\", length(head))","filename":"Python"}'),
  ('b5a11d50-ea15-7699-a777-f9919225dbff', 'a6', 'code', '{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int data;\n    Node* next;\n    Node(int d) : data(d), next(nullptr) {}   // no next node yet\n};\n\nvoid show(Node* head) {\n    for (Node* curr = head; curr; curr = curr->next) {   // traversal: follow next until null\n        cout << curr->data;\n        if (curr->next) cout << \" -> \";\n    }\n    cout << \"\\n\";\n}\n\nint length(Node* head) {\n    int n = 0;\n    for (Node* curr = head; curr; curr = curr->next) n++;\n    return n;\n}\n\nint main() {\n    Node* head = new Node(10);           // build by hand: 10 -> 20 -> 30\n    head->next = new Node(20);\n    head->next->next = new Node(30);\n    show(head);\n    cout << \"length: \" << length(head) << \"\\n\";\n}","filename":"C++"}'),
  ('4f060f59-e955-7f7b-8901-4d632528b52c', 'a7', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;              // next stays null until linked\n        Node(int d) { data = d; }\n    }\n\n    static void show(Node head) {\n        StringBuilder sb = new StringBuilder();\n        for (Node curr = head; curr != null; curr = curr.next) {   // traversal\n            sb.append(curr.data);\n            if (curr.next != null) sb.append(\" -> \");\n        }\n        System.out.println(sb);\n    }\n\n    static int length(Node head) {\n        int n = 0;\n        for (Node curr = head; curr != null; curr = curr.next) n++;\n        return n;\n    }\n\n    public static void main(String[] args) {\n        Node head = new Node(10);         // build by hand: 10 -> 20 -> 30\n        head.next = new Node(20);\n        head.next.next = new Node(30);\n        show(head);\n        System.out.println(\"length: \" + length(head));\n    }\n}","filename":"Java"}'),
  ('87fb4bf9-7dfa-75b8-9491-d0fccbc66571', 'a8', 'code', '{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }   // no next node yet\n}\n\nfunction show(head) {\n    const parts = [];\n    for (let curr = head; curr !== null; curr = curr.next)     // traversal\n        parts.push(curr.data);\n    console.log(parts.join(\" -> \"));\n}\n\nfunction length(head) {\n    let n = 0;\n    for (let curr = head; curr !== null; curr = curr.next) n++;\n    return n;\n}\n\nconst head = new Node(10);               // build by hand: 10 -> 20 -> 30\nhead.next = new Node(20);\nhead.next.next = new Node(30);\nshow(head);\nconsole.log(\"length:\", length(head));","filename":"JavaScript"}'),
  ('f01834e1-59aa-7f14-bde5-22373b2ac3f3', 'a9', 'code', '{"language":"text","code":"10 -> 20 -> 30\nlength: 3","filename":"Output"}'),
  ('81141d09-fd57-79af-ad6b-4c54e48b431c', 'aA', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) traversal · Space O(n) for n nodes"}]}]}}'),
  ('df2a1c73-7d1e-7f1e-b807-807af593d80a', 'aB', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The list has no "},{"type":"text","text":"size","marks":[{"type":"code"}]},{"type":"text","text":" unless you maintain a counter: "},{"type":"text","text":"length","marks":[{"type":"code"}]},{"type":"text","text":" walks all nodes in O(n). Real implementations wrap the head in a "},{"type":"text","text":"LinkedList","marks":[{"type":"code"}]},{"type":"text","text":" class that also stores "},{"type":"text","text":"size","marks":[{"type":"code"}]},{"type":"text","text":" (and often a "},{"type":"text","text":"tail","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}}'),
  ('3e96d6fc-c1ca-7fde-b3fd-941db23daff3', 'aC', 'heading', '{"level":1,"content":[{"type":"text","text":"Why — and why not — a linked list"}]}'),
  ('3a40a083-b8ae-7a67-9648-e76fedd9d61f', 'aD', 'callout', '{"variant":"note","title":"Dynamic size","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Grows one node at a time; no capacity to guess, no O(n) resize copy."}]}]}}'),
  ('cc05ded8-4fc0-7884-aeb9-79715ca2c637', 'aE', 'callout', '{"variant":"note","title":"O(1) insert / delete at a known node","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Re-link two pointers. An array must shift every later element."}]}]}}'),
  ('99cdb2fd-225e-7d16-b7f1-c9f13da55edc', 'aF', 'callout', '{"variant":"note","title":"No contiguous block needed","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Nodes can live anywhere in memory — useful when large arrays cannot be allocated."}]}]}}'),
  ('facdd8e8-1459-7593-9472-5a2472e73411', 'aG', 'callout', '{"variant":"note","title":"No random access","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"list[i]","marks":[{"type":"code"}]},{"type":"text","text":" means walking "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" nodes: O(n). Binary search is impossible."}]}]}}'),
  ('8614d472-f4e0-78d5-8b16-d8e091406c1c', 'aH', 'callout', '{"variant":"note","title":"Extra memory","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"One pointer per element (8 bytes on 64-bit) — a list of small ints doubles its footprint."}]}]}}'),
  ('8dd45efc-fddc-7fe0-b551-5a2ca4bf33ae', 'aI', 'callout', '{"variant":"note","title":"Cache unfriendly","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Nodes are scattered; each "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" is a potential cache miss, so traversals are slower than over an array of the same size."}]}]}}'),
  ('7b537f62-5ae3-7cec-add2-cd5561bedc28', 'aJ', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Linked lists are the building block of other structures: stacks and queues (O(1) at the ends), hash-table chains, adjacency lists in graphs, and the LRU cache (a doubly linked list plus a hash map)."}]}]}}'),
  ('9be420e6-e005-7814-8929-fc3fb55e92bf', 'aK', 'heading', '{"level":1,"content":[{"type":"text","text":"Operations and their cost"}]}'),
  ('9f8da471-b201-7f6f-aa36-dd0297d1529d', 'aL', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Operation"}],[{"type":"text","text":"Time"}],[{"type":"text","text":"Why"}]],[[{"type":"text","text":"Insert at beginning"}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"New node points at the old head; the head reference moves. No traversal."}]],[[{"type":"text","text":"Insert at end"}],[{"type":"text","text":"O(n) — O(1) with a tail pointer"}],[{"type":"text","text":"Without a tail you must walk to the last node first."}]],[[{"type":"text","text":"Delete head"}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"Head moves to "},{"type":"text","text":"head.next","marks":[{"type":"code"}]},{"type":"text","text":"."}]],[[{"type":"text","text":"Delete last"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"Need the "},{"type":"text","text":"second-to-last","marks":[{"type":"italic"}]},{"type":"text","text":" node to clear its "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":"; a singly linked list cannot go backwards."}]],[[{"type":"text","text":"Insert / delete after a given node"}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"Only pointers of the given node and its neighbour change."}]],[[{"type":"text","text":"Search"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"Sequential scan; nothing better is possible without random access."}]],[[{"type":"text","text":"Access by index"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"Walk "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" links."}]]]}'),
  ('d697423d-c90e-70b8-8a52-c43d0362fae6', 'aM', 'heading', '{"level":1,"content":[{"type":"text","text":"Insert at the beginning"}]}'),
  ('c66dd88e-0d3d-7b73-90b8-e4ddfa282ce4', 'aN', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = 20 -> 30, insert 10 at the beginning","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 -> 20 -> 30","marks":[{"type":"code"}]}]}]}}'),
  ('5820f7b3-4ae0-797c-9264-2154f70e22a8', 'aO', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Create the node, make it point at the current head, and return it as the new head. No node is visited, so it is O(1) regardless of the list length — the one place where a linked list beats an array outright."}]}]}}'),
  ('2688deb0-df13-7c8a-9b6d-7ab340913f3e', 'aP', 'code', '{"language":"text","code":"before:   head ──▶ [20] ──▶ [30] ──▶ ∅\n\nstep 1:   new = [10]           new.next = head        [10] ──▶ [20] ──▶ [30] ──▶ ∅\nstep 2:   head = new                                   head ──▶ [10] ──▶ [20] ──▶ [30] ──▶ ∅","filename":"Insert at the beginning: two pointer assignments"}'),
  ('db9c8115-2764-7680-9433-d9a591f7b5b2', 'aQ', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef insert_at_beginning(head, data):\n    new_node = Node(data)\n    new_node.next = head         # new node points at the old head\n    return new_node              # it is the new head — caller must store it\n\ndef show(head):\n    parts = []\n    while head:\n        parts.append(str(head.data))\n        head = head.next\n    print(\" -> \".join(parts))\n\nhead = None\nfor x in (30, 20, 10):           # insert in reverse to get 10 -> 20 -> 30\n    head = insert_at_beginning(head, x)\n    show(head)","filename":"Python"}'),
  ('520ed815-f1de-7217-84be-222c803e84f7', 'aR', 'code', '{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nNode* insertAtBeginning(Node* head, int data) {\n    Node* newNode = new Node(data);\n    newNode->next = head;        // new node points at the old head\n    return newNode;              // it is the new head — caller must store it\n}\n\nvoid show(Node* head) {\n    for (; head; head = head->next) cout << head->data << (head->next ? \" -> \" : \"\\n\");\n}\n\nint main() {\n    Node* head = nullptr;\n    for (int x : {30, 20, 10}) {     // insert in reverse to get 10 -> 20 -> 30\n        head = insertAtBeginning(head, x);\n        show(head);\n    }\n}","filename":"C++"}'),
  ('6d1bd82d-356c-74ed-8363-3c1fbd6892eb', 'aS', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static Node insertAtBeginning(Node head, int data) {\n        Node newNode = new Node(data);\n        newNode.next = head;         // new node points at the old head\n        return newNode;              // it is the new head — caller must store it\n    }\n\n    static void show(Node head) {\n        StringBuilder sb = new StringBuilder();\n        for (; head != null; head = head.next) sb.append(head.data).append(head.next != null ? \" -> \" : \"\");\n        System.out.println(sb);\n    }\n\n    public static void main(String[] args) {\n        Node head = null;\n        for (int x : new int[]{30, 20, 10}) {   // insert in reverse to get 10 -> 20 -> 30\n            head = insertAtBeginning(head, x);\n            show(head);\n        }\n    }\n}","filename":"Java"}'),
  ('822ea3e2-52dd-7346-b8e7-4d084d5e445a', 'aT', 'code', '{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction insertAtBeginning(head, data) {\n    const newNode = new Node(data);\n    newNode.next = head;             // new node points at the old head\n    return newNode;                  // it is the new head — caller must store it\n}\n\nfunction show(head) {\n    const parts = [];\n    for (; head !== null; head = head.next) parts.push(head.data);\n    console.log(parts.join(\" -> \"));\n}\n\nlet head = null;\nfor (const x of [30, 20, 10]) {      // insert in reverse to get 10 -> 20 -> 30\n    head = insertAtBeginning(head, x);\n    show(head);\n}","filename":"JavaScript"}'),
  ('e3a792dd-cff4-7213-b64d-7571a6809b15', 'aU', 'code', '{"language":"text","code":"30\n20 -> 30\n10 -> 20 -> 30","filename":"Output"}'),
  ('83f529e4-1258-7d5a-8830-f8b056daca08', 'aV', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(1) · Space O(1)"}]}]}}'),
  ('e8967130-7fe0-7288-a23b-ef87df3f235f', 'aW', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Functions that change the head must "},{"type":"text","text":"return the new head","marks":[{"type":"bold"}]},{"type":"text","text":" (or work on a wrapper object). Writing "},{"type":"text","text":"insert_at_beginning(head, 10)","marks":[{"type":"code"}]},{"type":"text","text":" without "},{"type":"text","text":"head = …","marks":[{"type":"code"}]},{"type":"text","text":" leaves the caller pointing at the old second node — the new node is lost."}]}]}}'),
  ('6fc84ec6-587b-7e88-9b74-bfad10519b48', 'aX', 'heading', '{"level":1,"content":[{"type":"text","text":"Insert at the end"}]}'),
  ('b2240621-a479-7c68-a75a-47fa2fff1c03', 'aY', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = 10 -> 20, insert 30 at the end","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 -> 20 -> 30","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = empty, insert 10","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10","marks":[{"type":"code"}]}]}]}}'),
  ('a2f8462c-5752-76b1-81be-6937ee59daf4', 'aZ', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Walk to the last node (the one whose "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":") and hang the new node there. The walk makes it O(n); keeping a "},{"type":"text","text":"tail","marks":[{"type":"code"}]},{"type":"text","text":" pointer in a wrapper class makes it O(1). The empty list is a special case: the new node simply becomes the head."}]}]}}'),
  ('02013739-b7de-73fc-9433-92c463421e66', 'aa', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef insert_at_end(head, data):\n    new_node = Node(data)\n    if head is None:                 # empty list: the new node is the head\n        return new_node\n    current = head\n    while current.next is not None:  # O(n) walk to the last node\n        current = current.next\n    current.next = new_node\n    return head                      # head is unchanged\n\ndef show(head):\n    parts = []\n    while head:\n        parts.append(str(head.data))\n        head = head.next\n    print(\" -> \".join(parts))\n\nhead = None\nfor x in (10, 20, 30):\n    head = insert_at_end(head, x)\n    show(head)","filename":"Python"}'),
  ('fcdcc2b9-407d-7c58-88ea-08c3661effca', 'ab', 'code', '{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nNode* insertAtEnd(Node* head, int data) {\n    Node* newNode = new Node(data);\n    if (!head) return newNode;           // empty list: the new node is the head\n    Node* current = head;\n    while (current->next) current = current->next;   // O(n) walk to the last node\n    current->next = newNode;\n    return head;                         // head is unchanged\n}\n\nvoid show(Node* head) {\n    for (; head; head = head->next) cout << head->data << (head->next ? \" -> \" : \"\\n\");\n}\n\nint main() {\n    Node* head = nullptr;\n    for (int x : {10, 20, 30}) {\n        head = insertAtEnd(head, x);\n        show(head);\n    }\n}","filename":"C++"}'),
  ('85ed502c-fe85-753e-a4b0-5d76108696f8', 'ac', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static Node insertAtEnd(Node head, int data) {\n        Node newNode = new Node(data);\n        if (head == null) return newNode;    // empty list: the new node is the head\n        Node current = head;\n        while (current.next != null) current = current.next;   // O(n) walk to the last node\n        current.next = newNode;\n        return head;                         // head is unchanged\n    }\n\n    static void show(Node head) {\n        StringBuilder sb = new StringBuilder();\n        for (; head != null; head = head.next) sb.append(head.data).append(head.next != null ? \" -> \" : \"\");\n        System.out.println(sb);\n    }\n\n    public static void main(String[] args) {\n        Node head = null;\n        for (int x : new int[]{10, 20, 30}) {\n            head = insertAtEnd(head, x);\n            show(head);\n        }\n    }\n}","filename":"Java"}'),
  ('bbabff3a-a049-7819-ae78-5f0c5891d7be', 'ad', 'code', '{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction insertAtEnd(head, data) {\n    const newNode = new Node(data);\n    if (head === null) return newNode;       // empty list: the new node is the head\n    let current = head;\n    while (current.next !== null) current = current.next;   // O(n) walk to the last node\n    current.next = newNode;\n    return head;                             // head is unchanged\n}\n\nfunction show(head) {\n    const parts = [];\n    for (; head !== null; head = head.next) parts.push(head.data);\n    console.log(parts.join(\" -> \"));\n}\n\nlet head = null;\nfor (const x of [10, 20, 30]) {\n    head = insertAtEnd(head, x);\n    show(head);\n}","filename":"JavaScript"}'),
  ('7fd1f333-36f8-7c85-bb2d-f18a96b4e953', 'ae', 'code', '{"language":"text","code":"10\n10 -> 20\n10 -> 20 -> 30","filename":"Output"}'),
  ('646e48c9-156f-755b-95bb-44ac9988c139', 'af', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) — O(1) with a tail pointer · Space O(1)"}]}]}}'),
  ('0ac6e15f-f2ac-7d92-a51c-7607000aa624', 'ag', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Building a list of "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" elements by repeated "},{"type":"text","text":"insert_at_end","marks":[{"type":"code"}]},{"type":"text","text":" costs O(n²) without a tail pointer. Either keep a tail, or insert at the beginning and reverse once at the end."}]}]}}'),
  ('53dc18d6-340a-7bff-be47-b73b798b714f', 'ah', 'heading', '{"level":1,"content":[{"type":"text","text":"Delete the head"}]}'),
  ('f3200767-32a1-7a9e-9e5f-ca29d6f835da', 'ai', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = 10 -> 20 -> 30","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"20 -> 30","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = 10","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"empty","marks":[{"type":"code"}]}]}]}}'),
  ('dac76375-f5f4-7566-8402-e915c09c210a', 'aj', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The second node becomes the head: return "},{"type":"text","text":"head.next","marks":[{"type":"code"}]},{"type":"text","text":". In C++ free the old node; in Python, Java and JavaScript the garbage collector reclaims it once nothing refers to it. An empty list stays empty."}]}]}}'),
  ('8f6fb73c-c83c-758f-a795-032976d31d3c', 'ak', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef delete_head(head):\n    if head is None:\n        return None                  # nothing to delete\n    return head.next                 # the old head is garbage-collected\n\ndef show(head):\n    parts = []\n    while head:\n        parts.append(str(head.data))\n        head = head.next\n    print(\" -> \".join(parts) if parts else \"empty\")\n\nhead = Node(10); head.next = Node(20); head.next.next = Node(30)\nshow(head)\nfor _ in range(4):\n    head = delete_head(head)\n    print(\"after delete head: \", end=\"\")\n    show(head)","filename":"Python"}'),
  ('4051055f-b097-7c80-8984-94698199467b', 'al', 'code', '{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nNode* deleteHead(Node* head) {\n    if (!head) return nullptr;           // nothing to delete\n    Node* next = head->next;\n    delete head;                         // free the old head\n    return next;\n}\n\nvoid show(Node* head) {\n    if (!head) { cout << \"empty\\n\"; return; }\n    for (; head; head = head->next) cout << head->data << (head->next ? \" -> \" : \"\\n\");\n}\n\nint main() {\n    Node* head = new Node(10); head->next = new Node(20); head->next->next = new Node(30);\n    show(head);\n    for (int i = 0; i < 4; i++) {\n        head = deleteHead(head);\n        cout << \"after delete head: \";\n        show(head);\n    }\n}","filename":"C++"}'),
  ('76ad511e-3da9-785b-a67d-b6d90d29b0d7', 'am', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static Node deleteHead(Node head) {\n        if (head == null) return null;       // nothing to delete\n        return head.next;                    // the old head is garbage-collected\n    }\n\n    static void show(Node head) {\n        if (head == null) { System.out.println(\"empty\"); return; }\n        StringBuilder sb = new StringBuilder();\n        for (; head != null; head = head.next) sb.append(head.data).append(head.next != null ? \" -> \" : \"\");\n        System.out.println(sb);\n    }\n\n    public static void main(String[] args) {\n        Node head = new Node(10); head.next = new Node(20); head.next.next = new Node(30);\n        show(head);\n        for (int i = 0; i < 4; i++) {\n            head = deleteHead(head);\n            System.out.print(\"after delete head: \");\n            show(head);\n        }\n    }\n}","filename":"Java"}'),
  ('9efd7cef-b0da-7430-a4f1-75c93f48f1b3', 'an', 'code', '{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction deleteHead(head) {\n    if (head === null) return null;          // nothing to delete\n    return head.next;                        // the old head is garbage-collected\n}\n\nfunction show(head) {\n    const parts = [];\n    for (; head !== null; head = head.next) parts.push(head.data);\n    console.log(parts.length ? parts.join(\" -> \") : \"empty\");\n}\n\nlet head = new Node(10); head.next = new Node(20); head.next.next = new Node(30);\nshow(head);\nfor (let i = 0; i < 4; i++) {\n    head = deleteHead(head);\n    process.stdout.write(\"after delete head: \");\n    show(head);\n}","filename":"JavaScript"}'),
  ('0db06c2a-b477-730d-8c2c-2ee67f6a7e17', 'ao', 'code', '{"language":"text","code":"10 -> 20 -> 30\nafter delete head: 20 -> 30\nafter delete head: 30\nafter delete head: empty\nafter delete head: empty","filename":"Output"}'),
  ('4b5438a0-d87d-700c-ac20-e79ff6bd0639', 'ap', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(1) · Space O(1)"}]}]}}'),
  ('9ef5c7c0-dace-7159-b0bf-5cb7f4c166a2', 'aq', 'heading', '{"level":1,"content":[{"type":"text","text":"Delete the last node"}]}'),
  ('ab405a02-cf5b-7b1c-a023-e8e3eeb0dde8', 'ar', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = 10 -> 20 -> 30","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 -> 20","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = 10","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"empty","marks":[{"type":"code"}]}]}]}}'),
  ('a7bf7acd-2db8-716d-a2ae-2fc90edeea1e', 'as', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A singly linked list cannot step backwards, so to drop the last node we must stop at the "},{"type":"text","text":"second-to-last","marks":[{"type":"bold"}]},{"type":"text","text":" one ("},{"type":"text","text":"current.next.next is None","marks":[{"type":"code"}]},{"type":"text","text":") and clear its "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":". That walk is what makes the operation O(n), while deleting the head is O(1)."}]}]}}'),
  ('558a6a84-5689-74c1-bfcc-51da204c3dae', 'at', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef delete_last(head):\n    if head is None or head.next is None:\n        return None                          # 0 or 1 node → empty list\n    current = head\n    while current.next.next is not None:     # stop at the second-to-last node\n        current = current.next\n    current.next = None\n    return head\n\ndef show(head):\n    parts = []\n    while head:\n        parts.append(str(head.data))\n        head = head.next\n    print(\" -> \".join(parts) if parts else \"empty\")\n\nhead = Node(10); head.next = Node(20); head.next.next = Node(30)\nshow(head)\nfor _ in range(3):\n    head = delete_last(head)\n    print(\"after delete last: \", end=\"\")\n    show(head)","filename":"Python"}'),
  ('3fd09aee-700d-7748-809f-e7c006f21dfb', 'au', 'code', '{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nNode* deleteLast(Node* head) {\n    if (!head || !head->next) { delete head; return nullptr; }   // 0 or 1 node → empty list\n    Node* current = head;\n    while (current->next->next) current = current->next;        // stop at the second-to-last node\n    delete current->next;\n    current->next = nullptr;\n    return head;\n}\n\nvoid show(Node* head) {\n    if (!head) { cout << \"empty\\n\"; return; }\n    for (; head; head = head->next) cout << head->data << (head->next ? \" -> \" : \"\\n\");\n}\n\nint main() {\n    Node* head = new Node(10); head->next = new Node(20); head->next->next = new Node(30);\n    show(head);\n    for (int i = 0; i < 3; i++) {\n        head = deleteLast(head);\n        cout << \"after delete last: \";\n        show(head);\n    }\n}","filename":"C++"}'),
  ('5b367ee6-a931-7041-9edb-d80767f27070', 'av', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static Node deleteLast(Node head) {\n        if (head == null || head.next == null) return null;       // 0 or 1 node → empty list\n        Node current = head;\n        while (current.next.next != null) current = current.next; // stop at the second-to-last node\n        current.next = null;\n        return head;\n    }\n\n    static void show(Node head) {\n        if (head == null) { System.out.println(\"empty\"); return; }\n        StringBuilder sb = new StringBuilder();\n        for (; head != null; head = head.next) sb.append(head.data).append(head.next != null ? \" -> \" : \"\");\n        System.out.println(sb);\n    }\n\n    public static void main(String[] args) {\n        Node head = new Node(10); head.next = new Node(20); head.next.next = new Node(30);\n        show(head);\n        for (int i = 0; i < 3; i++) {\n            head = deleteLast(head);\n            System.out.print(\"after delete last: \");\n            show(head);\n        }\n    }\n}","filename":"Java"}'),
  ('a8d08e69-dd3c-7c61-9ef1-9b9ebf7371e5', 'aw', 'code', '{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction deleteLast(head) {\n    if (head === null || head.next === null) return null;        // 0 or 1 node → empty list\n    let current = head;\n    while (current.next.next !== null) current = current.next;   // stop at the second-to-last node\n    current.next = null;\n    return head;\n}\n\nfunction show(head) {\n    const parts = [];\n    for (; head !== null; head = head.next) parts.push(head.data);\n    console.log(parts.length ? parts.join(\" -> \") : \"empty\");\n}\n\nlet head = new Node(10); head.next = new Node(20); head.next.next = new Node(30);\nshow(head);\nfor (let i = 0; i < 3; i++) {\n    head = deleteLast(head);\n    process.stdout.write(\"after delete last: \");\n    show(head);\n}","filename":"JavaScript"}'),
  ('6f60499c-f4cf-769c-aec5-2ae2580c1971', 'ax', 'code', '{"language":"text","code":"10 -> 20 -> 30\nafter delete last: 10 -> 20\nafter delete last: 10\nafter delete last: empty","filename":"Output"}'),
  ('500f4740-371a-7b9f-9b1b-56ee4d8d2e6a', 'ay', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(1)"}]}]}}'),
  ('1b6198c1-d338-7865-91b9-b5cd29818468', 'az', 'heading', '{"level":1,"content":[{"type":"text","text":"Search in a linked list"}]}'),
  ('b0c6b46f-3bc4-7b53-a00c-d7188ab96c41', 'b00', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"list = 10 -> 20 -> 30, target = 20","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"position 2","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"target = 40","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"-1","marks":[{"type":"code"}]}]}]}}'),
  ('a5181f8e-f671-74e8-bb42-f221fb80ec5c', 'b01', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Walk from the head comparing each node''s data with the target and counting positions (1-indexed). Return the position on a match, "},{"type":"text","text":"-1","marks":[{"type":"code"}]},{"type":"text","text":" after falling off the end. Without random access, a linear scan is the only option — even on a sorted list."}]}]}}'),
  ('149391e3-dd18-7a4e-ab9a-b3f46176a561', 'b02', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef search_list(head, target):\n    current, position = head, 1\n    while current is not None:\n        if current.data == target:\n            return position\n        current = current.next\n        position += 1\n    return -1                            # fell off the end\n\ndef report(head, x):\n    pos = search_list(head, x)\n    print(f\"search {x}:\", f\"position {pos}\" if pos != -1 else -1)\n\nhead = Node(10); head.next = Node(20); head.next.next = Node(30)\nfor x in (20, 10, 40):\n    report(head, x)","filename":"Python"}'),
  ('89368610-2de5-764e-ba77-d888dfd52243', 'b03', 'code', '{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nint searchList(Node* head, int target) {\n    int position = 1;\n    for (Node* current = head; current; current = current->next, position++)\n        if (current->data == target) return position;\n    return -1;                           // fell off the end\n}\n\nvoid report(Node* head, int x) {\n    int pos = searchList(head, x);\n    cout << \"search \" << x << \": \";\n    if (pos != -1) cout << \"position \" << pos << \"\\n\"; else cout << \"-1\\n\";\n}\n\nint main() {\n    Node* head = new Node(10); head->next = new Node(20); head->next->next = new Node(30);\n    for (int x : {20, 10, 40}) report(head, x);\n}","filename":"C++"}'),
  ('3cebbce5-103f-7638-a426-fe4479beb357', 'b04', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static int searchList(Node head, int target) {\n        int position = 1;\n        for (Node current = head; current != null; current = current.next, position++)\n            if (current.data == target) return position;\n        return -1;                           // fell off the end\n    }\n\n    static void report(Node head, int x) {\n        int pos = searchList(head, x);\n        System.out.println(\"search \" + x + \": \" + (pos != -1 ? \"position \" + pos : \"-1\"));\n    }\n\n    public static void main(String[] args) {\n        Node head = new Node(10); head.next = new Node(20); head.next.next = new Node(30);\n        for (int x : new int[]{20, 10, 40}) report(head, x);\n    }\n}","filename":"Java"}'),
  ('b71cf1fb-9378-7195-8171-05134625d808', 'b05', 'code', '{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction searchList(head, target) {\n    let position = 1;\n    for (let current = head; current !== null; current = current.next, position++)\n        if (current.data === target) return position;\n    return -1;                               // fell off the end\n}\n\nfunction report(head, x) {\n    const pos = searchList(head, x);\n    console.log(`search ${x}:`, pos !== -1 ? `position ${pos}` : -1);\n}\n\nconst head = new Node(10); head.next = new Node(20); head.next.next = new Node(30);\nfor (const x of [20, 10, 40]) report(head, x);","filename":"JavaScript"}'),
