  ('77955e2c-1c0c-7b37-9ec9-db5686f8c7b7', 'b09', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Operation"}],[{"type":"text","text":"Array / dynamic array (contiguous)"}],[{"type":"text","text":"Linked list (pointers)"}]],[[{"type":"text","text":"Access by index"}],[{"type":"text","text":"O(1) — address = base + i · size"}],[{"type":"text","text":"O(n) — walk "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" links"}]],[[{"type":"text","text":"Search (unsorted)"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"O(n)"}]],[[{"type":"text","text":"Search (sorted)"}],[{"type":"text","text":"O(log n) binary search"}],[{"type":"text","text":"O(n) — no random access, binary search impossible"}]],[[{"type":"text","text":"Insert / delete at start"}],[{"type":"text","text":"O(n) — shift every element"}],[{"type":"text","text":"O(1) — re-link the head"}]],[[{"type":"text","text":"Insert / delete at end"}],[{"type":"text","text":"O(1) amortised (occasional resize copy)"}],[{"type":"text","text":"O(n), or O(1) with a tail pointer (delete last stays O(n) for singly linked)"}]],[[{"type":"text","text":"Insert / delete in the middle (position known)"}],[{"type":"text","text":"O(n) — shift the tail"}],[{"type":"text","text":"O(1) — once you hold the previous node"}]],[[{"type":"text","text":"Extra memory"}],[{"type":"text","text":"None per element; unused capacity in dynamic arrays"}],[{"type":"text","text":"One "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" pointer per node"}]],[[{"type":"text","text":"Memory layout"}],[{"type":"text","text":"Contiguous — cache friendly, prefetchable"}],[{"type":"text","text":"Scattered — pointer chasing, cache misses"}]],[[{"type":"text","text":"Size"}],[{"type":"text","text":"Fixed, or resized by copying"}],[{"type":"text","text":"Grows node by node"}]]]}'),
  ('582e72a8-f5e6-7327-b2e9-921c6b096bed', 'b0A', 'callout', '{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Default to an array / dynamic array: random access and cache locality win most of the time. Reach for a linked list when you need many O(1) insertions or deletions at known nodes (queues, LRU caches, adjacency lists, splicing lists together) or cannot afford resize copies."}]}]}}'),
  ('2a3530aa-0eaf-7e17-9afa-991da619dae4', 'b0B', 'heading', '{"level":1,"content":[{"type":"text","text":"Interview Q&A"}]}'),
  ('302c2ae8-aa7d-7bd6-bd81-e12200090887', 'b0C', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is inserting at the front O(1) in a linked list but O(n) in an array?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An array keeps elements contiguous, so making room at index 0 means moving every existing element one slot right. A linked list has no positions — a new node just points at the old head and becomes the new head; nothing else moves."}]}]}}'),
  ('05e961ca-b0e4-7075-8549-1fd2581ae9d2', 'b0D', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is binary search not possible on a linked list?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Binary search needs the middle element in O(1). In a linked list reaching the middle costs O(n/2) pointer hops, so every probe is O(n) and the search becomes O(n) overall — no better than a linear scan."}]}]}}'),
  ('128403c2-2d87-7bb4-9b47-67cc56422856', 'b0E', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you find the middle of a linked list in one pass?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two pointers: "},{"type":"text","text":"slow","marks":[{"type":"code"}]},{"type":"text","text":" moves one node per step, "},{"type":"text","text":"fast","marks":[{"type":"code"}]},{"type":"text","text":" two. When "},{"type":"text","text":"fast","marks":[{"type":"code"}]},{"type":"text","text":" reaches the end, "},{"type":"text","text":"slow","marks":[{"type":"code"}]},{"type":"text","text":" is at the middle. The same trick (Floyd''s algorithm) detects a cycle: if "},{"type":"text","text":"fast","marks":[{"type":"code"}]},{"type":"text","text":" ever meets "},{"type":"text","text":"slow","marks":[{"type":"code"}]},{"type":"text","text":", the list loops."}]}]}}'),
  ('4c0413f6-8c76-705e-83a8-d23cc8b7ca1a', 'b0F', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How would you reverse a singly linked list?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Iterate with three pointers "},{"type":"text","text":"prev","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"curr","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":": save "},{"type":"text","text":"next = curr.next","marks":[{"type":"code"}]},{"type":"text","text":", redirect "},{"type":"text","text":"curr.next = prev","marks":[{"type":"code"}]},{"type":"text","text":", then advance "},{"type":"text","text":"prev = curr","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"curr = next","marks":[{"type":"code"}]},{"type":"text","text":". When "},{"type":"text","text":"curr","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"prev","marks":[{"type":"code"}]},{"type":"text","text":" is the new head. O(n) time, O(1) space."}]}]}}'),
  ('93283a3e-2f7d-7753-8a67-02b3bce74f4e', 'b0G', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When is a linked list a better choice than a dynamic array?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When the workload is dominated by inserts/deletes at the ends or at nodes you already hold (a queue, an LRU cache, merging sorted lists), when element moves are expensive, or when a guaranteed O(1) without occasional resize pauses matters. For index-heavy or cache-sensitive code, arrays win."}]}]}}')
