INSERT INTO "notes"."Card" ("id", "noteId", "position", "type", "content", "revision", "createdAt", "updatedAt")
SELECT c.id::uuid, '31485ed0-c6bc-7149-82ad-e362b5b1b2f1', c.position, c.type::"notes"."CardType", c.content::jsonb, 1, TIMESTAMPTZ '2026-10-07 03:23:53+00', TIMESTAMPTZ '2026-10-07 03:23:53+00'
FROM (VALUES
  ('003ee9ec-d782-7c1f-9943-5b85024a7582', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sorting arranges data in increasing or decreasing order. It is the most studied problem in computer science because so much else — binary search, deduplication, merging, finding medians, grouping — becomes easy once the data is sorted. These notes cover the library sorts you should actually call and the classic algorithms you must be able to write and analyse: bubble, selection, insertion, merge, quick and heap sort."}]}]}}'),
  ('07147bdd-44b5-79d2-80fd-91c1963abac6', 'a1', 'callout', '{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sorting","marks":[{"type":"bold"}]},{"type":"text","text":" — rearranging a sequence so that every element is "},{"type":"text","text":"≤","marks":[{"type":"code"}]},{"type":"text","text":" the one after it (ascending) or "},{"type":"text","text":"≥","marks":[{"type":"code"}]},{"type":"text","text":" it (descending), according to a "},{"type":"text","text":"comparison","marks":[{"type":"italic"}]},{"type":"text","text":" — numeric, alphabetic, or any custom key."}]}]}}'),
  ('58532c43-fa4d-7ffc-b5a9-f7c11a059bd4', 'a2', 'heading', '{"level":1,"content":[{"type":"text","text":"Comparison of sorting algorithms"}]}'),
  ('114877e0-ccf2-73c9-8319-983435ebd4ea', 'a3', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The two properties interviewers ask about after time complexity are "},{"type":"text","text":"stability","marks":[{"type":"bold"}]},{"type":"text","text":" (equal elements keep their original relative order) and whether the sort is "},{"type":"text","text":"in-place","marks":[{"type":"bold"}]},{"type":"text","text":" (needs only "},{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":" — or "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":" stack — extra memory)."}]}]}}'),
  ('442b94af-ce9e-7536-b9f9-3944546b0400', 'a4', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Algorithm"}],[{"type":"text","text":"Best"}],[{"type":"text","text":"Average"}],[{"type":"text","text":"Worst"}],[{"type":"text","text":"Extra space"}],[{"type":"text","text":"Stable"}],[{"type":"text","text":"In-place"}],[{"type":"text","text":"Notes"}]],[[{"type":"text","text":"Bubble sort"}],[{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":"*"}],[{"type":"text","text":"O(n²)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n²)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(1)","marks":[{"type":"code"}]}],[{"type":"text","text":"yes"}],[{"type":"text","text":"yes"}],[{"type":"text","text":"*with the "},{"type":"text","text":"swapped","marks":[{"type":"italic"}]},{"type":"text","text":" flag; academic only"}]],[[{"type":"text","text":"Selection sort"}],[{"type":"text","text":"O(n²)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n²)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n²)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(1)","marks":[{"type":"code"}]}],[{"type":"text","text":"no"}],[{"type":"text","text":"yes"}],[{"type":"text","text":"fewest writes: at most "},{"type":"text","text":"n − 1","marks":[{"type":"code"}]},{"type":"text","text":" swaps"}]],[[{"type":"text","text":"Insertion sort"}],[{"type":"text","text":"O(n)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n²)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n²)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(1)","marks":[{"type":"code"}]}],[{"type":"text","text":"yes"}],[{"type":"text","text":"yes"}],[{"type":"text","text":"best for small or nearly sorted input; used inside Timsort / introsort"}]],[[{"type":"text","text":"Merge sort"}],[{"type":"text","text":"O(n log n)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n log n)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n log n)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n)","marks":[{"type":"code"}]}],[{"type":"text","text":"yes"}],[{"type":"text","text":"no"}],[{"type":"text","text":"linked lists and external sorting; guaranteed "},{"type":"text","text":"n log n","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Quick sort"}],[{"type":"text","text":"O(n log n)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n log n)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n²)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":" stack"}],[{"type":"text","text":"no"}],[{"type":"text","text":"yes"}],[{"type":"text","text":"fastest in practice: cache-friendly, low constants"}]],[[{"type":"text","text":"Heap sort"}],[{"type":"text","text":"O(n log n)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n log n)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n log n)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(1)","marks":[{"type":"code"}]}],[{"type":"text","text":"no"}],[{"type":"text","text":"yes"}],[{"type":"text","text":"guaranteed "},{"type":"text","text":"n log n","marks":[{"type":"code"}]},{"type":"text","text":" in place; poor cache behaviour"}]],[[{"type":"text","text":"Timsort (library)"}],[{"type":"text","text":"O(n)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n log n)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n log n)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n)","marks":[{"type":"code"}]}],[{"type":"text","text":"yes"}],[{"type":"text","text":"no"}],[{"type":"text","text":"merge sort + insertion sort on natural runs; Python, Java objects, V8"}]]]}'),
  ('02ffaabf-4468-7524-a871-51cf88cab35d', 'a5', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Any sort that only "},{"type":"text","text":"compares","marks":[{"type":"italic"}]},{"type":"text","text":" elements needs "},{"type":"text","text":"Ω(n log n)","marks":[{"type":"code"}]},{"type":"text","text":" comparisons in the worst case — there are "},{"type":"text","text":"n!","marks":[{"type":"code"}]},{"type":"text","text":" orderings and each comparison rules out at most half. Merge, heap and quick sort are optimal in that sense; counting and radix sort beat it only by not comparing (they index on the values)."}]}]}}'),
  ('1c4c9e40-be64-7626-859a-df111ffe55f5', 'a6', 'heading', '{"level":1,"content":[{"type":"text","text":"Built-in sorting in each language"}]}'),
  ('7de10b96-d2f2-78aa-8aca-6f478e5ab5bc', 'a7', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In real code you call the library sort. Know what it runs, whether it is stable, and how to pass a key or comparator."}]}]}}'),
  ('aed81d30-45df-7545-8945-354f0050c380', 'a8', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Language"}],[{"type":"text","text":"Call"}],[{"type":"text","text":"Algorithm"}],[{"type":"text","text":"Stable"}],[{"type":"text","text":"Custom order"}]],[[{"type":"text","text":"Python"}],[{"type":"text","text":"sorted(iterable, key=, reverse=)","marks":[{"type":"code"}]},{"type":"text","text":" → new list · "},{"type":"text","text":"list.sort()","marks":[{"type":"code"}]},{"type":"text","text":" in place"}],[{"type":"text","text":"Timsort"}],[{"type":"text","text":"yes"}],[{"type":"text","text":"key=","marks":[{"type":"code"}]},{"type":"text","text":" function ("},{"type":"text","text":"len","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"abs","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"lambda p: (p.x, p.y)","marks":[{"type":"code"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"C++"}],[{"type":"text","text":"std::sort(begin, end, cmp)","marks":[{"type":"code"}]}],[{"type":"text","text":"introsort (quick + heap + insertion)"}],[{"type":"text","text":"no","marks":[{"type":"bold"}]}],[{"type":"text","text":"comparator: "},{"type":"text","text":"greater<int>()","marks":[{"type":"code"}]},{"type":"text","text":", lambda"}]],[[{"type":"text","text":"C++"}],[{"type":"text","text":"std::stable_sort(begin, end, cmp)","marks":[{"type":"code"}]}],[{"type":"text","text":"merge sort"}],[{"type":"text","text":"yes"}],[{"type":"text","text":"same comparator"}]],[[{"type":"text","text":"Java"}],[{"type":"text","text":"Arrays.sort(int[])","marks":[{"type":"code"}]},{"type":"text","text":" (primitives)"}],[{"type":"text","text":"dual-pivot quicksort"}],[{"type":"text","text":"n/a (primitives are indistinguishable)"}],[{"type":"text","text":"—"}]],[[{"type":"text","text":"Java"}],[{"type":"text","text":"Arrays.sort(T[])","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Collections.sort(list)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"list.sort(cmp)","marks":[{"type":"code"}]}],[{"type":"text","text":"Timsort"}],[{"type":"text","text":"yes"}],[{"type":"text","text":"Comparator.comparingInt(...)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"reverseOrder()","marks":[{"type":"code"}]}]],[[{"type":"text","text":"JavaScript"}],[{"type":"text","text":"arr.sort(cmp)","marks":[{"type":"code"}]},{"type":"text","text":" in place · "},{"type":"text","text":"arr.toSorted(cmp)","marks":[{"type":"code"}]},{"type":"text","text":" copy"}],[{"type":"text","text":"Timsort (V8)"}],[{"type":"text","text":"yes (since ES2019)"}],[{"type":"text","text":"(a, b) => a - b","marks":[{"type":"code"}]},{"type":"text","text":" — "},{"type":"text","text":"required","marks":[{"type":"bold"}]},{"type":"text","text":" for numbers"}]]]}'),
  ('3db85f24-bc51-7423-963f-5e18d0c98002', 'a9', 'code', '{"language":"python","code":"nums = [5, 10, 15, 1]\nprint(\"ascending:\", *sorted(nums))\nprint(\"descending:\", *sorted(nums, reverse=True))\n\nwords = [\"Thrishank\", \"Nani\", \"Kuntimaddi\"]\nprint(\"by length:\", *sorted(words, key=len))        # key: sort by what len() returns","filename":"Python"}'),
  ('f49dae49-ca4c-73bb-905f-9269433e5a00', 'aA', 'code', '{"language":"cpp","code":"#include <algorithm>\n#include <functional>\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> nums = {5, 10, 15, 1};\n    sort(nums.begin(), nums.end());\n    cout << \"ascending:\";\n    for (int x : nums) cout << \" \" << x;\n    cout << \"\\n\";\n    sort(nums.begin(), nums.end(), greater<int>());        // comparator: descending\n    cout << \"descending:\";\n    for (int x : nums) cout << \" \" << x;\n    cout << \"\\n\";\n\n    vector<string> words = {\"Thrishank\", \"Nani\", \"Kuntimaddi\"};\n    stable_sort(words.begin(), words.end(),                // stable: equal lengths keep their order\n                [](const string& a, const string& b) { return a.size() < b.size(); });\n    cout << \"by length:\";\n    for (const string& w : words) cout << \" \" << w;\n    cout << \"\\n\";\n}","filename":"C++"}'),
  ('f8c50c4e-ac46-7051-818f-f5b25b4e2add', 'aB', 'code', '{"language":"java","code":"import java.util.Arrays;\nimport java.util.Collections;\nimport java.util.Comparator;\n\npublic class Main {\n    public static void main(String[] args) {\n        Integer[] nums = {5, 10, 15, 1};                      // boxed: needed for a Comparator\n        Arrays.sort(nums);\n        System.out.println(\"ascending: \" + join(nums));\n        Arrays.sort(nums, Collections.reverseOrder());        // comparator: descending\n        System.out.println(\"descending: \" + join(nums));\n\n        String[] words = {\"Thrishank\", \"Nani\", \"Kuntimaddi\"};\n        Arrays.sort(words, Comparator.comparingInt(String::length));   // Timsort: stable\n        System.out.println(\"by length: \" + join(words));\n    }\n\n    static String join(Object[] a) {\n        StringBuilder sb = new StringBuilder();\n        for (Object x : a) sb.append(sb.length() == 0 ? \"\" : \" \").append(x);\n        return sb.toString();\n    }\n}","filename":"Java"}'),
  ('fa86eb44-377f-7641-b0c8-7b126e698de1', 'aC', 'code', '{"language":"javascript","code":"const nums = [5, 10, 15, 1];\nconsole.log(\"ascending:\", [...nums].sort((a, b) => a - b).join(\" \"));    // numeric comparator!\nconsole.log(\"descending:\", [...nums].sort((a, b) => b - a).join(\" \"));\n\nconst words = [\"Thrishank\", \"Nani\", \"Kuntimaddi\"];\nconsole.log(\"by length:\", words.toSorted((a, b) => a.length - b.length).join(\" \"));   // stable","filename":"JavaScript"}'),
  ('f654fb1c-3dbc-7f08-b099-1a055f1f1b16', 'aD', 'code', '{"language":"text","code":"ascending: 1 5 10 15\ndescending: 15 10 5 1\nby length: Nani Thrishank Kuntimaddi","filename":"Output"}'),
  ('5b54773e-e759-7066-bcd3-0bc9d0a72890', 'aE', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"JavaScript''s "},{"type":"text","text":"arr.sort()","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"without a comparator converts every element to a string","marks":[{"type":"bold"}]},{"type":"text","text":" and compares the strings. Numbers come out in dictionary order — a classic bug."}]}]}}'),
  ('798b7011-59a3-78b4-9a3f-2f679add83ca', 'aF', 'code', '{"language":"javascript","code":"const arr = [10, 9, 1, 100];\nconsole.log([...arr].sort().join(\" \"));              // \"10\" < \"9\" as strings\nconsole.log([...arr].sort((a, b) => a - b).join(\" \"));","filename":"JavaScript"}'),
  ('196727a4-4681-7279-aec0-75f0566d0f2e', 'aG', 'code', '{"language":"text","code":"1 10 100 9\n1 9 10 100","filename":"Output"}'),
  ('5faeac04-a31a-782e-bd1d-9b50413b8852', 'aH', 'heading', '{"level":1,"content":[{"type":"text","text":"Python: sort() and sorted()"}]}'),
  ('f3fe4618-0224-7ba7-b61a-5e359c1e2d83', 'aI', 'table', '{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"list.sort()","marks":[{"type":"code"}]}],[{"type":"text","text":"sorted(iterable)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Works on"}],[{"type":"text","text":"lists only"}],[{"type":"text","text":"any iterable: list, tuple, string, set, dict (its keys), generator"}]],[[{"type":"text","text":"Result"}],[{"type":"text","text":"sorts "},{"type":"text","text":"in place","marks":[{"type":"bold"}]},{"type":"text","text":", returns "},{"type":"text","text":"None","marks":[{"type":"code"}]}],[{"type":"text","text":"returns a "},{"type":"text","text":"new list","marks":[{"type":"bold"}]},{"type":"text","text":"; the input is untouched"}]],[[{"type":"text","text":"Parameters"}],[{"type":"text","text":"key=","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"reverse=","marks":[{"type":"code"}]}],[{"type":"text","text":"key=","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"reverse=","marks":[{"type":"code"}]},{"type":"text","text":" — identical meaning"}]],[[{"type":"text","text":"Algorithm"}],[{"type":"text","text":"Timsort, stable, "},{"type":"text","text":"O(n log n)","marks":[{"type":"code"}]},{"type":"text","text":" worst, "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" on sorted input"}],[{"type":"text","text":"same"}]]]}'),
  ('0dd046db-f1ef-71cb-9891-0883d00dd8a3', 'aJ', 'code', '{"language":"python","code":"l1 = [5, 10, 15, 1]\nl1.sort()                          # in place\nprint(l1)                          # [1, 5, 10, 15]\n\nl2 = [5, 10, 15, 1]\nl2.sort(reverse=True)\nprint(l2)                          # [15, 10, 5, 1]\n\nl3 = [''Thrishank'', ''Nani'', ''Kuntimaddi'']\nl3.sort()                          # strings: dictionary order\nprint(l3)                          # [''Kuntimaddi'', ''Nani'', ''Thrishank'']\n\nl4 = [''Thrishank'', ''Nani'', ''Kuntimaddi'']\nl4.sort(key=len)                   # sort by the key''s value: 4, 9, 10\nprint(l4)                          # [''Nani'', ''Thrishank'', ''Kuntimaddi'']\nl4.sort(key=len, reverse=True)\nprint(l4)                          # [''Kuntimaddi'', ''Thrishank'', ''Nani'']\n\nprint([5, 1, 3].sort())            # None   ← sort() returns None: a classic slip","filename":"Python"}'),
  ('edead31d-6785-7634-8d5b-d364b0e9f831', 'aK', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"x = l.sort()","marks":[{"type":"code"}]},{"type":"text","text":" leaves "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":" as "},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":". Use "},{"type":"text","text":"l.sort()","marks":[{"type":"code"}]},{"type":"text","text":" on its own line, or "},{"type":"text","text":"x = sorted(l)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('4e33471a-c9ea-7c86-a6f5-ba4a1b477d5f', 'aL', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sorting objects.","marks":[{"type":"bold"}]},{"type":"text","text":" Either pass a "},{"type":"text","text":"key","marks":[{"type":"code"}]},{"type":"text","text":" function that extracts the field to compare, or define "},{"type":"text","text":"__lt__","marks":[{"type":"code"}]},{"type":"text","text":" on the class so the objects compare themselves. A tuple key such as "},{"type":"text","text":"(p.x, p.y)","marks":[{"type":"code"}]},{"type":"text","text":" sorts by "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":" and breaks ties by "},{"type":"text","text":"y","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('7cacc595-3bd9-7b20-bb9e-70a74102f1d0', 'aM', 'code', '{"language":"python","code":"class Point:\n    def __init__(self, x, y):\n        self.x = x\n        self.y = y\n\n    def __lt__(self, other):           # \"less than\": lets sort() compare Points directly\n        if self.x == other.x:\n            return self.y < other.y    # tie on x → compare y\n        return self.x < other.x\n\npts = [Point(10, 15), Point(1, 15), Point(3, 8), Point(1, 7)]\n\nby_x = sorted(pts, key=lambda p: p.x)             # key function: compare x only (stable → 1 15 before 1 7)\nprint(\"by x:\", *(f\"({p.x},{p.y})\" for p in by_x))\n\npts.sort()                                        # uses __lt__: x, then y\nprint(\"by x then y:\", *(f\"({p.x},{p.y})\" for p in pts))\n\npts.sort(key=lambda p: (p.y, p.x))                # tuple key: y, then x\nprint(\"by y then x:\", *(f\"({p.x},{p.y})\" for p in pts))","filename":"Python"}'),
  ('11cd9d8d-7943-7d3f-a477-0c0b3cdddaf9', 'aN', 'code', '{"language":"text","code":"by x: (1,15) (1,7) (3,8) (10,15)\nby x then y: (1,7) (1,15) (3,8) (10,15)\nby y then x: (1,7) (3,8) (1,15) (10,15)","filename":"Output"}'),
  ('4e357549-e323-7d61-aaa6-2eecd581092f', 'aO', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"sorted()","marks":[{"type":"bold"},{"type":"code"}]},{"type":"text","text":" on other iterables","marks":[{"type":"bold"}]},{"type":"text","text":" — the result is always a list, even for a tuple, string or set. A dict sorts by its keys."}]}]}}'),
  ('9e055014-55b3-7185-8eac-86107094c99f', 'aP', 'code', '{"language":"python","code":"l = [30, 8, 23, 76, 12, 1, 12]\nprint(sorted(l))                         # [1, 8, 12, 12, 23, 30, 76]\nprint(l)                                 # [30, 8, 23, 76, 12, 1, 12]   ← untouched\n\nl = [10, -15, -2, 1]\nprint(sorted(l, key=abs))                # [1, -2, 10, -15]\nprint(sorted(l, key=abs, reverse=True))  # [-15, 10, -2, 1]\nprint(sorted(l))                         # [-15, -2, 1, 10]\n\nprint(sorted((10, 12, 5, 1)))            # [1, 5, 10, 12]\nprint(sorted({''Thrishank'', ''Nani'', ''Kuntimaddi''}))   # [''Kuntimaddi'', ''Nani'', ''Thrishank'']\nprint(sorted(''gfg''))                     # [''f'', ''g'', ''g'']\nprint(sorted({10: ''a'', 12: ''b'', 5: ''c''}))            # [5, 10, 12]   ← keys only\nprint(sorted([(10, 15), (12, 15), (3, 8)]))          # [(3, 8), (10, 15), (12, 15)]","filename":"Python"}'),
  ('ba888e86-af09-710a-8e2d-98cdd47b5c02', 'aQ', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Timsort","marks":[{"type":"bold"}]},{"type":"text","text":" (Tim Peters, 2002) is a hybrid: it finds already-ordered "},{"type":"text","text":"runs","marks":[{"type":"italic"}]},{"type":"text","text":" in the input, sorts short runs with insertion sort, then merges runs with merge sort. That is why it is stable, "},{"type":"text","text":"O(n log n)","marks":[{"type":"code"}]},{"type":"text","text":" in the worst case and "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" on already-sorted data. Java uses it for objects and V8 for "},{"type":"text","text":"Array.prototype.sort","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('88886dd0-73d7-7df6-ac8d-7c4871453930', 'aR', 'heading', '{"level":1,"content":[{"type":"text","text":"Stability"}]}'),
  ('5bce2972-c24a-7871-b45c-3a1c63f945ca', 'aS', 'callout', '{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Stable sort","marks":[{"type":"bold"}]},{"type":"text","text":" — a sort that keeps elements with "},{"type":"text","text":"equal keys","marks":[{"type":"bold"}]},{"type":"text","text":" in the same relative order they had in the input."}]}]}}'),
  ('750e428e-485c-7dfb-a1db-a06929bc2d27', 'aT', 'code', '{"language":"text","code":"input   (name, marks):  (Anil, 50)  (Ayan, 80)  (Pyush, 50)  (Ramesh, 80)\n\nsort by marks, stable:  (Anil, 50)  (Pyush, 50)  (Ayan, 80)  (Ramesh, 80)\n                         ^ Anil still before Pyush, Ayan still before Ramesh\n\na possible unstable result:  (Pyush, 50)  (Anil, 50)  (Ayan, 80)  (Ramesh, 80)\n                              ^ the two 50s swapped — equal keys, order lost","filename":"Stability only matters when keys repeat"}'),
  ('eb410ecc-2700-7f82-8ffd-fda15048de6f', 'aU', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why it matters:","marks":[{"type":"bold"}]},{"type":"text","text":" stability lets you sort by several fields in "},{"type":"text","text":"passes","marks":[{"type":"italic"}]},{"type":"text","text":". Sort by the secondary key first, then stably by the primary key — rows with the same primary key stay in secondary order. Spreadsheets, SQL "},{"type":"text","text":"ORDER BY a, b","marks":[{"type":"code"}]},{"type":"text","text":" and \"sort by marks, then alphabetically\" all rely on this. It is also what makes "},{"type":"text","text":"sort by marks","marks":[{"type":"code"}]},{"type":"text","text":" leave an already alphabetical list alphabetical within each group."}]}]}}'),
  ('9f2d4fe3-f779-79fb-9e31-82389599993c', 'aV', 'code', '{"language":"python","code":"students = [(\"Ramesh\", 80), (\"Anil\", 50), (\"Pyush\", 50), (\"Ayan\", 80)]\nshow = lambda rows: \", \".join(f\"{name} {marks}\" for name, marks in rows)\n\nprint(\"input:\", show(students))\nprint(\"by marks only:\", show(sorted(students, key=lambda s: s[1])))   # ties keep input order\n\nby_name = sorted(students)                                 # pass 1: secondary key\nby_both = sorted(by_name, key=lambda s: s[1])              # pass 2: primary key, stable\nprint(\"by name, then by marks:\", show(by_both))","filename":"Python"}'),
  ('872c7b6d-665a-776f-9d2f-b3a0653a58d3', 'aW', 'code', '{"language":"cpp","code":"#include <algorithm>\n#include <iostream>\n#include <string>\n#include <utility>\n#include <vector>\nusing namespace std;\n\nusing Student = pair<string, int>;\n\nvoid show(const char* label, const vector<Student>& rows) {\n    cout << label;\n    for (size_t i = 0; i < rows.size(); i++)\n        cout << (i ? \", \" : \" \") << rows[i].first << \" \" << rows[i].second;\n    cout << \"\\n\";\n}\n\nint main() {\n    vector<Student> students = {{\"Ramesh\", 80}, {\"Anil\", 50}, {\"Pyush\", 50}, {\"Ayan\", 80}};\n    auto byMarks = [](const Student& a, const Student& b) { return a.second < b.second; };\n    show(\"input:\", students);\n\n    vector<Student> v = students;\n    stable_sort(v.begin(), v.end(), byMarks);          // std::sort would NOT guarantee the tie order\n    show(\"by marks only:\", v);\n\n    v = students;\n    sort(v.begin(), v.end());                          // pass 1: by name (pairs compare by first)\n    stable_sort(v.begin(), v.end(), byMarks);          // pass 2: by marks, stable\n    show(\"by name, then by marks:\", v);\n}","filename":"C++"}'),
  ('43492841-177e-7a5a-8280-50ba1f8eec33', 'aX', 'code', '{"language":"java","code":"import java.util.ArrayList;\nimport java.util.Comparator;\nimport java.util.List;\n\npublic class Main {\n    record Student(String name, int marks) {}\n\n    static String show(List<Student> rows) {\n        StringBuilder sb = new StringBuilder();\n        for (Student s : rows) sb.append(sb.length() == 0 ? \"\" : \", \").append(s.name()).append('' '').append(s.marks());\n        return sb.toString();\n    }\n\n    public static void main(String[] args) {\n        List<Student> students = List.of(new Student(\"Ramesh\", 80), new Student(\"Anil\", 50),\n                                         new Student(\"Pyush\", 50), new Student(\"Ayan\", 80));\n        System.out.println(\"input: \" + show(students));\n\n        List<Student> v = new ArrayList<>(students);\n        v.sort(Comparator.comparingInt(Student::marks));     // List.sort is Timsort: stable\n        System.out.println(\"by marks only: \" + show(v));\n\n        v = new ArrayList<>(students);\n        v.sort(Comparator.comparing(Student::name));         // pass 1: by name\n        v.sort(Comparator.comparingInt(Student::marks));     // pass 2: by marks, stable\n        System.out.println(\"by name, then by marks: \" + show(v));\n    }\n}","filename":"Java"}'),
  ('0bed2aaf-c84d-7022-ad53-bbe9ee04aa82', 'aY', 'code', '{"language":"javascript","code":"const students = [[\"Ramesh\", 80], [\"Anil\", 50], [\"Pyush\", 50], [\"Ayan\", 80]];\nconst show = rows => rows.map(([name, marks]) => `${name} ${marks}`).join(\", \");\n\nconsole.log(\"input:\", show(students));\nconsole.log(\"by marks only:\", show(students.toSorted((a, b) => a[1] - b[1])));   // stable since ES2019\n\nconst byName = students.toSorted((a, b) => a[0].localeCompare(b[0]));   // pass 1: by name\nconst byBoth = byName.toSorted((a, b) => a[1] - b[1]);                  // pass 2: by marks, stable\nconsole.log(\"by name, then by marks:\", show(byBoth));","filename":"JavaScript"}'),
  ('5657c56c-856f-733a-b785-4d187b3b7247', 'aZ', 'code', '{"language":"text","code":"input: Ramesh 80, Anil 50, Pyush 50, Ayan 80\nby marks only: Anil 50, Pyush 50, Ramesh 80, Ayan 80\nby name, then by marks: Anil 50, Pyush 50, Ayan 80, Ramesh 80","filename":"Output"}'),
  ('e1c64e58-aa18-7a64-839e-aec941b874c1', 'aa', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Stable"}],[{"type":"text","text":"Not stable"}],[{"type":"text","text":"Why"}]],[[{"type":"text","text":"Bubble sort"}],[{"type":"text","text":"Selection sort"}],[{"type":"text","text":"selection swaps the minimum over elements it has not compared with — a long-distance swap can jump one equal element over another"}]],[[{"type":"text","text":"Insertion sort"}],[{"type":"text","text":"Quick sort"}],[{"type":"text","text":"partition swaps elements across the whole range"}]],[[{"type":"text","text":"Merge sort"}],[{"type":"text","text":"Heap sort"}],[{"type":"text","text":"the heap''s swaps with the last leaf reorder equal keys"}]],[[{"type":"text","text":"Timsort, counting sort"}],[{"type":"text","text":"std::sort","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Arrays.sort(int[])","marks":[{"type":"code"}]}],[{"type":"text","text":"introsort / quicksort based"}]]]}'),
  ('9e12d38b-bb34-73e8-b3f1-2cd6b0570373', 'ab', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Any unstable sort can be made stable by sorting "},{"type":"text","text":"(key, original index)","marks":[{"type":"code"}]},{"type":"text","text":" pairs — at the cost of "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" extra memory. And stability is irrelevant when keys are "},{"type":"text","text":"all","marks":[{"type":"italic"}]},{"type":"text","text":" of the data (sorting plain integers): two equal "},{"type":"text","text":"5","marks":[{"type":"code"}]},{"type":"text","text":"s are indistinguishable."}]}]}}'),
  ('99e66ce2-807a-7607-bbfe-e0b53ed16740', 'ac', 'heading', '{"level":1,"content":[{"type":"text","text":"Bubble sort"}]}'),
  ('b22ae3e7-bb98-7b54-a9b6-7e62ef980f6a', 'ad', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"arr = [10, 12, 5, 1, 10, 4, 56, 100]","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"1 4 5 10 10 12 56 100","marks":[{"type":"code"}]}]}]}}'),
  ('855eff90-4b4e-7cc5-9738-1da49828aa2e', 'ae', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Repeatedly walk the array and "},{"type":"text","text":"swap adjacent elements that are out of order","marks":[{"type":"bold"}]},{"type":"text","text":". After pass 1 the largest element has "},{"type":"text","text":"bubbled","marks":[{"type":"italic"}]},{"type":"text","text":" to the end; after pass "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" the last "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" positions are final, so each pass can stop earlier. If a whole pass makes no swap the array is sorted — stop early."}]}]}}'),
  ('e1279d4e-39f4-7f61-90f1-bf595329b4d1', 'af', 'code', '{"language":"text","code":"pass 1 on [5, 1, 4, 2]:\n  (5 1) 4 2  →  swap  →  1 5 4 2\n  1 (5 4) 2  →  swap  →  1 4 5 2\n  1 4 (5 2)  →  swap  →  1 4 2 5      5 is now final\npass 2 on the first 3:\n  (1 4) 2    →  ok\n  1 (4 2)    →  swap  →  1 2 4 5      4 is now final\npass 3: (1 2) ok → no swap in the whole pass → sorted","filename":"Each pass carries the largest remaining element to its place"}'),
  ('8d890054-5d41-7fef-be8f-e5a43bcd64d5', 'ag', 'code', '{"language":"python","code":"def bubble_sort(arr):\n    n = len(arr)\n    passes = 0\n    for i in range(n - 1):\n        swapped = False\n        passes += 1\n        for j in range(n - i - 1):            # last i elements are already in place\n            if arr[j] > arr[j + 1]:\n                arr[j], arr[j + 1] = arr[j + 1], arr[j]\n                swapped = True\n        if not swapped:                       # a clean pass: already sorted\n            break\n    return passes\n\nfor arr in ([10, 12, 5, 1, 10, 4, 56, 100], [1, 2, 3, 4, 5]):\n    passes = bubble_sort(arr)\n    print(\"sorted:\", *arr)\n    print(\"passes:\", passes)","filename":"Python"}'),
  ('e09f0d65-4c79-7c36-b27f-efb2eb28b64d', 'ah', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <utility>\n#include <vector>\nusing namespace std;\n\nint bubbleSort(vector<int>& arr) {\n    int n = arr.size(), passes = 0;\n    for (int i = 0; i < n - 1; i++) {\n        bool swapped = false;\n        passes++;\n        for (int j = 0; j < n - i - 1; j++) {        // last i elements are already in place\n            if (arr[j] > arr[j + 1]) {\n                swap(arr[j], arr[j + 1]);\n                swapped = true;\n            }\n        }\n        if (!swapped) break;                           // a clean pass: already sorted\n    }\n    return passes;\n}\n\nint main() {\n    vector<vector<int>> tests = {{10, 12, 5, 1, 10, 4, 56, 100}, {1, 2, 3, 4, 5}};\n    for (auto& arr : tests) {\n        int passes = bubbleSort(arr);\n        cout << \"sorted:\";\n        for (int x : arr) cout << \" \" << x;\n        cout << \"\\npasses: \" << passes << \"\\n\";\n    }\n}","filename":"C++"}'),
  ('1acfd301-de3c-7dbb-8a8e-e64adbad8944', 'ai', 'code', '{"language":"java","code":"public class Main {\n    static int bubbleSort(int[] arr) {\n        int n = arr.length, passes = 0;\n        for (int i = 0; i < n - 1; i++) {\n            boolean swapped = false;\n            passes++;\n            for (int j = 0; j < n - i - 1; j++) {        // last i elements are already in place\n                if (arr[j] > arr[j + 1]) {\n                    int t = arr[j]; arr[j] = arr[j + 1]; arr[j + 1] = t;\n                    swapped = true;\n                }\n            }\n            if (!swapped) break;                           // a clean pass: already sorted\n        }\n        return passes;\n    }\n\n    public static void main(String[] args) {\n        int[][] tests = {{10, 12, 5, 1, 10, 4, 56, 100}, {1, 2, 3, 4, 5}};\n        for (int[] arr : tests) {\n            int passes = bubbleSort(arr);\n            StringBuilder sb = new StringBuilder(\"sorted:\");\n            for (int x : arr) sb.append('' '').append(x);\n            System.out.println(sb);\n            System.out.println(\"passes: \" + passes);\n        }\n    }\n}","filename":"Java"}'),
  ('40112717-f8a8-7091-a2b4-c69c5458301f', 'aj', 'code', '{"language":"javascript","code":"function bubbleSort(arr) {\n    const n = arr.length;\n    let passes = 0;\n    for (let i = 0; i < n - 1; i++) {\n        let swapped = false;\n        passes++;\n        for (let j = 0; j < n - i - 1; j++) {            // last i elements are already in place\n            if (arr[j] > arr[j + 1]) {\n                [arr[j], arr[j + 1]] = [arr[j + 1], arr[j]];\n                swapped = true;\n            }\n        }\n        if (!swapped) break;                               // a clean pass: already sorted\n    }\n    return passes;\n}\n\nfor (const arr of [[10, 12, 5, 1, 10, 4, 56, 100], [1, 2, 3, 4, 5]]) {\n    const passes = bubbleSort(arr);\n    console.log(\"sorted:\", arr.join(\" \"));\n    console.log(\"passes:\", passes);\n}","filename":"JavaScript"}'),
  ('b847c470-7339-7054-8920-eae42f8e8753', 'ak', 'code', '{"language":"text","code":"sorted: 1 4 5 10 10 12 56 100\npasses: 5\nsorted: 1 2 3 4 5\npasses: 1","filename":"Output"}'),
  ('ebb39e9d-b3f3-7637-a12a-8a02ed0cb6c9', 'al', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n²) — O(n) best with the swapped flag · Space O(1)"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Stable","marks":[{"type":"bold"}]},{"type":"text","text":": only adjacent elements are swapped, and only when strictly greater — equal neighbours never cross."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"In-place","marks":[{"type":"bold"}]},{"type":"text","text":", trivially simple — which is why it appears in every textbook and almost no real program."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Without the "},{"type":"text","text":"swapped","marks":[{"type":"code"}]},{"type":"text","text":" flag it always runs "},{"type":"text","text":"n − 1","marks":[{"type":"code"}]},{"type":"text","text":" full passes, even on sorted input."}]}]}]}]}}'),
  ('4ac867ff-7b3a-746b-b281-832c43d62a69', 'am', 'heading', '{"level":1,"content":[{"type":"text","text":"Selection sort"}]}'),
  ('4ac5b1d9-5790-75d2-8bcf-7d2cda3d02f4', 'an', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"arr = [29, 10, 14, 37, 13]","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 13 14 29 37","marks":[{"type":"code"}]}]}]}}'),
  ('fae5c294-49ac-7827-9b78-2cfe62bddd4b', 'ao', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Position "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" should hold the "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":"-th smallest value. Find the "},{"type":"text","text":"minimum of the unsorted part","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"arr[i..n-1]","marks":[{"type":"code"}]},{"type":"text","text":" and swap it into position "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":"; the sorted prefix grows by one each pass. Exactly "},{"type":"text","text":"n − 1","marks":[{"type":"code"}]},{"type":"text","text":" swaps, whatever the input."}]}]}}'),
  ('8872efdd-6e3c-7acc-bca8-d1e6fa4738c5', 'ap', 'code', '{"language":"python","code":"def selection_sort(arr, trace=False):\n    n = len(arr)\n    for i in range(n - 1):\n        min_index = i\n        for j in range(i + 1, n):           # find the minimum of arr[i..n-1]\n            if arr[j] < arr[min_index]:\n                min_index = j\n        arr[i], arr[min_index] = arr[min_index], arr[i]   # one swap per pass\n        if trace:\n            print(f\"pass {i + 1}: min {arr[i]} ->\", *arr)\n\nselection_sort([29, 10, 14, 37, 13], trace=True)\narr = [10, 12, 5, 1, 10, 4, 56, 100]\nselection_sort(arr)\nprint(\"sorted:\", *arr)","filename":"Python"}'),
  ('07b18272-786f-74cf-9712-c62386b6b696', 'aq', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <utility>\n#include <vector>\nusing namespace std;\n\nvoid show(const vector<int>& arr) {\n    for (int x : arr) cout << \" \" << x;\n    cout << \"\\n\";\n}\n\nvoid selectionSort(vector<int>& arr, bool trace = false) {\n    int n = arr.size();\n    for (int i = 0; i < n - 1; i++) {\n        int minIndex = i;\n        for (int j = i + 1; j < n; j++)              // find the minimum of arr[i..n-1]\n            if (arr[j] < arr[minIndex]) minIndex = j;\n        swap(arr[i], arr[minIndex]);                 // one swap per pass\n        if (trace) { cout << \"pass \" << i + 1 << \": min \" << arr[i] << \" ->\"; show(arr); }\n    }\n}\n\nint main() {\n    vector<int> small = {29, 10, 14, 37, 13};\n    selectionSort(small, true);\n    vector<int> arr = {10, 12, 5, 1, 10, 4, 56, 100};\n    selectionSort(arr);\n    cout << \"sorted:\";\n    show(arr);\n}","filename":"C++"}'),
  ('54ef0ab5-393b-7f2f-a107-f0bfb8e503d8', 'ar', 'code', '{"language":"java","code":"public class Main {\n    static String join(int[] arr) {\n        StringBuilder sb = new StringBuilder();\n        for (int x : arr) sb.append('' '').append(x);\n        return sb.toString();\n    }\n\n    static void selectionSort(int[] arr, boolean trace) {\n        int n = arr.length;\n        for (int i = 0; i < n - 1; i++) {\n            int minIndex = i;\n            for (int j = i + 1; j < n; j++)              // find the minimum of arr[i..n-1]\n                if (arr[j] < arr[minIndex]) minIndex = j;\n            int t = arr[i]; arr[i] = arr[minIndex]; arr[minIndex] = t;   // one swap per pass\n            if (trace) System.out.println(\"pass \" + (i + 1) + \": min \" + arr[i] + \" ->\" + join(arr));\n        }\n    }\n\n    public static void main(String[] args) {\n        selectionSort(new int[]{29, 10, 14, 37, 13}, true);\n        int[] arr = {10, 12, 5, 1, 10, 4, 56, 100};\n        selectionSort(arr, false);\n        System.out.println(\"sorted:\" + join(arr));\n    }\n}","filename":"Java"}'),
  ('fa8cecbd-5392-7f37-b5a1-33e9bb42c51a', 'as', 'code', '{"language":"javascript","code":"function selectionSort(arr, trace = false) {\n    const n = arr.length;\n    for (let i = 0; i < n - 1; i++) {\n        let minIndex = i;\n        for (let j = i + 1; j < n; j++)                  // find the minimum of arr[i..n-1]\n            if (arr[j] < arr[minIndex]) minIndex = j;\n        [arr[i], arr[minIndex]] = [arr[minIndex], arr[i]];   // one swap per pass\n        if (trace) console.log(`pass ${i + 1}: min ${arr[i]} ->`, arr.join(\" \"));\n    }\n}\n\nselectionSort([29, 10, 14, 37, 13], true);\nconst arr = [10, 12, 5, 1, 10, 4, 56, 100];\nselectionSort(arr);\nconsole.log(\"sorted:\", arr.join(\" \"));","filename":"JavaScript"}'),
  ('c2b7763e-7476-784d-b0c9-6a8617f93013', 'at', 'code', '{"language":"text","code":"pass 1: min 10 -> 10 29 14 37 13\npass 2: min 13 -> 10 13 14 37 29\npass 3: min 14 -> 10 13 14 37 29\npass 4: min 29 -> 10 13 14 29 37\nsorted: 1 4 5 10 10 12 56 100","filename":"Output"}'),
  ('6d82250e-b996-737f-894a-3b7d2218a6be', 'au', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time Θ(n²) in every case · Space O(1)"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Always "},{"type":"text","text":"Θ(n²)","marks":[{"type":"code"}]},{"type":"text","text":" comparisons — it cannot notice that the input is already sorted."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fewest memory writes","marks":[{"type":"bold"}]},{"type":"text","text":" of the simple sorts (at most "},{"type":"text","text":"n − 1","marks":[{"type":"code"}]},{"type":"text","text":" swaps), useful when writes are expensive (flash memory). Cycle sort is the optimum for writes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Not stable","marks":[{"type":"bold"}]},{"type":"text","text":": in pass 1 on "},{"type":"text","text":"[2a, 2b, 1]","marks":[{"type":"code"}]},{"type":"text","text":" the "},{"type":"text","text":"1","marks":[{"type":"code"}]},{"type":"text","text":" is swapped with "},{"type":"text","text":"2a","marks":[{"type":"code"}]},{"type":"text","text":", which lands after "},{"type":"text","text":"2b","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"In-place. Its idea — repeatedly extract the minimum — is the seed of "},{"type":"text","text":"heap sort","marks":[{"type":"bold"}]},{"type":"text","text":", which extracts it in "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":" instead of "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}}'),
  ('e058650b-282f-7cca-889b-4c41e0db6f35', 'av', 'heading', '{"level":1,"content":[{"type":"text","text":"Insertion sort"}]}'),
  ('6e3d1993-92ce-79ff-bdc9-9ac0eb5f5e8f', 'aw', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"arr = [10, 12, 5, 1, 10, 4]","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"1 4 5 10 10 12","marks":[{"type":"code"}]}]}]}}'),
  ('27d3c9a1-260a-7f89-badb-692190c36705', 'ax', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Keep the prefix "},{"type":"text","text":"arr[0..i-1]","marks":[{"type":"code"}]},{"type":"text","text":" sorted (as you would sort cards in your hand). Take the next element "},{"type":"text","text":"x = arr[i]","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"shift","marks":[{"type":"bold"}]},{"type":"text","text":" every larger element of the prefix one slot to the right, and drop "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":" into the gap. On nearly sorted input almost nothing shifts, which is why it is "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" in the best case."}]}]}}'),
  ('0d782c2c-12af-7761-94f5-8741b76fc608', 'ay', 'code', '{"language":"text","code":"i = 2, x = 5:     [10, 12 | 5, 1, 10, 4]\n                   shift 12 →  [10, _, 12]   shift 10 →  [_, 10, 12]   place 5 →  [5, 10, 12 | 1, 10, 4]","filename":"Insert arr[i] into the sorted prefix by shifting, not swapping"}'),
  ('1d07cbd5-4025-7903-8e99-b6e42b0ae2fa', 'az', 'code', '{"language":"python","code":"def insertion_sort(arr, trace=False):\n    for i in range(1, len(arr)):\n        x = arr[i]                             # the element to insert\n        j = i - 1\n        while j >= 0 and arr[j] > x:           # shift larger elements right ...\n            arr[j + 1] = arr[j]\n            j -= 1\n        arr[j + 1] = x                         # ... and drop x into the gap\n        if trace:\n            print(f\"insert {x}:\", *arr)\n\ninsertion_sort([10, 12, 5, 1, 10, 4], trace=True)\narr = [10, 12, 5, 1, 10, 4, 56, 100]\ninsertion_sort(arr)\nprint(\"sorted:\", *arr)","filename":"Python"}'),
  ('19b4acb3-7084-7d49-a93f-57d0f9c474d6', 'b00', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <vector>\nusing namespace std;\n\nvoid show(const vector<int>& arr) {\n    for (int x : arr) cout << \" \" << x;\n    cout << \"\\n\";\n}\n\nvoid insertionSort(vector<int>& arr, bool trace = false) {\n    int n = arr.size();\n    for (int i = 1; i < n; i++) {\n        int x = arr[i];                              // the element to insert\n        int j = i - 1;\n        while (j >= 0 && arr[j] > x) {               // shift larger elements right ...\n            arr[j + 1] = arr[j];\n            j--;\n        }\n        arr[j + 1] = x;                              // ... and drop x into the gap\n        if (trace) { cout << \"insert \" << x << \":\"; show(arr); }\n    }\n}\n\nint main() {\n    vector<int> small = {10, 12, 5, 1, 10, 4};\n    insertionSort(small, true);\n    vector<int> arr = {10, 12, 5, 1, 10, 4, 56, 100};\n    insertionSort(arr);\n    cout << \"sorted:\";\n    show(arr);\n}","filename":"C++"}'),
  ('b108cc35-f1f8-7546-9cb4-227df8dd390e', 'b01', 'code', '{"language":"java","code":"public class Main {\n    static String join(int[] arr) {\n        StringBuilder sb = new StringBuilder();\n        for (int x : arr) sb.append('' '').append(x);\n        return sb.toString();\n    }\n\n    static void insertionSort(int[] arr, boolean trace) {\n        for (int i = 1; i < arr.length; i++) {\n            int x = arr[i];                              // the element to insert\n            int j = i - 1;\n            while (j >= 0 && arr[j] > x) {               // shift larger elements right ...\n                arr[j + 1] = arr[j];\n                j--;\n            }\n            arr[j + 1] = x;                              // ... and drop x into the gap\n            if (trace) System.out.println(\"insert \" + x + \":\" + join(arr));\n        }\n    }\n\n    public static void main(String[] args) {\n        insertionSort(new int[]{10, 12, 5, 1, 10, 4}, true);\n        int[] arr = {10, 12, 5, 1, 10, 4, 56, 100};\n        insertionSort(arr, false);\n        System.out.println(\"sorted:\" + join(arr));\n    }\n}","filename":"Java"}'),
  ('587b0f48-f48d-7914-9d73-ecc1476fce76', 'b02', 'code', '{"language":"javascript","code":"function insertionSort(arr, trace = false) {\n    for (let i = 1; i < arr.length; i++) {\n        const x = arr[i];                                // the element to insert\n        let j = i - 1;\n        while (j >= 0 && arr[j] > x) {                   // shift larger elements right ...\n            arr[j + 1] = arr[j];\n            j--;\n        }\n        arr[j + 1] = x;                                  // ... and drop x into the gap\n        if (trace) console.log(`insert ${x}:`, arr.join(\" \"));\n    }\n}\n\ninsertionSort([10, 12, 5, 1, 10, 4], true);\nconst arr = [10, 12, 5, 1, 10, 4, 56, 100];\ninsertionSort(arr);\nconsole.log(\"sorted:\", arr.join(\" \"));","filename":"JavaScript"}'),
  ('e5b16371-fbe5-7cd6-b6e3-d8161af5bc27', 'b03', 'code', '{"language":"text","code":"insert 12: 10 12 5 1 10 4\ninsert 5: 5 10 12 1 10 4\ninsert 1: 1 5 10 12 10 4\ninsert 10: 1 5 10 10 12 4\ninsert 4: 1 4 5 10 10 12\nsorted: 1 4 5 10 10 12 56 100","filename":"Output"}'),
  ('94306608-9774-7ee6-849a-c87757e612ea', 'b04', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n²) worst / average · O(n) best (sorted input) · Space O(1)"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Stable","marks":[{"type":"bold"}]},{"type":"text","text":" (shifts only strictly greater elements) and "},{"type":"text","text":"in-place","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The practical choice for "},{"type":"text","text":"small arrays","marks":[{"type":"bold"}]},{"type":"text","text":" (≈ 16–32 elements) and nearly sorted data — Timsort and introsort both switch to insertion sort for short ranges."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"O(n + d)","marks":[{"type":"code"}]},{"type":"text","text":" where "},{"type":"text","text":"d","marks":[{"type":"code"}]},{"type":"text","text":" is the number of inversions: an array with few elements out of place sorts in almost linear time."}]}]}]}]}}'),
  ('018b78bd-4cf8-7748-8ab9-74c03d283297', 'b05', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The original notes compared "},{"type":"text","text":"x < l[i]","marks":[{"type":"code"}]},{"type":"text","text":" in the inner loop. "},{"type":"text","text":"l[i]","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"is","marks":[{"type":"italic"}]},{"type":"text","text":" "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":", so the condition is never true and nothing is ever shifted — the array came back unsorted. The comparison must be against "},{"type":"text","text":"arr[j]","marks":[{"type":"code"}]},{"type":"text","text":", the element being shifted."}]}]}}'),
  ('e0f45cb5-d88b-7bcb-90ac-d3424515d360', 'b06', 'heading', '{"level":1,"content":[{"type":"text","text":"Merging two sorted arrays"}]}'),
  ('3da958f6-b218-7c8c-928d-3b10ec443df2', 'b07', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"a = [10, 15, 20], b = [5, 6, 6, 30]","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"5 6 6 10 15 20 30","marks":[{"type":"code"}]}]}]}}'),
  ('b9b88b46-b4fa-7dbf-ac1d-a3a27a45e429', 'b08', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Naive: concatenate and sort — "},{"type":"text","text":"O((m + n) log(m + n))","marks":[{"type":"code"}]},{"type":"text","text":". It ignores the fact that both inputs are already sorted."}]}]}}'),
  ('48b317f4-4c91-7995-af2b-c62729d132a4', 'b09', 'code', '{"language":"python","code":"def merge_naive(a, b):\n    res = a + b\n    res.sort()                 # throws away the order we already had\n    return res\n\nprint(*merge_naive([10, 15, 20], [5, 6, 6, 30]))","filename":"Python"}'),
  ('4ac38a45-1122-7549-b9e3-1d8d2370454e', 'b0A', 'code', '{"language":"text","code":"5 6 6 10 15 20 30","filename":"Output"}'),
  ('0d84983f-8dd1-74f5-b08c-50ed809ef49a', 'b0B', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two pointers.","marks":[{"type":"bold"}]},{"type":"text","text":" The smallest remaining element of the union is either "},{"type":"text","text":"a[i]","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"b[j]","marks":[{"type":"code"}]},{"type":"text","text":" — the heads of the two arrays. Compare them, copy the smaller one to the result and advance its pointer. When one array runs out, copy the rest of the other. Every element is looked at once: "},{"type":"text","text":"O(m + n)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('258d8aa9-240c-7cc5-9bca-ebf4ab8297fd', 'b0C', 'code', '{"language":"text","code":"a = [10, 15, 20]       b = [5, 6, 6, 30]       res = []\n     i                      j\n10 > 5   → take 5          res = [5]              j → 6\n10 > 6   → take 6          res = [5 6]            j → 6\n10 > 6   → take 6          res = [5 6 6]          j → 30\n10 < 30  → take 10         res = [5 6 6 10]       i → 15\n15 < 30  → take 15         res = [5 6 6 10 15]    i → 20\n20 < 30  → take 20         res = [5 6 6 10 15 20] a is exhausted\ncopy the rest of b         res = [5 6 6 10 15 20 30]","filename":"The merge step: always take the smaller head"}'),
  ('885a1749-eabc-78c7-9dd0-5f05f9fcdd7f', 'b0D', 'code', '{"language":"python","code":"def merge(a, b):\n    res = []\n    i = j = 0\n    while i < len(a) and j < len(b):\n        if a[i] <= b[j]:             # <= keeps the merge stable (a''s element first on a tie)\n            res.append(a[i])\n            i += 1\n        else:\n            res.append(b[j])\n            j += 1\n    res.extend(a[i:])                # at most one of these has anything left\n    res.extend(b[j:])\n    return res\n\nprint(*merge([10, 15, 20], [5, 6, 6, 30]))","filename":"Python"}'),
  ('45bb1ced-e79c-7072-a4ec-af3375f98e03', 'b0E', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <vector>\nusing namespace std;\n\nvector<int> merge(const vector<int>& a, const vector<int>& b) {\n    vector<int> res;\n    int m = a.size(), n = b.size(), i = 0, j = 0;\n    while (i < m && j < n) {\n        if (a[i] <= b[j]) res.push_back(a[i++]);   // <= keeps the merge stable\n        else res.push_back(b[j++]);\n    }\n    while (i < m) res.push_back(a[i++]);           // at most one of these has anything left\n    while (j < n) res.push_back(b[j++]);\n    return res;\n}\n\nint main() {\n    vector<int> res = merge({10, 15, 20}, {5, 6, 6, 30});\n    for (size_t k = 0; k < res.size(); k++) cout << (k ? \" \" : \"\") << res[k];\n    cout << \"\\n\";\n}","filename":"C++"}'),
  ('e5d595cc-67df-77f1-b13a-642506b301af', 'b0F', 'code', '{"language":"java","code":"public class Main {\n    static int[] merge(int[] a, int[] b) {\n        int m = a.length, n = b.length, i = 0, j = 0, k = 0;\n        int[] res = new int[m + n];\n        while (i < m && j < n) {\n            if (a[i] <= b[j]) res[k++] = a[i++];     // <= keeps the merge stable\n            else res[k++] = b[j++];\n        }\n        while (i < m) res[k++] = a[i++];             // at most one of these has anything left\n        while (j < n) res[k++] = b[j++];\n        return res;\n    }\n\n    public static void main(String[] args) {\n        int[] res = merge(new int[]{10, 15, 20}, new int[]{5, 6, 6, 30});\n        StringBuilder sb = new StringBuilder();\n        for (int x : res) sb.append(sb.length() == 0 ? \"\" : \" \").append(x);\n        System.out.println(sb);\n    }\n}","filename":"Java"}'),
  ('c4aeb389-2dd8-722c-b244-7df580618010', 'b0G', 'code', '{"language":"javascript","code":"function merge(a, b) {\n    const res = [];\n    let i = 0, j = 0;\n    while (i < a.length && j < b.length) {\n        if (a[i] <= b[j]) res.push(a[i++]);       // <= keeps the merge stable\n        else res.push(b[j++]);\n    }\n    while (i < a.length) res.push(a[i++]);        // at most one of these has anything left\n    while (j < b.length) res.push(b[j++]);\n    return res;\n}\n\nconsole.log(merge([10, 15, 20], [5, 6, 6, 30]).join(\" \"));","filename":"JavaScript"}'),
  ('2a354b98-0941-7dc9-91a8-ca758bec0fd4', 'b0H', 'code', '{"language":"text","code":"5 6 6 10 15 20 30","filename":"Output"}'),
  ('7598a926-d15f-7100-831b-bd8768d7bdf6', 'b0I', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(m + n) · Space O(m + n) for the result"}]}]}}'),
  ('3d97dbf8-cebd-72e6-8b4a-9db15b4dcb7f', 'b0J', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use "},{"type":"text","text":"<=","marks":[{"type":"code"}]},{"type":"text","text":" (not "},{"type":"text","text":"<","marks":[{"type":"code"}]},{"type":"text","text":") when comparing "},{"type":"text","text":"a[i]","marks":[{"type":"code"}]},{"type":"text","text":" with "},{"type":"text","text":"b[j]","marks":[{"type":"code"}]},{"type":"text","text":": on a tie the element from the "},{"type":"text","text":"left","marks":[{"type":"italic"}]},{"type":"text","text":" array is taken first, which is what makes merge sort stable."}]}]}}'),
  ('6037e033-f004-7978-ac78-3e3c20a753e0', 'b0K', 'heading', '{"level":1,"content":[{"type":"text","text":"Merge subarray"}]}'),
  ('7a63e06b-6846-717f-8cfa-f3a18f6463fe', 'b0L', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"a = [10, 15, 20, 11, 13], low = 0, mid = 2, high = 4","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 11 13 15 20","marks":[{"type":"code"}]}]}]}}'),
  ('fd4a5829-2eb4-74bd-be1a-565c5ba3ca27', 'b0M', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Merge sort needs the same merge, but "},{"type":"text","text":"inside one array","marks":[{"type":"bold"}]},{"type":"text","text":": the two sorted halves are "},{"type":"text","text":"a[low..mid]","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"a[mid+1..high]","marks":[{"type":"code"}]},{"type":"text","text":", and the merged result must land back in "},{"type":"text","text":"a[low..high]","marks":[{"type":"code"}]},{"type":"text","text":". Copy the two halves into temporary arrays "},{"type":"text","text":"left","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"right","marks":[{"type":"code"}]},{"type":"text","text":", then merge them back starting at index "},{"type":"text","text":"low","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('61acafa0-c521-7c9e-ab3b-071b5b0e849a', 'b0N', 'code', '{"language":"python","code":"def merge(a, low, mid, high):\n    left = a[low:mid + 1]                   # copies: a[low..mid] and a[mid+1..high]\n    right = a[mid + 1:high + 1]\n    i = j = 0\n    k = low                                 # write position in a\n    while i < len(left) and j < len(right):\n        if left[i] <= right[j]:\n            a[k] = left[i]\n            i += 1\n        else:\n            a[k] = right[j]\n            j += 1\n        k += 1\n    while i < len(left):                    # leftovers\n        a[k] = left[i]\n        i += 1\n        k += 1\n    while j < len(right):\n        a[k] = right[j]\n        j += 1\n        k += 1\n\na = [10, 15, 20, 11, 13]\nmerge(a, 0, 2, 4)\nprint(*a)","filename":"Python"}'),
  ('8cfa81db-75cb-7d5f-b302-ee9941b78e95', 'b0O', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <vector>\nusing namespace std;\n\nvoid merge(vector<int>& a, int low, int mid, int high) {\n    vector<int> left(a.begin() + low, a.begin() + mid + 1);        // a[low..mid]\n    vector<int> right(a.begin() + mid + 1, a.begin() + high + 1);  // a[mid+1..high]\n    int nl = left.size(), nr = right.size(), i = 0, j = 0, k = low;   // k: write position in a\n    while (i < nl && j < nr) {\n        if (left[i] <= right[j]) a[k++] = left[i++];\n        else a[k++] = right[j++];\n    }\n    while (i < nl) a[k++] = left[i++];        // leftovers\n    while (j < nr) a[k++] = right[j++];\n}\n\nint main() {\n    vector<int> a = {10, 15, 20, 11, 13};\n    merge(a, 0, 2, 4);\n    for (size_t k = 0; k < a.size(); k++) cout << (k ? \" \" : \"\") << a[k];\n    cout << \"\\n\";\n}","filename":"C++"}'),
  ('24e4d971-a522-783c-a34e-c8dee3685aee', 'b0P', 'code', '{"language":"java","code":"import java.util.Arrays;\n\npublic class Main {\n    static void merge(int[] a, int low, int mid, int high) {\n        int[] left = Arrays.copyOfRange(a, low, mid + 1);         // a[low..mid]\n        int[] right = Arrays.copyOfRange(a, mid + 1, high + 1);   // a[mid+1..high]\n        int i = 0, j = 0, k = low;                                // k: write position in a\n        while (i < left.length && j < right.length) {\n            if (left[i] <= right[j]) a[k++] = left[i++];\n            else a[k++] = right[j++];\n        }\n        while (i < left.length) a[k++] = left[i++];              // leftovers\n        while (j < right.length) a[k++] = right[j++];\n    }\n\n    public static void main(String[] args) {\n        int[] a = {10, 15, 20, 11, 13};\n        merge(a, 0, 2, 4);\n        StringBuilder sb = new StringBuilder();\n        for (int x : a) sb.append(sb.length() == 0 ? \"\" : \" \").append(x);\n        System.out.println(sb);\n    }\n}","filename":"Java"}'),
  ('d37c4ae8-d59b-7560-bc91-1543f6cda167', 'b0Q', 'code', '{"language":"javascript","code":"function merge(a, low, mid, high) {\n    const left = a.slice(low, mid + 1);            // a[low..mid]\n    const right = a.slice(mid + 1, high + 1);      // a[mid+1..high]\n    let i = 0, j = 0, k = low;                     // k: write position in a\n    while (i < left.length && j < right.length) {\n        if (left[i] <= right[j]) a[k++] = left[i++];\n        else a[k++] = right[j++];\n    }\n    while (i < left.length) a[k++] = left[i++];   // leftovers\n    while (j < right.length) a[k++] = right[j++];\n}\n\nconst a = [10, 15, 20, 11, 13];\nmerge(a, 0, 2, 4);\nconsole.log(a.join(\" \"));","filename":"JavaScript"}'),
  ('f735c383-3883-7877-98e0-2dedfdb14772', 'b0R', 'code', '{"language":"text","code":"10 11 13 15 20","filename":"Output"}'),
  ('e5c232b5-6a05-7283-94d8-c5e3829cae37', 'b0S', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(high − low + 1) · Space O(high − low + 1) temporary copies"}]}]}}'),
  ('93057d3c-a4c3-7797-ac21-33736f206a47', 'b0T', 'heading', '{"level":1,"content":[{"type":"text","text":"Merge sort"}]}'),
  ('b67ef793-f065-76f7-9bc0-58aee9dcf3c4', 'b0U', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"arr = [38, 27, 43, 3, 9, 82, 10]","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"3 9 10 27 38 43 82","marks":[{"type":"code"}]}]}]}}'),
  ('14617de0-d823-7fc4-b4a9-40eed400e80b', 'b0V', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Divide and conquer.","marks":[{"type":"bold"}]},{"type":"text","text":" A one-element array is sorted. Otherwise split the array in half, sort each half recursively, and "},{"type":"text","text":"merge","marks":[{"type":"italic"}]},{"type":"text","text":" the two sorted halves with the merge above. All the real work happens in the merges: "},{"type":"text","text":"log n","marks":[{"type":"code"}]},{"type":"text","text":" levels, each merging "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" elements in total."}]}]}}'),
  ('9b498654-265b-7fcd-9509-a94ca8efe376', 'b0W', 'code', '{"language":"text","code":"             [38 27 43 3 9 82 10]\n            /                    \\                  divide\n     [38 27 43 3]              [9 82 10]\n      /        \\                /       \\\n  [38 27]    [43 3]         [9 82]     [10]\n  /    \\      /   \\         /   \\\n[38]  [27]  [43]  [3]     [9]  [82]\n  \\    /      \\   /         \\   /\n  [27 38]    [3 43]        [9 82]     [10]           merge\n      \\        /                \\       /\n     [3 27 38 43]              [9 10 82]\n            \\                    /\n             [3 9 10 27 38 43 82]","filename":"Split down to single elements, then merge back up — log2 n levels"}'),
  ('e73a5e12-d871-731d-8de6-e2b49e311e45', 'b0X', 'code', '{"language":"python","code":"def merge(a, low, mid, high):\n    left, right = a[low:mid + 1], a[mid + 1:high + 1]\n    i = j = 0\n    k = low\n    while i < len(left) and j < len(right):\n        if left[i] <= right[j]:\n            a[k] = left[i]; i += 1\n        else:\n            a[k] = right[j]; j += 1\n        k += 1\n    while i < len(left):\n        a[k] = left[i]; i += 1; k += 1\n    while j < len(right):\n        a[k] = right[j]; j += 1; k += 1\n\ndef merge_sort(a, low, high):\n    if low < high:                       # at least two elements\n        mid = low + (high - low) // 2\n        merge_sort(a, low, mid)          # sort the left half\n        merge_sort(a, mid + 1, high)     # sort the right half\n        merge(a, low, mid, high)         # combine\n\nfor arr in ([38, 27, 43, 3, 9, 82, 10], [10, 15, 20, 11, 13]):\n    merge_sort(arr, 0, len(arr) - 1)\n    print(*arr)","filename":"Python"}'),
  ('65ea69da-c82f-7a1a-a9e4-37ee84718b55', 'b0Y', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <vector>\nusing namespace std;\n\nvoid merge(vector<int>& a, int low, int mid, int high) {\n    vector<int> left(a.begin() + low, a.begin() + mid + 1);\n    vector<int> right(a.begin() + mid + 1, a.begin() + high + 1);\n    int nl = left.size(), nr = right.size(), i = 0, j = 0, k = low;\n    while (i < nl && j < nr) a[k++] = (left[i] <= right[j]) ? left[i++] : right[j++];\n    while (i < nl) a[k++] = left[i++];\n    while (j < nr) a[k++] = right[j++];\n}\n\nvoid mergeSort(vector<int>& a, int low, int high) {\n    if (low < high) {                          // at least two elements\n        int mid = low + (high - low) / 2;\n        mergeSort(a, low, mid);                // sort the left half\n        mergeSort(a, mid + 1, high);           // sort the right half\n        merge(a, low, mid, high);              // combine\n    }\n}\n\nint main() {\n    vector<vector<int>> tests = {{38, 27, 43, 3, 9, 82, 10}, {10, 15, 20, 11, 13}};\n    for (auto& arr : tests) {\n        mergeSort(arr, 0, (int)arr.size() - 1);\n        for (size_t k = 0; k < arr.size(); k++) cout << (k ? \" \" : \"\") << arr[k];\n        cout << \"\\n\";\n    }\n}","filename":"C++"}'),
  ('2ba96ade-2a57-745a-86ec-86745de42cfe', 'b0Z', 'code', '{"language":"java","code":"import java.util.Arrays;\n\npublic class Main {\n    static void merge(int[] a, int low, int mid, int high) {\n        int[] left = Arrays.copyOfRange(a, low, mid + 1);\n        int[] right = Arrays.copyOfRange(a, mid + 1, high + 1);\n        int i = 0, j = 0, k = low;\n        while (i < left.length && j < right.length) a[k++] = (left[i] <= right[j]) ? left[i++] : right[j++];\n        while (i < left.length) a[k++] = left[i++];\n        while (j < right.length) a[k++] = right[j++];\n    }\n\n    static void mergeSort(int[] a, int low, int high) {\n        if (low < high) {                          // at least two elements\n            int mid = low + (high - low) / 2;\n            mergeSort(a, low, mid);                // sort the left half\n            mergeSort(a, mid + 1, high);           // sort the right half\n            merge(a, low, mid, high);              // combine\n        }\n    }\n\n    public static void main(String[] args) {\n        int[][] tests = {{38, 27, 43, 3, 9, 82, 10}, {10, 15, 20, 11, 13}};\n        for (int[] arr : tests) {\n            mergeSort(arr, 0, arr.length - 1);\n            StringBuilder sb = new StringBuilder();\n            for (int x : arr) sb.append(sb.length() == 0 ? \"\" : \" \").append(x);\n            System.out.println(sb);\n        }\n    }\n}","filename":"Java"}'),
  ('32c5aa16-690f-7977-ab71-334c08d6c200', 'b0a', 'code', '{"language":"javascript","code":"function merge(a, low, mid, high) {\n    const left = a.slice(low, mid + 1), right = a.slice(mid + 1, high + 1);\n    let i = 0, j = 0, k = low;\n    while (i < left.length && j < right.length) a[k++] = (left[i] <= right[j]) ? left[i++] : right[j++];\n    while (i < left.length) a[k++] = left[i++];\n    while (j < right.length) a[k++] = right[j++];\n}\n\nfunction mergeSort(a, low, high) {\n    if (low < high) {                              // at least two elements\n        const mid = low + Math.floor((high - low) / 2);\n        mergeSort(a, low, mid);                    // sort the left half\n        mergeSort(a, mid + 1, high);               // sort the right half\n        merge(a, low, mid, high);                  // combine\n    }\n}\n\nfor (const arr of [[38, 27, 43, 3, 9, 82, 10], [10, 15, 20, 11, 13]]) {\n    mergeSort(arr, 0, arr.length - 1);\n    console.log(arr.join(\" \"));\n}","filename":"JavaScript"}'),
  ('9eba3ce6-0bb8-742c-8543-252184294315', 'b0b', 'code', '{"language":"text","code":"3 9 10 27 38 43 82\n10 11 13 15 20","filename":"Output"}'),
  ('17559a5f-c2aa-7bb7-bdab-63ccb571f338', 'b0c', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time Θ(n log n) in every case · Space O(n) temporary arrays + O(log n) stack"}]},{"type":"paragraph","content":[{"type":"text","text":"T(n) = 2 T(n / 2) + Θ(n) ⇒ T(n) = Θ(n log n)","marks":[{"type":"code"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Stable","marks":[{"type":"bold"}]},{"type":"text","text":" (the "},{"type":"text","text":"<=","marks":[{"type":"code"}]},{"type":"text","text":" in merge) and "},{"type":"text","text":"guaranteed","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"Θ(n log n)","marks":[{"type":"code"}]},{"type":"text","text":" — no bad inputs, unlike quick sort."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Not in-place","marks":[{"type":"bold"}]},{"type":"text","text":": the merge needs "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" temporary space. (In-place variants exist but are slow or complex.)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ideal for "},{"type":"text","text":"linked lists","marks":[{"type":"bold"}]},{"type":"text","text":": splitting and merging lists needs no extra array, so it sorts a list in "},{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":" auxiliary space — and it is the default list sort in many libraries."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Used in "},{"type":"text","text":"external sorting","marks":[{"type":"bold"}]},{"type":"text","text":" (data larger than memory): sort chunks that fit in RAM, then merge the sorted chunks sequentially from disk."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Timsort is merge sort with insertion-sorted runs; it is what Python and Java''s object sort run."}]}]}]}]}}'),
  ('81d6802b-e032-7fff-b468-71fafa77f8d9', 'b0d', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Writing "},{"type":"text","text":"mergeSort(a, mid, high)","marks":[{"type":"code"}]},{"type":"text","text":" for the right half re-includes "},{"type":"text","text":"a[mid]","marks":[{"type":"code"}]},{"type":"text","text":" in both halves and recurses forever on two elements. The halves are "},{"type":"text","text":"[low..mid]","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"[mid+1..high]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('97472cee-586a-7d8a-9fe6-d11ddcd80279', 'b0e', 'heading', '{"level":1,"content":[{"type":"text","text":"Union of two sorted arrays"}]}'),
  ('83550af4-eabc-7231-8180-5aaaf5c35791', 'b0f', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"a = [3, 5, 8, 9, 10, 15], b = [2, 8, 9, 10, 15]","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"2 3 5 8 9 10 15","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"a = [1, 1, 3, 3, 5], b = [1, 2, 2, 3]","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"1 2 3 5","marks":[{"type":"code"}]}]}]}}'),
  ('e3d2b139-e551-77fe-b6c7-f2ceb5bc1023', 'b0g', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The union is every distinct value present in either array, in sorted order. Naive: concatenate, sort, then print each element that differs from its predecessor — "},{"type":"text","text":"O((m + n) log(m + n))","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('e1175526-a871-7a94-a0dc-e54843af6fbd', 'b0h', 'code', '{"language":"python","code":"def union_naive(a, b):\n    c = sorted(a + b)\n    return [c[i] for i in range(len(c)) if i == 0 or c[i] != c[i - 1]]   # skip repeats\n\nprint(*union_naive([3, 5, 8, 9, 10, 15], [2, 8, 9, 10, 15]))","filename":"Python"}'),
  ('cf3b0419-7f76-7575-8cd4-8c2f14e4193d', 'b0i', 'code', '{"language":"text","code":"2 3 5 8 9 10 15","filename":"Output"}'),
  ('2907d2ac-fbd4-78cb-9476-412f1a12bfb9', 'b0j', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It is the "},{"type":"text","text":"merge","marks":[{"type":"bold"}]},{"type":"text","text":" two-pointer walk with two extra rules: skip an element equal to the previous one in its own array (duplicates "},{"type":"text","text":"within","marks":[{"type":"italic"}]},{"type":"text","text":" an array), and when "},{"type":"text","text":"a[i] == b[j]","marks":[{"type":"code"}]},{"type":"text","text":" output it once and advance both pointers (duplicates "},{"type":"text","text":"across","marks":[{"type":"italic"}]},{"type":"text","text":" the arrays). The leftovers after one array is exhausted need the same within-array duplicate check."}]}]}}'),
  ('82832b6b-96f5-742a-a58e-7468a0800833', 'b0k', 'code', '{"language":"python","code":"def union(a, b):\n    res = []\n    i = j = 0\n    m, n = len(a), len(b)\n    while i < m and j < n:\n        if i > 0 and a[i] == a[i - 1]:          # duplicate inside a: skip\n            i += 1\n        elif j > 0 and b[j] == b[j - 1]:        # duplicate inside b: skip\n            j += 1\n        elif a[i] < b[j]:\n            res.append(a[i]); i += 1\n        elif a[i] > b[j]:\n            res.append(b[j]); j += 1\n        else:                                   # equal: take once, advance both\n            res.append(a[i]); i += 1; j += 1\n    while i < m:                                # leftovers of a (still skipping duplicates)\n        if i == 0 or a[i] != a[i - 1]:\n            res.append(a[i])\n        i += 1\n    while j < n:                                # leftovers of b\n        if j == 0 or b[j] != b[j - 1]:\n            res.append(b[j])\n        j += 1\n    return res\n\nprint(*union([3, 5, 8, 9, 10, 15], [2, 8, 9, 10, 15]))\nprint(*union([1, 1, 3, 3, 5], [1, 2, 2, 3]))","filename":"Python"}'),
  ('bb6f37b4-aa7f-705d-b35a-0027e7f6f9a6', 'b0l', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <vector>\nusing namespace std;\n\nvector<int> unionOf(const vector<int>& a, const vector<int>& b) {\n    vector<int> res;\n    int m = a.size(), n = b.size(), i = 0, j = 0;\n    while (i < m && j < n) {\n        if (i > 0 && a[i] == a[i - 1]) i++;              // duplicate inside a: skip\n        else if (j > 0 && b[j] == b[j - 1]) j++;         // duplicate inside b: skip\n        else if (a[i] < b[j]) res.push_back(a[i++]);\n        else if (a[i] > b[j]) res.push_back(b[j++]);\n        else { res.push_back(a[i]); i++; j++; }          // equal: take once, advance both\n    }\n    for (; i < m; i++) if (i == 0 || a[i] != a[i - 1]) res.push_back(a[i]);   // leftovers of a\n    for (; j < n; j++) if (j == 0 || b[j] != b[j - 1]) res.push_back(b[j]);   // leftovers of b\n    return res;\n}\n\nvoid show(const vector<int>& v) {\n    for (size_t k = 0; k < v.size(); k++) cout << (k ? \" \" : \"\") << v[k];\n    cout << \"\\n\";\n}\n\nint main() {\n    show(unionOf({3, 5, 8, 9, 10, 15}, {2, 8, 9, 10, 15}));\n    show(unionOf({1, 1, 3, 3, 5}, {1, 2, 2, 3}));\n}","filename":"C++"}'),
  ('3df8f2b8-5d81-72b3-b77e-13969fa44794', 'b0m', 'code', '{"language":"java","code":"import java.util.ArrayList;\nimport java.util.List;\n\npublic class Main {\n    static List<Integer> union(int[] a, int[] b) {\n        List<Integer> res = new ArrayList<>();\n        int m = a.length, n = b.length, i = 0, j = 0;\n        while (i < m && j < n) {\n            if (i > 0 && a[i] == a[i - 1]) i++;              // duplicate inside a: skip\n            else if (j > 0 && b[j] == b[j - 1]) j++;         // duplicate inside b: skip\n            else if (a[i] < b[j]) res.add(a[i++]);\n            else if (a[i] > b[j]) res.add(b[j++]);\n            else { res.add(a[i]); i++; j++; }                // equal: take once, advance both\n        }\n        for (; i < m; i++) if (i == 0 || a[i] != a[i - 1]) res.add(a[i]);   // leftovers of a\n        for (; j < n; j++) if (j == 0 || b[j] != b[j - 1]) res.add(b[j]);   // leftovers of b\n        return res;\n    }\n\n    static void show(List<Integer> v) {\n        StringBuilder sb = new StringBuilder();\n        for (int x : v) sb.append(sb.length() == 0 ? \"\" : \" \").append(x);\n        System.out.println(sb);\n    }\n\n    public static void main(String[] args) {\n        show(union(new int[]{3, 5, 8, 9, 10, 15}, new int[]{2, 8, 9, 10, 15}));\n        show(union(new int[]{1, 1, 3, 3, 5}, new int[]{1, 2, 2, 3}));\n    }\n}","filename":"Java"}'),
  ('a0cd619e-252b-7216-b45d-358ef1fc345a', 'b0n', 'code', '{"language":"javascript","code":"function union(a, b) {\n    const res = [];\n    let i = 0, j = 0;\n    while (i < a.length && j < b.length) {\n        if (i > 0 && a[i] === a[i - 1]) i++;                 // duplicate inside a: skip\n        else if (j > 0 && b[j] === b[j - 1]) j++;            // duplicate inside b: skip\n        else if (a[i] < b[j]) res.push(a[i++]);\n        else if (a[i] > b[j]) res.push(b[j++]);\n        else { res.push(a[i]); i++; j++; }                   // equal: take once, advance both\n    }\n    for (; i < a.length; i++) if (i === 0 || a[i] !== a[i - 1]) res.push(a[i]);   // leftovers of a\n    for (; j < b.length; j++) if (j === 0 || b[j] !== b[j - 1]) res.push(b[j]);   // leftovers of b\n    return res;\n}\n\nconsole.log(union([3, 5, 8, 9, 10, 15], [2, 8, 9, 10, 15]).join(\" \"));\nconsole.log(union([1, 1, 3, 3, 5], [1, 2, 2, 3]).join(\" \"));","filename":"JavaScript"}'),
  ('a426e8c4-6087-77fe-932b-68bfca68a52a', 'b0o', 'code', '{"language":"text","code":"2 3 5 8 9 10 15\n1 2 3 5","filename":"Output"}'),
  ('b5b6a2b9-4f10-7b32-9dcb-be3711f06736', 'b0p', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(m + n) · Space O(m + n) for the result"}]}]}}'),
  ('b0833f50-f8b2-77d9-9584-44efe24ab294', 'b0q', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The original notes'' leftover loops printed an element only when it "},{"type":"text","text":"equalled","marks":[{"type":"bold"}]},{"type":"text","text":" its predecessor and advanced the pointer only in that case — so they printed the wrong values and looped forever on a non-duplicate. The leftover loop must advance on every iteration and print when the element "},{"type":"text","text":"differs","marks":[{"type":"italic"}]},{"type":"text","text":" from its predecessor."}]}]}}'),
  ('a5f426ab-ca46-7d46-a193-3e528306ecc9', 'b0r', 'heading', '{"level":1,"content":[{"type":"text","text":"Intersection of two sorted arrays"}]}'),
  ('a9942ab8-be51-744e-a42b-9b31030637a6', 'b0s', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"a = [3, 5, 10, 10, 10, 10, 15, 15, 20], b = [5, 10, 10, 15, 30]","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"5 10 15","marks":[{"type":"code"}]}]}]}}'),
  ('bf8fc251-a622-782b-a3ac-34513c7960fe', 'b0t', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The intersection is every distinct value present in "},{"type":"text","text":"both","marks":[{"type":"bold"}]},{"type":"text","text":" arrays. Naive: for each element of "},{"type":"text","text":"a","marks":[{"type":"code"}]},{"type":"text","text":" (skipping repeats), scan "},{"type":"text","text":"b","marks":[{"type":"code"}]},{"type":"text","text":" for it — "},{"type":"text","text":"O(m · n)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('c750589a-02b9-7931-b2c3-d963884c2b28', 'b0u', 'code', '{"language":"python","code":"def intersection_naive(a, b):\n    res = []\n    for i in range(len(a)):\n        if i > 0 and a[i] == a[i - 1]:\n            continue                         # already handled this value\n        for x in b:                          # linear scan of b\n            if x == a[i]:\n                res.append(x)\n                break\n    return res\n\nprint(*intersection_naive([3, 5, 10, 10, 10, 10, 15, 15, 20], [5, 10, 10, 15, 30]))","filename":"Python"}'),
  ('de5fd0fa-b4f1-71b3-905a-7fc4e07bc6ad', 'b0v', 'code', '{"language":"text","code":"5 10 15","filename":"Output"}'),
  ('1f4d112a-fe1c-7c3a-bacc-b879fcc8ae65', 'b0w', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two pointers again. Skip duplicates in "},{"type":"text","text":"a","marks":[{"type":"code"}]},{"type":"text","text":". If "},{"type":"text","text":"a[i] < b[j]","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"a[i]","marks":[{"type":"code"}]},{"type":"text","text":" cannot be in "},{"type":"text","text":"b","marks":[{"type":"code"}]},{"type":"text","text":" any more — advance "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":"; if "},{"type":"text","text":"a[i] > b[j]","marks":[{"type":"code"}]},{"type":"text","text":" advance "},{"type":"text","text":"j","marks":[{"type":"code"}]},{"type":"text","text":"; if equal, output it and advance both. Duplicates in "},{"type":"text","text":"b","marks":[{"type":"code"}]},{"type":"text","text":" are harmless: after a match "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" moves to a larger value, so the repeated "},{"type":"text","text":"b[j]","marks":[{"type":"code"}]},{"type":"text","text":" is simply skipped by the "},{"type":"text","text":">","marks":[{"type":"code"}]},{"type":"text","text":" rule."}]}]}}'),
  ('66fe2649-142a-7804-a788-016d87d4838f', 'b0x', 'code', '{"language":"python","code":"def intersection(a, b):\n    res = []\n    i = j = 0\n    while i < len(a) and j < len(b):\n        if i > 0 and a[i] == a[i - 1]:      # duplicate inside a: skip\n            i += 1\n        elif a[i] < b[j]:                   # a[i] is too small to be in b from here on\n            i += 1\n        elif a[i] > b[j]:                   # b[j] is too small\n            j += 1\n        else:                               # common value\n            res.append(a[i]); i += 1; j += 1\n    return res\n\nprint(*intersection([3, 5, 10, 10, 10, 10, 15, 15, 20], [5, 10, 10, 15, 30]))\nprint(*intersection([1, 2, 2, 3, 3, 3], [2, 2, 3, 4]))","filename":"Python"}'),
  ('efd76aa6-cae2-7e45-9202-d0fb475c0607', 'b0y', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <vector>\nusing namespace std;\n\nvector<int> intersection(const vector<int>& a, const vector<int>& b) {\n    vector<int> res;\n    int m = a.size(), n = b.size(), i = 0, j = 0;\n    while (i < m && j < n) {\n        if (i > 0 && a[i] == a[i - 1]) i++;          // duplicate inside a: skip\n        else if (a[i] < b[j]) i++;                   // a[i] is too small to be in b from here on\n        else if (a[i] > b[j]) j++;                   // b[j] is too small\n        else { res.push_back(a[i]); i++; j++; }      // common value\n    }\n    return res;\n}\n\nvoid show(const vector<int>& v) {\n    for (size_t k = 0; k < v.size(); k++) cout << (k ? \" \" : \"\") << v[k];\n    cout << \"\\n\";\n}\n\nint main() {\n    show(intersection({3, 5, 10, 10, 10, 10, 15, 15, 20}, {5, 10, 10, 15, 30}));\n    show(intersection({1, 2, 2, 3, 3, 3}, {2, 2, 3, 4}));\n}","filename":"C++"}'),
  ('9735871b-e879-79bc-b719-f832a99ea359', 'b0z', 'code', '{"language":"java","code":"import java.util.ArrayList;\nimport java.util.List;\n\npublic class Main {\n    static List<Integer> intersection(int[] a, int[] b) {\n        List<Integer> res = new ArrayList<>();\n        int m = a.length, n = b.length, i = 0, j = 0;\n        while (i < m && j < n) {\n            if (i > 0 && a[i] == a[i - 1]) i++;          // duplicate inside a: skip\n            else if (a[i] < b[j]) i++;                   // a[i] is too small to be in b from here on\n            else if (a[i] > b[j]) j++;                   // b[j] is too small\n            else { res.add(a[i]); i++; j++; }            // common value\n        }\n        return res;\n    }\n\n    static void show(List<Integer> v) {\n        StringBuilder sb = new StringBuilder();\n        for (int x : v) sb.append(sb.length() == 0 ? \"\" : \" \").append(x);\n        System.out.println(sb);\n    }\n\n    public static void main(String[] args) {\n        show(intersection(new int[]{3, 5, 10, 10, 10, 10, 15, 15, 20}, new int[]{5, 10, 10, 15, 30}));\n        show(intersection(new int[]{1, 2, 2, 3, 3, 3}, new int[]{2, 2, 3, 4}));\n    }\n}","filename":"Java"}'),
  ('0642f440-24ab-7325-b682-9ee98fdfcb37', 'b10', 'code', '{"language":"javascript","code":"function intersection(a, b) {\n    const res = [];\n    let i = 0, j = 0;\n    while (i < a.length && j < b.length) {\n        if (i > 0 && a[i] === a[i - 1]) i++;             // duplicate inside a: skip\n        else if (a[i] < b[j]) i++;                       // a[i] is too small to be in b from here on\n        else if (a[i] > b[j]) j++;                       // b[j] is too small\n        else { res.push(a[i]); i++; j++; }               // common value\n    }\n    return res;\n}\n\nconsole.log(intersection([3, 5, 10, 10, 10, 10, 15, 15, 20], [5, 10, 10, 15, 30]).join(\" \"));\nconsole.log(intersection([1, 2, 2, 3, 3, 3], [2, 2, 3, 4]).join(\" \"));","filename":"JavaScript"}'),
  ('af4ec140-ad54-79a2-a8a3-cc4bfa37cf05', 'b11', 'code', '{"language":"text","code":"5 10 15\n2 3","filename":"Output"}'),
  ('e943486c-eb51-77bf-806c-eca5f7e30e52', 'b12', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(m + n) · Space O(min(m, n)) for the result"}]}]}}'),
  ('70b214d4-ee41-7f16-89e7-ea0de29b0b26', 'b13', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Union and intersection on "},{"type":"text","text":"unsorted","marks":[{"type":"bold"}]},{"type":"text","text":" arrays: put one array in a hash set and scan the other — "},{"type":"text","text":"O(m + n)","marks":[{"type":"code"}]},{"type":"text","text":" expected time, "},{"type":"text","text":"O(m)","marks":[{"type":"code"}]},{"type":"text","text":" space. Sorting first costs "},{"type":"text","text":"O(n log n)","marks":[{"type":"code"}]},{"type":"text","text":" but needs no extra memory and keeps the output sorted."}]}]}}'),
  ('5b8725ba-eee1-7a1c-ab43-e46d95ac8ace', 'b14', 'heading', '{"level":1,"content":[{"type":"text","text":"Count inversions"}]}'),
  ('ef4b3374-d42e-7ff5-99f9-9e40678e5382', 'b15', 'callout', '{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Inversion","marks":[{"type":"bold"}]},{"type":"text","text":" — a pair of indices "},{"type":"text","text":"i < j","marks":[{"type":"code"}]},{"type":"text","text":" with "},{"type":"text","text":"arr[i] > arr[j]","marks":[{"type":"code"}]},{"type":"text","text":" — two elements that are in the wrong order relative to each other. A sorted array has 0 inversions; a reverse-sorted one has "},{"type":"text","text":"n(n − 1) / 2","marks":[{"type":"code"}]},{"type":"text","text":". The count measures "},{"type":"text","text":"how unsorted","marks":[{"type":"italic"}]},{"type":"text","text":" an array is."}]}]}}'),
  ('85981250-7681-7b73-b832-a9d3474fd2cb', 'b16', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"arr = [2, 4, 1, 3, 5]","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"3 — the pairs (2,1), (4,1), (4,3)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"arr = [5, 4, 3, 2, 1]","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10","marks":[{"type":"code"}]}]}]}}'),
  ('3825c9bf-5b8d-7c1b-a430-e7635d6e7c04', 'b17', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Naive: check every pair — "},{"type":"text","text":"O(n²)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('d3c1dab6-6d79-7d8a-b69d-dc6b453b1d8f', 'b18', 'code', '{"language":"python","code":"def count_inversions_naive(arr):\n    n = len(arr)\n    count = 0\n    for i in range(n - 1):\n        for j in range(i + 1, n):\n            if arr[i] > arr[j]:\n                count += 1\n    return count\n\nprint(count_inversions_naive([2, 4, 1, 3, 5]), count_inversions_naive([2, 4, 1, 3, 5, 2]))","filename":"Python"}'),
  ('7a801fa2-ba56-7aca-b3c4-d7f6391f59af', 'b19', 'code', '{"language":"text","code":"3 6","filename":"Output"}'),
  ('18e0b741-17a3-7dd2-83aa-2e62dbeaf955', 'b1A', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Piggy-back on "},{"type":"text","text":"merge sort","marks":[{"type":"bold"}]},{"type":"text","text":". Split the array at "},{"type":"text","text":"mid","marks":[{"type":"code"}]},{"type":"text","text":"; every inversion "},{"type":"text","text":"(x, y)","marks":[{"type":"code"}]},{"type":"text","text":" has both elements in the left half, both in the right half, or "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":" on the left and "},{"type":"text","text":"y","marks":[{"type":"code"}]},{"type":"text","text":" on the right. The first two kinds are counted by the recursive calls. The third kind is counted "},{"type":"text","text":"during the merge","marks":[{"type":"italic"}]},{"type":"text","text":": when "},{"type":"text","text":"right[j]","marks":[{"type":"code"}]},{"type":"text","text":" is taken before "},{"type":"text","text":"left[i]","marks":[{"type":"code"}]},{"type":"text","text":", it is smaller than "},{"type":"text","text":"left[i]","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"and every element after it","marks":[{"type":"bold"}]},{"type":"text","text":" in the sorted left half — that is "},{"type":"text","text":"len(left) − i","marks":[{"type":"code"}]},{"type":"text","text":" inversions at once."}]}]}}'),
  ('eabd46e6-08c9-7760-ac5a-e312fa1f78d4', 'b1B', 'code', '{"language":"text","code":"merge  left = [2 4]   right = [1 3 5]\n       take 1 from right  → 1 < every remaining left element (2, 4)   → +2 inversions\n       take 2 from left\n       take 3 from right  → 3 < remaining left (4)                   → +1 inversion\n       take 4, 5                                                      total: 3","filename":"Cross inversions are counted in bulk while merging"}'),
  ('e8d20d00-c64a-7841-99a6-b9b34466d3dd', 'b1C', 'code', '{"language":"python","code":"def count_merge(arr, low, mid, high):\n    left, right = arr[low:mid + 1], arr[mid + 1:high + 1]\n    count = 0\n    i = j = 0\n    k = low\n    while i < len(left) and j < len(right):\n        if left[i] <= right[j]:\n            arr[k] = left[i]; i += 1\n        else:\n            arr[k] = right[j]; j += 1\n            count += len(left) - i          # right[j] is smaller than all remaining left elements\n        k += 1\n    while i < len(left):\n        arr[k] = left[i]; i += 1; k += 1\n    while j < len(right):\n        arr[k] = right[j]; j += 1; k += 1\n    return count\n\ndef count_inversions(arr, low, high):\n    count = 0\n    if low < high:\n        mid = low + (high - low) // 2\n        count += count_inversions(arr, low, mid)        # both in the left half\n        count += count_inversions(arr, mid + 1, high)   # both in the right half\n        count += count_merge(arr, low, mid, high)       # one in each half\n    return count\n\nfor arr in ([2, 4, 1, 3, 5], [2, 4, 1, 3, 5, 2], [5, 4, 3, 2, 1], [1, 2, 3, 4, 5]):\n    label = \"[\" + \" \".join(map(str, arr)) + \"]\"\n    print(f\"{label}:\", count_inversions(arr, 0, len(arr) - 1))    # note: arr ends up sorted","filename":"Python"}'),
  ('1bd82557-6be4-72ba-bfd7-0e12180bc9e0', 'b1D', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <vector>\nusing namespace std;\n\nlong long countMerge(vector<int>& arr, int low, int mid, int high) {\n    vector<int> left(arr.begin() + low, arr.begin() + mid + 1);\n    vector<int> right(arr.begin() + mid + 1, arr.begin() + high + 1);\n    int nl = left.size(), nr = right.size(), i = 0, j = 0, k = low;\n    long long count = 0;\n    while (i < nl && j < nr) {\n        if (left[i] <= right[j]) arr[k++] = left[i++];\n        else { arr[k++] = right[j++]; count += nl - i; }   // right[j] < all remaining left elements\n    }\n    while (i < nl) arr[k++] = left[i++];\n    while (j < nr) arr[k++] = right[j++];\n    return count;\n}\n\nlong long countInversions(vector<int>& arr, int low, int high) {\n    long long count = 0;\n    if (low < high) {\n        int mid = low + (high - low) / 2;\n        count += countInversions(arr, low, mid);          // both in the left half\n        count += countInversions(arr, mid + 1, high);     // both in the right half\n        count += countMerge(arr, low, mid, high);         // one in each half\n    }\n    return count;\n}\n\nint main() {\n    vector<vector<int>> tests = {{2, 4, 1, 3, 5}, {2, 4, 1, 3, 5, 2}, {5, 4, 3, 2, 1}, {1, 2, 3, 4, 5}};\n    for (auto& arr : tests) {\n        cout << \"[\";\n        for (size_t k = 0; k < arr.size(); k++) cout << (k ? \" \" : \"\") << arr[k];\n        cout << \"]: \" << countInversions(arr, 0, (int)arr.size() - 1) << \"\\n\";   // arr ends up sorted\n    }\n}","filename":"C++"}'),
  ('a42d79e1-67e8-7b31-bfc8-d2ae22e9550c', 'b1E', 'code', '{"language":"java","code":"import java.util.Arrays;\n\npublic class Main {\n    static long countMerge(int[] arr, int low, int mid, int high) {\n        int[] left = Arrays.copyOfRange(arr, low, mid + 1);\n        int[] right = Arrays.copyOfRange(arr, mid + 1, high + 1);\n        int i = 0, j = 0, k = low;\n        long count = 0;\n        while (i < left.length && j < right.length) {\n            if (left[i] <= right[j]) arr[k++] = left[i++];\n            else { arr[k++] = right[j++]; count += left.length - i; }   // right[j] < all remaining left\n        }\n        while (i < left.length) arr[k++] = left[i++];\n        while (j < right.length) arr[k++] = right[j++];\n        return count;\n    }\n\n    static long countInversions(int[] arr, int low, int high) {\n        long count = 0;\n        if (low < high) {\n            int mid = low + (high - low) / 2;\n            count += countInversions(arr, low, mid);          // both in the left half\n            count += countInversions(arr, mid + 1, high);     // both in the right half\n            count += countMerge(arr, low, mid, high);         // one in each half\n        }\n        return count;\n    }\n\n    public static void main(String[] args) {\n        int[][] tests = {{2, 4, 1, 3, 5}, {2, 4, 1, 3, 5, 2}, {5, 4, 3, 2, 1}, {1, 2, 3, 4, 5}};\n        for (int[] arr : tests) {\n            StringBuilder sb = new StringBuilder(\"[\");\n            for (int k = 0; k < arr.length; k++) sb.append(k > 0 ? \" \" : \"\").append(arr[k]);\n            System.out.println(sb + \"]: \" + countInversions(arr, 0, arr.length - 1));   // arr ends up sorted\n        }\n    }\n}","filename":"Java"}'),
  ('d097f1a3-c961-7e0e-97ca-b90ec4a66c77', 'b1F', 'code', '{"language":"javascript","code":"function countMerge(arr, low, mid, high) {\n    const left = arr.slice(low, mid + 1), right = arr.slice(mid + 1, high + 1);\n    let i = 0, j = 0, k = low, count = 0;\n    while (i < left.length && j < right.length) {\n        if (left[i] <= right[j]) arr[k++] = left[i++];\n        else { arr[k++] = right[j++]; count += left.length - i; }   // right[j] < all remaining left\n    }\n    while (i < left.length) arr[k++] = left[i++];\n    while (j < right.length) arr[k++] = right[j++];\n    return count;\n}\n\nfunction countInversions(arr, low, high) {\n    let count = 0;\n    if (low < high) {\n        const mid = low + Math.floor((high - low) / 2);\n        count += countInversions(arr, low, mid);          // both in the left half\n        count += countInversions(arr, mid + 1, high);     // both in the right half\n        count += countMerge(arr, low, mid, high);         // one in each half\n    }\n    return count;\n}\n\nfor (const arr of [[2, 4, 1, 3, 5], [2, 4, 1, 3, 5, 2], [5, 4, 3, 2, 1], [1, 2, 3, 4, 5]]) {\n    const label = \"[\" + arr.join(\" \") + \"]\";\n    console.log(`${label}:`, countInversions(arr, 0, arr.length - 1));   // arr ends up sorted\n}","filename":"JavaScript"}'),
  ('8d949782-683b-7b77-b3c9-51b1676c5bc6', 'b1G', 'code', '{"language":"text","code":"[2 4 1 3 5]: 3\n[2 4 1 3 5 2]: 6\n[5 4 3 2 1]: 10\n[1 2 3 4 5]: 0","filename":"Output"}'),
  ('2e3b3623-dd17-7184-9e99-23f549498302', 'b1H', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n log n) · Space O(n)"}]}]}}'),
  ('e909ddd1-d945-7dad-85de-d1853680da8e', 'b1I', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use "},{"type":"text","text":"<=","marks":[{"type":"code"}]},{"type":"text","text":" when comparing "},{"type":"text","text":"left[i]","marks":[{"type":"code"}]},{"type":"text","text":" with "},{"type":"text","text":"right[j]","marks":[{"type":"code"}]},{"type":"text","text":": equal elements are "},{"type":"text","text":"not","marks":[{"type":"bold"}]},{"type":"text","text":" an inversion ("},{"type":"text","text":"arr[i] > arr[j]","marks":[{"type":"code"}]},{"type":"text","text":" is strict), so a tie must take the left element without counting. The count can reach "},{"type":"text","text":"n(n − 1) / 2 ≈ 5 × 10¹⁷","marks":[{"type":"code"}]},{"type":"text","text":" for "},{"type":"text","text":"n = 10⁹","marks":[{"type":"code"}]},{"type":"text","text":" — use a 64-bit integer in C++/Java."}]}]}}'),
  ('b4a5fbd0-c5e9-7a9e-84e9-ef756628b118', 'b1J', 'heading', '{"level":1,"content":[{"type":"text","text":"Partition around a pivot"}]}'),
  ('6e9a110d-7034-735a-9fb4-82f0fda03a5e', 'b1K', 'callout', '{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Partition","marks":[{"type":"bold"}]},{"type":"text","text":" — rearranging "},{"type":"text","text":"arr[low..high]","marks":[{"type":"code"}]},{"type":"text","text":" around a chosen "},{"type":"text","text":"pivot","marks":[{"type":"bold"}]},{"type":"text","text":" value so that everything "},{"type":"text","text":"≤ pivot","marks":[{"type":"code"}]},{"type":"text","text":" comes before everything "},{"type":"text","text":"> pivot","marks":[{"type":"code"}]},{"type":"text","text":", and returning the boundary. It is the heart of quick sort: after partitioning, the pivot is in its final sorted position and the two sides can be sorted independently."}]}]}}'),
  ('1ee4cb89-eb69-705c-b1e6-8423cfaba46e', 'b1L', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"arr = [3, 8, 6, 12, 10, 7], pivot = arr[5] = 7","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"3 6 7 8 12 10 (any order inside each side is valid)","marks":[{"type":"code"}]}]}]}}'),
  ('0f481d31-4c9f-7a75-9d62-d7c9de6e0714', 'b1M', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Naive, "},{"type":"text","text":"stable","marks":[{"type":"bold"}]},{"type":"text","text":" partition: move the pivot to the end, copy the "},{"type":"text","text":"≤ pivot","marks":[{"type":"code"}]},{"type":"text","text":" elements and then the "},{"type":"text","text":"> pivot","marks":[{"type":"code"}]},{"type":"text","text":" elements into a temporary array, copy back — "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" time but "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" extra space."}]}]}}'),
  ('5ec58ae6-8757-78c1-b6c9-881060b3ad5b', 'b1N', 'code', '{"language":"python","code":"def partition_naive(arr, p):\n    n = len(arr)\n    arr[p], arr[n - 1] = arr[n - 1], arr[p]       # pivot goes to the end\n    pivot = arr[n - 1]\n    temp = [x for x in arr if x <= pivot]          # smaller-or-equal first (includes the pivot) ...\n    temp += [x for x in arr if x > pivot]          # ... then the larger ones; order inside each part kept\n    arr[:] = temp\n    return len([x for x in arr if x <= pivot]) - 1   # index of the pivot\n\narr = [3, 8, 6, 12, 10, 7]\nprint(\"pivot index:\", partition_naive(arr, 5))\nprint(*arr)","filename":"Python"}'),
  ('de7c2b3f-54a3-75e8-a371-5e96abb9467c', 'b1O', 'code', '{"language":"text","code":"pivot index: 2\n3 6 7 8 12 10","filename":"Output"}'),
  ('1f844d60-b2d7-7b83-9e58-3a94765bc996', 'b1P', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The two in-place schemes below do it in "},{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":" extra space. Both are "},{"type":"text","text":"unstable","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}}'),
  ('01f397df-0beb-7118-a5e2-9f2ef80f85c7', 'b1Q', 'heading', '{"level":1,"content":[{"type":"text","text":"Lomuto partition"}]}'),
  ('aabe851f-565c-79e9-9a86-29e5fedd1cf7', 'b1R', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"arr = [10, 80, 30, 90, 40, 50, 70], pivot = arr[high] = 70","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"pivot index 4, arr = 10 30 40 50 70 90 80","marks":[{"type":"code"}]}]}]}}'),
  ('a33ed15a-2d07-7171-84a8-73a30c28a40a', 'b1S', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pivot is the "},{"type":"text","text":"last","marks":[{"type":"bold"}]},{"type":"text","text":" element. Keep an index "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" marking the end of the "},{"type":"text","text":"≤ pivot","marks":[{"type":"code"}]},{"type":"text","text":" zone (initially "},{"type":"text","text":"low − 1","marks":[{"type":"code"}]},{"type":"text","text":"). Scan "},{"type":"text","text":"j","marks":[{"type":"code"}]},{"type":"text","text":" from "},{"type":"text","text":"low","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"high − 1","marks":[{"type":"code"}]},{"type":"text","text":": whenever "},{"type":"text","text":"arr[j] ≤ pivot","marks":[{"type":"code"}]},{"type":"text","text":", grow the zone ("},{"type":"text","text":"i++","marks":[{"type":"code"}]},{"type":"text","text":") and swap "},{"type":"text","text":"arr[j]","marks":[{"type":"code"}]},{"type":"text","text":" into it. Finally swap the pivot into position "},{"type":"text","text":"i + 1","marks":[{"type":"code"}]},{"type":"text","text":" — it is now exactly between the two zones, so it "},{"type":"text","text":"is guaranteed to be in its final place","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}}'),
  ('ac94de27-032a-7f72-8add-2bcc2c5c40b1', 'b1T', 'code', '{"language":"text","code":"pivot = 70       zone of <= pivot | zone of > pivot | unscanned\nstart   i=-1     [10 80 30 90 40 50 | 70]\nj=0 10<=70  i=0  [10 | 80 30 90 40 50 | 70]\nj=1 80 > 70      [10 | 80 30 90 40 50 | 70]\nj=2 30<=70  i=1  [10 30 | 80 90 40 50 | 70]      swap arr[1], arr[2]\nj=3 90 > 70      [10 30 | 80 90 40 50 | 70]\nj=4 40<=70  i=2  [10 30 40 | 90 80 50 | 70]      swap arr[2], arr[4]\nj=5 50<=70  i=3  [10 30 40 50 | 80 90 | 70]      swap arr[3], arr[5]\nend: swap pivot into i+1 = 4  →  [10 30 40 50 | 70 | 90 80]","filename":"Lomuto: the ≤ zone grows from the left; the pivot lands at i + 1"}'),
  ('3e0d5925-d131-74a8-a26a-d7a180a95d52', 'b1U', 'code', '{"language":"python","code":"def lomuto_partition(arr, low, high):\n    pivot = arr[high]                         # last element is the pivot\n    i = low - 1                               # end of the \"<= pivot\" zone\n    for j in range(low, high):\n        if arr[j] <= pivot:\n            i += 1\n            arr[i], arr[j] = arr[j], arr[i]   # pull arr[j] into the zone\n    arr[i + 1], arr[high] = arr[high], arr[i + 1]   # pivot goes between the zones\n    return i + 1\n\narr = [10, 80, 30, 90, 40, 50, 70]\nprint(\"before:\", *arr)\nprint(\"pivot index:\", lomuto_partition(arr, 0, len(arr) - 1))\nprint(\"after:\", *arr)","filename":"Python"}'),
  ('fe035c88-7fd9-74c1-a7fe-ec353780ca0b', 'b1V', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <utility>\n#include <vector>\nusing namespace std;\n\nint lomutoPartition(vector<int>& arr, int low, int high) {\n    int pivot = arr[high];                        // last element is the pivot\n    int i = low - 1;                              // end of the \"<= pivot\" zone\n    for (int j = low; j < high; j++) {\n        if (arr[j] <= pivot) swap(arr[++i], arr[j]);   // pull arr[j] into the zone\n    }\n    swap(arr[i + 1], arr[high]);                  // pivot goes between the zones\n    return i + 1;\n}\n\nvoid show(const char* label, const vector<int>& v) {\n    cout << label;\n    for (int x : v) cout << \" \" << x;\n    cout << \"\\n\";\n}\n\nint main() {\n    vector<int> arr = {10, 80, 30, 90, 40, 50, 70};\n    show(\"before:\", arr);\n    cout << \"pivot index: \" << lomutoPartition(arr, 0, (int)arr.size() - 1) << \"\\n\";\n    show(\"after:\", arr);\n}","filename":"C++"}'),
  ('f08c25db-7821-78fb-92a8-1549f81ae737', 'b1W', 'code', '{"language":"java","code":"public class Main {\n    static int lomutoPartition(int[] arr, int low, int high) {\n        int pivot = arr[high];                        // last element is the pivot\n        int i = low - 1;                              // end of the \"<= pivot\" zone\n        for (int j = low; j < high; j++) {\n            if (arr[j] <= pivot) {\n                i++;\n                int t = arr[i]; arr[i] = arr[j]; arr[j] = t;   // pull arr[j] into the zone\n            }\n        }\n        int t = arr[i + 1]; arr[i + 1] = arr[high]; arr[high] = t;   // pivot between the zones\n        return i + 1;\n    }\n\n    static String join(int[] a) {\n        StringBuilder sb = new StringBuilder();\n        for (int x : a) sb.append('' '').append(x);\n        return sb.toString();\n    }\n\n    public static void main(String[] args) {\n        int[] arr = {10, 80, 30, 90, 40, 50, 70};\n        System.out.println(\"before:\" + join(arr));\n        System.out.println(\"pivot index: \" + lomutoPartition(arr, 0, arr.length - 1));\n        System.out.println(\"after:\" + join(arr));\n    }\n}","filename":"Java"}'),
  ('e17583a1-4b49-7243-b4fa-efb780631283', 'b1X', 'code', '{"language":"javascript","code":"function lomutoPartition(arr, low, high) {\n    const pivot = arr[high];                          // last element is the pivot\n    let i = low - 1;                                  // end of the \"<= pivot\" zone\n    for (let j = low; j < high; j++) {\n        if (arr[j] <= pivot) {\n            i++;\n            [arr[i], arr[j]] = [arr[j], arr[i]];      // pull arr[j] into the zone\n        }\n    }\n    [arr[i + 1], arr[high]] = [arr[high], arr[i + 1]];   // pivot goes between the zones\n    return i + 1;\n}\n\nconst arr = [10, 80, 30, 90, 40, 50, 70];\nconsole.log(\"before:\", arr.join(\" \"));\nconsole.log(\"pivot index:\", lomutoPartition(arr, 0, arr.length - 1));\nconsole.log(\"after:\", arr.join(\" \"));","filename":"JavaScript"}'),
  ('420baed4-5bcd-734a-a14c-38233683e7bc', 'b1Y', 'code', '{"language":"text","code":"before: 10 80 30 90 40 50 70\npivot index: 4\nafter: 10 30 40 50 70 90 80","filename":"Output"}'),
  ('e1f5987d-3c63-7c6e-8495-cd3db189ba88', 'b1Z', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(1)"}]}]}}'),
  ('15008f66-491d-7df6-815b-a98961939164', 'b1a', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Lomuto returns the pivot''s "},{"type":"text","text":"final index","marks":[{"type":"bold"}]},{"type":"text","text":" — quick sort then recurses on "},{"type":"text","text":"[low..p−1]","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"[p+1..high]","marks":[{"type":"code"}]},{"type":"text","text":", never touching "},{"type":"text","text":"p","marks":[{"type":"code"}]},{"type":"text","text":" again. To use a different pivot (random, median-of-three), swap it to "},{"type":"text","text":"arr[high]","marks":[{"type":"code"}]},{"type":"text","text":" first."}]}]}}'),
  ('9bf1d3af-c9a9-73a3-bb20-2cef7404ae20', 'b1b', 'heading', '{"level":1,"content":[{"type":"text","text":"Hoare partition"}]}'),
  ('621c2bad-e8c3-75b6-b496-3e773a08c5ed', 'b1c', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"arr = [10, 80, 30, 90, 40, 50, 70, 100, 120, 10, 5], pivot = arr[low] = 10","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"returns 1, arr = 5 10 30 90 40 50 70 100 120 80 10","marks":[{"type":"code"}]}]}]}}'),
  ('fa30cc37-cfba-7c0a-ad99-dce8a58dc505', 'b1d', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pivot is the "},{"type":"text","text":"first","marks":[{"type":"bold"}]},{"type":"text","text":" element. Two indices walk towards each other: "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" from the left stops at an element "},{"type":"text","text":"≥ pivot","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"j","marks":[{"type":"code"}]},{"type":"text","text":" from the right stops at one "},{"type":"text","text":"≤ pivot","marks":[{"type":"code"}]},{"type":"text","text":". If they have not crossed, swap and continue; once "},{"type":"text","text":"i ≥ j","marks":[{"type":"code"}]},{"type":"text","text":", return "},{"type":"text","text":"j","marks":[{"type":"code"}]},{"type":"text","text":". Everything in "},{"type":"text","text":"[low..j]","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"≤ pivot","marks":[{"type":"code"}]},{"type":"text","text":" and everything in "},{"type":"text","text":"[j+1..high]","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"≥ pivot","marks":[{"type":"code"}]},{"type":"text","text":" — but the pivot itself can be "},{"type":"text","text":"anywhere in the left part","marks":[{"type":"bold"}]},{"type":"text","text":", so quick sort must recurse on "},{"type":"text","text":"[low..j]","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"[j+1..high]","marks":[{"type":"code"}]},{"type":"text","text":", not skip "},{"type":"text","text":"j","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('f6f145e2-b427-7693-b994-1cf11681c51f', 'b1e', 'code', '{"language":"python","code":"def hoare_partition(arr, low, high):\n    pivot = arr[low]                     # first element is the pivot\n    i, j = low - 1, high + 1\n    while True:\n        i += 1\n        while arr[i] < pivot:            # stop at something >= pivot\n            i += 1\n        j -= 1\n        while arr[j] > pivot:            # stop at something <= pivot\n            j -= 1\n        if i >= j:                       # crossed: [low..j] <= pivot <= [j+1..high]\n            return j\n        arr[i], arr[j] = arr[j], arr[i]\n\narr = [10, 80, 30, 90, 40, 50, 70, 100, 120, 10, 5]\nprint(\"before:\", *arr)\nprint(\"returned:\", hoare_partition(arr, 0, len(arr) - 1))\nprint(\"after:\", *arr)","filename":"Python"}'),
  ('01f4c070-91a4-7cc3-a4b0-b71c35afd954', 'b1f', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <utility>\n#include <vector>\nusing namespace std;\n\nint hoarePartition(vector<int>& arr, int low, int high) {\n    int pivot = arr[low];                    // first element is the pivot\n    int i = low - 1, j = high + 1;\n    while (true) {\n        do { i++; } while (arr[i] < pivot);  // stop at something >= pivot\n        do { j--; } while (arr[j] > pivot);  // stop at something <= pivot\n        if (i >= j) return j;                // crossed: [low..j] <= pivot <= [j+1..high]\n        swap(arr[i], arr[j]);\n    }\n}\n\nvoid show(const char* label, const vector<int>& v) {\n    cout << label;\n    for (int x : v) cout << \" \" << x;\n    cout << \"\\n\";\n}\n\nint main() {\n    vector<int> arr = {10, 80, 30, 90, 40, 50, 70, 100, 120, 10, 5};\n    show(\"before:\", arr);\n    cout << \"returned: \" << hoarePartition(arr, 0, (int)arr.size() - 1) << \"\\n\";\n    show(\"after:\", arr);\n}","filename":"C++"}'),
  ('88966f05-2402-7b9e-a2ec-b592417f6fbe', 'b1g', 'code', '{"language":"java","code":"public class Main {\n    static int hoarePartition(int[] arr, int low, int high) {\n        int pivot = arr[low];                    // first element is the pivot\n        int i = low - 1, j = high + 1;\n        while (true) {\n            do { i++; } while (arr[i] < pivot);  // stop at something >= pivot\n            do { j--; } while (arr[j] > pivot);  // stop at something <= pivot\n            if (i >= j) return j;                // crossed: [low..j] <= pivot <= [j+1..high]\n            int t = arr[i]; arr[i] = arr[j]; arr[j] = t;\n        }\n    }\n\n    static String join(int[] a) {\n        StringBuilder sb = new StringBuilder();\n        for (int x : a) sb.append('' '').append(x);\n        return sb.toString();\n    }\n\n    public static void main(String[] args) {\n        int[] arr = {10, 80, 30, 90, 40, 50, 70, 100, 120, 10, 5};\n        System.out.println(\"before:\" + join(arr));\n        System.out.println(\"returned: \" + hoarePartition(arr, 0, arr.length - 1));\n        System.out.println(\"after:\" + join(arr));\n    }\n}","filename":"Java"}'),
  ('4569ff46-7477-7e36-8a4d-1dc9502036ff', 'b1h', 'code', '{"language":"javascript","code":"function hoarePartition(arr, low, high) {\n    const pivot = arr[low];                      // first element is the pivot\n    let i = low - 1, j = high + 1;\n    while (true) {\n        do { i++; } while (arr[i] < pivot);      // stop at something >= pivot\n        do { j--; } while (arr[j] > pivot);      // stop at something <= pivot\n        if (i >= j) return j;                    // crossed: [low..j] <= pivot <= [j+1..high]\n        [arr[i], arr[j]] = [arr[j], arr[i]];\n    }\n}\n\nconst arr = [10, 80, 30, 90, 40, 50, 70, 100, 120, 10, 5];\nconsole.log(\"before:\", arr.join(\" \"));\nconsole.log(\"returned:\", hoarePartition(arr, 0, arr.length - 1));\nconsole.log(\"after:\", arr.join(\" \"));","filename":"JavaScript"}'),
  ('19ee3396-e835-7422-8af6-f547a0c7ba5e', 'b1i', 'code', '{"language":"text","code":"before: 10 80 30 90 40 50 70 100 120 10 5\nreturned: 1\nafter: 5 10 30 90 40 50 70 100 120 80 10","filename":"Output"}'),
  ('f6230eca-6dae-7cd4-938e-9e74a8af7c30', 'b1j', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(1)"}]}]}}'),
  ('a2959041-f788-72f0-b1af-8b87c1aa10a7', 'b1k', 'table', '{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"Lomuto"}],[{"type":"text","text":"Hoare"}]],[[{"type":"text","text":"Pivot"}],[{"type":"text","text":"last element "},{"type":"text","text":"arr[high]","marks":[{"type":"code"}]}],[{"type":"text","text":"first element "},{"type":"text","text":"arr[low]","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Returns"}],[{"type":"text","text":"the pivot''s final index "},{"type":"text","text":"p","marks":[{"type":"code"}]}],[{"type":"text","text":"a boundary "},{"type":"text","text":"j","marks":[{"type":"code"}]},{"type":"text","text":"; the pivot is somewhere in "},{"type":"text","text":"[low..j]","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Quick sort recursion"}],[{"type":"text","text":"[low..p−1]","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"[p+1..high]","marks":[{"type":"code"}]}],[{"type":"text","text":"[low..j]","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"[j+1..high]","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Swaps"}],[{"type":"text","text":"about "},{"type":"text","text":"n/2","marks":[{"type":"code"}]},{"type":"text","text":" on average"}],[{"type":"text","text":"about "},{"type":"text","text":"n/6","marks":[{"type":"code"}]},{"type":"text","text":" — roughly three times fewer"}]],[[{"type":"text","text":"All-equal input"}],[{"type":"text","text":"degenerates: every element goes left → "},{"type":"text","text":"O(n²)","marks":[{"type":"code"}]}],[{"type":"text","text":"splits in the middle → stays "},{"type":"text","text":"O(n log n)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Simplicity"}],[{"type":"text","text":"easier to get right"}],[{"type":"text","text":"the stop conditions and the "},{"type":"text","text":"i >= j","marks":[{"type":"code"}]},{"type":"text","text":" test are easy to get wrong"}]]]}'),
  ('0b616c4e-01fc-77c0-a970-5e91bbff83e5', 'b1l', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"With Hoare, recursing on "},{"type":"text","text":"[low..j−1]","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"[j+1..high]","marks":[{"type":"code"}]},{"type":"text","text":" (as for Lomuto) loses the element at "},{"type":"text","text":"j","marks":[{"type":"code"}]},{"type":"text","text":", which is "},{"type":"text","text":"not","marks":[{"type":"bold"}]},{"type":"text","text":" necessarily the pivot. And the inner loops must use strict "},{"type":"text","text":"<","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":">","marks":[{"type":"code"}]},{"type":"text","text":" — with "},{"type":"text","text":"<=","marks":[{"type":"code"}]},{"type":"text","text":" they can run off the ends of the array."}]}]}}'),
  ('61443a74-ed26-7a54-8b87-7642418b27f8', 'b1m', 'heading', '{"level":1,"content":[{"type":"text","text":"Quick sort"}]}'),
  ('e3b58c21-d906-7514-9a85-f6e7cec79e79', 'b1n', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"arr = [10, 80, 30, 90, 40, 50, 70]","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 30 40 50 70 80 90","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"arr = [3, 5, 6, 7, 1, 2, 4]","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"1 2 3 4 5 6 7","marks":[{"type":"code"}]}]}]}}'),
  ('0ec025dc-548d-7089-876a-bd9c8eb332dd', 'b1o', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Divide and conquer","marks":[{"type":"bold"}]},{"type":"text","text":" where the work is in the "},{"type":"text","text":"divide","marks":[{"type":"italic"}]},{"type":"text","text":": partition the array around a pivot, then sort the two sides recursively. There is no merge step — once both sides are sorted, the whole array is, because every left element "},{"type":"text","text":"≤","marks":[{"type":"code"}]},{"type":"text","text":" pivot "},{"type":"text","text":"≤","marks":[{"type":"code"}]},{"type":"text","text":" every right element."}]}]}}'),
  ('635c039d-338b-76f4-9a06-ad54484e2c30', 'b1p', 'code', '{"language":"text","code":"[3 5 6 7 1 2 4]   pivot 4 (Lomuto, last)\n       ↓ partition\n[3 1 2] 4 [5 6 7]          4 is final\n  ↓            ↓\n[1] 2 [3]    [5 6] 7        2 and 7 are final\n               ↓\n             [5] 6          6 is final\nresult: 1 2 3 4 5 6 7","filename":"Each partition fixes the pivot; the sides are sorted independently"}'),
  ('f9fcd173-e4d9-7ce4-a3ea-e8cc80213160', 'b1q', 'code', '{"language":"python","code":"def lomuto_partition(arr, low, high):\n    pivot, i = arr[high], low - 1\n    for j in range(low, high):\n        if arr[j] <= pivot:\n            i += 1\n            arr[i], arr[j] = arr[j], arr[i]\n    arr[i + 1], arr[high] = arr[high], arr[i + 1]\n    return i + 1\n\ndef hoare_partition(arr, low, high):\n    pivot, i, j = arr[low], low - 1, high + 1\n    while True:\n        i += 1\n        while arr[i] < pivot: i += 1\n        j -= 1\n        while arr[j] > pivot: j -= 1\n        if i >= j: return j\n        arr[i], arr[j] = arr[j], arr[i]\n\ndef quick_sort_lomuto(arr, low, high):\n    if low < high:\n        p = lomuto_partition(arr, low, high)\n        quick_sort_lomuto(arr, low, p - 1)      # pivot at p is final: skip it\n        quick_sort_lomuto(arr, p + 1, high)\n\ndef quick_sort_hoare(arr, low, high):\n    if low < high:\n        p = hoare_partition(arr, low, high)\n        quick_sort_hoare(arr, low, p)           # p is a boundary, not the pivot: include it\n        quick_sort_hoare(arr, p + 1, high)\n\nfor arr in ([10, 80, 30, 90, 40, 50, 70], [3, 5, 6, 7, 1, 2, 4]):\n    a, b = arr[:], arr[:]\n    quick_sort_lomuto(a, 0, len(a) - 1)\n    quick_sort_hoare(b, 0, len(b) - 1)\n    print(\"lomuto:\", *a)\n    print(\"hoare:\", *b)","filename":"Python"}'),
  ('e0e24cfc-0f1c-70e2-a9d3-3bc6c2eb57b5', 'b1r', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <utility>\n#include <vector>\nusing namespace std;\n\nint lomutoPartition(vector<int>& arr, int low, int high) {\n    int pivot = arr[high], i = low - 1;\n    for (int j = low; j < high; j++)\n        if (arr[j] <= pivot) swap(arr[++i], arr[j]);\n    swap(arr[i + 1], arr[high]);\n    return i + 1;\n}\n\nint hoarePartition(vector<int>& arr, int low, int high) {\n    int pivot = arr[low], i = low - 1, j = high + 1;\n    while (true) {\n        do { i++; } while (arr[i] < pivot);\n        do { j--; } while (arr[j] > pivot);\n        if (i >= j) return j;\n        swap(arr[i], arr[j]);\n    }\n}\n\nvoid quickSortLomuto(vector<int>& arr, int low, int high) {\n    if (low < high) {\n        int p = lomutoPartition(arr, low, high);\n        quickSortLomuto(arr, low, p - 1);        // pivot at p is final: skip it\n        quickSortLomuto(arr, p + 1, high);\n    }\n}\n\nvoid quickSortHoare(vector<int>& arr, int low, int high) {\n    if (low < high) {\n        int p = hoarePartition(arr, low, high);\n        quickSortHoare(arr, low, p);             // p is a boundary, not the pivot: include it\n        quickSortHoare(arr, p + 1, high);\n    }\n}\n\nvoid show(const char* label, const vector<int>& v) {\n    cout << label;\n    for (int x : v) cout << \" \" << x;\n    cout << \"\\n\";\n}\n\nint main() {\n    vector<vector<int>> tests = {{10, 80, 30, 90, 40, 50, 70}, {3, 5, 6, 7, 1, 2, 4}};\n    for (const auto& arr : tests) {\n        vector<int> a = arr, b = arr;\n        quickSortLomuto(a, 0, (int)a.size() - 1);\n        quickSortHoare(b, 0, (int)b.size() - 1);\n        show(\"lomuto:\", a);\n        show(\"hoare:\", b);\n    }\n}","filename":"C++"}'),
  ('9c5ff89a-28fb-780c-af61-43e502be9351', 'b1s', 'code', '{"language":"java","code":"public class Main {\n    static int lomutoPartition(int[] arr, int low, int high) {\n        int pivot = arr[high], i = low - 1;\n        for (int j = low; j < high; j++)\n            if (arr[j] <= pivot) { i++; int t = arr[i]; arr[i] = arr[j]; arr[j] = t; }\n        int t = arr[i + 1]; arr[i + 1] = arr[high]; arr[high] = t;\n        return i + 1;\n    }\n\n    static int hoarePartition(int[] arr, int low, int high) {\n        int pivot = arr[low], i = low - 1, j = high + 1;\n        while (true) {\n            do { i++; } while (arr[i] < pivot);\n            do { j--; } while (arr[j] > pivot);\n            if (i >= j) return j;\n            int t = arr[i]; arr[i] = arr[j]; arr[j] = t;\n        }\n    }\n\n    static void quickSortLomuto(int[] arr, int low, int high) {\n        if (low < high) {\n            int p = lomutoPartition(arr, low, high);\n            quickSortLomuto(arr, low, p - 1);        // pivot at p is final: skip it\n            quickSortLomuto(arr, p + 1, high);\n        }\n    }\n\n    static void quickSortHoare(int[] arr, int low, int high) {\n        if (low < high) {\n            int p = hoarePartition(arr, low, high);\n            quickSortHoare(arr, low, p);             // p is a boundary, not the pivot: include it\n            quickSortHoare(arr, p + 1, high);\n        }\n    }\n\n    static String join(int[] a) {\n        StringBuilder sb = new StringBuilder();\n        for (int x : a) sb.append('' '').append(x);\n        return sb.toString();\n    }\n\n    public static void main(String[] args) {\n        int[][] tests = {{10, 80, 30, 90, 40, 50, 70}, {3, 5, 6, 7, 1, 2, 4}};\n        for (int[] arr : tests) {\n            int[] a = arr.clone(), b = arr.clone();\n            quickSortLomuto(a, 0, a.length - 1);\n            quickSortHoare(b, 0, b.length - 1);\n            System.out.println(\"lomuto:\" + join(a));\n            System.out.println(\"hoare:\" + join(b));\n        }\n    }\n}","filename":"Java"}'),
  ('60b8e18b-f64f-7607-9ca9-e1a8bcf230b5', 'b1t', 'code', '{"language":"javascript","code":"function lomutoPartition(arr, low, high) {\n    const pivot = arr[high];\n    let i = low - 1;\n    for (let j = low; j < high; j++)\n        if (arr[j] <= pivot) { i++; [arr[i], arr[j]] = [arr[j], arr[i]]; }\n    [arr[i + 1], arr[high]] = [arr[high], arr[i + 1]];\n    return i + 1;\n}\n\nfunction hoarePartition(arr, low, high) {\n    const pivot = arr[low];\n    let i = low - 1, j = high + 1;\n    while (true) {\n        do { i++; } while (arr[i] < pivot);\n        do { j--; } while (arr[j] > pivot);\n        if (i >= j) return j;\n        [arr[i], arr[j]] = [arr[j], arr[i]];\n    }\n}\n\nfunction quickSortLomuto(arr, low, high) {\n    if (low < high) {\n        const p = lomutoPartition(arr, low, high);\n        quickSortLomuto(arr, low, p - 1);            // pivot at p is final: skip it\n        quickSortLomuto(arr, p + 1, high);\n    }\n}\n\nfunction quickSortHoare(arr, low, high) {\n    if (low < high) {\n        const p = hoarePartition(arr, low, high);\n        quickSortHoare(arr, low, p);                 // p is a boundary, not the pivot: include it\n        quickSortHoare(arr, p + 1, high);\n    }\n}\n\nfor (const arr of [[10, 80, 30, 90, 40, 50, 70], [3, 5, 6, 7, 1, 2, 4]]) {\n    const a = [...arr], b = [...arr];\n    quickSortLomuto(a, 0, a.length - 1);\n    quickSortHoare(b, 0, b.length - 1);\n    console.log(\"lomuto:\", a.join(\" \"));\n    console.log(\"hoare:\", b.join(\" \"));\n}","filename":"JavaScript"}'),
  ('24d70c8f-e148-7114-8b9a-efa985d79c5e', 'b1u', 'code', '{"language":"text","code":"lomuto: 10 30 40 50 70 80 90\nhoare: 10 30 40 50 70 80 90\nlomuto: 1 2 3 4 5 6 7\nhoare: 1 2 3 4 5 6 7","filename":"Output"}'),
  ('ca80c511-ca96-7506-b73f-68e1265796d1', 'b1v', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n log n) average · O(n²) worst · Space O(log n) stack on average"}]}]}}'),
  ('2e853c18-420e-7b01-a470-2f355d9cabe2', 'b1w', 'heading', '{"level":1,"content":[{"type":"text","text":"Analysis of quick sort"}]}'),
  ('ab4e402f-984c-7f4f-a65b-1fdc4a47b465', 'b1x', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Case"}],[{"type":"text","text":"When"}],[{"type":"text","text":"Recurrence"}],[{"type":"text","text":"Time"}]],[[{"type":"text","text":"Best"}],[{"type":"text","text":"every partition splits in half"}],[{"type":"text","text":"T(n) = 2T(n/2) + Θ(n)","marks":[{"type":"code"}]}],[{"type":"text","text":"Θ(n log n)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Average"}],[{"type":"text","text":"random pivots / random input"}],[{"type":"text","text":"T(n) = T(n/4) + T(3n/4) + Θ(n)","marks":[{"type":"code"}]},{"type":"text","text":" (a typical uneven split)"}],[{"type":"text","text":"Θ(n log n)","marks":[{"type":"code"}]},{"type":"text","text":" — about "},{"type":"text","text":"1.39 n log2 n","marks":[{"type":"code"}]},{"type":"text","text":" comparisons"}]],[[{"type":"text","text":"Worst"}],[{"type":"text","text":"the pivot is always the min or max — sorted input with first/last pivot, or all equal values with Lomuto"}],[{"type":"text","text":"T(n) = T(n − 1) + Θ(n)","marks":[{"type":"code"}]}],[{"type":"text","text":"Θ(n²)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Space"}],[{"type":"text","text":"recursion depth"}],[{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":" average; "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" in the worst case unless the smaller side is recursed first"}],[]]]}'),
  ('78f1e648-1922-79d3-a8e9-5351f63a2a27', 'b1y', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Despite the "},{"type":"text","text":"O(n²)","marks":[{"type":"code"}]},{"type":"text","text":" worst case, quick sort is usually the fastest comparison sort in practice:"}]}]}}'),
  ('59a7980c-4e14-7486-b3dd-abb70fea7552', 'b1z', 'callout', '{"variant":"note","title":"In-place","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Partition needs "},{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":" extra memory; merge sort needs an "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" buffer."}]}]}}'),
  ('303e8421-c83b-7754-96fe-3fb82ca08990', 'b20', 'callout', '{"variant":"note","title":"Cache-friendly","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Partition sweeps the array sequentially; heap sort jumps around and misses the cache."}]}]}}'),
  ('60841f69-85b9-74c8-9422-ddd5d0bce2f6', 'b21', 'callout', '{"variant":"note","title":"Small constants","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The inner loop is a compare and an occasional swap — less work per element than merge sort''s copying."}]}]}}'),
  ('183fa095-74e3-747f-ac66-2a78338a2add', 'b22', 'callout', '{"variant":"note","title":"Tail recursion","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The second recursive call can become a loop; recursing on the "},{"type":"text","text":"smaller","marks":[{"type":"italic"}]},{"type":"text","text":" side first bounds the stack at "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('39f7683d-c55a-7401-9861-de687bcff003', 'b23', 'callout', '{"variant":"note","title":"Worst case is avoidable","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A random pivot (or median-of-three) makes the "},{"type":"text","text":"O(n²)","marks":[{"type":"code"}]},{"type":"text","text":" case astronomically unlikely; introsort falls back to heap sort if the depth gets too large."}]}]}}'),
  ('63251c16-0236-77e6-acc0-cdf4473dd1d2', 'b24', 'callout', '{"variant":"note","title":"Not stable","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Both in-place partitions move elements across the range, so equal keys can swap order. Use merge sort / Timsort when stability matters."}]}]}}'),
  ('241983ce-18db-7478-948a-aee1cd9c969b', 'b25', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Three statements in the original notes were wrong: the "},{"type":"text","text":"best","marks":[{"type":"italic"}]},{"type":"text","text":" case is "},{"type":"text","text":"Θ(n log n)","marks":[{"type":"code"}]},{"type":"text","text":", not "},{"type":"text","text":"Θ(log n)","marks":[{"type":"code"}]},{"type":"text","text":" — you cannot sort without looking at every element; the space complexity is "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":" on average (recursion depth), not "},{"type":"text","text":"Θ(n)","marks":[{"type":"code"}]},{"type":"text","text":"; and Hoare''s partition is not \"three times faster\" overall — it does about "},{"type":"text","text":"three times fewer swaps","marks":[{"type":"bold"}]},{"type":"text","text":" on average, which makes it somewhat faster. Hoare also handles many equal keys gracefully, while Lomuto degrades to "},{"type":"text","text":"O(n²)","marks":[{"type":"code"}]},{"type":"text","text":" on them."}]}]}}'),
  ('6ec61cca-2f5d-7991-9ca5-8f68bc894666', 'b26', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"std::sort","marks":[{"type":"code"}]},{"type":"text","text":" in C++ is "},{"type":"text","text":"introsort","marks":[{"type":"bold"}]},{"type":"text","text":": quick sort with median-of-three pivots, switching to heap sort when the recursion depth exceeds "},{"type":"text","text":"2 log n","marks":[{"type":"code"}]},{"type":"text","text":" and to insertion sort for ranges of ≈ 16 elements. Java sorts primitives with a dual-pivot quick sort. Both are "},{"type":"text","text":"O(n log n)","marks":[{"type":"code"}]},{"type":"text","text":" worst case in practice."}]}]}}'),
  ('2e361e72-e9f9-7f64-b0de-eb8fc4ed7851', 'b27', 'heading', '{"level":1,"content":[{"type":"text","text":"Heap sort"}]}'),
  ('369c94b2-e1a8-7313-8983-045bd07f3f9e', 'b28', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"arr = [4, 10, 3, 5, 1, 12, 7]","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"1 3 4 5 7 10 12","marks":[{"type":"code"}]}]}]}}'),
  ('babc3e8b-448e-72f9-bfb8-e7bb40b4afb9', 'b29', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Selection sort finds the maximum in "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" per pass; a "},{"type":"text","text":"max-heap","marks":[{"type":"bold"}]},{"type":"text","text":" finds it in "},{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":" and restores itself in "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":". So: build a max-heap from the array in place, then repeatedly swap the root (the maximum) with the last element of the heap, shrink the heap by one and "},{"type":"text","text":"heapify","marks":[{"type":"italic"}]},{"type":"text","text":" the new root down. The sorted elements accumulate at the end of the array."}]}]}}'),
  ('9da77d27-51af-7159-84aa-7f9793457fe8', 'b2A', 'code', '{"language":"text","code":"array [12 10 7 5 1 3 4] as a max-heap:      children of i are 2i+1 and 2i+2\n\n              12 (0)\n            /        \\\n       10 (1)         7 (2)\n      /     \\        /    \\\n   5 (3)   1 (4)   3 (5)  4 (6)\n\nswap root 12 with last (4)  →  [4 10 7 5 1 3 | 12]   heapify 4 down over the first 6","filename":"A max-heap stored in an array; sorting pulls the root out one at a time"}'),
  ('da0174e8-fe92-74aa-9bf5-4c61b9f919c5', 'b2B', 'text', '{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"heapify(i)","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Compare node "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" with its children; swap with the larger child if it is bigger, and continue down. "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"build heap","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Call "},{"type":"text","text":"heapify","marks":[{"type":"code"}]},{"type":"text","text":" on every internal node from the last one ("},{"type":"text","text":"n/2 − 1","marks":[{"type":"code"}]},{"type":"text","text":") down to the root. Leaves are already heaps. This takes "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" in total, not "},{"type":"text","text":"O(n log n)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"extract","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"For "},{"type":"text","text":"i = n − 1 … 1","marks":[{"type":"code"}]},{"type":"text","text":": swap "},{"type":"text","text":"arr[0]","marks":[{"type":"code"}]},{"type":"text","text":" (the max) with "},{"type":"text","text":"arr[i]","marks":[{"type":"code"}]},{"type":"text","text":", then "},{"type":"text","text":"heapify(0)","marks":[{"type":"code"}]},{"type":"text","text":" on the heap of size "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":". Each extraction is "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}}'),
  ('84a79dc0-1288-7076-b62d-08fb69dc68a1', 'b2C', 'code', '{"language":"python","code":"def heapify(arr, n, i):\n    largest = i\n    left, right = 2 * i + 1, 2 * i + 2\n    if left < n and arr[left] > arr[largest]:\n        largest = left\n    if right < n and arr[right] > arr[largest]:\n        largest = right\n    if largest != i:\n        arr[i], arr[largest] = arr[largest], arr[i]\n        heapify(arr, n, largest)                 # keep sinking the displaced value\n\ndef build_heap(arr):\n    n = len(arr)\n    for i in range(n // 2 - 1, -1, -1):          # internal nodes, bottom-up\n        heapify(arr, n, i)\n\ndef heap_sort(arr):\n    n = len(arr)\n    build_heap(arr)\n    print(\"max-heap:\", *arr)\n    for i in range(n - 1, 0, -1):\n        arr[0], arr[i] = arr[i], arr[0]          # max goes to the end\n        heapify(arr, i, 0)                       # restore the heap of size i\n\nfor arr in ([4, 10, 3, 5, 1, 12, 7], [50, 20, 10, 4, 15]):\n    heap_sort(arr)\n    print(\"sorted:\", *arr)","filename":"Python"}'),
  ('0cd5418a-10f1-7867-8eb4-1f970e169693', 'b2D', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <utility>\n#include <vector>\nusing namespace std;\n\nvoid heapify(vector<int>& arr, int n, int i) {\n    int largest = i, left = 2 * i + 1, right = 2 * i + 2;\n    if (left < n && arr[left] > arr[largest]) largest = left;\n    if (right < n && arr[right] > arr[largest]) largest = right;\n    if (largest != i) {\n        swap(arr[i], arr[largest]);\n        heapify(arr, n, largest);                // keep sinking the displaced value\n    }\n}\n\nvoid show(const char* label, const vector<int>& v) {\n    cout << label;\n    for (int x : v) cout << \" \" << x;\n    cout << \"\\n\";\n}\n\nvoid heapSort(vector<int>& arr) {\n    int n = arr.size();\n    for (int i = n / 2 - 1; i >= 0; i--) heapify(arr, n, i);   // build heap, bottom-up\n    show(\"max-heap:\", arr);\n    for (int i = n - 1; i > 0; i--) {\n        swap(arr[0], arr[i]);                    // max goes to the end\n        heapify(arr, i, 0);                      // restore the heap of size i\n    }\n}\n\nint main() {\n    vector<vector<int>> tests = {{4, 10, 3, 5, 1, 12, 7}, {50, 20, 10, 4, 15}};\n    for (auto& arr : tests) {\n        heapSort(arr);\n        show(\"sorted:\", arr);\n    }\n}","filename":"C++"}'),
  ('de6669e2-4278-7fa7-9ae1-65c7f2d4c8c1', 'b2E', 'code', '{"language":"java","code":"public class Main {\n    static void heapify(int[] arr, int n, int i) {\n        int largest = i, left = 2 * i + 1, right = 2 * i + 2;\n        if (left < n && arr[left] > arr[largest]) largest = left;\n        if (right < n && arr[right] > arr[largest]) largest = right;\n        if (largest != i) {\n            int t = arr[i]; arr[i] = arr[largest]; arr[largest] = t;\n            heapify(arr, n, largest);            // keep sinking the displaced value\n        }\n    }\n\n    static String join(int[] a) {\n        StringBuilder sb = new StringBuilder();\n        for (int x : a) sb.append('' '').append(x);\n        return sb.toString();\n    }\n\n    static void heapSort(int[] arr) {\n        int n = arr.length;\n        for (int i = n / 2 - 1; i >= 0; i--) heapify(arr, n, i);   // build heap, bottom-up\n        System.out.println(\"max-heap:\" + join(arr));\n        for (int i = n - 1; i > 0; i--) {\n            int t = arr[0]; arr[0] = arr[i]; arr[i] = t;   // max goes to the end\n            heapify(arr, i, 0);                            // restore the heap of size i\n        }\n    }\n\n    public static void main(String[] args) {\n        int[][] tests = {{4, 10, 3, 5, 1, 12, 7}, {50, 20, 10, 4, 15}};\n        for (int[] arr : tests) {\n            heapSort(arr);\n            System.out.println(\"sorted:\" + join(arr));\n        }\n    }\n}","filename":"Java"}'),
  ('f50f34b8-3916-7481-b308-7f616edf7293', 'b2F', 'code', '{"language":"javascript","code":"function heapify(arr, n, i) {\n    let largest = i;\n    const left = 2 * i + 1, right = 2 * i + 2;\n    if (left < n && arr[left] > arr[largest]) largest = left;\n    if (right < n && arr[right] > arr[largest]) largest = right;\n    if (largest !== i) {\n        [arr[i], arr[largest]] = [arr[largest], arr[i]];\n        heapify(arr, n, largest);                // keep sinking the displaced value\n    }\n}\n\nfunction heapSort(arr) {\n    const n = arr.length;\n    for (let i = Math.floor(n / 2) - 1; i >= 0; i--) heapify(arr, n, i);   // build heap, bottom-up\n    console.log(\"max-heap:\", arr.join(\" \"));\n    for (let i = n - 1; i > 0; i--) {\n        [arr[0], arr[i]] = [arr[i], arr[0]];     // max goes to the end\n        heapify(arr, i, 0);                      // restore the heap of size i\n    }\n}\n\nfor (const arr of [[4, 10, 3, 5, 1, 12, 7], [50, 20, 10, 4, 15]]) {\n    heapSort(arr);\n    console.log(\"sorted:\", arr.join(\" \"));\n}","filename":"JavaScript"}'),
  ('2323f365-e90e-71df-9d22-f68be8002410', 'b2G', 'code', '{"language":"text","code":"max-heap: 12 10 7 5 1 3 4\nsorted: 1 3 4 5 7 10 12\nmax-heap: 50 20 10 4 15\nsorted: 4 10 15 20 50","filename":"Output"}'),
  ('48b67b11-f1d1-77ba-9ca4-dc05efd185e1', 'b2H', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n log n) in every case · Space O(1)"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An optimisation of "},{"type":"text","text":"selection sort","marks":[{"type":"bold"}]},{"type":"text","text":": the same "},{"type":"text","text":"extract the extreme, shrink the range","marks":[{"type":"italic"}]},{"type":"text","text":" loop, with an "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":" extraction instead of "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Guaranteed","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"O(n log n)","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"in-place","marks":[{"type":"bold"}]},{"type":"text","text":" — the combination merge sort and quick sort each lack. The price: poor cache locality, so it is slower than quick sort in practice."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Not stable","marks":[{"type":"bold"}]},{"type":"text","text":": swapping the root with the last leaf can jump an element over equal keys."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Used as the fallback inside "},{"type":"text","text":"introsort","marks":[{"type":"bold"}]},{"type":"text","text":" ("},{"type":"text","text":"std::sort","marks":[{"type":"code"}]},{"type":"text","text":") and wherever a worst-case guarantee matters. The heap itself is the DSA Basics → Heap topic."}]}]}]}]}}'),
  ('87a106f1-5507-777f-bcef-acb84975b3d0', 'b2I', 'heading', '{"level":1,"content":[{"type":"text","text":"Interview Q&A"}]}'),
  ('802bbe39-4e7d-7f33-b4de-f6840113b944', 'b2J', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Which sorting algorithm would you pick, and why?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"For general use, the library sort: Timsort (Python/Java objects/JS) or introsort ("},{"type":"text","text":"std::sort","marks":[{"type":"code"}]},{"type":"text","text":"). Hand-rolled: quick sort for speed on arrays in memory; merge sort when stability or a guaranteed "},{"type":"text","text":"n log n","marks":[{"type":"code"}]},{"type":"text","text":" is needed, for linked lists, or for data that does not fit in memory; heap sort when memory is tight and the worst case must be bounded; insertion sort for tiny or nearly sorted inputs; counting/radix sort when keys are small integers."}]}]}}'),
  ('f177affe-10c4-7809-a6f6-f96c2835f2d7', 'b2K', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does stable mean, and which algorithms are stable?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Equal keys keep their input order. Stable: bubble, insertion, merge, Timsort, counting sort. Not stable: selection, quick, heap, "},{"type":"text","text":"std::sort","marks":[{"type":"code"}]},{"type":"text","text":". It matters for multi-key sorts (sort by name, then stably by marks) and for sorting records by one field while keeping a meaningful prior order."}]}]}}'),
  ('e92879c0-3717-72e5-900d-9c49d6e305a3', 'b2L', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is quick sort faster than merge sort in practice if both are O(n log n)?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Quick sort partitions in place with a tight inner loop and sequential memory access; merge sort copies every element into a buffer at every level. Quick sort does more comparisons on average ("},{"type":"text","text":"≈ 1.39 n log n","marks":[{"type":"code"}]},{"type":"text","text":" vs "},{"type":"text","text":"n log n","marks":[{"type":"code"}]},{"type":"text","text":") but fewer memory moves and far fewer cache misses. Merge sort wins on linked lists, on stability, and when a worst-case guarantee is required."}]}]}}'),
  ('c65d3e41-49d8-7a35-8020-f810b16811d1', 'b2M', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When does quick sort degrade to O(n²), and how do you prevent it?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When every partition is maximally unbalanced: already sorted or reverse-sorted input with a first/last pivot, or many equal keys with Lomuto. Fixes: choose a random pivot or the median of three, use Hoare or three-way (Dutch flag) partitioning for duplicates, recurse on the smaller side first to cap the stack, and switch to heap sort if the depth exceeds "},{"type":"text","text":"2 log n","marks":[{"type":"code"}]},{"type":"text","text":" (introsort)."}]}]}}'),
  ('2179c525-102d-70a5-a9ba-35f45e69259a', 'b2N', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Can you sort in better than O(n log n)?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Not by comparing: a comparison sort must distinguish "},{"type":"text","text":"n!","marks":[{"type":"code"}]},{"type":"text","text":" permutations, which needs "},{"type":"text","text":"log2(n!) = Θ(n log n)","marks":[{"type":"code"}]},{"type":"text","text":" comparisons. Non-comparison sorts use the structure of the keys: counting sort is "},{"type":"text","text":"O(n + k)","marks":[{"type":"code"}]},{"type":"text","text":" for integers in "},{"type":"text","text":"0..k","marks":[{"type":"code"}]},{"type":"text","text":", radix sort "},{"type":"text","text":"O(d(n + k))","marks":[{"type":"code"}]},{"type":"text","text":" for "},{"type":"text","text":"d","marks":[{"type":"code"}]},{"type":"text","text":"-digit keys, bucket sort for uniformly distributed reals."}]}]}}'),
  ('13cf0e98-3294-70f8-b1be-6c609a70e8cf', 'b2O', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between sort() and sorted() in Python?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"list.sort()","marks":[{"type":"code"}]},{"type":"text","text":" sorts the list in place and returns "},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":"; "},{"type":"text","text":"sorted(iterable)","marks":[{"type":"code"}]},{"type":"text","text":" accepts any iterable and returns a new list, leaving the input untouched. Both are Timsort, stable, and take the same "},{"type":"text","text":"key=","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"reverse=","marks":[{"type":"code"}]},{"type":"text","text":" arguments."}]}]}}'),
  ('e1b85478-32dd-7022-b1a2-69844bd7ecd9', 'b2P', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why does [10, 9, 1].sort() give [1, 10, 9] in JavaScript?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Without a comparator, "},{"type":"text","text":"Array.prototype.sort","marks":[{"type":"code"}]},{"type":"text","text":" converts elements to strings and compares them lexicographically: "},{"type":"text","text":"\"10\" < \"9\"","marks":[{"type":"code"}]},{"type":"text","text":" because "},{"type":"text","text":"\"1\" < \"9\"","marks":[{"type":"code"}]},{"type":"text","text":". Always pass "},{"type":"text","text":"(a, b) => a - b","marks":[{"type":"code"}]},{"type":"text","text":" for numbers."}]}]}}'),
  ('0745d8d7-c99e-7c08-a5c2-9a041f9fde0e', 'b2Q', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How many swaps does selection sort make, and why is that interesting?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"At most "},{"type":"text","text":"n − 1","marks":[{"type":"code"}]},{"type":"text","text":" — one per pass — regardless of input, versus "},{"type":"text","text":"O(n²)","marks":[{"type":"code"}]},{"type":"text","text":" for bubble sort and "},{"type":"text","text":"O(n²)","marks":[{"type":"code"}]},{"type":"text","text":" shifts for insertion sort. On media where writes are expensive (flash) that can matter; cycle sort takes the idea to its limit with the minimum possible number of writes."}]}]}}')
