FROM (VALUES
  ('f6f63eb5-1819-7ba3-84c5-e452b26a374c', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A stack is a "},{"type":"text","text":"Last In, First Out","marks":[{"type":"bold"}]},{"type":"text","text":" (LIFO) collection: you can only add to or remove from one end, the "},{"type":"text","text":"top","marks":[{"type":"italic"}]},{"type":"text","text":". It is the data structure behind function calls, undo, bracket matching and expression evaluation."}]}]}}'),
  ('5b26b22a-56cc-73c4-abeb-675a7816b3a4', 'a1', 'callout', '{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Stack","marks":[{"type":"bold"}]},{"type":"text","text":" — a linear data structure where insertion ("},{"type":"text","text":"push","marks":[{"type":"code"}]},{"type":"text","text":") and deletion ("},{"type":"text","text":"pop","marks":[{"type":"code"}]},{"type":"text","text":") happen at the same end, called the top. The element pushed last is popped first."}]}]}}'),
  ('334a2703-0fd4-75b0-95af-4abf80af5c24', 'a2', 'code', '{"language":"text","code":"push(40)  →   ┌────┐  ← top        pop()  →  returns 40\n              │ 40 │\n              ├────┤\n              │ 30 │\n              ├────┤\n              │ 20 │\n              ├────┤\n              │ 10 │  ← bottom\n              └────┘","filename":"A stack after push(10), push(20), push(30), push(40)"}'),
  ('d329dec6-647e-7de5-899a-25639d273386', 'a3', 'heading', '{"level":1,"content":[{"type":"text","text":"Operations"}]}'),
  ('5db67043-3fd9-7ee0-a4ce-73e9ec445bab', 'a4', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Operation"}],[{"type":"text","text":"What it does"}],[{"type":"text","text":"Time"}]],[[{"type":"text","text":"push(x)","marks":[{"type":"code"}]}],[{"type":"text","text":"Insert "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":" at the top"}],[{"type":"text","text":"O(1)"}]],[[{"type":"text","text":"pop()","marks":[{"type":"code"}]}],[{"type":"text","text":"Remove and return the top element"}],[{"type":"text","text":"O(1)"}]],[[{"type":"text","text":"peek()","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"top()","marks":[{"type":"code"}]}],[{"type":"text","text":"Return the top element without removing it"}],[{"type":"text","text":"O(1)"}]],[[{"type":"text","text":"isEmpty()","marks":[{"type":"code"}]}],[{"type":"text","text":"true","marks":[{"type":"code"}]},{"type":"text","text":" when the stack has no elements"}],[{"type":"text","text":"O(1)"}]],[[{"type":"text","text":"size()","marks":[{"type":"code"}]}],[{"type":"text","text":"Number of elements"}],[{"type":"text","text":"O(1)"}]]]}'),
  ('6d298c7e-f3f3-7272-b208-7c9dd9368786', 'a5', 'callout', '{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Underflow","marks":[{"type":"bold"}]},{"type":"text","text":" — calling "},{"type":"text","text":"pop()","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"peek()","marks":[{"type":"code"}]},{"type":"text","text":" on an empty stack. "},{"type":"text","text":"Overflow","marks":[{"type":"bold"}]},{"type":"text","text":" — calling "},{"type":"text","text":"push()","marks":[{"type":"code"}]},{"type":"text","text":" on a fixed-capacity stack that is full. Always check "},{"type":"text","text":"isEmpty()","marks":[{"type":"code"}]},{"type":"text","text":" before popping; the built-in containers below raise an error (Python/Java) or return "},{"type":"text","text":"undefined","marks":[{"type":"code"}]},{"type":"text","text":" (JavaScript) instead."}]}]}}'),
  ('75109600-5b98-7c0f-a2ce-853d1a84cbde', 'a6', 'heading', '{"level":1,"content":[{"type":"text","text":"Using the built-in containers"}]}'),
  ('fb230752-921f-7a06-80b6-7ab1d48dc3aa', 'a7', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every language already has a container that works as a stack. Use the end of a dynamic array (append / pop at the back are amortised O(1)) — never the front, where every operation shifts all elements."}]}]}}'),
  ('38a8556c-cdeb-7c8d-98fd-93f9a41fd257', 'a8', 'code', '{"language":"python","code":"stack = []                 # a list used as a stack\nstack.append(''a'')          # push\nstack.append(''b'')\nstack.append(''c'')\nprint(\"top:\", stack[-1])   # peek\nprint(\"popped:\", stack.pop())\nprint(\"popped:\", stack.pop())\nprint(\"size:\", len(stack))\nprint(\"empty:\", len(stack) == 0)","filename":"Python"}'),
  ('d8f36c0d-2d2b-798c-bc2b-9204a6a02970', 'a9', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <stack>\nusing namespace std;\n\nint main() {\n    stack<char> st;            // std::stack adapts a deque\n    st.push(''a'');\n    st.push(''b'');\n    st.push(''c'');\n    cout << \"top: \" << st.top() << \"\\n\";\n    cout << \"popped: \" << st.top() << \"\\n\"; st.pop();   // pop() returns nothing in C++\n    cout << \"popped: \" << st.top() << \"\\n\"; st.pop();\n    cout << \"size: \" << st.size() << \"\\n\";\n    cout << \"empty: \" << (st.empty() ? \"True\" : \"False\") << \"\\n\";\n}","filename":"C++"}'),
  ('09937c62-dddc-74b9-a204-db244e68955b', 'aA', 'code', '{"language":"java","code":"import java.util.ArrayDeque;\nimport java.util.Deque;\n\npublic class Main {\n    public static void main(String[] args) {\n        Deque<Character> stack = new ArrayDeque<>();   // preferred over the legacy java.util.Stack\n        stack.push(''a'');\n        stack.push(''b'');\n        stack.push(''c'');\n        System.out.println(\"top: \" + stack.peek());\n        System.out.println(\"popped: \" + stack.pop());\n        System.out.println(\"popped: \" + stack.pop());\n        System.out.println(\"size: \" + stack.size());\n        System.out.println(\"empty: \" + (stack.isEmpty() ? \"True\" : \"False\"));\n    }\n}","filename":"Java"}'),
  ('deec2aac-02ff-759a-8d4f-fc8cfadd9c7c', 'aB', 'code', '{"language":"javascript","code":"const stack = [];              // an array used as a stack\nstack.push(''a'');\nstack.push(''b'');\nstack.push(''c'');\nconsole.log(\"top:\", stack[stack.length - 1]);\nconsole.log(\"popped:\", stack.pop());\nconsole.log(\"popped:\", stack.pop());\nconsole.log(\"size:\", stack.length);\nconsole.log(\"empty:\", stack.length === 0 ? \"True\" : \"False\");","filename":"JavaScript"}'),
  ('5d853dfc-427d-74b1-81d4-098e7af645a2', 'aC', 'code', '{"language":"text","code":"top: c\npopped: c\npopped: b\nsize: 1\nempty: False","filename":"Output"}'),
  ('0c02a141-6a7b-779d-89c5-ec123e4e051b', 'aD', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Python''s "},{"type":"text","text":"collections.deque","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"queue.LifoQueue","marks":[{"type":"code"}]},{"type":"text","text":" also work as stacks. "},{"type":"text","text":"deque","marks":[{"type":"code"}]},{"type":"text","text":" is the right choice when the same container must also behave as a queue; "},{"type":"text","text":"LifoQueue","marks":[{"type":"code"}]},{"type":"text","text":" is thread-safe and meant for producer/consumer code, not for algorithms."}]}]}}'),
  ('2da9a951-cf4e-7c20-be05-8e9c0a85124b', 'aE', 'heading', '{"level":1,"content":[{"type":"text","text":"Implementing a stack with a linked list"}]}'),
  ('796d4a73-dee9-7981-8c77-faf6216c3e65', 'aF', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pushing and popping at the head of a singly linked list are both O(1), so a linked list gives a stack that never needs resizing. The head node is the top."}]}]}}'),
  ('44f1cc73-53dc-7910-88a1-32726789d95a', 'aG', 'code', '{"language":"text","code":"top\n ↓\n┌────┬───┐   ┌────┬───┐   ┌────┬───┐\n│ 30 │ ●─┼──▶│ 20 │ ●─┼──▶│ 10 │ ∅ │\n└────┴───┘   └────┴───┘   └────┴───┘","filename":"push(10), push(20), push(30) — the newest node becomes the head"}'),
  ('98b3e388-4648-767c-888a-431f7c895d8a', 'aH', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, value):\n        self.value = value\n        self.next = None\n\nclass Stack:\n    def __init__(self):\n        self.head = None\n        self.size = 0\n\n    def push(self, value):\n        node = Node(value)\n        node.next = self.head      # new node points at the old top\n        self.head = node\n        self.size += 1\n\n    def pop(self):\n        if self.head is None:\n            raise IndexError(\"pop from empty stack\")\n        node = self.head\n        self.head = node.next\n        self.size -= 1\n        return node.value\n\n    def peek(self):\n        return None if self.head is None else self.head.value\n\n    def is_empty(self):\n        return self.head is None\n\ns = Stack()\nfor x in (10, 20, 30):\n    s.push(x)\nnode = s.head\nwhile node:                      # print top → bottom\n    print(node.value, end=\" \")\n    node = node.next\nprint()\nprint(\"size:\", s.size)\nprint(\"popped:\", s.pop())\nprint(\"peek:\", s.peek())","filename":"Python"}'),
  ('4fc5b135-4c64-7016-be43-b054b36ead2c', 'aI', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <stdexcept>\nusing namespace std;\n\nstruct Node {\n    int value;\n    Node* next;\n    Node(int v) : value(v), next(nullptr) {}\n};\n\nclass Stack {\n    Node* head = nullptr;\n    int count = 0;\npublic:\n    ~Stack() { while (head) pop(); }\n    void push(int v) {\n        Node* node = new Node(v);\n        node->next = head;           // new node points at the old top\n        head = node;\n        count++;\n    }\n    int pop() {\n        if (!head) throw runtime_error(\"pop from empty stack\");\n        Node* node = head;\n        int v = node->value;\n        head = node->next;\n        delete node;\n        count--;\n        return v;\n    }\n    int peek() const { return head->value; }\n    bool isEmpty() const { return head == nullptr; }\n    int size() const { return count; }\n    Node* top() const { return head; }\n};\n\nint main() {\n    Stack s;\n    for (int x : {10, 20, 30}) s.push(x);\n    for (Node* n = s.top(); n; n = n->next) cout << n->value << \" \";\n    cout << \"\\n\";\n    cout << \"size: \" << s.size() << \"\\n\";\n    cout << \"popped: \" << s.pop() << \"\\n\";\n    cout << \"peek: \" << s.peek() << \"\\n\";\n}","filename":"C++"}'),
  ('33dc7a72-7f4c-798d-a098-015296b11c39', 'aJ', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int value; Node next;\n        Node(int v) { value = v; }\n    }\n\n    static class Stack {\n        Node head; int size;\n        void push(int v) {\n            Node node = new Node(v);\n            node.next = head;            // new node points at the old top\n            head = node;\n            size++;\n        }\n        int pop() {\n            if (head == null) throw new RuntimeException(\"pop from empty stack\");\n            int v = head.value;\n            head = head.next;\n            size--;\n            return v;\n        }\n        Integer peek() { return head == null ? null : head.value; }\n        boolean isEmpty() { return head == null; }\n    }\n\n    public static void main(String[] args) {\n        Stack s = new Stack();\n        for (int x : new int[]{10, 20, 30}) s.push(x);\n        StringBuilder sb = new StringBuilder();\n        for (Node n = s.head; n != null; n = n.next) sb.append(n.value).append('' '');\n        System.out.println(sb.toString().trim());\n        System.out.println(\"size: \" + s.size);\n        System.out.println(\"popped: \" + s.pop());\n        System.out.println(\"peek: \" + s.peek());\n    }\n}","filename":"Java"}'),
  ('d8bb8744-b4a7-788d-8d4b-3f842596d75b', 'aK', 'code', '{"language":"javascript","code":"class Node {\n    constructor(value) { this.value = value; this.next = null; }\n}\n\nclass Stack {\n    constructor() { this.head = null; this.size = 0; }\n    push(value) {\n        const node = new Node(value);\n        node.next = this.head;           // new node points at the old top\n        this.head = node;\n        this.size++;\n    }\n    pop() {\n        if (!this.head) throw new Error(\"pop from empty stack\");\n        const node = this.head;\n        this.head = node.next;\n        this.size--;\n        return node.value;\n    }\n    peek() { return this.head ? this.head.value : null; }\n    isEmpty() { return this.head === null; }\n}\n\nconst s = new Stack();\nfor (const x of [10, 20, 30]) s.push(x);\nconst parts = [];\nfor (let n = s.head; n; n = n.next) parts.push(n.value);\nconsole.log(parts.join(\" \"));\nconsole.log(\"size:\", s.size);\nconsole.log(\"popped:\", s.pop());\nconsole.log(\"peek:\", s.peek());","filename":"JavaScript"}'),
