  ('b7b888ad-eefe-7176-abef-135c3acf84b5', 'aO', 'callout', '{"variant":"note","title":"Function calls","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The call stack stores one frame per active call; returning pops it. Deep recursion overflows it."}]}]}}'),
  ('6113d920-bf22-7aff-87c2-76d938662644', 'aP', 'callout', '{"variant":"note","title":"Balanced brackets","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Push every opener, pop on every closer and check that it matches — see below."}]}]}}'),
