  ('894d7224-54c6-701f-8935-caaf1ee11ce5', 'aR', 'callout', '{"variant":"note","title":"Expression evaluation","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Infix → postfix conversion and postfix evaluation both run on a stack."}]}]}}'),
  ('c0d4f959-b7b0-7ace-8437-4f11beab1140', 'aS', 'callout', '{"variant":"note","title":"Reversing","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Push everything, then pop everything — the order reverses."}]}]}}'),
