  ('39638dd2-8461-79e0-b240-6f2c2b4fa398', 'aV', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"s = \"([])\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"Yes","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"s = \"([)]\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"No","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"s = \"((\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"No","marks":[{"type":"code"}]}]}]}}'),
  ('1ca18e31-2441-75c1-afcf-ad348973d532', 'aW', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Scan left to right. Push every opening bracket. On a closing bracket the stack must be non-empty and its top must be the matching opener — pop it. At the end the stack must be empty. Any violation means the string is unbalanced."}]}]}}'),
  ('edd1f091-7dd3-7f3a-afd3-6e8e6bf2265c', 'aX', 'text', '{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Opening bracket","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Push it onto the stack."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Closing bracket","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"If the stack is empty → unbalanced. Pop the top; if it is not the matching opener → unbalanced."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"End of string","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Balanced only if the stack is empty (every opener was closed)."}]}]}]}]}}'),
  ('58670fbf-5cd7-7292-9b3a-84af61e37011', 'aY', 'code', '{"language":"python","code":"def is_balanced(s):\n    match = {'')'': ''('', '']'': ''['', ''}'': ''{''}\n    stack = []\n    for ch in s:\n        if ch in ''([{'':\n            stack.append(ch)\n        elif ch in match:\n            if not stack or stack.pop() != match[ch]:\n                return False\n    return not stack\n\nfor s in [\"([])\", \"([)]\", \"((\", \"{[()]}\"]:\n    print(s, \"→\", \"Yes\" if is_balanced(s) else \"No\")","filename":"Python"}'),
  ('cf62b0cb-7724-75f2-9777-483ca3eb2ca7', 'aZ', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <stack>\n#include <string>\nusing namespace std;\n\nbool isBalanced(const string& s) {\n    stack<char> st;\n    for (char ch : s) {\n        if (ch == ''('' || ch == ''['' || ch == ''{'') {\n            st.push(ch);\n        } else {\n            if (st.empty()) return false;\n            char open = st.top(); st.pop();\n            if ((ch == '')'' && open != ''('') || (ch == '']'' && open != ''['') || (ch == ''}'' && open != ''{''))\n                return false;\n        }\n    }\n    return st.empty();\n}\n\nint main() {\n    for (string s : {\"([])\", \"([)]\", \"((\", \"{[()]}\"})\n        cout << s << \" → \" << (isBalanced(s) ? \"Yes\" : \"No\") << \"\\n\";\n}","filename":"C++"}'),
  ('119efa42-1083-7505-bb81-f27f4d57f0bb', 'aa', 'code', '{"language":"java","code":"import java.util.ArrayDeque;\nimport java.util.Deque;\n\npublic class Main {\n    static boolean isBalanced(String s) {\n        Deque<Character> stack = new ArrayDeque<>();\n        for (char ch : s.toCharArray()) {\n            if (ch == ''('' || ch == ''['' || ch == ''{'') {\n                stack.push(ch);\n            } else {\n                if (stack.isEmpty()) return false;\n                char open = stack.pop();\n                if ((ch == '')'' && open != ''('') || (ch == '']'' && open != ''['') || (ch == ''}'' && open != ''{''))\n                    return false;\n            }\n        }\n        return stack.isEmpty();\n    }\n\n    public static void main(String[] args) {\n        for (String s : new String[]{\"([])\", \"([)]\", \"((\", \"{[()]}\"})\n            System.out.println(s + \" → \" + (isBalanced(s) ? \"Yes\" : \"No\"));\n    }\n}","filename":"Java"}'),
  ('c03a1884-3985-73da-bb17-dbb037046f49', 'ab', 'code', '{"language":"javascript","code":"function isBalanced(s) {\n    const match = { '')'': ''('', '']'': ''['', ''}'': ''{'' };\n    const stack = [];\n    for (const ch of s) {\n        if (''([{''.includes(ch)) {\n            stack.push(ch);\n        } else if (ch in match) {\n            if (!stack.length || stack.pop() !== match[ch]) return false;\n        }\n    }\n    return stack.length === 0;\n}\n\nfor (const s of [\"([])\", \"([)]\", \"((\", \"{[()]}\"])\n    console.log(s, \"→\", isBalanced(s) ? \"Yes\" : \"No\");","filename":"JavaScript"}'),
