  ('20ca1b50-7e0c-70e1-a55b-013e7a269884', 'ad', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(n)"}]}]}}'),
  ('01d2662f-cd9f-7a5a-93d5-3d570c25b0a3', 'ae', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Forgetting the final "},{"type":"text","text":"stack is empty","marks":[{"type":"code"}]},{"type":"text","text":" check accepts "},{"type":"text","text":"\"((\"","marks":[{"type":"code"}]},{"type":"text","text":"; forgetting the "},{"type":"text","text":"empty before pop","marks":[{"type":"code"}]},{"type":"text","text":" check crashes on "},{"type":"text","text":"\")\"","marks":[{"type":"code"}]},{"type":"text","text":". Both are classic interview slips."}]}]}}'),
