  ('39e57ab2-738f-77c1-9db5-917b0c2cf064', 'b1x', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Leftmost repeating character in one pass — how?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Scan from the "},{"type":"text","text":"right","marks":[{"type":"bold"}]},{"type":"text","text":" with a "},{"type":"text","text":"visited","marks":[{"type":"code"}]},{"type":"text","text":" array: whenever the current character was already visited (i.e. appears further right), record its index. The scan moves left, so the last recorded index is the leftmost repeating one. "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" time, "},{"type":"text","text":"O(CHAR)","marks":[{"type":"code"}]},{"type":"text","text":" space."}]}]}}')
