SELECT c.id::uuid, '96630eeb-0cf3-7ef5-867c-99c67c04d5d4', c.position, c.type::"notes"."CardType", c.content::jsonb, 1, TIMESTAMPTZ '2026-10-07 03:23:53+00', TIMESTAMPTZ '2026-10-07 03:23:53+00'
FROM (VALUES
  ('d7f92b7a-37b2-7974-bae0-a6e4db461afd', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A tree is a "},{"type":"text","text":"non-linear","marks":[{"type":"bold"}]},{"type":"text","text":", hierarchical data structure: one root node with children, each of which is the root of a smaller tree. Folders, HTML documents, organisation charts, expression parsers, database indexes and every search tree and heap are trees — and most tree algorithms are five-line recursions once you see the structure."}]}]}}'),
  ('e31d3d56-5f0e-735e-ab34-41351386574a', 'a1', 'callout', '{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Tree","marks":[{"type":"bold"}]},{"type":"text","text":" — a collection of nodes connected by edges such that there is exactly one "},{"type":"text","text":"root","marks":[{"type":"italic"}]},{"type":"text","text":" and every other node has exactly one parent — so there are no cycles and "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" nodes always have "},{"type":"text","text":"n − 1","marks":[{"type":"code"}]},{"type":"text","text":" edges. A "},{"type":"text","text":"binary tree","marks":[{"type":"bold"}]},{"type":"text","text":" is a tree in which every node has at most two children, called "},{"type":"text","text":"left","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"right","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('219b0302-1e53-77c0-9ae6-4bb0db371f1f', 'a2', 'code', '{"language":"text","code":"       10                  ← root (depth 0, level 0)\n     /    \\\n   20      30              ← depth 1\n  /  \\       \\\n40    50      60           ← depth 2\n     /  \\\n   70    80                ← depth 3 — 40, 70, 80, 60 are the leaves","filename":"The sample binary tree used in every example below"}'),
  ('04ee64bc-4020-72f0-b950-e6e174165586', 'a3', 'heading', '{"level":1,"content":[{"type":"text","text":"Terminology"}]}'),
  ('7d66874c-c3db-7fcf-a1cd-30eb385f4e97', 'a4', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Term"}],[{"type":"text","text":"Meaning"}],[{"type":"text","text":"In the sample tree"}]],[[{"type":"text","text":"Node","marks":[{"type":"bold"}]}],[{"type":"text","text":"One element: a key plus links to its children"}],[{"type":"text","text":"10","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"20","marks":[{"type":"code"}]},{"type":"text","text":", … (8 nodes)"}]],[[{"type":"text","text":"Edge","marks":[{"type":"bold"}]}],[{"type":"text","text":"The link from a parent to a child; a tree of "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" nodes has "},{"type":"text","text":"n − 1","marks":[{"type":"code"}]},{"type":"text","text":" edges"}],[{"type":"text","text":"7 edges"}]],[[{"type":"text","text":"Root","marks":[{"type":"bold"}]}],[{"type":"text","text":"The topmost node — the only node without a parent"}],[{"type":"text","text":"10","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Parent / child","marks":[{"type":"bold"}]}],[{"type":"text","text":"The node directly above / directly below along an edge"}],[{"type":"text","text":"50","marks":[{"type":"code"}]},{"type":"text","text":" is the parent of "},{"type":"text","text":"70","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"80","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Siblings","marks":[{"type":"bold"}]}],[{"type":"text","text":"Children of the same parent"}],[{"type":"text","text":"70","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"80","marks":[{"type":"code"}]},{"type":"text","text":"; "},{"type":"text","text":"20","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"30","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Leaf","marks":[{"type":"bold"}]},{"type":"text","text":" (external node)"}],[{"type":"text","text":"A node with no children"}],[{"type":"text","text":"40","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"70","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"80","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"60","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Internal node","marks":[{"type":"bold"}]}],[{"type":"text","text":"A node with at least one child"}],[{"type":"text","text":"10","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"20","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"30","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"50","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Subtree","marks":[{"type":"bold"}]}],[{"type":"text","text":"A node together with all its descendants — itself a tree"}],[{"type":"text","text":"the subtree rooted at "},{"type":"text","text":"20","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"20, 40, 50, 70, 80","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Ancestors","marks":[{"type":"bold"}]}],[{"type":"text","text":"All nodes on the path from a node up to the root"}],[{"type":"text","text":"ancestors of "},{"type":"text","text":"70","marks":[{"type":"code"}]},{"type":"text","text":": "},{"type":"text","text":"50","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"20","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"10","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Descendants","marks":[{"type":"bold"}]}],[{"type":"text","text":"All nodes in a node''s subtree except itself"}],[{"type":"text","text":"descendants of "},{"type":"text","text":"20","marks":[{"type":"code"}]},{"type":"text","text":": "},{"type":"text","text":"40","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"50","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"70","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"80","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Degree","marks":[{"type":"bold"}]},{"type":"text","text":" of a node"}],[{"type":"text","text":"Number of children (at most 2 in a binary tree)"}],[{"type":"text","text":"degree of "},{"type":"text","text":"20","marks":[{"type":"code"}]},{"type":"text","text":" is 2, of "},{"type":"text","text":"30","marks":[{"type":"code"}]},{"type":"text","text":" is 1, of "},{"type":"text","text":"40","marks":[{"type":"code"}]},{"type":"text","text":" is 0"}]],[[{"type":"text","text":"Depth","marks":[{"type":"bold"}]},{"type":"text","text":" of a node"}],[{"type":"text","text":"Number of edges from the root down to the node"}],[{"type":"text","text":"depth of "},{"type":"text","text":"70","marks":[{"type":"code"}]},{"type":"text","text":" is 3, of the root is 0"}]],[[{"type":"text","text":"Level","marks":[{"type":"bold"}]}],[{"type":"text","text":"All nodes at the same depth ("},{"type":"text","text":"level 0","marks":[{"type":"code"}]},{"type":"text","text":" = root)"}],[{"type":"text","text":"level 2 is "},{"type":"text","text":"40 50 60","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Height","marks":[{"type":"bold"}]},{"type":"text","text":" of a node"}],[{"type":"text","text":"Number of edges on the longest downward path to a leaf (a leaf has height 0)"}],[{"type":"text","text":"height of "},{"type":"text","text":"20","marks":[{"type":"code"}]},{"type":"text","text":" is 2"}]],[[{"type":"text","text":"Height","marks":[{"type":"bold"}]},{"type":"text","text":" of the tree"}],[{"type":"text","text":"Height of the root"}],[{"type":"text","text":"3 edges — or 4 if you count "},{"type":"text","text":"nodes","marks":[{"type":"bold"}]},{"type":"text","text":" on that path (the convention of these notes)"}]]]}'),
  ('d57d446f-9b08-7ffd-a85e-db12ee6c933e', 'a5', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two height conventions exist. Counting "},{"type":"text","text":"edges","marks":[{"type":"bold"}]},{"type":"text","text":", the sample tree has height 3 and an empty tree has height −1. Counting "},{"type":"text","text":"nodes","marks":[{"type":"bold"}]},{"type":"text","text":" on the longest root-to-leaf path (what the notes and GeeksforGeeks do, and what the "},{"type":"text","text":"height()","marks":[{"type":"code"}]},{"type":"text","text":" code below returns), it has height 4 and an empty tree has height 0. Interviewers accept either — just say which one you use."}]}]}}'),
  ('db468b08-0fb4-7e5a-8918-5e79f8289c1c', 'a6', 'heading', '{"level":1,"content":[{"type":"text","text":"Where trees are used"}]}'),
  ('6a0f52fa-4659-7100-92a5-d7597da84573', 'a7', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Trees are the natural representation of anything "},{"type":"text","text":"hierarchical","marks":[{"type":"bold"}]},{"type":"text","text":", and the basis of most fast search structures."}]}]}}'),
  ('d0f30c1e-36c1-72a7-be40-aade6dc5d4af', 'a8', 'callout', '{"variant":"note","title":"Hierarchical data","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Organisation structures, folder / file systems, XML and HTML documents (the DOM), nested JSON objects, class inheritance in OOP."}]}]}}'),
  ('7de77149-4bd2-7ab4-a4ce-258b7e4a9e7d', 'a9', 'callout', '{"variant":"note","title":"Binary search tree","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Keys kept in sorted order with "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":" search, insert and delete — "},{"type":"text","text":"std::map","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"TreeMap","marks":[{"type":"code"}]},{"type":"text","text":" (next topic)."}]}]}}'),
  ('70083fdf-3eda-7f04-9b7e-1a72a465bfb9', 'aA', 'callout', '{"variant":"note","title":"Binary heap","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A complete binary tree in an array; the priority queue behind heap sort, Dijkstra and schedulers (topic after next)."}]}]}}'),
  ('1e0a4087-c125-7dcd-8d22-5b068f9a3a7d', 'aB', 'callout', '{"variant":"note","title":"B and B+ trees","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Wide, shallow search trees that keep disk reads to a minimum — the indexes of every relational database."}]}]}}'),
  ('933d193a-45af-7810-9869-42dde542f5c3', 'aC', 'callout', '{"variant":"note","title":"Spanning and shortest-path trees","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Prim''s and Kruskal''s minimum spanning trees, Dijkstra''s shortest-path tree — the backbone of routing in computer networks."}]}]}}'),
  ('da473e25-2b3a-76bc-b447-049c80a3ba67', 'aD', 'callout', '{"variant":"note","title":"Parse and expression trees","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Compilers turn source code into a syntax tree; "},{"type":"text","text":"(a + b) * c","marks":[{"type":"code"}]},{"type":"text","text":" is a tree with "},{"type":"text","text":"*","marks":[{"type":"code"}]},{"type":"text","text":" at the root."}]}]}}'),
  ('83276244-3f8e-7c4a-979d-013583701395', 'aE', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Special-purpose variations","marks":[{"type":"bold"}]},{"type":"text","text":" you will meet later in DSA Advanced:"}]}]}}'),
  ('43b90de2-bd3b-766c-9bdb-3abd308c95ec', 'aF', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Variation"}],[{"type":"text","text":"What it is for"}]],[[{"type":"text","text":"Trie","marks":[{"type":"bold"}]},{"type":"text","text":" (prefix tree)"}],[{"type":"text","text":"Strings keyed character by character — autocomplete, spell check, IP routing tables"}]],[[{"type":"text","text":"Suffix tree","marks":[{"type":"bold"}]}],[{"type":"text","text":"All suffixes of a text — substring search in "},{"type":"text","text":"O(m)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Binary Indexed Tree","marks":[{"type":"bold"}]},{"type":"text","text":" (Fenwick tree)"}],[{"type":"text","text":"Prefix sums with "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":" point updates in a plain array"}]],[[{"type":"text","text":"Segment tree","marks":[{"type":"bold"}]}],[{"type":"text","text":"Range queries (sum, min, max) with "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":" updates"}]]]}'),
  ('10407519-8556-7324-a96b-f220e5a2ff63', 'aG', 'heading', '{"level":1,"content":[{"type":"text","text":"Kinds of binary tree"}]}'),
  ('e3a548d4-99b7-718d-b1db-66bb5fdd4a01', 'aH', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The same "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" keys can form very different binary trees. The shape decides the height, and the height decides how fast everything runs — so the special shapes have names."}]}]}}'),
  ('5a0acac1-484b-7441-9ff8-02e192dfc4c0', 'aI', 'code', '{"language":"text","code":"FULL (0 or 2 children)      COMPLETE (left-filled)      PERFECT (all leaves same level)\n         1                          1                            1\n       /   \\                      /   \\                        /   \\\n      2     3                    2     3                      2     3\n     / \\                        / \\   /                      / \\   / \\\n    4   5                      4   5 6                      4   5 6   7\n\nBALANCED (|hL − hR| ≤ 1 at every node)      DEGENERATE / SKEWED (a linked list)\n         1                                      1\n       /   \\                                     \\\n      2     3                                      2\n     /       \\                                      \\\n    4         5                                       3\n                                                       \\\n                                                        4","filename":"The named shapes of a binary tree"}'),
  ('62e20ebb-5751-7cba-a5fc-dfc0da4142c1', 'aJ', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Kind"}],[{"type":"text","text":"Rule"}],[{"type":"text","text":"Why it matters"}]],[[{"type":"text","text":"Full","marks":[{"type":"bold"}]},{"type":"text","text":" (strict / proper)"}],[{"type":"text","text":"Every node has either 0 or 2 children"}],[{"type":"text","text":"Leaves = internal nodes + 1; expression trees are full"}]],[[{"type":"text","text":"Complete","marks":[{"type":"bold"}]}],[{"type":"text","text":"Every level is completely filled except possibly the last, which is filled from "},{"type":"text","text":"left to right","marks":[{"type":"bold"}]}],[{"type":"text","text":"Can be stored in an array with no gaps — this is what a binary heap is"}]],[[{"type":"text","text":"Perfect","marks":[{"type":"bold"}]}],[{"type":"text","text":"All internal nodes have 2 children and all leaves are on the same level"}],[{"type":"text","text":"Exactly "},{"type":"text","text":"2^h − 1","marks":[{"type":"code"}]},{"type":"text","text":" nodes for height "},{"type":"text","text":"h","marks":[{"type":"code"}]},{"type":"text","text":" (in nodes); the densest possible tree"}]],[[{"type":"text","text":"Balanced","marks":[{"type":"bold"}]}],[{"type":"text","text":"Height is "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":" — e.g. AVL: left and right heights differ by at most 1 at every node"}],[{"type":"text","text":"Guarantees "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":" search, insert and delete in a BST"}]],[[{"type":"text","text":"Degenerate","marks":[{"type":"bold"}]},{"type":"text","text":" (skewed)"}],[{"type":"text","text":"Every node has exactly one child"}],[{"type":"text","text":"Height "},{"type":"text","text":"n − 1","marks":[{"type":"code"}]},{"type":"text","text":": it behaves like a linked list, every operation becomes "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]}]]]}'),
  ('a4e6c1c7-d438-717e-9a50-dba20ae333f0', 'aK', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Useful facts (height counted in nodes): level "},{"type":"text","text":"l","marks":[{"type":"code"}]},{"type":"text","text":" holds at most "},{"type":"text","text":"2^l","marks":[{"type":"code"}]},{"type":"text","text":" nodes; a tree of height "},{"type":"text","text":"h","marks":[{"type":"code"}]},{"type":"text","text":" holds at most "},{"type":"text","text":"2^h − 1","marks":[{"type":"code"}]},{"type":"text","text":" nodes; therefore "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" nodes need height at least "},{"type":"text","text":"⌈log₂(n + 1)⌉","marks":[{"type":"code"}]},{"type":"text","text":". A perfect tree is always complete and full; a complete tree need not be full (node "},{"type":"text","text":"3","marks":[{"type":"code"}]},{"type":"text","text":" above has one child); a full tree need not be complete."}]}]}}'),
  ('90b3c2eb-0b85-7bbc-9d34-d82946689092', 'aL', 'heading', '{"level":1,"content":[{"type":"text","text":"Binary tree node and building the sample tree"}]}'),
  ('d225db97-410d-7edf-8438-7a535dc82838', 'aM', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A binary tree is a "},{"type":"text","text":"linked","marks":[{"type":"bold"}]},{"type":"text","text":" data structure, like a linked list with two links. Each node stores a key and pointers to its left and right child; a missing child is "},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"nullptr","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":". The tree is identified by its root pointer alone — there is no separate container object. Every program in this topic starts by building the sample tree with this node class."}]}]}}'),
  ('b36d5f65-49ba-7901-8d3b-89f9fc8fa10f', 'aN', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, key):\n        self.key = key\n        self.left = None\n        self.right = None\n\ndef sample_tree():                   # the tree from the notes\n    root = Node(10)\n    root.left = Node(20)\n    root.right = Node(30)\n    root.left.left = Node(40)\n    root.left.right = Node(50)\n    root.right.right = Node(60)\n    root.left.right.left = Node(70)\n    root.left.right.right = Node(80)\n    return root\n\ndef is_leaf(node):\n    return node.left is None and node.right is None\n\nroot = sample_tree()\nprint(\"root:\", root.key)\nprint(\"children of root:\", root.left.key, root.right.key)\nprint(\"left child of 20:\", root.left.left.key)\nprint(\"right child of 30:\", root.right.right.key)\nprint(\"30 has a left child:\", \"true\" if root.right.left else \"false\")\nprint(\"70 is a leaf:\", \"true\" if is_leaf(root.left.right.left) else \"false\")","filename":"Python"}'),
  ('135a264c-26e2-7d00-9a01-4111164358cb', 'aO', 'code', '{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int key;\n    Node *left, *right;\n    Node(int k) : key(k), left(nullptr), right(nullptr) {}\n};\n\nNode* sampleTree() {                 // the tree from the notes\n    Node* root = new Node(10);\n    root->left = new Node(20);\n    root->right = new Node(30);\n    root->left->left = new Node(40);\n    root->left->right = new Node(50);\n    root->right->right = new Node(60);\n    root->left->right->left = new Node(70);\n    root->left->right->right = new Node(80);\n    return root;\n}\n\nbool isLeaf(Node* node) { return !node->left && !node->right; }\n\nint main() {\n    Node* root = sampleTree();\n    cout << \"root: \" << root->key << \"\\n\";\n    cout << \"children of root: \" << root->left->key << \" \" << root->right->key << \"\\n\";\n    cout << \"left child of 20: \" << root->left->left->key << \"\\n\";\n    cout << \"right child of 30: \" << root->right->right->key << \"\\n\";\n    cout << \"30 has a left child: \" << (root->right->left ? \"true\" : \"false\") << \"\\n\";\n    cout << \"70 is a leaf: \" << (isLeaf(root->left->right->left) ? \"true\" : \"false\") << \"\\n\";\n}","filename":"C++"}'),
  ('ec6fed6f-6e2e-79d0-827b-8410c6727d6a', 'aP', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int key; Node left, right;\n        Node(int k) { key = k; }\n    }\n\n    static Node sampleTree() {           // the tree from the notes\n        Node root = new Node(10);\n        root.left = new Node(20);\n        root.right = new Node(30);\n        root.left.left = new Node(40);\n        root.left.right = new Node(50);\n        root.right.right = new Node(60);\n        root.left.right.left = new Node(70);\n        root.left.right.right = new Node(80);\n        return root;\n    }\n\n    static boolean isLeaf(Node node) { return node.left == null && node.right == null; }\n\n    public static void main(String[] args) {\n        Node root = sampleTree();\n        System.out.println(\"root: \" + root.key);\n        System.out.println(\"children of root: \" + root.left.key + \" \" + root.right.key);\n        System.out.println(\"left child of 20: \" + root.left.left.key);\n        System.out.println(\"right child of 30: \" + root.right.right.key);\n        System.out.println(\"30 has a left child: \" + (root.right.left != null ? \"true\" : \"false\"));\n        System.out.println(\"70 is a leaf: \" + (isLeaf(root.left.right.left) ? \"true\" : \"false\"));\n    }\n}","filename":"Java"}'),
  ('74f5db33-80f1-79b0-97bb-32a631676543', 'aQ', 'code', '{"language":"javascript","code":"class Node {\n    constructor(key) { this.key = key; this.left = null; this.right = null; }\n}\n\nfunction sampleTree() {              // the tree from the notes\n    const root = new Node(10);\n    root.left = new Node(20);\n    root.right = new Node(30);\n    root.left.left = new Node(40);\n    root.left.right = new Node(50);\n    root.right.right = new Node(60);\n    root.left.right.left = new Node(70);\n    root.left.right.right = new Node(80);\n    return root;\n}\n\nconst isLeaf = (node) => node.left === null && node.right === null;\n\nconst root = sampleTree();\nconsole.log(\"root:\", root.key);\nconsole.log(\"children of root:\", root.left.key, root.right.key);\nconsole.log(\"left child of 20:\", root.left.left.key);\nconsole.log(\"right child of 30:\", root.right.right.key);\nconsole.log(\"30 has a left child:\", root.right.left ? \"true\" : \"false\");\nconsole.log(\"70 is a leaf:\", isLeaf(root.left.right.left) ? \"true\" : \"false\");","filename":"JavaScript"}'),
  ('76210c08-199b-7c4b-99cb-24d654528cae', 'aR', 'code', '{"language":"text","code":"root: 10\nchildren of root: 20 30\nleft child of 20: 40\nright child of 30: 60\n30 has a left child: false\n70 is a leaf: true","filename":"Output"}'),
  ('cd6bda3b-2f4c-7e23-9fc0-a5d5a87850b3', 'aS', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Building a tree by hand like this is fine for examples. Real code builds trees by "},{"type":"text","text":"insertion","marks":[{"type":"bold"}]},{"type":"text","text":" (a BST), from an array (a heap, or a level-order array with "},{"type":"text","text":"-1","marks":[{"type":"code"}]},{"type":"text","text":" for missing nodes) or by parsing input."}]}]}}'),
  ('1d7ca097-5075-7d6f-a7d9-178e182037c5', 'aT', 'heading', '{"level":1,"content":[{"type":"text","text":"Tree traversals"}]}'),
  ('3917afed-4a4b-7e63-ad54-87a810d60201', 'aU', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Traversing means visiting every node exactly once. A list has one natural order; a tree has several, and each one is useful for something."}]}]}}'),
  ('c11ff4c5-0d13-713a-b865-8e53d294d961', 'aV', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Traversal"}],[{"type":"text","text":"Order"}],[{"type":"text","text":"Sample tree gives"}],[{"type":"text","text":"Typical use"}]],[[{"type":"text","text":"Inorder","marks":[{"type":"bold"}]},{"type":"text","text":" (depth-first)"}],[{"type":"text","text":"Left subtree → "},{"type":"text","text":"Root","marks":[{"type":"bold"}]},{"type":"text","text":" → Right subtree"}],[{"type":"text","text":"40 20 70 50 80 10 30 60","marks":[{"type":"code"}]}],[{"type":"text","text":"Sorted output of a binary search tree"}]],[[{"type":"text","text":"Preorder","marks":[{"type":"bold"}]},{"type":"text","text":" (depth-first)"}],[{"type":"text","text":"Root","marks":[{"type":"bold"}]},{"type":"text","text":" → Left → Right"}],[{"type":"text","text":"10 20 40 50 70 80 30 60","marks":[{"type":"code"}]}],[{"type":"text","text":"Copying / serialising a tree, prefix expressions"}]],[[{"type":"text","text":"Postorder","marks":[{"type":"bold"}]},{"type":"text","text":" (depth-first)"}],[{"type":"text","text":"Left → Right → "},{"type":"text","text":"Root","marks":[{"type":"bold"}]}],[{"type":"text","text":"40 70 80 50 20 60 30 10","marks":[{"type":"code"}]}],[{"type":"text","text":"Deleting a tree (children before parent), folder sizes, postfix expressions"}]],[[{"type":"text","text":"Level order","marks":[{"type":"bold"}]},{"type":"text","text":" (breadth-first)"}],[{"type":"text","text":"Level 0, then level 1, … left to right"}],[{"type":"text","text":"10 20 30 40 50 60 70 80","marks":[{"type":"code"}]}],[{"type":"text","text":"Shortest paths, printing by level, anything that needs "},{"type":"text","text":"closest first","marks":[{"type":"italic"}]}]]]}'),
  ('f3902dae-461f-75e9-98d0-d52b3c14a676', 'aW', 'code', '{"language":"text","code":"       10            Inorder   : (left of 10) 10 (right of 10)\n     /    \\                     = (40 20 70 50 80) 10 (30 60)\n   20      30\n  /  \\       \\      Preorder  : 10 (left of 10) (right of 10)\n40    50      60                = 10 (20 40 50 70 80) (30 60)\n     /  \\\n   70    80          Postorder : (left of 10) (right of 10) 10\n                                = (40 70 80 50 20) (60 30) 10","filename":"The three depth-first orders differ only in when the root is visited relative to its subtrees"}'),
  ('f46111e7-6e58-778e-b973-d9ef400e0899', 'aX', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"All three depth-first traversals are the "},{"type":"text","text":"same recursion","marks":[{"type":"bold"}]},{"type":"text","text":" — "},{"type":"text","text":"visit(root.left)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"visit(root.right)","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"print the root","marks":[{"type":"italic"}]},{"type":"text","text":" — in a different order. The names say where the root goes: "},{"type":"text","text":"pre","marks":[{"type":"bold"}]},{"type":"text","text":"-order before the children, "},{"type":"text","text":"in","marks":[{"type":"bold"}]},{"type":"text","text":"-order in between, "},{"type":"text","text":"post","marks":[{"type":"bold"}]},{"type":"text","text":"-order after. Each recursive call handles one node and makes two calls, so the total work is "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":"; the recursion stack is as deep as the tree, so auxiliary space is "},{"type":"text","text":"O(h)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('b20327b7-fdba-7dc4-b8d0-53b0c78cd98b', 'aY', 'heading', '{"level":1,"content":[{"type":"text","text":"Inorder traversal"}]}'),
  ('f43b4dfa-2fc3-7090-bda0-5cdaabbdaa8a', 'aZ', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"the sample tree","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"40 20 70 50 80 10 30 60","marks":[{"type":"code"}]}]}]}}'),
  ('4b5dc900-f83e-77db-b13a-8b62fad99526', 'aa', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Recurse into the left subtree, print the node, recurse into the right subtree. On a BST this prints the keys in sorted order, which is why inorder is the traversal you will use most."}]}]}}'),
  ('7110d343-c3b6-7b91-a70a-90a7e7fa143d', 'ab', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, key):\n        self.key = key\n        self.left = None\n        self.right = None\n\ndef sample_tree():                   # the tree from the notes\n    root = Node(10)\n    root.left = Node(20)\n    root.right = Node(30)\n    root.left.left = Node(40)\n    root.left.right = Node(50)\n    root.right.right = Node(60)\n    root.left.right.left = Node(70)\n    root.left.right.right = Node(80)\n    return root\n\ndef inorder(root):\n    if root is None:                 # base case: empty subtree\n        return\n    inorder(root.left)               # 1. left subtree\n    print(root.key, end=\" \")         # 2. root\n    inorder(root.right)              # 3. right subtree\n\ninorder(sample_tree())\nprint()","filename":"Python"}'),
  ('0a635c51-6a43-7adf-b828-c9e81f335cb2', 'ac', 'code', '{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int key;\n    Node *left, *right;\n    Node(int k) : key(k), left(nullptr), right(nullptr) {}\n};\n\nNode* sampleTree() {                 // the tree from the notes\n    Node* root = new Node(10);\n    root->left = new Node(20);\n    root->right = new Node(30);\n    root->left->left = new Node(40);\n    root->left->right = new Node(50);\n    root->right->right = new Node(60);\n    root->left->right->left = new Node(70);\n    root->left->right->right = new Node(80);\n    return root;\n}\n\nvoid inorder(Node* root) {\n    if (!root) return;               // base case: empty subtree\n    inorder(root->left);             // 1. left subtree\n    cout << root->key << \" \";        // 2. root\n    inorder(root->right);            // 3. right subtree\n}\n\nint main() {\n    inorder(sampleTree());\n    cout << \"\\n\";\n}","filename":"C++"}'),
  ('bed7564c-2ebd-71c2-bf22-9ba1b0c6fea2', 'ad', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int key; Node left, right;\n        Node(int k) { key = k; }\n    }\n\n    static Node sampleTree() {           // the tree from the notes\n        Node root = new Node(10);\n        root.left = new Node(20);\n        root.right = new Node(30);\n        root.left.left = new Node(40);\n        root.left.right = new Node(50);\n        root.right.right = new Node(60);\n        root.left.right.left = new Node(70);\n        root.left.right.right = new Node(80);\n        return root;\n    }\n\n    static void inorder(Node root) {\n        if (root == null) return;        // base case: empty subtree\n        inorder(root.left);              // 1. left subtree\n        System.out.print(root.key + \" \"); // 2. root\n        inorder(root.right);             // 3. right subtree\n    }\n\n    public static void main(String[] args) {\n        inorder(sampleTree());\n        System.out.println();\n    }\n}","filename":"Java"}'),
  ('179681b4-26d6-736e-94b5-7e24ec079a39', 'ae', 'code', '{"language":"javascript","code":"class Node {\n    constructor(key) { this.key = key; this.left = null; this.right = null; }\n}\n\nfunction sampleTree() {              // the tree from the notes\n    const root = new Node(10);\n    root.left = new Node(20);\n    root.right = new Node(30);\n    root.left.left = new Node(40);\n    root.left.right = new Node(50);\n    root.right.right = new Node(60);\n    root.left.right.left = new Node(70);\n    root.left.right.right = new Node(80);\n    return root;\n}\n\nfunction inorder(root) {\n    if (root === null) return;       // base case: empty subtree\n    inorder(root.left);              // 1. left subtree\n    process.stdout.write(root.key + \" \"); // 2. root\n    inorder(root.right);             // 3. right subtree\n}\n\ninorder(sampleTree());\nconsole.log();","filename":"JavaScript"}'),
  ('30133973-cf3c-7264-977d-3ec0081da44e', 'af', 'code', '{"language":"text","code":"40 20 70 50 80 10 30 60","filename":"Output"}'),
  ('e7cc80f4-ea1c-7d84-8ab2-40b046bc317f', 'ag', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(h) recursion stack — O(n) for a skewed tree, O(log n) when balanced"}]}]}}'),
  ('d0808321-8a54-7a91-b9a4-974d07c4bbce', 'ah', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The notes'' comment "},{"type":"text","text":"Auxiliary space Θ(n)","marks":[{"type":"italic"}]},{"type":"text","text":" is the worst case only. The stack holds one frame per "},{"type":"text","text":"ancestor","marks":[{"type":"bold"}]},{"type":"text","text":" of the current node, so its depth is the height "},{"type":"text","text":"h","marks":[{"type":"code"}]},{"type":"text","text":"; it reaches "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" only for a degenerate (linked-list-shaped) tree."}]}]}}'),
  ('c13576bc-f398-7031-a441-2c701029a5fe', 'ai', 'heading', '{"level":1,"content":[{"type":"text","text":"Preorder traversal"}]}'),
  ('51c225ac-6fab-7beb-b23f-de657b929da4', 'aj', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"the sample tree","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 20 40 50 70 80 30 60","marks":[{"type":"code"}]}]}]}}'),
  ('1a7c401c-4227-7a47-ba9b-4e6161d8c5e8', 'ak', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Print the node first, then its subtrees. Preorder lists every node before its descendants, so writing a tree out in preorder (with markers for missing children) is enough to rebuild it — this is how trees are serialised and copied."}]}]}}'),
  ('5d66d43d-97cb-7b70-9e54-b00505852d0f', 'al', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, key):\n        self.key = key\n        self.left = None\n        self.right = None\n\ndef sample_tree():                   # the tree from the notes\n    root = Node(10)\n    root.left = Node(20)\n    root.right = Node(30)\n    root.left.left = Node(40)\n    root.left.right = Node(50)\n    root.right.right = Node(60)\n    root.left.right.left = Node(70)\n    root.left.right.right = Node(80)\n    return root\n\ndef preorder(root):\n    if root is None:\n        return\n    print(root.key, end=\" \")         # 1. root first\n    preorder(root.left)              # 2. left subtree\n    preorder(root.right)             # 3. right subtree\n\npreorder(sample_tree())\nprint()","filename":"Python"}'),
  ('29e6dc07-ad90-7231-bac1-f28b8a7c38e5', 'am', 'code', '{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int key;\n    Node *left, *right;\n    Node(int k) : key(k), left(nullptr), right(nullptr) {}\n};\n\nNode* sampleTree() {                 // the tree from the notes\n    Node* root = new Node(10);\n    root->left = new Node(20);\n    root->right = new Node(30);\n    root->left->left = new Node(40);\n    root->left->right = new Node(50);\n    root->right->right = new Node(60);\n    root->left->right->left = new Node(70);\n    root->left->right->right = new Node(80);\n    return root;\n}\n\nvoid preorder(Node* root) {\n    if (!root) return;\n    cout << root->key << \" \";        // 1. root first\n    preorder(root->left);            // 2. left subtree\n    preorder(root->right);           // 3. right subtree\n}\n\nint main() {\n    preorder(sampleTree());\n    cout << \"\\n\";\n}","filename":"C++"}'),
  ('36e8b42a-9376-7019-b713-92b5774848aa', 'an', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int key; Node left, right;\n        Node(int k) { key = k; }\n    }\n\n    static Node sampleTree() {           // the tree from the notes\n        Node root = new Node(10);\n        root.left = new Node(20);\n        root.right = new Node(30);\n        root.left.left = new Node(40);\n        root.left.right = new Node(50);\n        root.right.right = new Node(60);\n        root.left.right.left = new Node(70);\n        root.left.right.right = new Node(80);\n        return root;\n    }\n\n    static void preorder(Node root) {\n        if (root == null) return;\n        System.out.print(root.key + \" \"); // 1. root first\n        preorder(root.left);             // 2. left subtree\n        preorder(root.right);            // 3. right subtree\n    }\n\n    public static void main(String[] args) {\n        preorder(sampleTree());\n        System.out.println();\n    }\n}","filename":"Java"}'),
  ('1d4ae339-458a-7ead-a1a7-2f866065cf6e', 'ao', 'code', '{"language":"javascript","code":"class Node {\n    constructor(key) { this.key = key; this.left = null; this.right = null; }\n}\n\nfunction sampleTree() {              // the tree from the notes\n    const root = new Node(10);\n    root.left = new Node(20);\n    root.right = new Node(30);\n    root.left.left = new Node(40);\n    root.left.right = new Node(50);\n    root.right.right = new Node(60);\n    root.left.right.left = new Node(70);\n    root.left.right.right = new Node(80);\n    return root;\n}\n\nfunction preorder(root) {\n    if (root === null) return;\n    process.stdout.write(root.key + \" \"); // 1. root first\n    preorder(root.left);             // 2. left subtree\n    preorder(root.right);            // 3. right subtree\n}\n\npreorder(sampleTree());\nconsole.log();","filename":"JavaScript"}'),
  ('d08376d8-796c-7d60-90bb-364b7e533f9a', 'ap', 'code', '{"language":"text","code":"10 20 40 50 70 80 30 60","filename":"Output"}'),
  ('552cd7f4-a6b1-7c96-8a7b-77b22e8fbe1d', 'aq', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(h)"}]}]}}'),
  ('c2a3cdb2-0bc8-7198-bed0-ab4c9a44d099', 'ar', 'heading', '{"level":1,"content":[{"type":"text","text":"Postorder traversal"}]}'),
  ('9cd22b44-9bce-7d43-b410-dfc78a2f8a77', 'as', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"the sample tree","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"40 70 80 50 20 60 30 10","marks":[{"type":"code"}]}]}]}}'),
  ('e17144b7-8d74-776a-8847-8492beb20b3b', 'at', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Both subtrees first, the node last. Postorder visits children before their parent, so it is the order for anything that must finish the parts before the whole: freeing a tree''s nodes, computing directory sizes, evaluating an expression tree."}]}]}}'),
  ('492e9858-3ecf-7160-9bb8-56e216819fda', 'au', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, key):\n        self.key = key\n        self.left = None\n        self.right = None\n\ndef sample_tree():                   # the tree from the notes\n    root = Node(10)\n    root.left = Node(20)\n    root.right = Node(30)\n    root.left.left = Node(40)\n    root.left.right = Node(50)\n    root.right.right = Node(60)\n    root.left.right.left = Node(70)\n    root.left.right.right = Node(80)\n    return root\n\ndef postorder(root):\n    if root is None:\n        return\n    postorder(root.left)             # 1. left subtree\n    postorder(root.right)            # 2. right subtree\n    print(root.key, end=\" \")         # 3. root last\n\npostorder(sample_tree())\nprint()","filename":"Python"}'),
  ('8275ba86-868d-71c9-b389-aa3a3ef17466', 'av', 'code', '{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int key;\n    Node *left, *right;\n    Node(int k) : key(k), left(nullptr), right(nullptr) {}\n};\n\nNode* sampleTree() {                 // the tree from the notes\n    Node* root = new Node(10);\n    root->left = new Node(20);\n    root->right = new Node(30);\n    root->left->left = new Node(40);\n    root->left->right = new Node(50);\n    root->right->right = new Node(60);\n    root->left->right->left = new Node(70);\n    root->left->right->right = new Node(80);\n    return root;\n}\n\nvoid postorder(Node* root) {\n    if (!root) return;\n    postorder(root->left);           // 1. left subtree\n    postorder(root->right);          // 2. right subtree\n    cout << root->key << \" \";        // 3. root last\n}\n\nint main() {\n    postorder(sampleTree());\n    cout << \"\\n\";\n}","filename":"C++"}'),
  ('e36b4b7c-091b-71b9-a277-aff52db029e4', 'aw', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int key; Node left, right;\n        Node(int k) { key = k; }\n    }\n\n    static Node sampleTree() {           // the tree from the notes\n        Node root = new Node(10);\n        root.left = new Node(20);\n        root.right = new Node(30);\n        root.left.left = new Node(40);\n        root.left.right = new Node(50);\n        root.right.right = new Node(60);\n        root.left.right.left = new Node(70);\n        root.left.right.right = new Node(80);\n        return root;\n    }\n\n    static void postorder(Node root) {\n        if (root == null) return;\n        postorder(root.left);            // 1. left subtree\n        postorder(root.right);           // 2. right subtree\n        System.out.print(root.key + \" \"); // 3. root last\n    }\n\n    public static void main(String[] args) {\n        postorder(sampleTree());\n        System.out.println();\n    }\n}","filename":"Java"}'),
  ('37afb5e5-71f4-7242-9977-205b14a1b39d', 'ax', 'code', '{"language":"javascript","code":"class Node {\n    constructor(key) { this.key = key; this.left = null; this.right = null; }\n}\n\nfunction sampleTree() {              // the tree from the notes\n    const root = new Node(10);\n    root.left = new Node(20);\n    root.right = new Node(30);\n    root.left.left = new Node(40);\n    root.left.right = new Node(50);\n    root.right.right = new Node(60);\n    root.left.right.left = new Node(70);\n    root.left.right.right = new Node(80);\n    return root;\n}\n\nfunction postorder(root) {\n    if (root === null) return;\n    postorder(root.left);            // 1. left subtree\n    postorder(root.right);           // 2. right subtree\n    process.stdout.write(root.key + \" \"); // 3. root last\n}\n\npostorder(sampleTree());\nconsole.log();","filename":"JavaScript"}'),
  ('d9bfe4c6-be93-7dd0-9407-92364a54e353', 'ay', 'code', '{"language":"text","code":"40 70 80 50 20 60 30 10","filename":"Output"}'),
  ('47848b78-595b-7500-8408-11b05b326593', 'az', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(h)"}]}]}}'),
  ('33b3e55a-703d-7d33-a95b-eb372bac8669', 'b00', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In C++ the destructor of a tree "},{"type":"text","text":"is","marks":[{"type":"italic"}]},{"type":"text","text":" a postorder traversal: "},{"type":"text","text":"delete","marks":[{"type":"code"}]},{"type":"text","text":" the left subtree, "},{"type":"text","text":"delete","marks":[{"type":"code"}]},{"type":"text","text":" the right subtree, then the node — deleting the node first would lose the pointers to its children."}]}]}}'),
  ('18bec971-a81a-71ea-aa08-acba64abd120', 'b01', 'heading', '{"level":1,"content":[{"type":"text","text":"Height of a binary tree"}]}'),
  ('c1a87caf-260a-70e0-ade5-82547bda447c', 'b02', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"the sample tree","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"4 (nodes on the longest root-to-leaf path 10 → 20 → 50 → 70)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"an empty tree","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"0","marks":[{"type":"code"}]}]}]}}'),
  ('40d0633b-3312-799c-886c-2bbebc28752e', 'b03', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The height of a tree is "},{"type":"text","text":"one more than the taller of its two subtrees","marks":[{"type":"bold"}]},{"type":"text","text":". That is the whole algorithm: recurse into both children, take the maximum, add 1. The base case — an empty subtree — has height 0 under the node-counting convention."}]}]}}'),
  ('ed38a705-a34e-7e6b-ac30-6295a597cca1', 'b04', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, key):\n        self.key = key\n        self.left = None\n        self.right = None\n\ndef sample_tree():                   # the tree from the notes\n    root = Node(10)\n    root.left = Node(20)\n    root.right = Node(30)\n    root.left.left = Node(40)\n    root.left.right = Node(50)\n    root.right.right = Node(60)\n    root.left.right.left = Node(70)\n    root.left.right.right = Node(80)\n    return root\n\ndef height(root):\n    if root is None:\n        return 0                             # empty tree (node convention)\n    return max(height(root.left), height(root.right)) + 1   # +1 for the root\n\nroot = sample_tree()\nprint(\"height:\", height(root))\nprint(\"height of left subtree:\", height(root.left))\nprint(\"height of right subtree:\", height(root.right))","filename":"Python"}'),
  ('5a638f59-ccb9-75af-8376-3579aee4ded4', 'b05', 'code', '{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int key;\n    Node *left, *right;\n    Node(int k) : key(k), left(nullptr), right(nullptr) {}\n};\n\nNode* sampleTree() {                 // the tree from the notes\n    Node* root = new Node(10);\n    root->left = new Node(20);\n    root->right = new Node(30);\n    root->left->left = new Node(40);\n    root->left->right = new Node(50);\n    root->right->right = new Node(60);\n    root->left->right->left = new Node(70);\n    root->left->right->right = new Node(80);\n    return root;\n}\n\nint height(Node* root) {\n    if (!root) return 0;                     // empty tree (node convention)\n    return max(height(root->left), height(root->right)) + 1;   // +1 for the root\n}\n\nint main() {\n    Node* root = sampleTree();\n    cout << \"height: \" << height(root) << \"\\n\";\n    cout << \"height of left subtree: \" << height(root->left) << \"\\n\";\n    cout << \"height of right subtree: \" << height(root->right) << \"\\n\";\n}","filename":"C++"}'),
  ('6c871101-bdb3-7c24-a404-df8f523176dd', 'b06', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int key; Node left, right;\n        Node(int k) { key = k; }\n    }\n\n    static Node sampleTree() {           // the tree from the notes\n        Node root = new Node(10);\n        root.left = new Node(20);\n        root.right = new Node(30);\n        root.left.left = new Node(40);\n        root.left.right = new Node(50);\n        root.right.right = new Node(60);\n        root.left.right.left = new Node(70);\n        root.left.right.right = new Node(80);\n        return root;\n    }\n\n    static int height(Node root) {\n        if (root == null) return 0;              // empty tree (node convention)\n        return Math.max(height(root.left), height(root.right)) + 1;   // +1 for the root\n    }\n\n    public static void main(String[] args) {\n        Node root = sampleTree();\n        System.out.println(\"height: \" + height(root));\n        System.out.println(\"height of left subtree: \" + height(root.left));\n        System.out.println(\"height of right subtree: \" + height(root.right));\n    }\n}","filename":"Java"}'),
  ('80427f5a-0d97-7d69-992d-6677dafecb0e', 'b07', 'code', '{"language":"javascript","code":"class Node {\n    constructor(key) { this.key = key; this.left = null; this.right = null; }\n}\n\nfunction sampleTree() {              // the tree from the notes\n    const root = new Node(10);\n    root.left = new Node(20);\n    root.right = new Node(30);\n    root.left.left = new Node(40);\n    root.left.right = new Node(50);\n    root.right.right = new Node(60);\n    root.left.right.left = new Node(70);\n    root.left.right.right = new Node(80);\n    return root;\n}\n\nfunction height(root) {\n    if (root === null) return 0;             // empty tree (node convention)\n    return Math.max(height(root.left), height(root.right)) + 1;   // +1 for the root\n}\n\nconst root = sampleTree();\nconsole.log(\"height:\", height(root));\nconsole.log(\"height of left subtree:\", height(root.left));\nconsole.log(\"height of right subtree:\", height(root.right));","filename":"JavaScript"}'),
  ('3bab346c-0b12-73c7-a5b7-181e657b0366', 'b08', 'code', '{"language":"text","code":"height: 4\nheight of left subtree: 3\nheight of right subtree: 2","filename":"Output"}'),
  ('a486c669-cc98-7bdf-8add-c6f707aa5a10', 'b09', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(h)"}]}]}}'),
  ('6e91dfef-0625-7027-bcca-a992215ed6c7', 'b0A', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"To count "},{"type":"text","text":"edges","marks":[{"type":"bold"}]},{"type":"text","text":" instead, return "},{"type":"text","text":"-1","marks":[{"type":"code"}]},{"type":"text","text":" for an empty tree; the sample tree then has height 3. The "},{"type":"text","text":"+ 1","marks":[{"type":"code"}]},{"type":"text","text":" stays the same."}]}]}}'),
  ('32bdbda0-fe91-7e9d-94d5-c6836026c72b', 'b0B', 'heading', '{"level":1,"content":[{"type":"text","text":"Print nodes at distance K from the root"}]}'),
  ('4ff9d4e9-9af7-7313-8765-a5088275c02e', 'b0C', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"the sample tree, K = 2","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"40 50 60","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"K = 1","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"20 30","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"K = 3","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"70 80","marks":[{"type":"code"}]}]}]}}'),
  ('a7c2d758-ea38-7550-9e0e-33cfb5b2eb85', 'b0D', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A node is at distance "},{"type":"text","text":"K","marks":[{"type":"code"}]},{"type":"text","text":" from the root exactly when it is at distance "},{"type":"text","text":"K − 1","marks":[{"type":"code"}]},{"type":"text","text":" from one of the root''s children. So pass "},{"type":"text","text":"K","marks":[{"type":"code"}]},{"type":"text","text":" down the recursion, decrementing at each level; when it reaches 0, the current node is one of the answers. Nothing needs to come back up — the recursion just needs to reach depth "},{"type":"text","text":"K","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('45b4f230-d95d-70b9-a6c4-983840d412b2', 'b0E', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, key):\n        self.key = key\n        self.left = None\n        self.right = None\n\ndef sample_tree():                   # the tree from the notes\n    root = Node(10)\n    root.left = Node(20)\n    root.right = Node(30)\n    root.left.left = Node(40)\n    root.left.right = Node(50)\n    root.right.right = Node(60)\n    root.left.right.left = Node(70)\n    root.left.right.right = Node(80)\n    return root\n\ndef print_k_distance(root, k):\n    if root is None:\n        return\n    if k == 0:                           # reached distance K: this node is an answer\n        print(root.key, end=\" \")\n    else:                                # both children are one step closer\n        print_k_distance(root.left, k - 1)\n        print_k_distance(root.right, k - 1)\n\nroot = sample_tree()\nfor k in range(4):\n    print(f\"k = {k}:\", end=\" \")\n    print_k_distance(root, k)\n    print()","filename":"Python"}'),
  ('4610ce12-d8cd-76d7-82aa-1c836e7ff79e', 'b0F', 'code', '{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int key;\n    Node *left, *right;\n    Node(int k) : key(k), left(nullptr), right(nullptr) {}\n};\n\nNode* sampleTree() {                 // the tree from the notes\n    Node* root = new Node(10);\n    root->left = new Node(20);\n    root->right = new Node(30);\n    root->left->left = new Node(40);\n    root->left->right = new Node(50);\n    root->right->right = new Node(60);\n    root->left->right->left = new Node(70);\n    root->left->right->right = new Node(80);\n    return root;\n}\n\nvoid printKDistance(Node* root, int k) {\n    if (!root) return;\n    if (k == 0) {                            // reached distance K: this node is an answer\n        cout << root->key << \" \";\n    } else {                                 // both children are one step closer\n        printKDistance(root->left, k - 1);\n        printKDistance(root->right, k - 1);\n    }\n}\n\nint main() {\n    Node* root = sampleTree();\n    for (int k = 0; k < 4; k++) {\n        cout << \"k = \" << k << \": \";\n        printKDistance(root, k);\n        cout << \"\\n\";\n    }\n}","filename":"C++"}'),
  ('ca6bd187-25cb-71bf-838d-c365d06d361a', 'b0G', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int key; Node left, right;\n        Node(int k) { key = k; }\n    }\n\n    static Node sampleTree() {           // the tree from the notes\n        Node root = new Node(10);\n        root.left = new Node(20);\n        root.right = new Node(30);\n        root.left.left = new Node(40);\n        root.left.right = new Node(50);\n        root.right.right = new Node(60);\n        root.left.right.left = new Node(70);\n        root.left.right.right = new Node(80);\n        return root;\n    }\n\n    static void printKDistance(Node root, int k) {\n        if (root == null) return;\n        if (k == 0) {                            // reached distance K: this node is an answer\n            System.out.print(root.key + \" \");\n        } else {                                 // both children are one step closer\n            printKDistance(root.left, k - 1);\n            printKDistance(root.right, k - 1);\n        }\n    }\n\n    public static void main(String[] args) {\n        Node root = sampleTree();\n        for (int k = 0; k < 4; k++) {\n            System.out.print(\"k = \" + k + \": \");\n            printKDistance(root, k);\n            System.out.println();\n        }\n    }\n}","filename":"Java"}'),
  ('9d9c3570-8a78-75cd-97b7-462a5a18bcb0', 'b0H', 'code', '{"language":"javascript","code":"class Node {\n    constructor(key) { this.key = key; this.left = null; this.right = null; }\n}\n\nfunction sampleTree() {              // the tree from the notes\n    const root = new Node(10);\n    root.left = new Node(20);\n    root.right = new Node(30);\n    root.left.left = new Node(40);\n    root.left.right = new Node(50);\n    root.right.right = new Node(60);\n    root.left.right.left = new Node(70);\n    root.left.right.right = new Node(80);\n    return root;\n}\n\nfunction printKDistance(root, k) {\n    if (root === null) return;\n    if (k === 0) {                           // reached distance K: this node is an answer\n        process.stdout.write(root.key + \" \");\n    } else {                                 // both children are one step closer\n        printKDistance(root.left, k - 1);\n        printKDistance(root.right, k - 1);\n    }\n}\n\nconst root = sampleTree();\nfor (let k = 0; k < 4; k++) {\n    process.stdout.write(`k = ${k}: `);\n    printKDistance(root, k);\n    console.log();\n}","filename":"JavaScript"}'),
  ('f463473e-a674-7ba5-bec9-b67927eec27f', 'b0I', 'code', '{"language":"text","code":"k = 0: 10\nk = 1: 20 30\nk = 2: 40 50 60\nk = 3: 70 80","filename":"Output"}'),
  ('40dce113-bad5-7c2a-9ac3-21e1b322ec65', 'b0J', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(h)"}]}]}}'),
  ('316532da-57c6-7c70-88c5-d3e9ea121307', 'b0K', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The recursion visits at most all nodes down to depth "},{"type":"text","text":"K","marks":[{"type":"code"}]},{"type":"text","text":", so it is "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" in the worst case but stops early for small "},{"type":"text","text":"K","marks":[{"type":"code"}]},{"type":"text","text":". Nodes at distance "},{"type":"text","text":"K","marks":[{"type":"code"}]},{"type":"text","text":" from the root are exactly "},{"type":"text","text":"level K","marks":[{"type":"bold"}]},{"type":"text","text":" — the level-order traversal below produces the same groups without recursion."}]}]}}'),
  ('aa354edd-3772-7a1a-a42f-126010f44de7', 'b0L', 'heading', '{"level":1,"content":[{"type":"text","text":"Level order traversal (breadth-first)"}]}'),
  ('faea1a01-d5bc-7882-80c8-5bd8d05d8bea', 'b0M', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"the sample tree","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 20 30 40 50 60 70 80","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"the tree 3 → 4 → 5 (each the left child of the previous)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"3 4 5","marks":[{"type":"code"}]}]}]}}'),
  ('9ea45a0f-896a-7a82-bf57-b9e6e41200ca', 'b0N', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Recursion naturally goes "},{"type":"text","text":"deep","marks":[{"type":"italic"}]},{"type":"text","text":". To go "},{"type":"text","text":"wide","marks":[{"type":"italic"}]},{"type":"text","text":" — whole level before the next — use a "},{"type":"text","text":"queue","marks":[{"type":"bold"}]},{"type":"text","text":": start with the root, and every time you dequeue a node, enqueue its children. Because a queue is FIFO, all of level "},{"type":"text","text":"d","marks":[{"type":"code"}]},{"type":"text","text":" is dequeued before anything from level "},{"type":"text","text":"d + 1","marks":[{"type":"code"}]},{"type":"text","text":", which was enqueued later."}]}]}}'),
  ('ebfe7f02-a132-7e76-a8f9-791e2ff83882', 'b0O', 'text', '{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Start","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Push the root into an empty queue."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Loop while the queue is not empty","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Pop the front node and print it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enqueue children","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Push its left child, then its right child (if they exist) — they will be visited after everything already in the queue."}]}]}]}]}}'),
  ('8085e7bb-f890-7ab7-a1b9-46bfca25b2d4', 'b0P', 'code', '{"language":"text","code":"queue →  [10]                 print 10, push 20 30\n         [20 30]              print 20, push 40 50\n         [30 40 50]           print 30, push 60\n         [40 50 60]           print 40 (leaf)\n         [50 60]              print 50, push 70 80\n         [60 70 80]           print 60, 70, 80 (leaves)\n         []                   done:  10 20 30 40 50 60 70 80","filename":"The queue holds at most one level (plus part of the next) at any time"}'),
  ('ac038e7f-f68a-7136-be21-09307d54553a', 'b0Q', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, key):\n        self.key = key\n        self.left = None\n        self.right = None\n\ndef sample_tree():                   # the tree from the notes\n    root = Node(10)\n    root.left = Node(20)\n    root.right = Node(30)\n    root.left.left = Node(40)\n    root.left.right = Node(50)\n    root.right.right = Node(60)\n    root.left.right.left = Node(70)\n    root.left.right.right = Node(80)\n    return root\n\nfrom collections import deque\n\ndef level_order(root):\n    if root is None:\n        return\n    q = deque([root])\n    while q:\n        node = q.popleft()               # oldest node first (FIFO)\n        print(node.key, end=\" \")\n        if node.left:                    # its children join the back of the line\n            q.append(node.left)\n        if node.right:\n            q.append(node.right)\n\nlevel_order(sample_tree())\nprint()","filename":"Python"}'),
  ('0ea01f8e-9d62-7cac-ae90-05927a294713', 'b0R', 'code', '{"language":"cpp","code":"#include <queue>\n#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int key;\n    Node *left, *right;\n    Node(int k) : key(k), left(nullptr), right(nullptr) {}\n};\n\nNode* sampleTree() {                 // the tree from the notes\n    Node* root = new Node(10);\n    root->left = new Node(20);\n    root->right = new Node(30);\n    root->left->left = new Node(40);\n    root->left->right = new Node(50);\n    root->right->right = new Node(60);\n    root->left->right->left = new Node(70);\n    root->left->right->right = new Node(80);\n    return root;\n}\n\nvoid levelOrder(Node* root) {\n    if (!root) return;\n    queue<Node*> q;\n    q.push(root);\n    while (!q.empty()) {\n        Node* node = q.front(); q.pop();     // oldest node first (FIFO)\n        cout << node->key << \" \";\n        if (node->left) q.push(node->left);  // its children join the back of the line\n        if (node->right) q.push(node->right);\n    }\n}\n\nint main() {\n    levelOrder(sampleTree());\n    cout << \"\\n\";\n}","filename":"C++"}'),
  ('ad60b676-b63a-767e-9d78-34d2bf726aef', 'b0S', 'code', '{"language":"java","code":"import java.util.ArrayDeque;\nimport java.util.Queue;\n\npublic class Main {\n    static class Node {\n        int key; Node left, right;\n        Node(int k) { key = k; }\n    }\n\n    static Node sampleTree() {           // the tree from the notes\n        Node root = new Node(10);\n        root.left = new Node(20);\n        root.right = new Node(30);\n        root.left.left = new Node(40);\n        root.left.right = new Node(50);\n        root.right.right = new Node(60);\n        root.left.right.left = new Node(70);\n        root.left.right.right = new Node(80);\n        return root;\n    }\n\n    static void levelOrder(Node root) {\n        if (root == null) return;\n        Queue<Node> q = new ArrayDeque<>();\n        q.offer(root);\n        while (!q.isEmpty()) {\n            Node node = q.poll();                // oldest node first (FIFO)\n            System.out.print(node.key + \" \");\n            if (node.left != null) q.offer(node.left);   // children join the back of the line\n            if (node.right != null) q.offer(node.right);\n        }\n    }\n\n    public static void main(String[] args) {\n        levelOrder(sampleTree());\n        System.out.println();\n    }\n}","filename":"Java"}'),
  ('def3b8cb-bf25-7186-83c2-a082725b1280', 'b0T', 'code', '{"language":"javascript","code":"class Node {\n    constructor(key) { this.key = key; this.left = null; this.right = null; }\n}\n\nfunction sampleTree() {              // the tree from the notes\n    const root = new Node(10);\n    root.left = new Node(20);\n    root.right = new Node(30);\n    root.left.left = new Node(40);\n    root.left.right = new Node(50);\n    root.right.right = new Node(60);\n    root.left.right.left = new Node(70);\n    root.left.right.right = new Node(80);\n    return root;\n}\n\nfunction levelOrder(root) {\n    if (root === null) return;\n    const q = [root];\n    let head = 0;                        // index of the front: avoids O(n) shift()\n    while (head < q.length) {\n        const node = q[head++];          // oldest node first (FIFO)\n        process.stdout.write(node.key + \" \");\n        if (node.left) q.push(node.left);    // its children join the back of the line\n        if (node.right) q.push(node.right);\n    }\n}\n\nlevelOrder(sampleTree());\nconsole.log();","filename":"JavaScript"}'),
  ('19cd2b83-63d4-795d-87a8-8b95b314dcb8', 'b0U', 'code', '{"language":"text","code":"10 20 30 40 50 60 70 80","filename":"Output"}'),
  ('3d509c7b-c0da-7fcd-83de-89054179db06', 'b0V', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(w) — the widest level, up to n/2 nodes for a perfect tree"}]},{"type":"paragraph","content":[{"type":"text","text":"Level by level.","marks":[{"type":"bold"}]},{"type":"text","text":" Interviewers usually want each level on its own line. Record the queue''s size at the start of each round: exactly that many nodes belong to the current level, so pop just those, then start the next line."}]}]}}'),
  ('9eb4e8b0-d400-7e4b-930c-9fc90ba95e75', 'b0W', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, key):\n        self.key = key\n        self.left = None\n        self.right = None\n\ndef sample_tree():                   # the tree from the notes\n    root = Node(10)\n    root.left = Node(20)\n    root.right = Node(30)\n    root.left.left = Node(40)\n    root.left.right = Node(50)\n    root.right.right = Node(60)\n    root.left.right.left = Node(70)\n    root.left.right.right = Node(80)\n    return root\n\nfrom collections import deque\n\ndef level_order_lines(root):\n    if root is None:\n        return\n    q = deque([root])\n    while q:\n        count = len(q)                   # nodes of the current level\n        for _ in range(count):\n            node = q.popleft()\n            print(node.key, end=\" \")\n            if node.left:\n                q.append(node.left)\n            if node.right:\n                q.append(node.right)\n        print()                          # level finished\n\nlevel_order_lines(sample_tree())","filename":"Python"}'),
  ('6603f27f-01d3-7d80-937e-59679512bf00', 'b0X', 'code', '{"language":"cpp","code":"#include <queue>\n#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int key;\n    Node *left, *right;\n    Node(int k) : key(k), left(nullptr), right(nullptr) {}\n};\n\nNode* sampleTree() {                 // the tree from the notes\n    Node* root = new Node(10);\n    root->left = new Node(20);\n    root->right = new Node(30);\n    root->left->left = new Node(40);\n    root->left->right = new Node(50);\n    root->right->right = new Node(60);\n    root->left->right->left = new Node(70);\n    root->left->right->right = new Node(80);\n    return root;\n}\n\nvoid levelOrderLines(Node* root) {\n    if (!root) return;\n    queue<Node*> q;\n    q.push(root);\n    while (!q.empty()) {\n        int count = (int)q.size();           // nodes of the current level\n        for (int i = 0; i < count; i++) {\n            Node* node = q.front(); q.pop();\n            cout << node->key << \" \";\n            if (node->left) q.push(node->left);\n            if (node->right) q.push(node->right);\n        }\n        cout << \"\\n\";                        // level finished\n    }\n}\n\nint main() { levelOrderLines(sampleTree()); }","filename":"C++"}'),
  ('a0dad84e-c36f-7203-8ea1-beb2f831fa9c', 'b0Y', 'code', '{"language":"java","code":"import java.util.ArrayDeque;\nimport java.util.Queue;\n\npublic class Main {\n    static class Node {\n        int key; Node left, right;\n        Node(int k) { key = k; }\n    }\n\n    static Node sampleTree() {           // the tree from the notes\n        Node root = new Node(10);\n        root.left = new Node(20);\n        root.right = new Node(30);\n        root.left.left = new Node(40);\n        root.left.right = new Node(50);\n        root.right.right = new Node(60);\n        root.left.right.left = new Node(70);\n        root.left.right.right = new Node(80);\n        return root;\n    }\n\n    static void levelOrderLines(Node root) {\n        if (root == null) return;\n        Queue<Node> q = new ArrayDeque<>();\n        q.offer(root);\n        while (!q.isEmpty()) {\n            int count = q.size();                // nodes of the current level\n            for (int i = 0; i < count; i++) {\n                Node node = q.poll();\n                System.out.print(node.key + \" \");\n                if (node.left != null) q.offer(node.left);\n                if (node.right != null) q.offer(node.right);\n            }\n            System.out.println();                // level finished\n        }\n    }\n\n    public static void main(String[] args) { levelOrderLines(sampleTree()); }\n}","filename":"Java"}'),
  ('bfe96b95-4c24-726f-add0-15ce7efd4de7', 'b0Z', 'code', '{"language":"javascript","code":"class Node {\n    constructor(key) { this.key = key; this.left = null; this.right = null; }\n}\n\nfunction sampleTree() {              // the tree from the notes\n    const root = new Node(10);\n    root.left = new Node(20);\n    root.right = new Node(30);\n    root.left.left = new Node(40);\n    root.left.right = new Node(50);\n    root.right.right = new Node(60);\n    root.left.right.left = new Node(70);\n    root.left.right.right = new Node(80);\n    return root;\n}\n\nfunction levelOrderLines(root) {\n    if (root === null) return;\n    let level = [root];\n    while (level.length) {               // the current level is a whole array\n        const next = [];\n        process.stdout.write(level.map(n => n.key).join(\" \") + \"\\n\");\n        for (const node of level) {\n            if (node.left) next.push(node.left);\n            if (node.right) next.push(node.right);\n        }\n        level = next;                    // level finished\n    }\n}\n\nlevelOrderLines(sampleTree());","filename":"JavaScript"}'),
  ('530212f5-a71f-79c0-8fdd-f873841c7040', 'b0a', 'code', '{"language":"text","code":"10\n20 30\n40 50 60\n70 80","filename":"Output"}'),
  ('e55846b4-66ec-7f6d-ace3-688f6df7c49b', 'b0b', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(w)"}]}]}}'),
  ('9bfb0247-3a4b-74af-a4d8-0e466db30adc', 'b0c', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Using a plain list / array as the queue and removing from the front ("},{"type":"text","text":"list.pop(0)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Array.shift()","marks":[{"type":"code"}]},{"type":"text","text":") makes every dequeue "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" and the traversal "},{"type":"text","text":"O(n²)","marks":[{"type":"code"}]},{"type":"text","text":". Use "},{"type":"text","text":"collections.deque","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"std::queue","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"ArrayDeque","marks":[{"type":"code"}]},{"type":"text","text":", or an index into the array as above."}]}]}}'),
  ('eefea2ba-6c6d-7c1f-9b0c-53697c8a88b6', 'b0d', 'heading', '{"level":1,"content":[{"type":"text","text":"Size of a binary tree"}]}'),
  ('54a5b2df-96d7-7079-b24a-eef8c830aecb', 'b0e', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"the sample tree","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"8","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"an empty tree","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"0","marks":[{"type":"code"}]}]}]}}'),
  ('adde00c3-0492-7f2c-bcc7-a944404e517d', 'b0f', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The size of a tree is the size of the left subtree plus the size of the right subtree plus one for the root. Same shape as "},{"type":"text","text":"height()","marks":[{"type":"code"}]},{"type":"text","text":", with "},{"type":"text","text":"+","marks":[{"type":"code"}]},{"type":"text","text":" instead of "},{"type":"text","text":"max","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('2ecb696e-ccac-7beb-987e-031532f351e2', 'b0g', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, key):\n        self.key = key\n        self.left = None\n        self.right = None\n\ndef sample_tree():                   # the tree from the notes\n    root = Node(10)\n    root.left = Node(20)\n    root.right = Node(30)\n    root.left.left = Node(40)\n    root.left.right = Node(50)\n    root.right.right = Node(60)\n    root.left.right.left = Node(70)\n    root.left.right.right = Node(80)\n    return root\n\ndef size(root):\n    if root is None:\n        return 0\n    return size(root.left) + size(root.right) + 1    # left + right + the root\n\nroot = sample_tree()\nprint(\"size:\", size(root))\nprint(\"size of left subtree:\", size(root.left))\nprint(\"size of right subtree:\", size(root.right))","filename":"Python"}'),
  ('cf170bd3-abb6-73e8-b90e-5d405b573e7d', 'b0h', 'code', '{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int key;\n    Node *left, *right;\n    Node(int k) : key(k), left(nullptr), right(nullptr) {}\n};\n\nNode* sampleTree() {                 // the tree from the notes\n    Node* root = new Node(10);\n    root->left = new Node(20);\n    root->right = new Node(30);\n    root->left->left = new Node(40);\n    root->left->right = new Node(50);\n    root->right->right = new Node(60);\n    root->left->right->left = new Node(70);\n    root->left->right->right = new Node(80);\n    return root;\n}\n\nint size(Node* root) {\n    if (!root) return 0;\n    return size(root->left) + size(root->right) + 1;  // left + right + the root\n}\n\nint main() {\n    Node* root = sampleTree();\n    cout << \"size: \" << size(root) << \"\\n\";\n    cout << \"size of left subtree: \" << size(root->left) << \"\\n\";\n    cout << \"size of right subtree: \" << size(root->right) << \"\\n\";\n}","filename":"C++"}'),
  ('8f308f1a-ad9d-7c5d-8d3c-8156b9b93eaa', 'b0i', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int key; Node left, right;\n        Node(int k) { key = k; }\n    }\n\n    static Node sampleTree() {           // the tree from the notes\n        Node root = new Node(10);\n        root.left = new Node(20);\n        root.right = new Node(30);\n        root.left.left = new Node(40);\n        root.left.right = new Node(50);\n        root.right.right = new Node(60);\n        root.left.right.left = new Node(70);\n        root.left.right.right = new Node(80);\n        return root;\n    }\n\n    static int size(Node root) {\n        if (root == null) return 0;\n        return size(root.left) + size(root.right) + 1;    // left + right + the root\n    }\n\n    public static void main(String[] args) {\n        Node root = sampleTree();\n        System.out.println(\"size: \" + size(root));\n        System.out.println(\"size of left subtree: \" + size(root.left));\n        System.out.println(\"size of right subtree: \" + size(root.right));\n    }\n}","filename":"Java"}'),
  ('fd5efa7d-a3f3-778e-a7e3-86ebbcedde60', 'b0j', 'code', '{"language":"javascript","code":"class Node {\n    constructor(key) { this.key = key; this.left = null; this.right = null; }\n}\n\nfunction sampleTree() {              // the tree from the notes\n    const root = new Node(10);\n    root.left = new Node(20);\n    root.right = new Node(30);\n    root.left.left = new Node(40);\n    root.left.right = new Node(50);\n    root.right.right = new Node(60);\n    root.left.right.left = new Node(70);\n    root.left.right.right = new Node(80);\n    return root;\n}\n\nfunction size(root) {\n    if (root === null) return 0;\n    return size(root.left) + size(root.right) + 1;    // left + right + the root\n}\n\nconst root = sampleTree();\nconsole.log(\"size:\", size(root));\nconsole.log(\"size of left subtree:\", size(root.left));\nconsole.log(\"size of right subtree:\", size(root.right));","filename":"JavaScript"}'),
  ('9b5bebc2-cc96-73ca-b24f-7868b9054937', 'b0k', 'code', '{"language":"text","code":"size: 8\nsize of left subtree: 5\nsize of right subtree: 2","filename":"Output"}'),
  ('ec7926bf-8ca2-7e73-900e-5395adea8711', 'b0l', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(h)"}]}]}}'),
  ('31dbc2bf-3eb1-792e-95ef-5d090cc99a54', 'b0m', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every node is visited once and does "},{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":" work, hence "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" time. An iterative version is level order with a counter — the recursion is just shorter."}]}]}}'),
  ('93d4424a-1d20-78dc-87f7-214dfa11765d', 'b0n', 'heading', '{"level":1,"content":[{"type":"text","text":"Maximum value in a binary tree"}]}'),
  ('a85c69db-f16f-745b-b273-fca8c62b385f', 'b0o', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"the sample tree","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"80","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"an empty tree","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"-inf (no maximum)","marks":[{"type":"code"}]}]}]}}'),
  ('1d8eac90-766b-7a5b-827a-4f3583c81c2a', 'b0p', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The maximum of a tree is the largest of three things: the root''s key, the maximum of the left subtree and the maximum of the right subtree. The base case returns "},{"type":"text","text":"−∞","marks":[{"type":"code"}]},{"type":"text","text":" so that an empty subtree never wins. A plain binary tree has no ordering, so "},{"type":"text","text":"every","marks":[{"type":"bold"}]},{"type":"text","text":" node must be looked at — unlike a BST, where the maximum is simply the rightmost node."}]}]}}'),
  ('d682bdb9-286a-72c2-ac78-b82aebf8f16d', 'b0q', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, key):\n        self.key = key\n        self.left = None\n        self.right = None\n\ndef sample_tree():                   # the tree from the notes\n    root = Node(10)\n    root.left = Node(20)\n    root.right = Node(30)\n    root.left.left = Node(40)\n    root.left.right = Node(50)\n    root.right.right = Node(60)\n    root.left.right.left = Node(70)\n    root.left.right.right = Node(80)\n    return root\n\nimport math\n\ndef get_max(root):\n    if root is None:\n        return -math.inf                     # identity for max: never wins\n    return max(root.key, get_max(root.left), get_max(root.right))\n\nroot = sample_tree()\nprint(\"max:\", get_max(root))\nprint(\"max of right subtree:\", get_max(root.right))","filename":"Python"}'),
  ('36caf5f4-3b4c-7a62-9a04-f40b3a4b1621', 'b0r', 'code', '{"language":"cpp","code":"#include <algorithm>\n#include <climits>\n#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int key;\n    Node *left, *right;\n    Node(int k) : key(k), left(nullptr), right(nullptr) {}\n};\n\nNode* sampleTree() {                 // the tree from the notes\n    Node* root = new Node(10);\n    root->left = new Node(20);\n    root->right = new Node(30);\n    root->left->left = new Node(40);\n    root->left->right = new Node(50);\n    root->right->right = new Node(60);\n    root->left->right->left = new Node(70);\n    root->left->right->right = new Node(80);\n    return root;\n}\n\nint getMax(Node* root) {\n    if (!root) return INT_MIN;               // identity for max: never wins\n    return max({root->key, getMax(root->left), getMax(root->right)});\n}\n\nint main() {\n    Node* root = sampleTree();\n    cout << \"max: \" << getMax(root) << \"\\n\";\n    cout << \"max of right subtree: \" << getMax(root->right) << \"\\n\";\n}","filename":"C++"}'),
  ('399568d0-238b-71de-980a-4390786f0d89', 'b0s', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int key; Node left, right;\n        Node(int k) { key = k; }\n    }\n\n    static Node sampleTree() {           // the tree from the notes\n        Node root = new Node(10);\n        root.left = new Node(20);\n        root.right = new Node(30);\n        root.left.left = new Node(40);\n        root.left.right = new Node(50);\n        root.right.right = new Node(60);\n        root.left.right.left = new Node(70);\n        root.left.right.right = new Node(80);\n        return root;\n    }\n\n    static int getMax(Node root) {\n        if (root == null) return Integer.MIN_VALUE;   // identity for max: never wins\n        return Math.max(root.key, Math.max(getMax(root.left), getMax(root.right)));\n    }\n\n    public static void main(String[] args) {\n        Node root = sampleTree();\n        System.out.println(\"max: \" + getMax(root));\n        System.out.println(\"max of right subtree: \" + getMax(root.right));\n    }\n}","filename":"Java"}'),
  ('e38518bc-b3aa-7664-8b0f-debcf9dfcf93', 'b0t', 'code', '{"language":"javascript","code":"class Node {\n    constructor(key) { this.key = key; this.left = null; this.right = null; }\n}\n\nfunction sampleTree() {              // the tree from the notes\n    const root = new Node(10);\n    root.left = new Node(20);\n    root.right = new Node(30);\n    root.left.left = new Node(40);\n    root.left.right = new Node(50);\n    root.right.right = new Node(60);\n    root.left.right.left = new Node(70);\n    root.left.right.right = new Node(80);\n    return root;\n}\n\nfunction getMax(root) {\n    if (root === null) return -Infinity;     // identity for max: never wins\n    return Math.max(root.key, getMax(root.left), getMax(root.right));\n}\n\nconst root = sampleTree();\nconsole.log(\"max:\", getMax(root));\nconsole.log(\"max of right subtree:\", getMax(root.right));","filename":"JavaScript"}'),
  ('e1742ab6-fb20-7311-9587-d24eb9da5025', 'b0u', 'code', '{"language":"text","code":"max: 80\nmax of right subtree: 60","filename":"Output"}'),
  ('1b8bec9c-c747-7275-8075-f27b943ba32d', 'b0v', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(h)"}]}]}}'),
  ('7ba89946-5361-74e7-861f-65a15dabeb83', 'b0w', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Returning "},{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":" for an empty subtree is wrong as soon as all keys are negative. Use the smallest possible value ("},{"type":"text","text":"-math.inf","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"INT_MIN","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Integer.MIN_VALUE","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"-Infinity","marks":[{"type":"code"}]},{"type":"text","text":") as the base case — the same trick gives "},{"type":"text","text":"getMin","marks":[{"type":"code"}]},{"type":"text","text":" with "},{"type":"text","text":"+∞","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"min","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('f05193de-5eea-7dc8-b38a-56bb9bfeda1f', 'b0x', 'heading', '{"level":1,"content":[{"type":"text","text":"Recursion on trees: the pattern"}]}'),
  ('c2077599-2926-7516-ad7c-d115e938d470', 'b0y', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Height, size, maximum, and most other tree problems have the same three-line shape — remember it and you can derive the others in an interview."}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Base case","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"if root is None: return <identity>","marks":[{"type":"code"}]},{"type":"text","text":" — "},{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":" for counting, "},{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"-1","marks":[{"type":"code"}]},{"type":"text","text":" for height, "},{"type":"text","text":"−∞","marks":[{"type":"code"}]},{"type":"text","text":" for max, "},{"type":"text","text":"+∞","marks":[{"type":"code"}]},{"type":"text","text":" for min, "},{"type":"text","text":"True","marks":[{"type":"code"}]},{"type":"text","text":" for "},{"type":"text","text":"is valid","marks":[{"type":"italic"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Recurse","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Solve the problem for "},{"type":"text","text":"root.left","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"root.right","marks":[{"type":"code"}]},{"type":"text","text":" — trust the recursion to return the right answer for each subtree."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Combine","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Mix the two answers with the root: "},{"type":"text","text":"max(l, r) + 1","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"l + r + 1","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"max(key, l, r)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"l and r and <condition on root>","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}}'),
  ('699edbb3-40ff-72d7-875e-216b99a77b5e', 'b0z', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Problem"}],[{"type":"text","text":"Base case"}],[{"type":"text","text":"Combine"}]],[[{"type":"text","text":"Height"}],[{"type":"text","text":"0","marks":[{"type":"code"}]}],[{"type":"text","text":"max(l, r) + 1","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Size"}],[{"type":"text","text":"0","marks":[{"type":"code"}]}],[{"type":"text","text":"l + r + 1","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Maximum"}],[{"type":"text","text":"−∞","marks":[{"type":"code"}]}],[{"type":"text","text":"max(key, l, r)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Sum of keys"}],[{"type":"text","text":"0","marks":[{"type":"code"}]}],[{"type":"text","text":"l + r + key","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Count leaves"}],[{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":"; a leaf returns "},{"type":"text","text":"1","marks":[{"type":"code"}]}],[{"type":"text","text":"l + r","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Is balanced"}],[{"type":"text","text":"True","marks":[{"type":"code"}]}],[{"type":"text","text":"l and r and |height(left) − height(right)| ≤ 1","marks":[{"type":"code"}]}]]]}'),
  ('6e0065df-bedd-7d0c-84b4-c5a21532902f', 'b10', 'heading', '{"level":1,"content":[{"type":"text","text":"Interview Q&A"}]}'),
  ('53636e73-7cd1-7ccf-8469-65f548e341c7', 'b11', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between a binary tree and a binary search tree?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A binary tree only limits every node to at most two children — the keys can be anywhere. A binary search tree adds an "},{"type":"text","text":"ordering invariant","marks":[{"type":"bold"}]},{"type":"text","text":": every key in a node''s left subtree is smaller and every key in its right subtree is larger. That invariant is what makes search "},{"type":"text","text":"O(h)","marks":[{"type":"code"}]},{"type":"text","text":" instead of "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('4a07fb39-905b-758e-a24c-1cadb9629e5c', 'b12', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is the height of a tree so important?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Almost every operation walks one root-to-leaf path, so it costs "},{"type":"text","text":"O(h)","marks":[{"type":"code"}]},{"type":"text","text":". For a balanced tree "},{"type":"text","text":"h = O(log n)","marks":[{"type":"code"}]},{"type":"text","text":"; for a skewed tree "},{"type":"text","text":"h = n − 1","marks":[{"type":"code"}]},{"type":"text","text":", and the tree degrades into a linked list. Self-balancing trees (AVL, red-black) exist purely to keep "},{"type":"text","text":"h","marks":[{"type":"code"}]},{"type":"text","text":" logarithmic."}]}]}}'),
  ('d1d597e9-db11-7412-8223-686819011923', 'b13', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Which traversal would you use to delete every node of a tree, and why?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Postorder","marks":[{"type":"bold"}]},{"type":"text","text":": both children are freed before the parent, so no pointer to a child is ever lost. Preorder would free the parent — and the links to its children — first."}]}]}}'),
  ('a8d41f41-9b60-7f28-a72d-a1094ddabaaf', 'b14', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you get the inorder sequence without recursion?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use an explicit stack: walk left pushing every node, pop one and print it, then move to its right child and repeat. It is the same "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" time and "},{"type":"text","text":"O(h)","marks":[{"type":"code"}]},{"type":"text","text":" space, but the stack is yours instead of the call stack — useful in languages with a small recursion limit (Python stops at about 1000 frames)."}]}]}}'),
  ('28732d0c-bcbf-7e6f-a8fe-6787ad3cf8f4', 'b15', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Is level order traversal depth-first or breadth-first, and what data structure does it need?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Breadth-first — it finishes a level before starting the next. It needs a "},{"type":"text","text":"queue","marks":[{"type":"bold"}]},{"type":"text","text":"; the three depth-first traversals need a "},{"type":"text","text":"stack","marks":[{"type":"bold"}]},{"type":"text","text":" (the call stack when written recursively). Space is "},{"type":"text","text":"O(w)","marks":[{"type":"code"}]},{"type":"text","text":" for the widest level versus "},{"type":"text","text":"O(h)","marks":[{"type":"code"}]},{"type":"text","text":" for depth-first; for a perfect tree the last level holds about "},{"type":"text","text":"n/2","marks":[{"type":"code"}]},{"type":"text","text":" nodes, so BFS can use far more memory."}]}]}}'),
  ('dcec039a-27ca-7e52-9441-dc6533efefbb', 'b16', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Can you rebuild a binary tree from its traversals?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"From "},{"type":"text","text":"inorder plus preorder","marks":[{"type":"bold"}]},{"type":"text","text":" (or inorder plus postorder), yes: the first preorder element is the root, its position in the inorder sequence splits the inorder into the left and right subtrees, and you recurse. Preorder plus postorder alone is "},{"type":"text","text":"not","marks":[{"type":"bold"}]},{"type":"text","text":" enough — a node with a single child is ambiguous. A single traversal with "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":" markers is also enough, which is how serialisation works."}]}]}}')
) AS c(id, position, type, content)
