SELECT 'b0e4236b-43eb-751e-ad39-c78a31454645', '5ce2b61d-cfb6-78a5-af97-c1ee4bb9d50d', 1, 'PUBLISHED', 'Binary Indexed Tree', '[{"id":"b13d79a5-bf13-7fbe-a1d8-46a0d75ab545","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A binary indexed tree (Fenwick tree) supports "},{"type":"text","text":"prefix queries","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"point updates","marks":[{"type":"bold"}]},{"type":"text","text":" over a fixed-size array in "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":" each, using a single array of "},{"type":"text","text":"n + 1","marks":[{"type":"code"}]},{"type":"text","text":" integers and a handful of lines of code. It is the lightweight alternative to a segment tree for sums, counts and XORs."}]}]}},"revision":1},{"id":"8476964e-26a6-7d33-b32a-15f3a65bca0b","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Binary indexed tree (BIT, Fenwick tree)","marks":[{"type":"bold"}]},{"type":"text","text":" — an array "},{"type":"text","text":"BIT[1..n]","marks":[{"type":"code"}]},{"type":"text","text":" in which "},{"type":"text","text":"BIT[i]","marks":[{"type":"code"}]},{"type":"text","text":" stores the sum of the "},{"type":"text","text":"i & −i","marks":[{"type":"code"}]},{"type":"text","text":" elements of the input ending at position "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" (1-based). Prefix sums and updates both walk "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":" entries by repeatedly clearing or adding the lowest set bit of the index."}]}]}},"revision":1},{"id":"94e65570-2615-78c6-8bef-c63c70367f7d","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It is used for a fixed input array with many operations of two kinds: a "},{"type":"text","text":"prefix operation","marks":[{"type":"bold"}]},{"type":"text","text":" — sum, product, XOR, OR, count — and "},{"type":"text","text":"updating a value","marks":[{"type":"bold"}]},{"type":"text","text":". It is stored as a plain array, but the idea behind the indices is a tree. It needs "},{"type":"text","text":"O(n log n)","marks":[{"type":"code"}]},{"type":"text","text":" preprocessing ("},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" with a trick) and "},{"type":"text","text":"Θ(n)","marks":[{"type":"code"}]},{"type":"text","text":" auxiliary space."}]}]}},"revision":1},{"id":"93c085d5-228e-71e3-81de-41749339ac7c","type":"callout","position":"a3","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"arr = [10, 20, 30, 40, 50, 60]; getSum(2); getSum(4)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"60 150","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"update(2, 35); getSum(2); getSum(4)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"65 155","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"5384bade-dd17-7d1d-9684-80de2de0be68","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"rangeSum(i, j) = prefixSum(j) − prefixSum(i − 1)","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"fb9a30fe-e272-7146-b57a-b91ddb4b6234","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Three approaches to prefix sum + update"}]},"revision":1},{"id":"da0cde6b-45b6-70be-995c-289c74168e4e","type":"text","position":"a6","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"getSum(i)","marks":[{"type":"code"}]},{"type":"text","text":" returns "},{"type":"text","text":"arr[0] + … + arr[i]","marks":[{"type":"code"}]},{"type":"text","text":"; "},{"type":"text","text":"update(i, x)","marks":[{"type":"code"}]},{"type":"text","text":" sets "},{"type":"text","text":"arr[i] = x","marks":[{"type":"code"}]},{"type":"text","text":". Both operations are frequent and interleaved."}]}]}},"revision":1},{"id":"2b14747a-1192-73b8-8ab6-f065168e6687","type":"table","position":"a7","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Method"}],[{"type":"text","text":"getSum(i)","marks":[{"type":"code"}]}],[{"type":"text","text":"update(i, x)","marks":[{"type":"code"}]}],[{"type":"text","text":"Space"}],[{"type":"text","text":"Code"}]],[[{"type":"text","text":"1 — simple","marks":[{"type":"bold"}]},{"type":"text","text":": loop from "},{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"i","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"O(1) — "},{"type":"text","text":"arr[i] = x","marks":[{"type":"code"}]}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"trivial"}]],[[{"type":"text","text":"2 — prefix-sum array","marks":[{"type":"bold"}]},{"type":"text","text":": "},{"type":"text","text":"pre[i]","marks":[{"type":"code"}]}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"O(n) — add "},{"type":"text","text":"diff","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"pre[i..n−1]","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"trivial"}]],[[{"type":"text","text":"3 — segment tree","marks":[{"type":"bold"}]}],[{"type":"text","text":"O(log n)"}],[{"type":"text","text":"O(log n)"}],[{"type":"text","text":"≈ 4n"}],[{"type":"text","text":"three recursive functions"}]],[[{"type":"text","text":"Binary indexed tree","marks":[{"type":"bold"}]}],[{"type":"text","text":"O(log n)"}],[{"type":"text","text":"O(log n)"}],[{"type":"text","text":"n + 1"}],[{"type":"text","text":"two short loops","marks":[{"type":"bold"}]}]]]},"revision":1},{"id":"f27efdc5-e345-7b9d-af23-43e657ba16f0","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Methods 1 and 2 each make one operation linear; with a mixed workload the average cost is "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" per operation. The segment tree fixes that but is a comparatively heavy piece of code. The BIT gets the same "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":" for both operations with less memory and about ten lines."}]}]}},"revision":1},{"id":"3823f461-505e-76e0-8ee7-7736cf771d8c","type":"callout","position":"a9","content":{"variant":"note","title":"Limitation","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Unlike a segment tree, a BIT works only for operations that have an "},{"type":"text","text":"inverse","marks":[{"type":"bold"}]},{"type":"text","text":": "},{"type":"text","text":"rangeSum(i, j) = getSum(j) − getSum(i−1)","marks":[{"type":"code"}]},{"type":"text","text":" needs subtraction. Prefix "},{"type":"text","text":"min","marks":[{"type":"italic"}]},{"type":"text","text":" or "},{"type":"text","text":"max","marks":[{"type":"italic"}]},{"type":"text","text":" cannot be undone, so range-min queries need a segment tree."}]}]}},"revision":1},{"id":"95453ca3-649f-7d1e-bdcf-769c242a4d9a","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"The idea: every prefix is a sum of powers of two"}]},"revision":1},{"id":"eea699ef-2599-7753-9fdc-311933be0d1d","type":"text","position":"aB","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Any positive integer is a sum of distinct powers of two: "},{"type":"text","text":"14 = 8 + 4 + 2","marks":[{"type":"code"}]},{"type":"text","text":". So a prefix of length "},{"type":"text","text":"14","marks":[{"type":"code"}]},{"type":"text","text":" can be split into three blocks of lengths "},{"type":"text","text":"8","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"4","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"2","marks":[{"type":"code"}]},{"type":"text","text":", and if the sum of each block is pre-computed, "},{"type":"text","text":"getSum","marks":[{"type":"code"}]},{"type":"text","text":" needs three additions instead of fourteen. The BIT stores exactly these blocks: entry "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" (1-based) is responsible for the "},{"type":"text","text":"last ","marks":[{"type":"bold"}]},{"type":"text","text":"i & −i","marks":[{"type":"bold"},{"type":"code"}]},{"type":"text","text":" elements ending at ","marks":[{"type":"bold"}]},{"type":"text","text":"i","marks":[{"type":"bold"},{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"071068dd-864a-7149-9767-24d0610938b6","type":"code","position":"aC","content":{"language":"text","code":"arr (0-based):  10   20   30   40   50   60\nBIT index i  :   1    2    3    4    5    6\ni & -i       :   1    2    1    4    1    2\ncovers       :  [1] [1,2] [3] [1..4] [5] [5,6]\nBIT[i]       :  10   30   30   100   50  110\n\n              0 (virtual root)\n        ┌─────┼──────────┐\n        1     2          4           parent of i for queries = i − (i & −i)\n              │        ┌─┴─┐\n              3        5   6\n\ngetSum(4) → arr[0..4] → i = 5:  BIT[5] + BIT[4] = 50 + 100 = 150","filename":"Each BIT entry covers a block whose length is the lowest set bit of its index; a query adds up the blocks on the path to the root"},"revision":1},{"id":"ebe15c4d-03ca-7e5b-b041-f8a28e510bd7","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"The i & -i trick: isolating the lowest set bit"}]},"revision":1},{"id":"ecc07fa2-7212-739d-861a-a7725d128f86","type":"text","position":"aE","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"−i","marks":[{"type":"code"}]},{"type":"text","text":" in two''s complement is "},{"type":"text","text":"~i + 1","marks":[{"type":"code"}]},{"type":"text","text":": flip every bit, then add one. Flipping turns the trailing zeros of "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" into ones and the lowest "},{"type":"text","text":"1","marks":[{"type":"code"}]},{"type":"text","text":" into "},{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":"; adding one carries through those ones and stops exactly at that position. The result shares only that one bit with "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":", so "},{"type":"text","text":"i & −i","marks":[{"type":"code"}]},{"type":"text","text":" is the lowest set bit as a power of two."}]}]}},"revision":1},{"id":"ea05c620-6c17-7642-89ca-8be06c312e7b","type":"code","position":"aF","content":{"language":"text","code":" i = 6  :  0 1 1 0\n~i      :  1 0 0 1\n-i = ~i+1: 1 0 1 0\n i & -i :  0 0 1 0   = 2        6 → block of length 2 ([5, 6]);  6 − 2 = 4 is the next block\n\n i = 12 :  1 1 0 0\n-i      :  0 1 0 0\n i & -i :  0 1 0 0   = 4        12 → block of length 4 ([9..12]); 12 − 4 = 8 is the next block","filename":"i & −i for i = 6 and i = 12"},"revision":1},{"id":"a36a9c8f-b2ac-79ed-aad0-07867cb89aa3","type":"code","position":"aG","content":{"language":"python","code":"for i in range(1, 9):\n    print(f\"{i}  {i:04b}  lowest set bit = {i & -i}\")","filename":"Python"},"revision":1},{"id":"5695903f-ce51-7125-bc09-71cd37606271","type":"code","position":"aH","content":{"language":"text","code":"1  0001  lowest set bit = 1\n2  0010  lowest set bit = 2\n3  0011  lowest set bit = 1\n4  0100  lowest set bit = 4\n5  0101  lowest set bit = 1\n6  0110  lowest set bit = 2\n7  0111  lowest set bit = 1\n8  1000  lowest set bit = 8","filename":"Output"},"revision":1},{"id":"7920a774-28d1-74ea-a70f-99dcd3751904","type":"table","position":"aI","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Expression"}],[{"type":"text","text":"Effect"}],[{"type":"text","text":"Used by"}]],[[{"type":"text","text":"i -= i & -i","marks":[{"type":"code"}]}],[{"type":"text","text":"clear the lowest set bit → jump to the parent block"}],[{"type":"text","text":"getSum","marks":[{"type":"code"}]},{"type":"text","text":" (walk towards 0)"}]],[[{"type":"text","text":"i += i & -i","marks":[{"type":"code"}]}],[{"type":"text","text":"add the lowest set bit → jump to the next entry whose block contains "},{"type":"text","text":"i","marks":[{"type":"code"}]}],[{"type":"text","text":"update","marks":[{"type":"code"}]},{"type":"text","text":" (walk towards n)"}]]]},"revision":1},{"id":"64e75651-d423-793f-9929-5615578d4d9f","type":"heading","position":"aJ","content":{"level":1,"content":[{"type":"text","text":"getSum: prefix sum"}]},"revision":1},{"id":"aa39d977-aeab-7994-ae49-57121f347a62","type":"text","position":"aK","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"To get the sum of "},{"type":"text","text":"arr[0..i]","marks":[{"type":"code"}]},{"type":"text","text":", convert to the 1-based BIT index "},{"type":"text","text":"i + 1","marks":[{"type":"code"}]},{"type":"text","text":" and keep adding "},{"type":"text","text":"BIT[i]","marks":[{"type":"code"}]},{"type":"text","text":" while clearing the lowest set bit. Every step removes one "},{"type":"text","text":"1","marks":[{"type":"code"}]},{"type":"text","text":" bit, so there are at most "},{"type":"text","text":"log₂ n","marks":[{"type":"code"}]},{"type":"text","text":" steps."}]}]}},"revision":1},{"id":"0c12f7d4-8e8b-7881-a0a6-9a88d22ffe91","type":"code","position":"aL","content":{"language":"text","code":"getSum(i):\n    i = i + 1                     # BIT is 1-based\n    result = 0\n    while i > 0:\n        result += BIT[i]\n        i -= i & -i               # parent(i): drop the lowest set bit\n    return result\n\nresult = BIT[i] + BIT[parent(i)] + BIT[parent(parent(i))] + …","filename":"Prefix sum walks from i towards 0"},"revision":1},{"id":"6555f6fa-279a-7aba-934d-2f7cb4e59b65","type":"callout","position":"aM","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"getSum(4)","marks":[{"type":"code"}]},{"type":"text","text":": "},{"type":"text","text":"i = 5 (101)","marks":[{"type":"code"}]},{"type":"text","text":" → add "},{"type":"text","text":"BIT[5] = 50","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"i = 4 (100)","marks":[{"type":"code"}]},{"type":"text","text":" → add "},{"type":"text","text":"BIT[4] = 100","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"i = 0","marks":[{"type":"code"}]},{"type":"text","text":" → stop. Result "},{"type":"text","text":"150","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"623a47ab-8bc0-7df0-bcac-84705c04cb62","type":"heading","position":"aN","content":{"level":1,"content":[{"type":"text","text":"update: change one value"}]},"revision":1},{"id":"ea843ced-fe7a-7ac8-85d7-7c5b396251bd","type":"text","position":"aO","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The first parameter is an index of "},{"type":"text","text":"arr","marks":[{"type":"code"}]},{"type":"text","text":". Compute "},{"type":"text","text":"diff = x − arr[i]","marks":[{"type":"code"}]},{"type":"text","text":", store the new value, convert to the 1-based index and add "},{"type":"text","text":"diff","marks":[{"type":"code"}]},{"type":"text","text":" to every BIT entry whose block contains "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" — these are reached by "},{"type":"text","text":"adding","marks":[{"type":"bold"}]},{"type":"text","text":" the lowest set bit each time until the index exceeds "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"de6c488e-3704-7edb-911f-dc6edfcbc3dc","type":"code","position":"aP","content":{"language":"text","code":"update(i, x):\n    diff = x - arr[i]\n    arr[i] = x\n    i = i + 1\n    while i <= n:\n        BIT[i] += diff\n        i += i & -i               # next entry whose block includes position i\n\nupdate(2, 35) with n = 6: diff = +5\n    i = 3 (011) → BIT[3] += 5        covers [3]\n    i = 4 (100) → BIT[4] += 5        covers [1..4]\n    i = 8        > 6 → stop          (BIT[5], BIT[6] cover [5], [5,6] — unaffected)","filename":"Update walks from i towards n"},"revision":1},{"id":"bf00b3ed-48d0-7546-a2b1-151125f6eeba","type":"heading","position":"aQ","content":{"level":1,"content":[{"type":"text","text":"Construction and the complete program"}]},"revision":1},{"id":"2bf2fdb9-a6a7-7178-ad05-638ab0caef0e","type":"callout","position":"aR","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Build the BIT by starting from all zeros and calling "},{"type":"text","text":"update(i, arr[i])","marks":[{"type":"code"}]},{"type":"text","text":" for every element — "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" updates of "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":" each. The program below builds the tree for "},{"type":"text","text":"[10, 20, 30, 40, 50, 60]","marks":[{"type":"code"}]},{"type":"text","text":", answers prefix and range sums, performs an update and queries again."}]}]}},"revision":1},{"id":"80080565-dd6a-75b4-8328-865d6b0e550a","type":"code","position":"aS","content":{"language":"python","code":"class FenwickTree:\n    def __init__(self, arr):\n        self.n = len(arr)\n        self.arr = [0] * self.n                  # current values, needed to compute diff\n        self.bit = [0] * (self.n + 1)            # 1-based\n        for i, v in enumerate(arr):\n            self.update(i, v)                    # construction = n updates\n\n    def get_sum(self, i):                        # sum of arr[0..i]\n        i += 1\n        res = 0\n        while i > 0:\n            res += self.bit[i]\n            i -= i & -i                          # drop the lowest set bit → parent block\n        return res\n\n    def range_sum(self, l, r):\n        return self.get_sum(r) - (self.get_sum(l - 1) if l > 0 else 0)\n\n    def update(self, i, x):                      # set arr[i] = x\n        diff = x - self.arr[i]\n        self.arr[i] = x\n        i += 1\n        while i <= self.n:\n            self.bit[i] += diff\n            i += i & -i                          # next block that contains position i\n\nft = FenwickTree([10, 20, 30, 40, 50, 60])\nprint(\"BIT:\", \" \".join(map(str, ft.bit[1:])))\nprint(\"getSum(2):\", ft.get_sum(2))\nprint(\"getSum(4):\", ft.get_sum(4))\nprint(\"rangeSum(1, 4):\", ft.range_sum(1, 4))\nprint(\"update(2, 35)\")\nft.update(2, 35)\nprint(\"BIT:\", \" \".join(map(str, ft.bit[1:])))\nprint(\"getSum(2):\", ft.get_sum(2))\nprint(\"getSum(4):\", ft.get_sum(4))","filename":"Python"},"revision":1},{"id":"21dc39d9-b526-7807-8994-f36668d08f64","type":"code","position":"aT","content":{"language":"cpp","code":"#include <iostream>\n#include <vector>\nusing namespace std;\n\nclass FenwickTree {\n    int n;\n    vector<int> arr, bit;                        // arr = current values, bit = 1-based tree\npublic:\n    FenwickTree(const vector<int>& a) : n(a.size()), arr(n, 0), bit(n + 1, 0) {\n        for (int i = 0; i < n; i++) update(i, a[i]);   // construction = n updates\n    }\n    int getSum(int i) const {                    // sum of arr[0..i]\n        int res = 0;\n        for (i = i + 1; i > 0; i -= i & -i)      // drop the lowest set bit → parent block\n            res += bit[i];\n        return res;\n    }\n    int rangeSum(int l, int r) const { return getSum(r) - (l > 0 ? getSum(l - 1) : 0); }\n    void update(int i, int x) {                  // set arr[i] = x\n        int diff = x - arr[i];\n        arr[i] = x;\n        for (i = i + 1; i <= n; i += i & -i)     // next block that contains position i\n            bit[i] += diff;\n    }\n    void print() const { cout << \"BIT:\"; for (int i = 1; i <= n; i++) cout << \" \" << bit[i]; cout << \"\\n\"; }\n};\n\nint main() {\n    FenwickTree ft({10, 20, 30, 40, 50, 60});\n    ft.print();\n    cout << \"getSum(2): \" << ft.getSum(2) << \"\\n\";\n    cout << \"getSum(4): \" << ft.getSum(4) << \"\\n\";\n    cout << \"rangeSum(1, 4): \" << ft.rangeSum(1, 4) << \"\\n\";\n    cout << \"update(2, 35)\\n\";\n    ft.update(2, 35);\n    ft.print();\n    cout << \"getSum(2): \" << ft.getSum(2) << \"\\n\";\n    cout << \"getSum(4): \" << ft.getSum(4) << \"\\n\";\n}","filename":"C++"},"revision":1},{"id":"fb4865da-ab9e-78f6-bf89-c00f9599cddc","type":"code","position":"aU","content":{"language":"java","code":"public class Main {\n    static class FenwickTree {\n        int n;\n        int[] arr, bit;                          // arr = current values, bit = 1-based tree\n        FenwickTree(int[] a) {\n            n = a.length; arr = new int[n]; bit = new int[n + 1];\n            for (int i = 0; i < n; i++) update(i, a[i]);   // construction = n updates\n        }\n        int getSum(int i) {                      // sum of arr[0..i]\n            int res = 0;\n            for (i = i + 1; i > 0; i -= i & -i)  // drop the lowest set bit → parent block\n                res += bit[i];\n            return res;\n        }\n        int rangeSum(int l, int r) { return getSum(r) - (l > 0 ? getSum(l - 1) : 0); }\n        void update(int i, int x) {              // set arr[i] = x\n            int diff = x - arr[i];\n            arr[i] = x;\n            for (i = i + 1; i <= n; i += i & -i) // next block that contains position i\n                bit[i] += diff;\n        }\n        String dump() { StringBuilder sb = new StringBuilder(\"BIT:\"); for (int i = 1; i <= n; i++) sb.append('' '').append(bit[i]); return sb.toString(); }\n    }\n\n    public static void main(String[] args) {\n        FenwickTree ft = new FenwickTree(new int[]{10, 20, 30, 40, 50, 60});\n        System.out.println(ft.dump());\n        System.out.println(\"getSum(2): \" + ft.getSum(2));\n        System.out.println(\"getSum(4): \" + ft.getSum(4));\n        System.out.println(\"rangeSum(1, 4): \" + ft.rangeSum(1, 4));\n        System.out.println(\"update(2, 35)\");\n        ft.update(2, 35);\n        System.out.println(ft.dump());\n        System.out.println(\"getSum(2): \" + ft.getSum(2));\n        System.out.println(\"getSum(4): \" + ft.getSum(4));\n    }\n}","filename":"Java"},"revision":1},{"id":"25c30b26-5ec6-7f17-b67d-f72a7d8bdcd2","type":"code","position":"aV","content":{"language":"javascript","code":"class FenwickTree {\n    constructor(a) {\n        this.n = a.length;\n        this.arr = new Array(this.n).fill(0);        // current values, needed to compute diff\n        this.bit = new Array(this.n + 1).fill(0);    // 1-based\n        a.forEach((v, i) => this.update(i, v));      // construction = n updates\n    }\n    getSum(i) {                                      // sum of arr[0..i]\n        let res = 0;\n        for (i = i + 1; i > 0; i -= i & -i) res += this.bit[i];   // drop the lowest set bit → parent block\n        return res;\n    }\n    rangeSum(l, r) { return this.getSum(r) - (l > 0 ? this.getSum(l - 1) : 0); }\n    update(i, x) {                                   // set arr[i] = x\n        const diff = x - this.arr[i];\n        this.arr[i] = x;\n        for (i = i + 1; i <= this.n; i += i & -i) this.bit[i] += diff;   // next block that contains position i\n    }\n}\n\nconst ft = new FenwickTree([10, 20, 30, 40, 50, 60]);\nconsole.log(\"BIT:\", ft.bit.slice(1).join(\" \"));\nconsole.log(\"getSum(2):\", ft.getSum(2));\nconsole.log(\"getSum(4):\", ft.getSum(4));\nconsole.log(\"rangeSum(1, 4):\", ft.rangeSum(1, 4));\nconsole.log(\"update(2, 35)\");\nft.update(2, 35);\nconsole.log(\"BIT:\", ft.bit.slice(1).join(\" \"));\nconsole.log(\"getSum(2):\", ft.getSum(2));\nconsole.log(\"getSum(4):\", ft.getSum(4));","filename":"JavaScript"},"revision":1},{"id":"6ebc25a5-fdc1-7eff-8b31-fcc574603875","type":"code","position":"aW","content":{"language":"text","code":"BIT: 10 30 30 100 50 110\ngetSum(2): 60\ngetSum(4): 150\nrangeSum(1, 4): 140\nupdate(2, 35)\nBIT: 10 30 35 105 50 110\ngetSum(2): 65\ngetSum(4): 155","filename":"Output"},"revision":1},{"id":"c38569fa-092b-71ba-95f0-71fceccf24ad","type":"text","position":"aX","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(log n) per getSum / update; O(n log n) construction · Space O(n)"}]}]}},"revision":1},{"id":"2cc715cc-c975-7e0d-9de6-5b8af6138a0f","type":"callout","position":"aY","content":{"variant":"note","title":"Linear construction","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Construction can be "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":": copy "},{"type":"text","text":"arr","marks":[{"type":"code"}]},{"type":"text","text":" into "},{"type":"text","text":"BIT[1..n]","marks":[{"type":"code"}]},{"type":"text","text":", then for "},{"type":"text","text":"i = 1..n","marks":[{"type":"code"}]},{"type":"text","text":" add "},{"type":"text","text":"BIT[i]","marks":[{"type":"code"}]},{"type":"text","text":" into "},{"type":"text","text":"BIT[i + (i & −i)]","marks":[{"type":"code"}]},{"type":"text","text":" if that index is "},{"type":"text","text":"≤ n","marks":[{"type":"code"}]},{"type":"text","text":". Every entry pushes its total to the one parent block that contains it — one pass, no logarithm."}]}]}},"revision":1},{"id":"76d758b8-52f0-735f-8da9-66673dd5ec2f","type":"callout","position":"aZ","content":{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two off-by-one traps: the BIT is "},{"type":"text","text":"1-based","marks":[{"type":"bold"}]},{"type":"text","text":" (so "},{"type":"text","text":"arr[i]","marks":[{"type":"code"}]},{"type":"text","text":" lives at "},{"type":"text","text":"i + 1","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"BIT[0]","marks":[{"type":"code"}]},{"type":"text","text":" is never used), and "},{"type":"text","text":"update","marks":[{"type":"code"}]},{"type":"text","text":" must use the "},{"type":"text","text":"difference","marks":[{"type":"bold"}]},{"type":"text","text":" against the stored "},{"type":"text","text":"arr[i]","marks":[{"type":"code"}]},{"type":"text","text":", not the new value — unless you are "},{"type":"text","text":"adding","marks":[{"type":"italic"}]},{"type":"text","text":" to an element rather than "},{"type":"text","text":"setting","marks":[{"type":"italic"}]},{"type":"text","text":" it, in which case the diff is the amount added and no "},{"type":"text","text":"arr","marks":[{"type":"code"}]},{"type":"text","text":" copy is needed."}]}]}},"revision":1},{"id":"2a61e369-c21d-7a9d-860a-0a13288481bc","type":"heading","position":"aa","content":{"level":1,"content":[{"type":"text","text":"Interview Q&A"}]},"revision":1},{"id":"436891f7-fdc8-7240-8b2a-bd29afcacbd2","type":"question","position":"ab","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Explain i & -i."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In two''s complement "},{"type":"text","text":"−i = ~i + 1","marks":[{"type":"code"}]},{"type":"text","text":". Negating flips all bits, and the "},{"type":"text","text":"+1","marks":[{"type":"code"}]},{"type":"text","text":" carries through the trailing ones, stopping at the position of "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":"''s lowest set bit. That bit is the only one set in both "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"−i","marks":[{"type":"code"}]},{"type":"text","text":", so "},{"type":"text","text":"i & −i","marks":[{"type":"code"}]},{"type":"text","text":" is exactly the lowest set bit (a power of two). In a BIT it is the length of the block entry "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" is responsible for."}]}]}},"revision":1},{"id":"61c98520-2125-7400-aea4-71efb6ec732a","type":"question","position":"ac","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is getSum O(log n)?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every iteration clears one set bit of the index ("},{"type":"text","text":"i -= i & -i","marks":[{"type":"code"}]},{"type":"text","text":"). A number below "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" has at most "},{"type":"text","text":"⌊log₂ n⌋ + 1","marks":[{"type":"code"}]},{"type":"text","text":" set bits, so the loop runs that many times at most. "},{"type":"text","text":"update","marks":[{"type":"code"}]},{"type":"text","text":" is symmetric: "},{"type":"text","text":"i += i & -i","marks":[{"type":"code"}]},{"type":"text","text":" increases the position of the lowest set bit each time, so it also takes "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":" steps to exceed "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"6c30c3be-3ac2-738e-b0d5-cf4dd4d8c0c0","type":"question","position":"ad","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"BIT vs segment tree?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Same "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":" for point update and prefix/range query. BIT: "},{"type":"text","text":"n + 1","marks":[{"type":"code"}]},{"type":"text","text":" memory, ~10 lines, faster constants; but only for "},{"type":"text","text":"invertible","marks":[{"type":"bold"}]},{"type":"text","text":" operations (sum, XOR, count) and point updates. Segment tree: any associative operation (min, max, gcd), range updates via lazy propagation, ≈ "},{"type":"text","text":"4n","marks":[{"type":"code"}]},{"type":"text","text":" memory, more code."}]}]}},"revision":1},{"id":"29c30f63-6757-726d-9e28-6b8c4816f690","type":"question","position":"ae","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you do a range update + point query with a BIT?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Store the "},{"type":"text","text":"differences","marks":[{"type":"bold"}]},{"type":"text","text":": to add "},{"type":"text","text":"v","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"[l, r]","marks":[{"type":"code"}]},{"type":"text","text":" do "},{"type":"text","text":"add(l, v)","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"add(r + 1, −v)","marks":[{"type":"code"}]},{"type":"text","text":"; a point query at "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" is then "},{"type":"text","text":"prefixSum(i)","marks":[{"type":"code"}]},{"type":"text","text":". Range update + range query needs two BITs. Both tricks rely on the sum being invertible."}]}]}},"revision":1},{"id":"72e14e8b-8cb8-7190-ba88-3a6deb751b99","type":"question","position":"af","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Name two classic BIT applications beyond prefix sums."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Counting inversions","marks":[{"type":"bold"}]},{"type":"text","text":" in "},{"type":"text","text":"O(n log n)","marks":[{"type":"code"}]},{"type":"text","text":": scan left to right and query how many previously seen values are greater. "},{"type":"text","text":"Order statistics / k-th smallest","marks":[{"type":"bold"}]},{"type":"text","text":" among the inserted values with a binary search over the BIT ("},{"type":"text","text":"O(log² n)","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":" with bit-walking). Both treat the BIT as a dynamic frequency table."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
